-- Complete owner financial source, maintained migration267 candidate.
-- One owning migration transaction; no runtime grants, flags, offers or funded effects.
-- Source: owner-admission-protocol-proposal-v3/qualification-source-columns.sql
-- UNNUMBERED source migration piece, ONE owning migration transaction.
-- Root applies after the accepted disabled owner-accounting schema checkpoint.
-- Exclusive topology before schema/account owner/provenance transition.
SELECT pg_advisory_xact_lock(83000003,1);
ALTER TABLE activity_qualifications ADD COLUMN participation_owner_id TEXT;
ALTER TABLE activity_qualifications ADD COLUMN participation_owner_kind TEXT;
ALTER TABLE activity_qualifications ADD COLUMN guest_main_operation_id TEXT;
DO $bounded_owner_qualification_backfill$
DECLARE original_definition TEXT; original_body TEXT; temporary_body TEXT;
 before_rows TEXT; after_rows TEXT; namespace_id OID; owner_id OID; actual_owner OID; schema_name TEXT;
BEGIN
 SELECT c.relnamespace,c.relowner,n.nspname INTO STRICT namespace_id,owner_id,schema_name FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid='participation_owners'::regclass;
 SELECT pg_get_functiondef(p.oid),p.prosrc,p.proowner INTO STRICT original_definition,original_body,actual_owner FROM pg_proc p WHERE p.oid='guard_activity_qualification()'::regprocedure AND p.pronamespace=namespace_id;
 IF (length(original_body)-length(replace(original_body,'BEGIN',''))) / length('BEGIN')<>1 THEN RAISE EXCEPTION 'bounded single guard insertion required'; END IF;
 IF actual_owner<>owner_id OR EXISTS(SELECT 1 FROM activity_qualifications q WHERE q.account_id IS NULL OR q.persona_id IS NULL
  OR NOT EXISTS(SELECT 1 FROM participation_owners o WHERE o.kind='account' AND o.account_id=q.account_id))
 THEN RAISE EXCEPTION 'qualified account source backfill unavailable'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(q)-ARRAY['participation_owner_id','participation_owner_kind','guest_main_operation_id'] ORDER BY qualification_id)::TEXT,'[]') INTO before_rows FROM activity_qualifications q;
 temporary_body:=replace(original_body,'BEGIN', $transition$BEGIN
 IF TG_OP='UPDATE' AND OLD.participation_owner_id IS NULL AND OLD.participation_owner_kind IS NULL AND OLD.guest_main_operation_id IS NULL
  AND NEW.participation_owner_kind='account' AND NEW.guest_main_operation_id IS NULL
  AND (to_jsonb(NEW)-ARRAY['participation_owner_id','participation_owner_kind','guest_main_operation_id'])=(to_jsonb(OLD)-ARRAY['participation_owner_id','participation_owner_kind','guest_main_operation_id'])
  AND EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=NEW.participation_owner_id AND kind='account' AND account_id=NEW.account_id)
 THEN RETURN NEW; END IF;
$transition$);
 IF temporary_body=original_body THEN RAISE EXCEPTION 'source backfill guard render failed'; END IF;
 -- Table DDL lock isolates the temporary bounded predicate. No GUC/replica
 -- bypass, disabled immutable trigger or application-granted backfill exists.
 EXECUTE format('CREATE OR REPLACE FUNCTION %I.guard_activity_qualification() RETURNS TRIGGER LANGUAGE plpgsql AS %L',schema_name,temporary_body);
 UPDATE activity_qualifications q SET participation_owner_id=o.owner_id,participation_owner_kind='account'
 FROM participation_owners o WHERE o.kind='account' AND o.account_id=q.account_id;
 EXECUTE original_definition;
 IF pg_get_functiondef('guard_activity_qualification()'::regprocedure) IS DISTINCT FROM original_definition THEN RAISE EXCEPTION 'original qualification guard restoration differs'; END IF;
 SELECT coalesce(jsonb_agg(to_jsonb(q)-ARRAY['participation_owner_id','participation_owner_kind','guest_main_operation_id'] ORDER BY qualification_id)::TEXT,'[]') INTO after_rows FROM activity_qualifications q;
 IF after_rows IS DISTINCT FROM before_rows THEN RAISE EXCEPTION 'historical qualification evidence changed'; END IF;
END $bounded_owner_qualification_backfill$;
ALTER TABLE activity_qualifications
 ALTER COLUMN participation_owner_id SET NOT NULL,
 ALTER COLUMN participation_owner_kind SET NOT NULL,
 ALTER COLUMN account_id DROP NOT NULL,
 ALTER COLUMN persona_id DROP NOT NULL,
 ADD CONSTRAINT qualification_owner_kind_fk FOREIGN KEY(participation_owner_id,participation_owner_kind) REFERENCES participation_owners(owner_id,kind),
 ADD CONSTRAINT qualification_account_owner_fk FOREIGN KEY(participation_owner_id,account_id) REFERENCES participation_owners(owner_id,account_id),
 ADD CONSTRAINT qualification_guest_operation_fk FOREIGN KEY(guest_main_operation_id,participation_owner_id) REFERENCES guest_participation_operations(operation_id,source_owner_id),
 ADD CONSTRAINT qualification_source_closed CHECK(
  (participation_owner_kind='account' AND account_id IS NOT NULL AND persona_id IS NOT NULL AND guest_main_operation_id IS NULL)
  OR (participation_owner_kind='guest' AND account_id IS NULL AND persona_id IS NULL AND activity_key='study' AND guest_main_operation_id IS NOT NULL)),
 ADD CONSTRAINT qualification_owner_identity_key UNIQUE(qualification_id,participation_owner_id),
 ADD CONSTRAINT qualification_guest_one_main UNIQUE(guest_main_operation_id);

CREATE UNIQUE INDEX guest_qualification_one_completed_source ON activity_qualifications(study_session_id) WHERE participation_owner_kind='guest';

-- Retained Account projections cannot point at a Guest qualification. No historical remapping.
ALTER TABLE activity_qualifications ADD CONSTRAINT qualification_retained_account_identity UNIQUE(qualification_id,account_id);
ALTER TABLE song_streak_days ADD CONSTRAINT retained_account_qualification_source_fk FOREIGN KEY(first_qualification_id,account_id) REFERENCES activity_qualifications(qualification_id,account_id);
ALTER TABLE song_streak_day_activities ADD CONSTRAINT retained_account_qualification_source_fk FOREIGN KEY(last_qualification_id,account_id) REFERENCES activity_qualifications(qualification_id,account_id);
ALTER TABLE community_streak_days ADD CONSTRAINT retained_account_qualification_source_fk FOREIGN KEY(first_qualification_id,account_id) REFERENCES activity_qualifications(qualification_id,account_id);
ALTER TABLE reward_eligibility_decisions ADD CONSTRAINT retained_account_qualification_source_fk FOREIGN KEY(qualification_id,account_id) REFERENCES activity_qualifications(qualification_id,account_id);
ALTER TABLE song_reward_bundle_claims ADD CONSTRAINT retained_account_qualification_source_fk FOREIGN KEY(qualification_id,account_id) REFERENCES activity_qualifications(qualification_id,account_id);
ALTER TABLE megapot_pool_shares ADD CONSTRAINT retained_account_qualification_source_fk FOREIGN KEY(qualification_id,account_id) REFERENCES activity_qualifications(qualification_id,account_id);
ALTER TABLE participation_eligibility_decisions ADD CONSTRAINT owner_eligibility_actual_qualification_fk FOREIGN KEY(qualification_id,owner_id) REFERENCES activity_qualifications(qualification_id,participation_owner_id);

-- Source: owner-admission-protocol-proposal-v3/source-group-locks.sql
CREATE FUNCTION require_owner_admission_read_committed_private_v1()
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
  RAISE EXCEPTION 'fresh original admission snapshot required' USING ERRCODE='GP006'; END IF;
END $$;

-- Common group lock primitive, ungranted. Current schema still blocks financial
-- association writers; full future admission requires their same EXCLUSIVE barrier.
CREATE FUNCTION lock_owner_participation_group_private_v1(p_source TEXT)
RETURNS TEXT[] LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_ids TEXT[]; account_ids TEXT[]; count_accounts INTEGER;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 LOCK TABLE account_aliases IN SHARE MODE;
 IF NOT EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=p_source) THEN
  RAISE EXCEPTION 'immutable source owner missing' USING ERRCODE='GP002'; END IF;
 WITH RECURSIVE group_members(owner_id) AS (
  SELECT p_source
  UNION
  SELECT next_member.owner_id FROM group_members prior CROSS JOIN LATERAL (
   SELECT a.canonical_owner_id AS owner_id FROM guest_empty_owner_aliases a WHERE a.source_owner_id=prior.owner_id
   UNION SELECT a.source_owner_id FROM guest_empty_owner_aliases a WHERE a.canonical_owner_id=prior.owner_id
   UNION SELECT a.account_owner_id FROM guest_owner_associations a WHERE a.guest_owner_id=prior.owner_id
   UNION SELECT a.guest_owner_id FROM guest_owner_associations a WHERE a.account_owner_id=prior.owner_id
   UNION SELECT other_owner.owner_id FROM participation_owners current_owner
    JOIN account_aliases a ON a.source_user_id=current_owner.account_id OR a.canonical_user_id=current_owner.account_id
    JOIN participation_owners other_owner ON other_owner.account_id IN(a.source_user_id,a.canonical_user_id)
    WHERE current_owner.owner_id=prior.owner_id AND current_owner.kind='account'
     AND ((a.kind='alias' AND a.status='active') OR (a.kind='merge' AND a.status IN('finalizing','completed')))
  ) next_member
 ) SELECT array_agg(owner_id ORDER BY convert_to(owner_id,'UTF8')) INTO source_ids FROM group_members;
 IF source_ids IS NULL OR cardinality(source_ids)>10000 OR EXISTS(SELECT 1 FROM unnest(source_ids) source_id
  WHERE NOT EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=source_id)) THEN
  RAISE EXCEPTION 'source group closure unavailable' USING ERRCODE='GP003'; END IF;
 SELECT array_agg(account_id ORDER BY convert_to(account_id,'UTF8')) INTO account_ids
 FROM participation_owners WHERE owner_id=ANY(source_ids) AND kind='account';
 IF EXISTS(SELECT 1 FROM account_aliases WHERE source_user_id=ANY(coalesce(account_ids,'{}'::TEXT[])) AND kind='merge' AND status='finalizing') THEN
  RAISE EXCEPTION 'account topology is unsettled' USING ERRCODE='GP003'; END IF;
 IF account_ids IS NOT NULL THEN
  SELECT count(*) INTO count_accounts FROM unnest(account_ids) id WHERE NOT EXISTS(SELECT 1 FROM account_aliases a WHERE a.source_user_id=id AND((a.kind='alias' AND a.status='active') OR(a.kind='merge' AND a.status='completed')));
  IF count_accounts<>1 THEN RAISE EXCEPTION 'canonical account group is unsettled' USING ERRCODE='GP003'; END IF;
 END IF;
 -- Compatible non-key state locks avoid freeze's immutable-FK KEY SHARE cycle.
 -- Every other owner/account business writer must use the same ordered protocol;
 -- old FOR UPDATE upgrades are NOT declared repaired by this helper alone.
 PERFORM 1 FROM users WHERE user_id=ANY(coalesce(account_ids,'{}'::TEXT[])) ORDER BY convert_to(user_id,'UTF8') FOR NO KEY UPDATE;
 PERFORM 1 FROM participation_owners WHERE owner_id=ANY(source_ids) ORDER BY convert_to(owner_id,'UTF8') FOR NO KEY UPDATE;
 RETURN source_ids;
END $$;
CREATE FUNCTION lock_account_reward_finalization_v1(p_account TEXT,p_community TEXT,p_session TEXT,p_activity TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_id TEXT; persona_id TEXT; actual_community TEXT;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 -- BEFORE any existing admission/capture/session/item/attempt/qualification lock.
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 SELECT owner_id INTO STRICT source_id FROM participation_owners WHERE kind='account' AND account_id=p_account;
 PERFORM lock_owner_participation_group_private_v1(source_id);
 IF p_activity='study_v2' THEN SELECT s.persona_id,s.community_id INTO persona_id,actual_community FROM study_sessions_v2 s WHERE session_id=p_session AND account_id=p_account;
 ELSIF p_activity='study_legacy' THEN SELECT s.persona_id,s.community_id INTO persona_id,actual_community FROM study_sessions s WHERE session_id=p_session AND account_id=p_account;
 ELSIF p_activity='karaoke' THEN SELECT s.persona_id,s.community_id INTO persona_id,actual_community FROM karaoke_sessions s WHERE session_id=p_session AND account_id=p_account;
 ELSE RAISE EXCEPTION 'closed account activity source required' USING ERRCODE='22023'; END IF;
 -- Locking only: retain the immutable Account/session/community provenance.
 -- Original producer admission checks remain in their original caller positions;
 -- an accepted captured finalizer must not gain a new live access/proof gate.
 IF persona_id IS NULL OR actual_community IS DISTINCT FROM p_community THEN
  RAISE EXCEPTION 'actual account activity source unavailable' USING ERRCODE='GP002'; END IF;
END $$;

-- Source: owner-admission-protocol-proposal-v3/qualification-dispatch.sql
CREATE FUNCTION set_qualification_original_source_private_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE actual_owner TEXT;
BEGIN
 IF NEW.account_id IS NOT NULL AND NEW.persona_id IS NOT NULL THEN
  SELECT owner_id INTO STRICT actual_owner FROM participation_owners WHERE kind='account' AND account_id=NEW.account_id;
  IF NEW.participation_owner_id IS NOT NULL AND NEW.participation_owner_id<>actual_owner
   OR NEW.participation_owner_kind IS NOT NULL AND NEW.participation_owner_kind<>'account'
   OR NEW.guest_main_operation_id IS NOT NULL THEN
   RAISE EXCEPTION 'qualification original account changed' USING ERRCODE='GP002'; END IF;
  NEW.participation_owner_id:=actual_owner; NEW.participation_owner_kind:='account';
 ELSIF NEW.account_id IS NULL AND NEW.persona_id IS NULL AND NEW.participation_owner_kind='guest'
  AND NEW.participation_owner_id IS NOT NULL AND NEW.guest_main_operation_id IS NOT NULL AND NEW.activity_key='study' THEN
  -- Original guest provenance is checked by actual qualified lesson guard below.
  NULL;
 ELSE RAISE EXCEPTION 'closed qualification source required' USING ERRCODE='GP002'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER activity_01_original_source BEFORE INSERT ON activity_qualifications FOR EACH ROW EXECUTE FUNCTION set_qualification_original_source_private_v1();
CREATE FUNCTION validate_qualified_guest_activity_private_v1(q activity_qualifications)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE facts JSONB;
BEGIN
 IF q.participation_owner_kind IS DISTINCT FROM 'guest' OR q.account_id IS NOT NULL OR q.persona_id IS NOT NULL
  OR q.activity_key IS DISTINCT FROM 'study' OR q.karaoke_session_id IS NOT NULL OR q.karaoke_attempt_id IS NOT NULL THEN
  RAISE EXCEPTION 'guest qualification has no account/Karaoke authority' USING ERRCODE='GP002'; END IF;
 facts:=read_qualified_guest_study_facts_private_v1(q.participation_owner_id,q.study_session_id,q.guest_main_operation_id);
 IF facts->>'state' IS DISTINCT FROM 'qualified'
  OR q.community_id IS DISTINCT FROM facts->>'communityId' OR q.post_id IS DISTINCT FROM facts->>'postId'
  OR q.audio_revision IS DISTINCT FROM (facts->>'audioRevision')::BIGINT
  OR q.qualification_policy_version_id IS DISTINCT FROM facts->>'policyRevision'
  OR q.score_bps IS DISTINCT FROM (facts->>'scoreBps')::INTEGER
  OR q.qualified_at IS DISTINCT FROM (facts->>'qualifiedAt')::TIMESTAMPTZ
  OR q.streak_day IS DISTINCT FROM (facts->>'streakDay')::DATE
  OR q.evidence_summary IS DISTINCT FROM facts->'evidence'
 THEN RAISE EXCEPTION 'guest qualification is not exact accepted lesson output' USING ERRCODE='GP003'; END IF;
END $$;
-- Actual0082 guard and actual0134 asset projector/secured retained-v2 projector
-- are rendered with an early exhaustive guest branch by derive-dispatch.py.
-- Account bodies remain byte-for-byte source statements; no guest side effects,
-- no account streak/public-standing/token/asset-bonus replay on signup.

-- Source: owner-admission-protocol-proposal-v3/guard_activity_qualification.successor.sql
CREATE OR REPLACE FUNCTION guard_activity_qualification() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  study_record study_sessions%ROWTYPE;
  study_v2_record RECORD;
  karaoke_session_record karaoke_sessions%ROWTYPE;
  karaoke_attempt_record karaoke_attempts%ROWTYPE;
  karaoke_policy_document JSONB;
  karaoke_policy_kind TEXT;
  expected_evidence JSONB;
BEGIN
  IF TG_OP='INSERT' AND NEW.participation_owner_kind='guest' THEN
    PERFORM validate_qualified_guest_activity_private_v1(NEW); RETURN NEW;
  END IF;
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'activity qualifications are append-only';
  END IF;
  IF NEW.activity_key = 'study' THEN
    SELECT session.account_id, session.persona_id, session.community_id, session.post_id,
           session.audio_revision, session.qualification_policy_revision,
           session.timezone, session.status, session.completed_at,
           count(item.session_item_id)::bigint AS qualifying_exercise_count,
           count(item.session_item_id) FILTER (WHERE EXISTS (
             SELECT 1 FROM study_attempts_v2 attempt
              WHERE attempt.session_item_id=item.session_item_id
           ))::bigint AS presented_count,
           count(item.session_item_id) FILTER (WHERE EXISTS (
             SELECT 1 FROM study_attempts_v2 attempt
              WHERE attempt.session_item_id=item.session_item_id
                AND attempt.attempt_number=1 AND attempt.outcome='correct'
           ))::bigint AS first_pass_correct
      INTO study_v2_record
     FROM study_sessions_v2 session
      JOIN study_session_items_v2 item ON item.session_id=session.session_id
     WHERE session.session_id=NEW.study_session_id
     GROUP BY session.session_id;
    IF study_v2_record.account_id IS NOT NULL THEN
      expected_evidence := jsonb_build_object(
        'kind', 'study_session_first_pass_v2',
        'qualifying_exercise_count', study_v2_record.qualifying_exercise_count,
        'first_pass_correct', study_v2_record.first_pass_correct,
        'required_correct', greatest(
          1, ceil((7 * study_v2_record.qualifying_exercise_count)::numeric / 10)::bigint
        )
      );
      IF study_v2_record.status <> 'completed'
         OR study_v2_record.presented_count <> study_v2_record.qualifying_exercise_count
         OR study_v2_record.first_pass_correct < greatest(
           1, ceil((7 * study_v2_record.qualifying_exercise_count)::numeric / 10)::bigint
         )
         OR ROW(
           NEW.account_id, NEW.persona_id, NEW.community_id, NEW.post_id,
           NEW.audio_revision, NEW.qualification_policy_version_id,
           NEW.score_bps, NEW.qualified_at, NEW.streak_day, NEW.evidence_summary
         ) IS DISTINCT FROM ROW(
           study_v2_record.account_id, study_v2_record.persona_id,
           study_v2_record.community_id, study_v2_record.post_id,
           study_v2_record.audio_revision, study_v2_record.qualification_policy_revision,
           ((10000 * study_v2_record.first_pass_correct)
             / study_v2_record.qualifying_exercise_count)::integer,
           study_v2_record.completed_at,
           (study_v2_record.completed_at AT TIME ZONE study_v2_record.timezone)::date,
           expected_evidence
         ) THEN
        RAISE EXCEPTION 'Study v2 qualification is not exact reducer output';
      END IF;
      RETURN NEW;
    END IF;

    SELECT * INTO study_record FROM study_sessions
     WHERE session_id = NEW.study_session_id FOR SHARE;
    expected_evidence := jsonb_build_object(
      'kind', 'study_session_first_pass_v2',
      'qualifying_exercise_count', study_record.qualifying_exercise_count,
      'first_pass_correct', study_record.first_pass_correct,
      'required_correct', study_record.required_correct
    );
    IF study_record.session_id IS NULL OR study_record.status <> 'completed'
       OR study_record.first_pass_correct < study_record.required_correct
       OR ROW(
         NEW.account_id, NEW.persona_id, NEW.community_id, NEW.post_id,
         NEW.audio_revision, NEW.qualification_policy_version_id,
         NEW.score_bps, NEW.qualified_at, NEW.streak_day, NEW.evidence_summary
       ) IS DISTINCT FROM ROW(
         study_record.account_id, study_record.persona_id,
         study_record.community_id, study_record.post_id,
         study_record.audio_revision, study_record.qualification_policy_version_id,
         study_record.score_bps, study_record.completed_at,
         study_record.streak_day, expected_evidence
       ) THEN
      RAISE EXCEPTION 'Study qualification is not exact reducer output';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.activity_key = 'karaoke' THEN
    SELECT * INTO karaoke_session_record FROM karaoke_sessions
     WHERE session_id = NEW.karaoke_session_id
       AND attempt_id = NEW.karaoke_attempt_id FOR SHARE;
    SELECT * INTO karaoke_attempt_record FROM karaoke_attempts
     WHERE session_id = NEW.karaoke_session_id
       AND attempt_id = NEW.karaoke_attempt_id FOR SHARE;
    SELECT policy_kind, policy_document INTO karaoke_policy_kind, karaoke_policy_document
      FROM qualification_policy_versions
     WHERE qualification_policy_version_id = karaoke_session_record.qualification_policy_version_id
       AND activity_key = 'karaoke';
    IF karaoke_session_record.session_id IS NULL
       OR karaoke_session_record.status <> 'completed'
       OR karaoke_attempt_record.completion_reason <> 'completed'
       OR karaoke_attempt_record.scored_line_count < 5
       OR karaoke_attempt_record.coverage_bps < 8500
       OR karaoke_attempt_record.final_score_bps < 7000
       OR (
         karaoke_policy_kind = 'karaoke_qualification_v2'
         AND NOT (karaoke_policy_document->'eligible_playback_kinds'
           ? karaoke_session_record.playback_kind)
       )
       OR ROW(
         NEW.account_id, NEW.persona_id, NEW.community_id, NEW.post_id,
         NEW.audio_revision, NEW.qualification_policy_version_id,
         NEW.score_bps, NEW.qualified_at, NEW.streak_day, NEW.evidence_summary
       ) IS DISTINCT FROM ROW(
         karaoke_session_record.account_id, karaoke_session_record.persona_id,
         karaoke_session_record.community_id, karaoke_session_record.post_id,
         karaoke_session_record.audio_revision,
         karaoke_session_record.qualification_policy_version_id,
         karaoke_attempt_record.final_score_bps, karaoke_attempt_record.completed_at,
         (karaoke_attempt_record.completed_at AT TIME ZONE karaoke_session_record.timezone)::date,
         karaoke_attempt_record.evidence_summary
       ) THEN
      RAISE EXCEPTION 'Karaoke qualification is not exact reducer output';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'reserved activities cannot produce qualifications';
END
$$;

-- Source: owner-admission-protocol-proposal-v3/project_asset_bonus_claim_from_qualification.successor.sql
CREATE OR REPLACE FUNCTION project_asset_bonus_claim_from_qualification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  candidate RECORD;
  asset_leg RECORD;
  evidence RECORD;
  existing_consumption reward_subject_consumptions%ROWTYPE;
  decided_at TIMESTAMPTZ := clock_timestamp();
  reason TEXT;
  decision_outcome TEXT;
  decision_id TEXT;
  eligibility_id TEXT;
  consumption_id TEXT;
  identity_digest TEXT;
  credit_id TEXT;
BEGIN
  IF NEW.participation_owner_kind='guest' THEN RETURN NEW; END IF;
  SELECT offer.offer_id, offer.community_id, offer.reward_policy_version_id,
         offer.ends_at, policy.policy_hash, leg.leg_id
    INTO candidate
    FROM song_reward_offers offer
    JOIN song_reward_offer_legs leg ON leg.offer_id = offer.offer_id
    JOIN policy_versions policy
      ON policy.community_id = offer.community_id
     AND policy.policy_version_id = offer.reward_policy_version_id
     AND policy.policy_purpose = 'reward'
     AND policy.uniqueness_authority_id = offer.offer_id
   WHERE offer.community_id = NEW.community_id
     AND offer.post_id = NEW.post_id
     AND offer.audio_revision = NEW.audio_revision
     AND offer.status = 'active'
     AND decided_at < offer.ends_at
     AND NEW.qualified_at >= offer.starts_at
     AND NEW.qualified_at < offer.ends_at
     AND leg.kind = 'asset_bonus'
     AND reward_leg_accepts_qualification(leg.leg_id, NEW.activity_key, NEW.qualification_policy_version_id) AND leg.status = 'active'
     AND NEW.qualified_at >= leg.participation_starts_at
     AND leg.fulfilled_atomic / leg.amount_per_claim_atomic < leg.max_claims
     AND leg.funded_atomic - leg.reserved_atomic - leg.spent_atomic
       - leg.fulfilled_atomic - leg.refunded_atomic >= leg.amount_per_claim_atomic
   ORDER BY leg.leg_id
   LIMIT 1
   FOR UPDATE OF leg;

  IF candidate.offer_id IS NULL THEN
    RETURN NEW;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    NEW.account_id || chr(31) || candidate.offer_id, 53000002
  ));
  IF EXISTS (
    SELECT 1 FROM song_reward_bundle_claims claim
     WHERE claim.account_id = NEW.account_id AND claim.offer_id = candidate.offer_id
  ) THEN
    RETURN NEW;
  END IF;

  identity_digest := md5(NEW.qualification_id || chr(31) || candidate.offer_id);
  decision_id := 'reward_decision_' || identity_digest;
  eligibility_id := 'reward_eligibility_' || identity_digest;
  consumption_id := 'reward_subject_' || identity_digest;

  WITH exact_evidence AS (
    SELECT DISTINCT ON (subject.subject_key_id)
           subject.subject_key_id, active_binding.binding_event_id,
           active_binding.binding_epoch, receipt.evidence_receipt_id,
           receipt.evidence_hash,
           LEAST(candidate.ends_at, receipt.expires_at,
             personhood.expires_at, subject_unique.expires_at) AS evidence_expires_at,
           receipt.observed_at
      FROM subject_keys subject
      JOIN active_subject_key_bindings active_binding
        ON active_binding.subject_key_id = subject.subject_key_id
       AND active_binding.user_id = NEW.account_id
      JOIN assertion_bindings binding
        ON binding.user_id = NEW.account_id AND binding.binding_mode = 'same_subject'
       AND binding.subject_key_id = subject.subject_key_id
       AND binding.subject_binding_event_id = active_binding.binding_event_id
       AND binding.subject_binding_epoch = active_binding.binding_epoch
      JOIN assertions personhood
        ON personhood.binding_group_id = binding.binding_group_id
       AND personhood.user_id = NEW.account_id
       AND personhood.subject_key_id = subject.subject_key_id
       AND personhood.claim_id = 'human.personhood'
       AND personhood.assertion_value = '{"personhood": true}'::jsonb
       AND personhood.assurance = 'provider_attested'
      JOIN assertions subject_unique
        ON subject_unique.binding_group_id = binding.binding_group_id
       AND subject_unique.user_id = NEW.account_id
       AND subject_unique.subject_key_id = subject.subject_key_id
       AND subject_unique.evidence_receipt_id = personhood.evidence_receipt_id
       AND subject_unique.claim_id = 'credential.subject_unique'
       AND subject_unique.assertion_value = '{"subject_unique": true}'::jsonb
       AND subject_unique.assurance = 'provider_attested'
      JOIN evidence_receipts receipt
        ON receipt.evidence_receipt_id = personhood.evidence_receipt_id
       AND receipt.user_id = NEW.account_id
       AND receipt.subject_key_id = subject.subject_key_id
       AND receipt.subject_binding_event_id = active_binding.binding_event_id
       AND receipt.subject_binding_epoch = active_binding.binding_epoch
       AND receipt.provider_id = 'very.web'
       AND receipt.issuer = 'https://verify.very.org'
       AND receipt.method = 'palm_web'
       AND receipt.scope_kind = 'issuer_rp_scope'
       AND receipt.issuer_rp_scope = 'pirate-social'
       AND receipt.issuer_rp_action_scope IS NULL
       AND receipt.protocol_version = 'very-web-v1'
       AND receipt.evidence_kind = 'very.web.server-verified.v1'
       AND receipt.provenance_kind = 'proof_session'
      JOIN proof_sessions session
        ON session.proof_session_id = receipt.proof_session_id
       AND session.actor_id = NEW.account_id
       AND session.status = 'completed' AND session.completed_at = session.terminal_at
       AND session.provider_id = receipt.provider_id AND session.issuer = receipt.issuer
       AND session.method = receipt.method AND session.scope_kind = receipt.scope_kind
       AND session.issuer_rp_scope = receipt.issuer_rp_scope
       AND session.issuer_rp_action_scope IS NOT DISTINCT FROM receipt.issuer_rp_action_scope
       AND session.protocol_version = receipt.protocol_version
       AND session.requested_requirements =
         '[{"claim_id":"credential.subject_unique"},{"claim_id":"human.personhood"}]'::jsonb
       AND session.requested_claim_ids =
         '["credential.subject_unique","human.personhood"]'::jsonb
     WHERE subject.issuer = 'https://verify.very.org'
       AND subject.method = 'palm_web' AND subject.scope_kind = 'issuer_rp_scope'
       AND subject.issuer_rp_scope = 'pirate-social'
       AND subject.issuer_rp_action_scope IS NULL
       AND (receipt.expires_at IS NULL OR receipt.expires_at > decided_at + interval '5 seconds')
       AND (personhood.expires_at IS NULL OR personhood.expires_at > decided_at + interval '5 seconds')
       AND (subject_unique.expires_at IS NULL OR subject_unique.expires_at > decided_at + interval '5 seconds')
       AND COALESCE((SELECT revalidation.outcome
          FROM assertion_revalidation_events revalidation
         WHERE revalidation.assertion_id = personhood.assertion_id
         ORDER BY revalidation.observed_at DESC,
                  revalidation.assertion_revalidation_event_id DESC LIMIT 1), 'accepted') = 'accepted'
       AND COALESCE((SELECT revalidation.outcome
          FROM assertion_revalidation_events revalidation
         WHERE revalidation.assertion_id = subject_unique.assertion_id
         ORDER BY revalidation.observed_at DESC,
                  revalidation.assertion_revalidation_event_id DESC LIMIT 1), 'accepted') = 'accepted'
     ORDER BY subject.subject_key_id, receipt.observed_at DESC,
              receipt.evidence_receipt_id DESC
  )
  SELECT exact_evidence.*, count(*) OVER () AS evidence_count
    INTO evidence FROM exact_evidence
   ORDER BY exact_evidence.observed_at DESC, exact_evidence.subject_key_id LIMIT 1;

  IF evidence.subject_key_id IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM subject_keys subject
      JOIN active_subject_key_bindings active_binding
        ON active_binding.subject_key_id = subject.subject_key_id
       AND active_binding.user_id = NEW.account_id
      JOIN assertions personhood ON personhood.subject_key_id = subject.subject_key_id
       AND personhood.user_id = NEW.account_id AND personhood.claim_id = 'human.personhood'
       AND personhood.assertion_value = '{"personhood": true}'::jsonb
      JOIN assertions subject_unique
        ON subject_unique.binding_group_id = personhood.binding_group_id
       AND subject_unique.evidence_receipt_id = personhood.evidence_receipt_id
       AND subject_unique.subject_key_id = subject.subject_key_id
       AND subject_unique.user_id = NEW.account_id
       AND subject_unique.claim_id = 'credential.subject_unique'
       AND subject_unique.assertion_value = '{"subject_unique": true}'::jsonb
      WHERE subject.issuer = 'https://verify.very.org' AND subject.method = 'palm_web'
        AND subject.scope_kind = 'issuer_rp_scope'
        AND subject.issuer_rp_scope = 'pirate-social'
    ) THEN
      reason := 'verification_stale'; decision_outcome := 'needs_evidence';
    ELSIF EXISTS (
      SELECT 1 FROM subject_keys subject
      JOIN active_subject_key_bindings active_binding
        ON active_binding.subject_key_id = subject.subject_key_id
       AND active_binding.user_id = NEW.account_id
      WHERE subject.issuer = 'https://verify.very.org' AND subject.method = 'palm_web'
        AND subject.scope_kind = 'issuer_rp_scope'
        AND subject.issuer_rp_scope = 'pirate-social'
    ) THEN
      reason := 'verification_failed'; decision_outcome := 'fail';
    ELSE
      reason := 'verification_missing'; decision_outcome := 'needs_evidence';
    END IF;
  ELSIF evidence.evidence_count <> 1 THEN
    reason := 'verification_failed'; decision_outcome := 'fail';
  ELSE
    PERFORM 1 FROM subject_keys WHERE subject_key_id = evidence.subject_key_id FOR UPDATE;
    SELECT * INTO existing_consumption FROM reward_subject_consumptions
     WHERE campaign_id = candidate.offer_id AND subject_key_id = evidence.subject_key_id
     FOR UPDATE;
    IF existing_consumption.reward_subject_consumption_id IS NULL THEN
      INSERT INTO reward_subject_consumptions (
        reward_subject_consumption_id,campaign_id,subject_key_id,user_id,
        binding_event_id,binding_epoch,evidence_receipt_id,consumed_at,created_at
      ) VALUES (
        consumption_id,candidate.offer_id,evidence.subject_key_id,NEW.account_id,
        evidence.binding_event_id,evidence.binding_epoch,evidence.evidence_receipt_id,
        decided_at,decided_at
      );
    ELSIF existing_consumption.user_id <> NEW.account_id THEN
      reason := 'subject_already_consumed'; decision_outcome := 'fail';
    END IF;
  END IF;

  IF reason IS NOT NULL THEN
    INSERT INTO decision_records (
      decision_record_id,community_id,user_id,policy_version_id,policy_hash,
      evaluation_mode,outcome,winning_witness,trace,indeterminate_reason,request_id,created_at
    ) VALUES (
      decision_id,candidate.community_id,NEW.account_id,candidate.reward_policy_version_id,
      candidate.policy_hash,'enforce',decision_outcome,'[]'::jsonb,
      jsonb_build_array(jsonb_build_object('reason',reason)),reason,
      'asset-claim:' || identity_digest,decided_at
    );
    INSERT INTO reward_eligibility_decisions (
      eligibility_decision_id,leg_id,account_id,persona_id,purpose,qualification_id,
      decision_record_id,outcome,reason,policy_version,evidence_hash,decided_at,expires_at
    ) VALUES (
      eligibility_id,candidate.leg_id,NEW.account_id,NEW.persona_id,'asset_claim',
      NEW.qualification_id,decision_id,'ineligible',reason,
      candidate.reward_policy_version_id,COALESCE(evidence.evidence_hash,candidate.policy_hash),
      decided_at,candidate.ends_at
    );
    INSERT INTO song_reward_bundle_claims (
      account_id,offer_id,persona_id,qualification_id,eligibility_decision_id,
      state,terminal_reason,created_at,updated_at
    ) VALUES (
      NEW.account_id,candidate.offer_id,NEW.persona_id,NEW.qualification_id,
      eligibility_id,'ineligible',reason,decided_at,decided_at
    );
    FOR asset_leg IN
      SELECT leg.* FROM song_reward_offer_legs leg
       WHERE leg.offer_id = candidate.offer_id AND leg.kind = 'asset_bonus'
     AND reward_leg_accepts_qualification(leg.leg_id, NEW.activity_key, NEW.qualification_policy_version_id)
         AND leg.status = 'active' AND NEW.qualified_at >= leg.participation_starts_at
         AND leg.fulfilled_atomic / leg.amount_per_claim_atomic < leg.max_claims
         AND leg.funded_atomic - leg.reserved_atomic - leg.spent_atomic
           - leg.fulfilled_atomic - leg.refunded_atomic >= leg.amount_per_claim_atomic
       ORDER BY leg.leg_id FOR UPDATE
    LOOP
      INSERT INTO song_reward_bundle_claim_legs (
        account_id,offer_id,leg_id,amount_atomic,state,terminal_reason,created_at
      ) VALUES (
        NEW.account_id,candidate.offer_id,asset_leg.leg_id,
        asset_leg.amount_per_claim_atomic,'unavailable',reason,decided_at
      );
    END LOOP;
    RETURN NEW;
  END IF;

  INSERT INTO decision_records (
    decision_record_id,community_id,user_id,policy_version_id,policy_hash,
    evaluation_mode,outcome,winning_witness,trace,request_id,created_at
  ) VALUES (
    decision_id,candidate.community_id,NEW.account_id,candidate.reward_policy_version_id,
    candidate.policy_hash,'enforce','pass',
    jsonb_build_array(jsonb_build_object('subject_key_id',evidence.subject_key_id,
      'evidence_receipt_id',evidence.evidence_receipt_id)),
    jsonb_build_array(jsonb_build_object('result','eligible')),
    'asset-claim:' || identity_digest,decided_at
  );
  INSERT INTO reward_eligibility_decisions (
    eligibility_decision_id,leg_id,account_id,persona_id,purpose,qualification_id,
    decision_record_id,outcome,policy_version,evidence_hash,decided_at,expires_at
  ) VALUES (
    eligibility_id,candidate.leg_id,NEW.account_id,NEW.persona_id,'asset_claim',
    NEW.qualification_id,decision_id,'eligible',candidate.reward_policy_version_id,
    evidence.evidence_hash,decided_at,evidence.evidence_expires_at
  );
  INSERT INTO song_reward_bundle_claims (
    account_id,offer_id,persona_id,qualification_id,eligibility_decision_id,
    state,created_at,updated_at
  ) VALUES (
    NEW.account_id,candidate.offer_id,NEW.persona_id,NEW.qualification_id,
    eligibility_id,'credited',decided_at,decided_at
  );

  FOR asset_leg IN
    SELECT leg.* FROM song_reward_offer_legs leg
     WHERE leg.offer_id = candidate.offer_id AND leg.kind = 'asset_bonus'
     AND reward_leg_accepts_qualification(leg.leg_id, NEW.activity_key, NEW.qualification_policy_version_id)
       AND leg.status = 'active' AND NEW.qualified_at >= leg.participation_starts_at
       AND leg.fulfilled_atomic / leg.amount_per_claim_atomic < leg.max_claims
       AND leg.funded_atomic - leg.reserved_atomic - leg.spent_atomic
         - leg.fulfilled_atomic - leg.refunded_atomic >= leg.amount_per_claim_atomic
     ORDER BY leg.leg_id FOR UPDATE
  LOOP
    credit_id := 'reward_credit_' || md5(
      NEW.account_id || chr(31) || asset_leg.leg_id || chr(31) || NEW.qualification_id
    );
    INSERT INTO reward_ledger_credits (
      credit_id,account_id,payout_persona_id,chain_id,token_address,amount_atomic,
      source_kind,source_reference,state,created_at,updated_at
    ) VALUES (
      credit_id,NEW.account_id,NEW.persona_id,asset_leg.chain_id,
      asset_leg.token_address,asset_leg.amount_per_claim_atomic,'asset_bonus',
      asset_leg.leg_id || ':' || NEW.qualification_id,'credited',decided_at,decided_at
    );
    INSERT INTO song_reward_bundle_claim_legs (
      account_id,offer_id,leg_id,amount_atomic,credit_id,state,created_at
    ) VALUES (
      NEW.account_id,candidate.offer_id,asset_leg.leg_id,
      asset_leg.amount_per_claim_atomic,credit_id,'credited',decided_at
    );
    UPDATE song_reward_offer_legs
       SET fulfilled_atomic = fulfilled_atomic + asset_leg.amount_per_claim_atomic,
           status = CASE
             WHEN (fulfilled_atomic + asset_leg.amount_per_claim_atomic)
                    / amount_per_claim_atomic >= max_claims
               OR funded_atomic - reserved_atomic - spent_atomic - refunded_atomic
                    - (fulfilled_atomic + asset_leg.amount_per_claim_atomic)
                    < amount_per_claim_atomic
             THEN 'exhausted' ELSE status END,
           participation_ends_at = CASE
             WHEN (fulfilled_atomic + asset_leg.amount_per_claim_atomic)
                    / amount_per_claim_atomic >= max_claims
               OR funded_atomic - reserved_atomic - spent_atomic - refunded_atomic
                    - (fulfilled_atomic + asset_leg.amount_per_claim_atomic)
                    < amount_per_claim_atomic
             THEN decided_at ELSE participation_ends_at END,
           updated_at = decided_at
     WHERE leg_id = asset_leg.leg_id;
  END LOOP;
  RETURN NEW;
END
$$;

-- Source: owner-admission-protocol-proposal-v3/account-audio-user-lock.successor.sql
CREATE OR REPLACE FUNCTION lock_account_audio_group_private_v1(p_original_account TEXT) RETURNS TEXT[]
 LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE account_ids TEXT[]; source_ids TEXT[]; canonical_count INTEGER; locked_account_id TEXT;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 -- No alias-row or user-row lock may precede topology. This table lock also
 -- stabilizes existing ordinary alias writers until their controlled outer
 -- exclusive-barrier admission is installed; it grants them no new authority.
 LOCK TABLE account_aliases IN SHARE MODE;
 WITH RECURSIVE group_members(account_id) AS (
  SELECT p_original_account UNION SELECT CASE WHEN a.source_user_id=g.account_id THEN a.canonical_user_id ELSE a.source_user_id END
  FROM group_members g JOIN account_aliases a ON (a.source_user_id=g.account_id OR a.canonical_user_id=g.account_id)
  WHERE (a.kind='alias' AND a.status='active') OR (a.kind='merge' AND a.status IN('finalizing','completed'))
 ) SELECT array_agg(account_id ORDER BY convert_to(account_id,'UTF8')) INTO account_ids FROM group_members;
 IF account_ids IS NULL OR cardinality(account_ids)>10000
  OR EXISTS(SELECT 1 FROM account_aliases WHERE source_user_id=ANY(account_ids) AND kind='merge' AND status='finalizing')
  OR EXISTS(SELECT 1 FROM unnest(account_ids) id WHERE NOT EXISTS(SELECT 1 FROM users WHERE user_id=id)) THEN
  RAISE EXCEPTION 'account audio group is unsettled'; END IF;
 SELECT count(*) INTO canonical_count FROM unnest(account_ids) id WHERE NOT EXISTS(SELECT 1 FROM account_aliases a
  WHERE a.source_user_id=id AND ((a.kind='alias' AND a.status='active') OR (a.kind='merge' AND a.status='completed')));
 IF canonical_count<>1 THEN RAISE EXCEPTION 'account audio group canonical closure differs'; END IF;
 PERFORM 1 FROM users WHERE user_id=ANY(account_ids) ORDER BY convert_to(user_id,'UTF8') FOR NO KEY UPDATE;
 SELECT array_agg(owner_id ORDER BY convert_to(owner_id,'UTF8')) INTO source_ids FROM participation_owners
  WHERE kind='account' AND account_id=ANY(account_ids);
 IF source_ids IS NULL OR cardinality(source_ids)<>cardinality(account_ids) THEN RAISE EXCEPTION 'account audio owner map incomplete'; END IF;
 PERFORM lock_learner_audio_sources_private_v1(source_ids);
 FOREACH locked_account_id IN ARRAY account_ids LOOP PERFORM pg_advisory_xact_lock(hashtextextended(locked_account_id,83000001)); END LOOP;
 RETURN source_ids;
END $$;

-- Source: owner-study-reward-producer-proposal-v2/reward-terms.sql
-- Concrete internal dependency on Root's ONE complete financial inventory.
-- No stub/default definition or runtime grant is supplied by this packet.
CREATE FUNCTION validate_guest_reward_terms_shape_private_v1(p_terms JSONB,p_community TEXT,p_post TEXT,
 p_audio BIGINT,p_lyrics BIGINT,p_qualification_policy TEXT,p_disclosure TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF p_terms IS NULL OR jsonb_typeof(p_terms) IS DISTINCT FROM 'object'
  OR EXISTS(SELECT 1 FROM unnest(ARRAY['community_id','post_id','disclosure_version','entry_cutoff_at','offer_id','original_drawing_id','policy_hash','pool_leg_id','qualification_policy_version_id','terms_hash']) field
   WHERE jsonb_typeof(p_terms->field) IS DISTINCT FROM 'string')
  OR jsonb_typeof(p_terms->'audio_revision') IS DISTINCT FROM 'number' OR jsonb_typeof(p_terms->'lyrics_revision') IS DISTINCT FROM 'number'
  OR p_audio IS NULL OR p_audio NOT BETWEEN 1 AND 9007199254740991 OR p_lyrics IS NULL OR p_lyrics NOT BETWEEN 1 AND 9007199254740991
  OR (SELECT array_agg(key ORDER BY key COLLATE "C") FROM jsonb_object_keys(p_terms) key)
   IS DISTINCT FROM ARRAY['audio_revision','community_id','disclosure_version','entry_cutoff_at','lyrics_revision','offer_id','original_drawing_id','policy_hash','pool_leg_id','post_id','qualification_policy_version_id','terms_hash']::TEXT[]
  OR p_terms->>'community_id' IS DISTINCT FROM p_community OR p_terms->>'post_id' IS DISTINCT FROM p_post
  OR p_terms->>'audio_revision' IS DISTINCT FROM p_audio::TEXT OR p_terms->>'lyrics_revision' IS DISTINCT FROM p_lyrics::TEXT
  OR p_terms->>'qualification_policy_version_id' IS DISTINCT FROM p_qualification_policy
  OR p_terms->>'disclosure_version' IS DISTINCT FROM p_disclosure
  OR p_terms->>'offer_id' !~ '^[^[:space:][:cntrl:]]{1,128}$'
  OR p_terms->>'pool_leg_id' !~ '^[^[:space:][:cntrl:]]{1,128}$'
  OR p_terms->>'original_drawing_id' !~ '^(0|[1-9][0-9]*)$'
  OR length(p_terms->>'original_drawing_id')>78
  OR p_terms->>'policy_hash' !~ '^[0-9a-f]{64}$' OR p_terms->>'terms_hash' !~ '^[0-9a-f]{64}$'
  OR p_terms->>'entry_cutoff_at' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$'
 THEN RAISE EXCEPTION 'exact immutable original reward terms required' USING ERRCODE='GP006'; END IF;
 -- Native cast rejects invalid calendar/time components rather than trusting regex.
 PERFORM (p_terms->>'entry_cutoff_at')::TIMESTAMPTZ;
END $$;

CREATE FUNCTION read_guest_owner_reward_terms_private_v1(p_community TEXT,p_post TEXT,p_audio BIGINT,p_lyrics BIGINT,
 p_disclosure TEXT,p_safety_margin INTEGER,p_original_leg TEXT DEFAULT NULL,p_original_drawing NUMERIC DEFAULT NULL)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE terms JSONB;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_safety_margin IS NULL OR p_safety_margin NOT BETWEEN 1 AND 86400 THEN RETURN NULL; END IF;
 IF p_disclosure IS NULL OR char_length(p_disclosure) NOT BETWEEN 1 AND 128
  OR p_audio IS NULL OR p_audio<1 OR p_lyrics IS NULL OR p_lyrics<1
  OR NOT can_guest_access_activity_song_v1(p_community,p_post)
 THEN RAISE EXCEPTION 'rewarded public source unavailable' USING ERRCODE='GP006'; END IF;
 SELECT jsonb_build_object('community_id',offer.community_id,'post_id',offer.post_id,
  'audio_revision',offer.audio_revision,'lyrics_revision',p_lyrics,'offer_id',offer.offer_id,
  'pool_leg_id',leg.leg_id,'original_drawing_id',drawing.drawing_id::TEXT,
  'qualification_policy_version_id','study_session_first_pass_v2@1','policy_hash',regexp_replace(policy.policy_hash,'^0x',''),
  'terms_hash',regexp_replace(leg.leg_terms_hash,'^0x',''),
  'entry_cutoff_at',to_char(drawing.entry_cutoff_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  'disclosure_version',p_disclosure)
 INTO terms FROM song_reward_offers offer JOIN song_reward_offer_legs leg USING(offer_id)
 JOIN megapot_pool_drawings drawing ON drawing.pool_leg_id=leg.leg_id
 JOIN policy_versions policy ON policy.community_id=offer.community_id AND policy.policy_version_id=offer.reward_policy_version_id
  AND policy.policy_purpose='reward' AND policy.uniqueness_authority_id=offer.offer_id
 JOIN LATERAL (SELECT observation.* FROM megapot_drawing_observations observation
  JOIN megapot_deployment_attestations att ON att.attestation_id=observation.attestation_id AND att.status='active'
  WHERE observation.attestation_id=leg.attestation_id AND observation.drawing_id=drawing.drawing_id
  ORDER BY observation.block_number DESC,observation.observation_id COLLATE "C" LIMIT 1) observed ON TRUE
 WHERE offer.community_id=p_community AND offer.post_id=p_post AND offer.audio_revision=p_audio
  AND offer.status='active' AND offer.starts_at<=clock_timestamp() AND offer.ends_at>clock_timestamp()
  AND leg.kind='megapot_pool' AND leg.status='active' AND leg.beneficiary_version=3
  AND drawing.beneficiary_version=3 AND drawing.status='entry_open'
  AND drawing.entry_cutoff_at>clock_timestamp() AND drawing.entry_cutoff_at=date_trunc('milliseconds',drawing.entry_cutoff_at) AND drawing.drawing_id>=leg.participation_starts_drawing_id
  AND clock_timestamp()>=leg.participation_starts_at AND 'study'=ANY(leg.eligible_activities)
  AND reward_leg_accepts_qualification(leg.leg_id,'study','study_session_first_pass_v2@1')
  AND observed.drawing_locked IS FALSE AND observed.expires_at>clock_timestamp()
  AND observed.drawing_time-make_interval(secs=>p_safety_margin)>clock_timestamp()
  AND observed.drawing_time-make_interval(secs=>leg.entry_cutoff_seconds)=drawing.entry_cutoff_at
  AND observed.ticket_price_atomic<=drawing.ticket_price_ceiling_atomic
  AND ((leg.funding_source='leg_budget' AND leg.funded_atomic-leg.reserved_atomic-leg.spent_atomic>=observed.ticket_price_atomic)
   OR (leg.funding_source='shared_sponsor_budget' AND EXISTS(SELECT 1 FROM platform_sponsorship_budgets budget
    WHERE budget.sponsor_account_id=leg.funder_account_id AND budget.chain_id=leg.chain_id AND budget.token_address=leg.token_address
     AND budget.funded_atomic+budget.winnings_credited_atomic-budget.reserved_atomic-budget.spent_atomic-budget.withdrawn_atomic>=observed.ticket_price_atomic)))
  AND (p_original_leg IS NULL OR leg.leg_id=p_original_leg)
  AND (p_original_drawing IS NULL OR drawing.drawing_id=p_original_drawing)
 ORDER BY drawing.drawing_id DESC,leg.leg_id COLLATE "C" LIMIT 1;
 IF terms IS NULL THEN RETURN NULL; END IF;
 PERFORM validate_guest_reward_terms_shape_private_v1(terms,p_community,p_post,p_audio,p_lyrics,'study_session_first_pass_v2@1',p_disclosure);
 RETURN terms;
END $$;

CREATE FUNCTION freeze_new_guest_study_reward_terms_private_v1(p_mode TEXT,p_accepted_terms JSONB,
 p_community TEXT,p_post TEXT,p_audio BIGINT,p_lyrics BIGINT,p_disclosure TEXT,p_safety_margin INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE original_drawing megapot_pool_drawings%ROWTYPE; terms JSONB;
BEGIN
 IF p_mode='practice_only' AND p_accepted_terms IS NULL THEN RETURN NULL; END IF;
 IF p_mode IS DISTINCT FROM 'megapot_guest_v1' OR p_accepted_terms IS NULL THEN
  RAISE EXCEPTION 'closed new lesson reward mode required' USING ERRCODE='GP006'; END IF;
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM validate_guest_reward_terms_shape_private_v1(p_accepted_terms,p_community,p_post,p_audio,p_lyrics,'study_session_first_pass_v2@1',p_disclosure);
 -- This is NEW-session-only. Existing original start outcome wins before this
 -- call; no renewed quote/disclosure/funding can rewrite a retained session.
 SELECT * INTO original_drawing FROM megapot_pool_drawings
  WHERE pool_leg_id=p_accepted_terms->>'pool_leg_id' AND drawing_id=(p_accepted_terms->>'original_drawing_id')::NUMERIC FOR SHARE;
 IF NOT FOUND OR original_drawing.beneficiary_version<>3 OR original_drawing.status<>'entry_open'
  OR original_drawing.entry_cutoff_at<=clock_timestamp() THEN
  RAISE EXCEPTION 'original prospective rewarded drawing unavailable' USING ERRCODE='GP006'; END IF;
 terms:=read_guest_owner_reward_terms_private_v1(p_community,p_post,p_audio,p_lyrics,p_disclosure,p_safety_margin,
  original_drawing.pool_leg_id,original_drawing.drawing_id);
 IF terms IS NULL OR terms IS DISTINCT FROM p_accepted_terms THEN
  RAISE EXCEPTION 'accepted original reward terms no longer match' USING ERRCODE='GP006'; END IF;
 RETURN terms;
END $$;

