  AND guest_disclosure_version IS NULL AND guest_disclosure_accepted IS NULL AND guest_reward_purchase_safety_deadline_at IS NULL)
 OR (participation_owner_kind='guest' AND account_id IS NULL AND persona_id IS NULL
