   OR (guest_reward_mode='megapot_guest_v1' AND guest_reward_terms IS NOT NULL
    AND jsonb_typeof(guest_reward_terms)='object' AND guest_disclosure_accepted IS TRUE AND guest_reward_purchase_safety_deadline_at IS NOT NULL)))
 ) IS TRUE);
CREATE FUNCTION guard_guest_study_reward_source_private_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF TG_OP='UPDATE' AND ROW(NEW.guest_reward_mode,NEW.guest_reward_terms,NEW.guest_start_operation_id,
  NEW.guest_disclosure_version,NEW.guest_disclosure_accepted,NEW.guest_reward_purchase_safety_deadline_at)
  IS DISTINCT FROM ROW(OLD.guest_reward_mode,OLD.guest_reward_terms,OLD.guest_start_operation_id,
   OLD.guest_disclosure_version,OLD.guest_disclosure_accepted,OLD.guest_reward_purchase_safety_deadline_at) THEN
  RAISE EXCEPTION 'original Study reward consent/terms cannot change' USING ERRCODE='GP005'; END IF;
 IF NEW.participation_owner_kind='guest' AND NEW.guest_reward_mode='megapot_guest_v1' THEN
  PERFORM validate_guest_reward_terms_shape_private_v1(NEW.guest_reward_terms,NEW.community_id,NEW.post_id,
   NEW.audio_revision,NEW.lyrics_revision,NEW.qualification_policy_revision,NEW.guest_disclosure_version);
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER study_guest_original_reward_source BEFORE INSERT OR UPDATE ON study_sessions_v2
 FOR EACH ROW EXECUTE FUNCTION guard_guest_study_reward_source_private_v1();

-- Version belongs to NEW leg creation, not a mutable runtime flag or client claim.
-- A managed prospective offer writer must explicitly insert3; ordinary writers
-- retain their historical default2. Existing created legs can never be promoted.
ALTER TABLE song_reward_offer_legs ADD COLUMN beneficiary_version SMALLINT NOT NULL DEFAULT 2 CHECK(beneficiary_version IN(2,3));
CREATE FUNCTION guard_reward_leg_beneficiary_version_private_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW.beneficiary_version IS DISTINCT FROM OLD.beneficiary_version THEN
  RAISE EXCEPTION 'original prospective leg beneficiary version immutable' USING ERRCODE='GP005'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER reward_leg_original_beneficiary_version BEFORE UPDATE ON song_reward_offer_legs
 FOR EACH ROW EXECUTE FUNCTION guard_reward_leg_beneficiary_version_private_v1();

