-- Source: owner-study-reward-producer-proposal-v2/choice-capture-schema.sql
-- Durable private choice grading command. No public/read/raw grants. The payload
-- and server's literal grade/reveal facts are accepted before finalizing COMMIT;
-- review scheduling remains a shared-engine operation over current locked review.
CREATE TABLE owner_captured_guest_choice_commands (
 command_id TEXT PRIMARY KEY CHECK(char_length(command_id) BETWEEN 1 AND 128),
 source_owner_id TEXT NOT NULL REFERENCES participation_owners(owner_id),
 operation_id TEXT NOT NULL UNIQUE,
 session_id TEXT NOT NULL,
 session_item_id TEXT NOT NULL REFERENCES study_session_items_v2(session_item_id),
 attempt_number INTEGER NOT NULL CHECK(attempt_number BETWEEN 1 AND 3),
 attempt_id TEXT NOT NULL CHECK(char_length(attempt_id) BETWEEN 1 AND 128),
 original_continuation_nonce TEXT NOT NULL CHECK(original_continuation_nonce ~ '^[0-9a-f]{64}$'),
 original_capture JSONB NOT NULL CHECK(jsonb_typeof(original_capture)='object'),
 original_grade JSONB NOT NULL CHECK(jsonb_typeof(original_grade)='object'),
 original_admission_result JSONB NOT NULL CHECK(jsonb_typeof(original_admission_result)='object'),
 state TEXT NOT NULL CHECK(state IN('reserved','completed')),
 result_snapshot JSONB,
 created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
 completed_at TIMESTAMPTZ,
 FOREIGN KEY(operation_id,source_owner_id) REFERENCES guest_participation_operations(operation_id,source_owner_id),
 FOREIGN KEY(session_id,source_owner_id) REFERENCES study_sessions_v2(session_id,participation_owner_id),
 CHECK((state='reserved' AND result_snapshot IS NULL AND completed_at IS NULL)
  OR (state='completed' AND result_snapshot IS NOT NULL AND completed_at IS NOT NULL))
);
CREATE UNIQUE INDEX guest_captured_choice_pending_slot ON owner_captured_guest_choice_commands(session_id,session_item_id,attempt_number) WHERE state='reserved';
CREATE FUNCTION retain_captured_guest_choice_private_v1() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF TG_OP IN('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'accepted original choice retained' USING ERRCODE='GP003'; END IF;
 IF TG_OP='UPDATE' AND ((to_jsonb(NEW)-ARRAY['state','result_snapshot','completed_at']) IS DISTINCT FROM
  (to_jsonb(OLD)-ARRAY['state','result_snapshot','completed_at']) OR OLD.state<>'reserved' OR NEW.state<>'completed') THEN
  RAISE EXCEPTION 'original choice provenance cannot change' USING ERRCODE='GP005'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER captured_guest_choice_retained BEFORE UPDATE OR DELETE ON owner_captured_guest_choice_commands
 FOR EACH ROW EXECUTE FUNCTION retain_captured_guest_choice_private_v1();
CREATE TRIGGER captured_guest_choice_retained_truncate BEFORE TRUNCATE ON owner_captured_guest_choice_commands
 FOR EACH STATEMENT EXECUTE FUNCTION retain_captured_guest_choice_private_v1();

-- Source: account-new-reward-preview-deadline-successor-171dc008/account-original-sources.sql
-- Private Account counterpart for Root's ONE complete owner-financial successor.
-- No ordinal, native execution, runtime grant, or retrospective promotion.
CREATE TABLE account_owner_reward_sources (
 source_owner_id TEXT NOT NULL,
 source_owner_kind TEXT NOT NULL DEFAULT 'account' CHECK(source_owner_kind='account'),
 session_kind TEXT NOT NULL CHECK(session_kind IN('study_legacy','study_v2','karaoke')),
 session_id TEXT NOT NULL,
 account_id TEXT NOT NULL,
 persona_id TEXT NOT NULL,
 community_id TEXT NOT NULL,
 post_id TEXT NOT NULL,
 audio_revision BIGINT NOT NULL CHECK(audio_revision>0),
 lyrics_revision BIGINT NOT NULL CHECK(lyrics_revision>0),
 qualification_policy_revision TEXT NOT NULL,
 original_terms JSONB NOT NULL CHECK(jsonb_typeof(original_terms)='object'),
 preview_terms_hash TEXT NOT NULL CHECK(preview_terms_hash ~ '^[0-9a-f]{64}$'),
 disclosure_version TEXT NOT NULL CHECK(disclosure_version !~ '[[:space:][:cntrl:]]' AND char_length(disclosure_version) BETWEEN 1 AND 128),
 disclosure_accepted BOOLEAN NOT NULL CHECK(disclosure_accepted IS TRUE),
 purchase_safety_deadline_at TIMESTAMPTZ NOT NULL,
 legacy_session_id TEXT REFERENCES study_sessions(session_id) DEFERRABLE INITIALLY DEFERRED,
 v2_session_id TEXT REFERENCES study_sessions_v2(session_id) DEFERRABLE INITIALLY DEFERRED,
 karaoke_session_id TEXT REFERENCES karaoke_sessions(session_id) DEFERRABLE INITIALLY DEFERRED,
 created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(source_owner_id,session_kind,session_id),
 UNIQUE(session_kind,session_id),
 UNIQUE(session_id),
 FOREIGN KEY(source_owner_id,source_owner_kind) REFERENCES participation_owners(owner_id,kind),
 FOREIGN KEY(source_owner_id,account_id) REFERENCES participation_owners(owner_id,account_id),
 FOREIGN KEY(account_id,persona_id) REFERENCES personas(account_id,persona_id),
 FOREIGN KEY(community_id,post_id) REFERENCES posts(community_id,post_id),
 CHECK(((session_kind='study_legacy' AND legacy_session_id=session_id AND v2_session_id IS NULL AND karaoke_session_id IS NULL)
  OR(session_kind='study_v2' AND legacy_session_id IS NULL AND v2_session_id=session_id AND karaoke_session_id IS NULL)
  OR(session_kind='karaoke' AND legacy_session_id IS NULL AND v2_session_id IS NULL AND karaoke_session_id=session_id)) IS TRUE)
);
CREATE TABLE account_owner_reward_operations (
 operation_id TEXT PRIMARY KEY CHECK(char_length(operation_id) BETWEEN 1 AND 128),
 source_owner_id TEXT NOT NULL,
 session_kind TEXT NOT NULL,
 session_id TEXT NOT NULL,
 operation_kind TEXT NOT NULL CHECK(operation_kind IN('study_answer','karaoke_finalize')),
 idempotency_key TEXT NOT NULL CHECK(char_length(idempotency_key) BETWEEN 1 AND 256),
 request_hash TEXT NOT NULL CHECK(request_hash ~ '^[0-9a-f]{64}$'),
 qualification_id TEXT NOT NULL UNIQUE CHECK(char_length(qualification_id) BETWEEN 1 AND 128),
 producer_kind TEXT NOT NULL CHECK(producer_kind IN('legacy_choice','v2_choice','v2_spoken','karaoke')),
 captured_payload JSONB NOT NULL CHECK(jsonb_typeof(captured_payload)='object'),
 original_admission_result JSONB CHECK(original_admission_result IS NULL OR (
  jsonb_typeof(original_admission_result)='object' AND original_admission_result->>'state'='entry_closed'
   AND original_admission_result-ARRAY['state']='{}'::JSONB) IS TRUE),
 state TEXT NOT NULL DEFAULT 'captured' CHECK(state IN('captured','completed')),
 completion_snapshot JSONB,
 created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
 completed_at TIMESTAMPTZ,
 UNIQUE(source_owner_id,session_kind,session_id,operation_kind,idempotency_key),
 UNIQUE(operation_id,source_owner_id),
 UNIQUE(operation_id,source_owner_id,session_kind,session_id,operation_kind,idempotency_key,request_hash),
 FOREIGN KEY(source_owner_id,session_kind,session_id) REFERENCES account_owner_reward_sources(source_owner_id,session_kind,session_id),
 CHECK((session_kind='study_legacy' AND operation_kind='study_answer' AND producer_kind='legacy_choice')
  OR(session_kind='study_v2' AND operation_kind='study_answer' AND producer_kind IN('v2_choice','v2_spoken'))
  OR(session_kind='karaoke' AND operation_kind='karaoke_finalize' AND producer_kind='karaoke')),
 CHECK(((state='captured' AND completion_snapshot IS NULL AND completed_at IS NULL)
  OR(state='completed' AND completion_snapshot IS NOT NULL AND jsonb_typeof(completion_snapshot)='object'
   AND completion_snapshot-ARRAY['answer','participation']='{}'::JSONB
   AND jsonb_typeof(completion_snapshot->'answer')='object' AND jsonb_typeof(completion_snapshot->'participation')='object'
   AND completed_at IS NOT NULL AND completed_at>=created_at)) IS TRUE)
);

-- The preview carries this SERVER hash; callers echo it, never reserialize it.
CREATE FUNCTION read_account_owner_reward_terms_private_v1(p_account TEXT,p_persona TEXT,p_activity TEXT,
 p_community TEXT,p_post TEXT,p_audio BIGINT,p_lyrics BIGINT,p_policy TEXT,p_disclosure TEXT,p_safety_margin INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE terms JSONB;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 -- Missing NEW-only server configuration suppresses the financial quote;
 -- ordinary practice availability is owned by its unchanged existing reader.
 IF p_safety_margin IS NULL OR p_safety_margin NOT BETWEEN 1 AND 86400 THEN RETURN NULL; END IF;
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_activity IS NULL OR p_activity NOT IN('study','karaoke') OR p_audio IS NULL OR p_audio<1 OR p_lyrics IS NULL OR p_lyrics<1
  OR p_policy IS NULL OR p_disclosure IS NULL OR p_disclosure ~ '[[:space:][:cntrl:]]'
  OR char_length(p_disclosure) NOT BETWEEN 1 AND 128
  OR NOT active_activity_persona(p_account,p_persona,p_community)
  OR NOT can_account_access_activity_song(p_account,p_community,p_post) THEN
  RAISE EXCEPTION 'actual Account reward preview authority unavailable' USING ERRCODE='GP006'; END IF;
 SELECT jsonb_build_object('community_id',offer.community_id,'post_id',offer.post_id,'audio_revision',offer.audio_revision,
  'lyrics_revision',p_lyrics,'offer_id',offer.offer_id,'pool_leg_id',leg.leg_id,'original_drawing_id',drawing.drawing_id::TEXT,
  'qualification_policy_version_id',p_policy,'policy_hash',regexp_replace(policy.policy_hash,'^0x',''),'terms_hash',regexp_replace(leg.leg_terms_hash,'^0x',''),
  'entry_cutoff_at',to_char(drawing.entry_cutoff_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'disclosure_version',p_disclosure)
 INTO terms FROM song_reward_offers offer JOIN song_reward_offer_legs leg USING(offer_id)
 JOIN megapot_pool_drawings drawing ON drawing.pool_leg_id=leg.leg_id
 JOIN policy_versions policy ON policy.community_id=offer.community_id AND policy.policy_version_id=offer.reward_policy_version_id
  AND policy.policy_purpose='reward' AND policy.uniqueness_authority_id=offer.offer_id
 JOIN LATERAL(SELECT observation.* FROM megapot_drawing_observations observation
  JOIN megapot_deployment_attestations att ON att.attestation_id=observation.attestation_id AND att.status='active'
  WHERE observation.attestation_id=leg.attestation_id AND observation.drawing_id=drawing.drawing_id
  ORDER BY observation.block_number DESC,observation.observation_id COLLATE "C" LIMIT 1) observed ON TRUE
 WHERE offer.community_id=p_community AND offer.post_id=p_post AND offer.audio_revision=p_audio
  AND offer.status='active' AND offer.starts_at<=clock_timestamp() AND offer.ends_at>clock_timestamp()
  AND leg.kind='megapot_pool' AND leg.status='active' AND leg.beneficiary_version=3
  AND drawing.beneficiary_version=3 AND drawing.status='entry_open'
  AND drawing.entry_cutoff_at>clock_timestamp() AND drawing.entry_cutoff_at=date_trunc('milliseconds',drawing.entry_cutoff_at)
  AND observed.drawing_time-make_interval(secs=>p_safety_margin)>clock_timestamp()
  AND drawing.drawing_id>=leg.participation_starts_drawing_id AND clock_timestamp()>=leg.participation_starts_at
  AND p_activity=ANY(leg.eligible_activities) AND reward_leg_accepts_qualification(leg.leg_id,p_activity,p_policy)
  AND observed.drawing_locked IS FALSE AND observed.expires_at>clock_timestamp()
  AND observed.drawing_time-make_interval(secs=>leg.entry_cutoff_seconds)=drawing.entry_cutoff_at
  AND observed.ticket_price_atomic<=drawing.ticket_price_ceiling_atomic
  AND((leg.funding_source='leg_budget' AND leg.funded_atomic-leg.reserved_atomic-leg.spent_atomic>=observed.ticket_price_atomic)
   OR(leg.funding_source='shared_sponsor_budget' AND EXISTS(SELECT 1 FROM platform_sponsorship_budgets budget
    WHERE budget.sponsor_account_id=leg.funder_account_id AND budget.chain_id=leg.chain_id AND budget.token_address=leg.token_address
     AND budget.funded_atomic+budget.winnings_credited_atomic-budget.reserved_atomic-budget.spent_atomic-budget.withdrawn_atomic>=observed.ticket_price_atomic)))
 ORDER BY drawing.drawing_id DESC,leg.leg_id COLLATE "C" LIMIT 1;
 IF terms IS NULL THEN RETURN NULL; END IF;
 PERFORM validate_guest_reward_terms_shape_private_v1(terms,p_community,p_post,p_audio,p_lyrics,p_policy,p_disclosure);
 RETURN jsonb_build_object('reward_terms',terms,'reward_preview_terms_hash',encode(sha256(convert_to(terms::TEXT,'UTF8')),'hex'));
END $$;

CREATE FUNCTION lock_account_owner_reward_birth_v1(p_account TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_id TEXT;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 SELECT owner_id INTO STRICT source_id FROM participation_owners WHERE kind='account' AND account_id=p_account;
 PERFORM lock_owner_participation_group_private_v1(source_id);
 PERFORM require_owner_accounting_ready_private_v1();
END $$;

-- Fields exist only on the explicit selected NEW-session path. All old inserts
-- leave them NULL, and NULL can NEVER be upgraded on a retained session.
DO $account_reward_source_columns$
DECLARE relation_name TEXT;
BEGIN
 FOREACH relation_name IN ARRAY ARRAY['study_sessions','study_sessions_v2','karaoke_sessions'] LOOP
  EXECUTE format('ALTER TABLE %I ADD COLUMN owner_reward_preview_hash TEXT,ADD COLUMN owner_reward_disclosure_version TEXT,ADD COLUMN owner_reward_disclosure_accepted BOOLEAN,ADD COLUMN owner_reward_purchase_safety_margin_seconds INTEGER',relation_name);
  EXECUTE format('ALTER TABLE %I ADD CONSTRAINT account_owner_reward_birth_shape CHECK((owner_reward_preview_hash IS NULL AND owner_reward_disclosure_version IS NULL AND owner_reward_disclosure_accepted IS NULL AND owner_reward_purchase_safety_margin_seconds IS NULL) OR(owner_reward_preview_hash IS NOT NULL AND owner_reward_preview_hash ~ ''^[0-9a-f]{64}$'' AND owner_reward_disclosure_version IS NOT NULL AND owner_reward_disclosure_accepted IS TRUE AND owner_reward_purchase_safety_margin_seconds IS NOT NULL AND owner_reward_purchase_safety_margin_seconds BETWEEN 1 AND 86400))',relation_name);
 END LOOP;
END $account_reward_source_columns$;
CREATE FUNCTION capture_new_account_reward_source_private_v1() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE family TEXT; source_id TEXT; policy_id TEXT; preview JSONB; terms JSONB; cutoff_seconds INTEGER; original_purchase_deadline TIMESTAMPTZ;
BEGIN
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.owner_reward_preview_hash,NEW.owner_reward_disclosure_version,NEW.owner_reward_disclosure_accepted,NEW.owner_reward_purchase_safety_margin_seconds)
   IS DISTINCT FROM ROW(OLD.owner_reward_preview_hash,OLD.owner_reward_disclosure_version,OLD.owner_reward_disclosure_accepted,OLD.owner_reward_purchase_safety_margin_seconds) THEN
   RAISE EXCEPTION 'original Account reward capture cannot be promoted or rewritten' USING ERRCODE='GP005'; END IF;
  IF OLD.owner_reward_preview_hash IS NOT NULL AND ROW(NEW.session_id,NEW.account_id,NEW.persona_id,NEW.community_id,NEW.post_id,NEW.audio_revision,NEW.lyrics_revision,
    coalesce(to_jsonb(NEW)->>'qualification_policy_revision',to_jsonb(NEW)->>'qualification_policy_version_id'))
   IS DISTINCT FROM ROW(OLD.session_id,OLD.account_id,OLD.persona_id,OLD.community_id,OLD.post_id,OLD.audio_revision,OLD.lyrics_revision,
    coalesce(to_jsonb(OLD)->>'qualification_policy_revision',to_jsonb(OLD)->>'qualification_policy_version_id')) THEN
   RAISE EXCEPTION 'original selected Account session provenance cannot change' USING ERRCODE='GP005'; END IF;
  RETURN NEW;
 END IF;
 IF EXISTS(SELECT 1 FROM account_owner_reward_sources src WHERE src.session_id=NEW.session_id
  AND src.session_kind<>CASE TG_TABLE_NAME WHEN 'study_sessions' THEN 'study_legacy' WHEN 'study_sessions_v2' THEN 'study_v2' WHEN 'karaoke_sessions' THEN 'karaoke' END) THEN
  RAISE EXCEPTION 'original selected source ID cannot be reused by another family' USING ERRCODE='GP005'; END IF;
 IF NEW.owner_reward_preview_hash IS NULL AND NEW.owner_reward_disclosure_version IS NULL AND NEW.owner_reward_disclosure_accepted IS NULL AND NEW.owner_reward_purchase_safety_margin_seconds IS NULL THEN RETURN NEW; END IF;
 IF NEW.owner_reward_preview_hash IS NULL OR NEW.owner_reward_disclosure_version IS NULL OR NEW.owner_reward_disclosure_accepted IS NOT TRUE
  OR NEW.owner_reward_purchase_safety_margin_seconds IS NULL OR NEW.owner_reward_purchase_safety_margin_seconds NOT BETWEEN 1 AND 86400
  OR NEW.account_id IS NULL OR NEW.persona_id IS NULL THEN RAISE EXCEPTION 'closed explicit Account reward consent required' USING ERRCODE='GP006'; END IF;
 IF TG_TABLE_NAME='study_sessions_v2' THEN
  IF NEW.participation_owner_kind IS DISTINCT FROM 'account' OR NEW.telegram_practice_only IS TRUE THEN
   RAISE EXCEPTION 'ordinary Account source required' USING ERRCODE='GP006'; END IF;
  family:='study_v2';policy_id:=NEW.qualification_policy_revision;
 ELSIF TG_TABLE_NAME='study_sessions' THEN family:='study_legacy';policy_id:=NEW.qualification_policy_version_id;
 ELSIF TG_TABLE_NAME='karaoke_sessions' THEN
  IF NEW.playback_kind IS DISTINCT FROM 'instrumental' OR NEW.qualification_policy_version_id IS DISTINCT FROM 'karaoke_qualification_v2@2' THEN
   RAISE EXCEPTION 'accepted scored instrumental source required' USING ERRCODE='GP006'; END IF;
  family:='karaoke';policy_id:=NEW.qualification_policy_version_id;
 ELSE RAISE EXCEPTION 'closed Account session family required' USING ERRCODE='GP006'; END IF;
 -- Native0082 resolves old Study qualifications by session ID across both
 -- Study families. A NEW selected source must not reuse another family ID.
 IF(family<>'study_legacy' AND EXISTS(SELECT 1 FROM study_sessions WHERE session_id=NEW.session_id))
  OR(family<>'study_v2' AND EXISTS(SELECT 1 FROM study_sessions_v2 WHERE session_id=NEW.session_id))
  OR(family<>'karaoke' AND EXISTS(SELECT 1 FROM karaoke_sessions WHERE session_id=NEW.session_id)) THEN
  RAISE EXCEPTION 'selected Account session ID already belongs to another family' USING ERRCODE='GP005'; END IF;
 SELECT owner_id INTO STRICT source_id FROM participation_owners WHERE kind='account' AND account_id=NEW.account_id;
 PERFORM read_locked_owner_participation_group_private_v1(source_id);
 preview:=read_account_owner_reward_terms_private_v1(NEW.account_id,NEW.persona_id,CASE WHEN family='karaoke' THEN 'karaoke' ELSE 'study' END,
  NEW.community_id,NEW.post_id,NEW.audio_revision,NEW.lyrics_revision,policy_id,NEW.owner_reward_disclosure_version,NEW.owner_reward_purchase_safety_margin_seconds);
 IF preview IS NULL OR preview->>'reward_preview_terms_hash' IS DISTINCT FROM NEW.owner_reward_preview_hash THEN
  RAISE EXCEPTION 'accepted original Account preview changed' USING ERRCODE='GP006'; END IF;
 terms:=preview->'reward_terms';
 SELECT entry_cutoff_seconds INTO STRICT cutoff_seconds FROM song_reward_offer_legs WHERE leg_id=terms->>'pool_leg_id';
 original_purchase_deadline:=(terms->>'entry_cutoff_at')::TIMESTAMPTZ+make_interval(secs=>cutoff_seconds-NEW.owner_reward_purchase_safety_margin_seconds);
 IF original_purchase_deadline<=clock_timestamp() THEN
  RAISE EXCEPTION 'new Account rewarded birth purchase window closed' USING ERRCODE='GP006'; END IF;
 -- Birth records a preview, not financial admission or a hold. Do not take a
 -- drawing lock before the genuine producer finishes its remaining media locks.
 -- The later independently acknowledged action hold locks this SAME drawing
 -- after the complete source/media/session group and rechecks its live cutoff.
 INSERT INTO account_owner_reward_sources(source_owner_id,session_kind,session_id,account_id,persona_id,community_id,post_id,audio_revision,lyrics_revision,
  qualification_policy_revision,original_terms,preview_terms_hash,disclosure_version,disclosure_accepted,purchase_safety_deadline_at,legacy_session_id,v2_session_id,karaoke_session_id)
 VALUES(source_id,family,NEW.session_id,NEW.account_id,NEW.persona_id,NEW.community_id,NEW.post_id,NEW.audio_revision,NEW.lyrics_revision,
  policy_id,terms,NEW.owner_reward_preview_hash,NEW.owner_reward_disclosure_version,TRUE,
  original_purchase_deadline,
  CASE WHEN family='study_legacy' THEN NEW.session_id END,CASE WHEN family='study_v2' THEN NEW.session_id END,CASE WHEN family='karaoke' THEN NEW.session_id END);
 RETURN NEW;
END $$;
DO $account_reward_birth_triggers$
DECLARE relation_name TEXT;
BEGIN
 FOREACH relation_name IN ARRAY ARRAY['study_sessions','study_sessions_v2','karaoke_sessions'] LOOP
  EXECUTE format('CREATE TRIGGER a02_account_owner_reward_birth BEFORE INSERT OR UPDATE ON %I FOR EACH ROW EXECUTE FUNCTION capture_new_account_reward_source_private_v1()',relation_name);
 END LOOP;
END $account_reward_birth_triggers$;

-- Source: owner-account-reward-producer-proposal-0cc7ef57/polymorphic-admission-journal.sql
-- Proposal-only protocol relation; no ordinal or runtime/public producer grant.
-- Original qualification/grade facts have independent durability. This journal
-- carries original-drawing uncertainty; it never creates a replacement drawing.
CREATE TABLE owner_participation_admission_operations (
 admission_id TEXT PRIMARY KEY CHECK(octet_length(admission_id) BETWEEN 1 AND 110),
 source_owner_id TEXT NOT NULL REFERENCES participation_owners(owner_id),
 source_owner_kind TEXT NOT NULL CHECK(source_owner_kind IN('account','guest')),
 source_session_kind TEXT NOT NULL CHECK(source_session_kind IN('study_legacy','study_v2','karaoke')),
 guest_main_operation_id TEXT,
 account_main_operation_id TEXT,
 guest_study_session_id TEXT,
 main_operation_id TEXT NOT NULL,
 operation_kind TEXT NOT NULL CHECK(operation_kind IN('study_answer','karaoke_finalize')),
 idempotency_key TEXT NOT NULL CHECK(char_length(idempotency_key) BETWEEN 1 AND 256),
 request_hash TEXT NOT NULL CHECK(request_hash ~ '^[0-9a-f]{64}$'),
 session_id TEXT NOT NULL,
 qualification_id TEXT NOT NULL CHECK(char_length(qualification_id) BETWEEN 1 AND 128),
 pool_leg_id TEXT NOT NULL,
 drawing_id NUMERIC(78,0) NOT NULL CHECK(drawing_id>=0),
 beneficiary_version SMALLINT NOT NULL DEFAULT 3 CHECK(beneficiary_version=3),
 terms_hash TEXT NOT NULL CHECK(terms_hash ~ '^[0-9a-f]{64}$'),
 policy_hash TEXT NOT NULL CHECK(policy_hash ~ '^[0-9a-f]{64}$'),
 qualification_policy_revision TEXT NOT NULL,
 entry_cutoff_at TIMESTAMPTZ NOT NULL,
 purchase_safety_deadline_at TIMESTAMPTZ NOT NULL,
 original_attempt_fence TEXT NOT NULL CHECK(original_attempt_fence ~ '^[0-9a-f]{64}$'),
 current_attempt_fence TEXT NOT NULL CHECK(current_attempt_fence ~ '^[0-9a-f]{64}$'),
 current_attempt_number INTEGER NOT NULL DEFAULT 1 CHECK(current_attempt_number>0),
 leaf_salt BYTEA NOT NULL CHECK(octet_length(leaf_salt)=32),
 state TEXT NOT NULL CHECK(state IN('pending','admitted','not_admitted','reconciled_no_commit')),
 result_snapshot JSONB,
 created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
 resolved_at TIMESTAMPTZ,
 UNIQUE(source_owner_id,source_session_kind,session_id,operation_kind,idempotency_key),
 UNIQUE(main_operation_id),
 FOREIGN KEY(source_owner_id,source_owner_kind) REFERENCES participation_owners(owner_id,kind),
 FOREIGN KEY(guest_main_operation_id,source_owner_id) REFERENCES guest_participation_operations(operation_id,source_owner_id),
 FOREIGN KEY(guest_study_session_id,source_owner_id,source_owner_kind) REFERENCES study_sessions_v2(session_id,participation_owner_id,participation_owner_kind),
 FOREIGN KEY(account_main_operation_id,source_owner_id,source_session_kind,session_id,operation_kind,idempotency_key,request_hash)
  REFERENCES account_owner_reward_operations(operation_id,source_owner_id,session_kind,session_id,operation_kind,idempotency_key,request_hash),
 CONSTRAINT owner_admission_polymorphic_source_closed CHECK((
  (source_owner_kind='guest' AND source_session_kind='study_v2' AND operation_kind='study_answer'
   AND guest_main_operation_id=main_operation_id AND guest_study_session_id=session_id AND account_main_operation_id IS NULL
   AND char_length(idempotency_key)<=128)
  OR(source_owner_kind='account' AND account_main_operation_id=main_operation_id AND guest_main_operation_id IS NULL AND guest_study_session_id IS NULL
   AND((source_session_kind IN('study_legacy','study_v2') AND operation_kind='study_answer')
    OR(source_session_kind='karaoke' AND operation_kind='karaoke_finalize')))
 ) IS TRUE),
 FOREIGN KEY(pool_leg_id,drawing_id,beneficiary_version) REFERENCES megapot_pool_drawings(pool_leg_id,drawing_id,beneficiary_version),
 CHECK((state='pending' AND result_snapshot IS NULL AND resolved_at IS NULL)
  OR (state<>'pending' AND result_snapshot IS NOT NULL AND resolved_at IS NOT NULL)),
 CONSTRAINT owner_admission_result_closed CHECK(result_snapshot IS NULL OR (
  jsonb_typeof(result_snapshot)='object' AND (
   (state='admitted' AND result_snapshot->>'state'='admitted'
    AND result_snapshot->>'share_id'=admission_id
    AND result_snapshot->>'original_drawing_id'=drawing_id::TEXT
    AND result_snapshot->>'pool_leg_id'=pool_leg_id
    AND result_snapshot-ARRAY['state','share_id','original_drawing_id','pool_leg_id']='{}'::JSONB)
   OR (state IN('not_admitted','reconciled_no_commit')
    AND result_snapshot->>'state' IN('entry_closed','unavailable','ineligible','already_participating','not_yet_qualified')
    AND result_snapshot-ARRAY['state']='{}'::JSONB)) ) IS TRUE)
);
CREATE TABLE owner_participation_admission_attempts (
 admission_id TEXT NOT NULL REFERENCES owner_participation_admission_operations(admission_id),
 attempt_number INTEGER NOT NULL CHECK(attempt_number>0),
 attempt_fence TEXT NOT NULL CHECK(attempt_fence ~ '^[0-9a-f]{64}$'),
 state TEXT NOT NULL CHECK(state IN('pending','admitted','not_admitted','authoritative_no_commit')),
 created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
 started_at TIMESTAMPTZ CHECK(started_at IS NULL OR started_at>=created_at),
 resolved_at TIMESTAMPTZ,
 PRIMARY KEY(admission_id,attempt_number), UNIQUE(admission_id,attempt_fence),
 CHECK((state='pending' AND resolved_at IS NULL) OR(state<>'pending' AND resolved_at IS NOT NULL))
);
ALTER TABLE owner_participation_admission_attempts ADD CONSTRAINT owner_admission_attempt_identity UNIQUE(admission_id,attempt_number,attempt_fence);

ALTER TABLE owner_participation_admission_operations ADD CONSTRAINT owner_admission_current_attempt_fk
 FOREIGN KEY(admission_id,current_attempt_number,current_attempt_fence)
 REFERENCES owner_participation_admission_attempts(admission_id,attempt_number,attempt_fence) DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX owner_admission_unresolved_drawing ON owner_participation_admission_operations(pool_leg_id,drawing_id) WHERE state='pending';
CREATE FUNCTION retain_owner_admission_operation_private_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF TG_OP='DELETE' OR TG_OP='TRUNCATE' THEN RAISE EXCEPTION 'original admission evidence is retained' USING ERRCODE='GP003'; END IF;
 IF TG_OP='UPDATE' AND (
  (to_jsonb(NEW)-ARRAY['state','result_snapshot','resolved_at','current_attempt_fence','current_attempt_number']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['state','result_snapshot','resolved_at','current_attempt_fence','current_attempt_number'])
  OR NOT((OLD.state='pending' AND NEW.state IN('admitted','not_admitted','reconciled_no_commit') AND NEW.current_attempt_fence=OLD.current_attempt_fence AND NEW.current_attempt_number=OLD.current_attempt_number)
   OR (OLD.state='reconciled_no_commit' AND NEW.state='pending' AND NEW.current_attempt_fence<>OLD.current_attempt_fence AND NEW.current_attempt_number=OLD.current_attempt_number+1))
  OR (NEW.resolved_at IS NOT NULL AND NEW.resolved_at<OLD.created_at)
 ) THEN RAISE EXCEPTION 'original admission identity/outcome cannot change' USING ERRCODE='GP005'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER owner_admission_identity_before_change BEFORE UPDATE OR DELETE ON owner_participation_admission_operations
 FOR EACH ROW EXECUTE FUNCTION retain_owner_admission_operation_private_v1();
CREATE TRIGGER owner_admission_retained_before_truncate BEFORE TRUNCATE ON owner_participation_admission_operations
 FOR EACH STATEMENT EXECUTE FUNCTION retain_owner_admission_operation_private_v1();

-- Invoke AFTER acquiring this exact drawing lock in freeze/purchase/recovery.
-- The separate prepare transaction COMMITTED pending BEFORE owning admission is
-- allowed to start. It therefore survives owning rollback/unknown COMMIT and
-- remains visible to this new READ COMMITTED statement AFTER drawing lock wait.
CREATE FUNCTION require_original_drawing_admission_resolved_private_v1(p_leg TEXT,p_drawing NUMERIC)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 IF EXISTS(SELECT 1 FROM owner_participation_admission_operations
  WHERE pool_leg_id=p_leg AND drawing_id=p_drawing AND state='pending') THEN
  RAISE EXCEPTION 'original drawing holds unresolved admission' USING ERRCODE='GP003'; END IF;
END $$;
CREATE FUNCTION retain_owner_admission_attempt_private_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF TG_OP IN('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'admission attempts are retained' USING ERRCODE='GP003'; END IF;
 IF TG_OP='UPDATE' AND((to_jsonb(NEW)-ARRAY['state','resolved_at','started_at']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','resolved_at','started_at'])
  OR NOT((OLD.state='pending' AND NEW.state='pending' AND OLD.started_at IS NULL AND NEW.started_at IS NOT NULL
       AND NEW.started_at>=OLD.created_at AND NEW.resolved_at IS NOT DISTINCT FROM OLD.resolved_at)
    OR(OLD.state='pending' AND NEW.state IN('admitted','not_admitted','authoritative_no_commit')
       AND NEW.started_at IS NOT DISTINCT FROM OLD.started_at AND NEW.resolved_at>=OLD.created_at))) THEN
  RAISE EXCEPTION 'admission attempt fact cannot change' USING ERRCODE='GP005'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER owner_admission_attempt_before_change BEFORE UPDATE OR DELETE ON owner_participation_admission_attempts
 FOR EACH ROW EXECUTE FUNCTION retain_owner_admission_attempt_private_v1();
CREATE TRIGGER owner_admission_attempt_before_truncate BEFORE TRUNCATE ON owner_participation_admission_attempts
 FOR EACH STATEMENT EXECUTE FUNCTION retain_owner_admission_attempt_private_v1();

CREATE FUNCTION require_megapot_drawing_admission_resolved_v1(p_leg TEXT,p_drawing NUMERIC)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF p_leg IS NULL OR p_drawing IS NULL OR p_drawing<0 THEN RAISE EXCEPTION 'exact original drawing required' USING ERRCODE='22023'; END IF;
 PERFORM require_original_drawing_admission_resolved_private_v1(p_leg,p_drawing);
END $$;

CREATE UNIQUE INDEX owner_admission_one_pending_session ON owner_participation_admission_operations(source_owner_id,source_session_kind,session_id) WHERE state='pending';

-- Source: owner-admission-protocol-proposal-v3/admission-operations.sql
CREATE FUNCTION owner_admission_private_receipt_v1(p_id TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE row owner_participation_admission_operations%ROWTYPE;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT row FROM owner_participation_admission_operations WHERE admission_id=p_id;
 RETURN jsonb_build_object('admissionId',row.admission_id,'sourceOwnerId',row.source_owner_id,
  'mainOperationId',row.main_operation_id,'operationKind',row.operation_kind,'idempotencyKey',row.idempotency_key,
  'requestHash',row.request_hash,'sessionId',row.session_id,'qualificationId',row.qualification_id,
  'poolLegId',row.pool_leg_id,'originalDrawingId',row.drawing_id::TEXT,
  'entryCutoffAt',to_char(row.entry_cutoff_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  'purchaseSafetyDeadlineAt',to_char(row.purchase_safety_deadline_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  'attemptFence',row.current_attempt_fence,'attemptNumber',row.current_attempt_number,'leafSaltHex',encode(row.leaf_salt,'hex'),
  'state',row.state,'result',row.result_snapshot);
END $$;
CREATE FUNCTION find_owner_admission_private_v1(p_source TEXT,p_main_operation TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE id TEXT;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT admission_id INTO id FROM owner_participation_admission_operations WHERE source_owner_id=p_source AND main_operation_id=p_main_operation;
 IF NOT FOUND THEN RETURN NULL; END IF;
 RETURN owner_admission_private_receipt_v1(id);
END $$;

-- Transaction1: acknowledged durable original-drawing hold BEFORE transaction2.
-- This is neither monetary admission nor a grade/provider transaction.

-- Source: owner-megapot-settlement-proposal-v2/snapshot-codec-private.sql
-- Source piece for Root's ONE complete financial successor. No ordinal/grant/activation.
-- Each function must be bound to participation_owners' actual owner/schema,
-- SECURITY DEFINER, pg_catalog/owned-schema/pg_temp and PUBLIC/all-other ACL revoke.
-- Exact accepted JS domain validId policy. PostgreSQL UTF8 text cannot
-- contain unpaired surrogates; scalar >FFFF counts TWO UTF16 code units.
-- Explicit ECMAScript whitespace, not locale-dependent POSIX [:space:].
CREATE FUNCTION owner_megapot_valid_id_private_v1(p_value TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER AS $$
DECLARE i INTEGER; code INTEGER; utf16_length INTEGER:=0;
BEGIN
 IF p_value IS NULL OR char_length(p_value)=0 THEN RETURN FALSE; END IF;
 FOR i IN 1..char_length(p_value) LOOP
  code:=ascii(substr(p_value,i,1));
  IF code<32 OR code=127 OR code IN(32,160,5760,8232,8233,8239,8287,12288,65279)
   OR code BETWEEN 8192 AND 8202 OR code BETWEEN 55296 AND 57343
  THEN RETURN FALSE; END IF;
  utf16_length:=utf16_length+(CASE WHEN code>65535 THEN 2 ELSE 1 END);
  IF utf16_length>128 THEN RETURN FALSE; END IF;
 END LOOP;
 RETURN TRUE;
END $$;
CREATE FUNCTION owner_megapot_lp_private_v1(p_value TEXT)
RETURNS BYTEA LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER AS $$
DECLARE body BYTEA;
BEGIN
 IF p_value IS NULL THEN RAISE EXCEPTION 'snapshot text absent' USING ERRCODE='GP003'; END IF;
 body:=convert_to(p_value,'UTF8');
 RETURN int4send(octet_length(body))||body;
END $$;
CREATE FUNCTION owner_megapot_u256_private_v1(p_value NUMERIC)
RETURNS BYTEA LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER AS $$
DECLARE value NUMERIC:=p_value; result BYTEA:=decode(repeat('00',32),'hex'); i INTEGER;
BEGIN
 IF value IS NULL OR value<>trunc(value) OR value<0 OR value>=power(2::NUMERIC,256)
 THEN RAISE EXCEPTION 'snapshot drawing encoding invalid' USING ERRCODE='GP003'; END IF;
 FOR i IN REVERSE 31..0 LOOP
  result:=set_byte(result,i,mod(value,256)::INTEGER); value:=trunc(value/256);
 END LOOP;
 RETURN result;
END $$;
CREATE FUNCTION build_owner_megapot_snapshot_private_v1(p_pool TEXT,p_drawing NUMERIC,p_terms TEXT,p_fallback BOOLEAN,p_leaves JSONB)
RETURNS JSONB LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER AS $$
DECLARE domain BYTEA:=convert_to('pirate.megapot-pool-beneficiary-snapshot.v3','UTF8');
 leaf JSONB; owner TEXT; kind TEXT; qualification TEXT; persona TEXT; salt BYTEA; ordering BYTEA; commitment BYTEA;
 private_leaves JSONB:='[]'; ordered JSONB; commitments JSONB; aggregate_bytes BYTEA:=''::BYTEA; snapshot_hash TEXT; n INTEGER;
BEGIN
 IF NOT owner_megapot_valid_id_private_v1(p_pool) OR p_terms !~ '^0x[0-9a-f]{64}$'
  OR p_terms IS NULL OR p_fallback IS NULL OR jsonb_typeof(p_leaves) IS DISTINCT FROM 'array' OR jsonb_array_length(p_leaves)=0
 THEN RAISE EXCEPTION 'snapshot input invalid' USING ERRCODE='GP003'; END IF;
 PERFORM owner_megapot_u256_private_v1(p_drawing);
 n:=jsonb_array_length(p_leaves);
 IF p_fallback AND n<>1 THEN RAISE EXCEPTION 'fallback snapshot requires one sponsor' USING ERRCODE='GP003'; END IF;
 FOR leaf IN SELECT value FROM jsonb_array_elements(p_leaves) LOOP
  IF jsonb_typeof(leaf) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(leaf))<>5
   OR (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys(leaf) k)
      IS DISTINCT FROM ARRAY['leafSalt','originalPersonaId','ownerId','ownerKind','qualificationId']::TEXT[]
   OR jsonb_typeof(leaf->'ownerId') IS DISTINCT FROM 'string' OR jsonb_typeof(leaf->'ownerKind') IS DISTINCT FROM 'string'
   OR jsonb_typeof(leaf->'qualificationId') IS DISTINCT FROM 'string' OR jsonb_typeof(leaf->'leafSalt') IS DISTINCT FROM 'string'
  THEN RAISE EXCEPTION 'snapshot leaf shape invalid' USING ERRCODE='GP003'; END IF;
  owner:=leaf->>'ownerId'; kind:=leaf->>'ownerKind'; qualification:=leaf->>'qualificationId'; persona:=leaf->>'originalPersonaId';
  IF NOT owner_megapot_valid_id_private_v1(owner) OR NOT owner_megapot_valid_id_private_v1(qualification)
   OR kind NOT IN('account','guest') OR leaf->>'leafSalt' !~ '^0x[0-9a-f]{64}$'
   OR (kind='account' AND (jsonb_typeof(leaf->'originalPersonaId') IS DISTINCT FROM 'string' OR NOT owner_megapot_valid_id_private_v1(persona)))
   OR (kind='guest' AND leaf->'originalPersonaId' IS DISTINCT FROM 'null'::JSONB)
   OR (p_fallback AND (kind<>'account' OR qualification<>'fallback')) OR (NOT p_fallback AND qualification='fallback')
   OR EXISTS(SELECT 1 FROM jsonb_array_elements(private_leaves) x WHERE x->>'ownerId'=owner OR x->>'qualificationId'=qualification)
  THEN RAISE EXCEPTION 'snapshot private identity invalid' USING ERRCODE='GP003'; END IF;
  salt:=decode(substr(leaf->>'leafSalt',3),'hex');
  ordering:=sha256(domain||decode('00','hex')||convert_to('order','UTF8')||owner_megapot_lp_private_v1(owner)
    ||owner_megapot_lp_private_v1(p_pool)||owner_megapot_u256_private_v1(p_drawing)||salt);
  commitment:=sha256(domain||decode('00','hex')||convert_to('leaf','UTF8')||ordering||owner_megapot_lp_private_v1(owner)
    ||owner_megapot_lp_private_v1(qualification)||owner_megapot_lp_private_v1(coalesce(persona,''))||salt);
  private_leaves:=private_leaves||jsonb_build_array(leaf||jsonb_build_object('orderKey','0x'||encode(ordering,'hex'),'leafCommitment','0x'||encode(commitment,'hex')));
 END LOOP;
 -- BYTEA ordering is raw unsigned bytes. Equal order hashes use original UTF8
 -- owner bytes; no locale order and no UNIQUE(snapshot_id,order_key) restriction.
 SELECT jsonb_agg(value ORDER BY decode(substr(value->>'orderKey',3),'hex'),convert_to(value->>'ownerId','UTF8'))
 INTO ordered FROM jsonb_array_elements(private_leaves);
 FOR leaf IN SELECT value FROM jsonb_array_elements(ordered) LOOP
  aggregate_bytes:=aggregate_bytes||decode(substr(leaf->>'leafCommitment',3),'hex');
 END LOOP;
 SELECT jsonb_agg(value->'leafCommitment') INTO commitments FROM jsonb_array_elements(ordered);
 snapshot_hash:='0x'||encode(sha256(domain||decode('00','hex')||owner_megapot_lp_private_v1(p_pool)
  ||owner_megapot_u256_private_v1(p_drawing)||decode(substr(p_terms,3),'hex')||owner_megapot_lp_private_v1('equal_v1')
  ||CASE WHEN p_fallback THEN decode('01','hex') ELSE decode('00','hex') END||int4send(n)||aggregate_bytes),'hex');
 RETURN jsonb_build_object('privateLeaves',ordered,'published',jsonb_build_object(
  'domain','pirate.megapot-pool-beneficiary-snapshot.v3','poolLegId',p_pool,'drawingId',trunc(p_drawing)::TEXT,'termsHash',p_terms,
  'algorithmVersion','equal_v1','fallback',p_fallback,'leafCount',n,'leafCommitments',commitments,'snapshotHash',snapshot_hash));
END $$;

CREATE FUNCTION require_owner_megapot_snapshot_private_v1(p_snapshot TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE s megapot_pool_beneficiary_snapshots%ROWTYPE; d megapot_pool_drawings%ROWTYPE; leg song_reward_offer_legs%ROWTYPE;
 leaves JSONB; expected JSONB; source_count INTEGER; actual_count INTEGER;
BEGIN
 SELECT * INTO STRICT s FROM megapot_pool_beneficiary_snapshots WHERE snapshot_id=p_snapshot;
 SELECT * INTO STRICT d FROM megapot_pool_drawings WHERE pool_leg_id=s.pool_leg_id AND drawing_id=s.drawing_id;
 SELECT * INTO STRICT leg FROM song_reward_offer_legs WHERE leg_id=s.pool_leg_id;
 IF s.beneficiary_version<>3 OR d.beneficiary_version<>3 OR s.domain<>'pirate.megapot-pool-beneficiary-snapshot.v3'
  OR d.snapshot_id IS DISTINCT FROM s.snapshot_id OR d.fallback_beneficiary IS DISTINCT FROM s.fallback
  OR s.algorithm_version<>'equal_v1' OR s.terms_hash IS DISTINCT FROM leg.leg_terms_hash
  OR EXISTS(SELECT 1 FROM megapot_pool_snapshot_private_leaves WHERE snapshot_id=p_snapshot)
 THEN RAISE EXCEPTION 'owner snapshot lineage invalid' USING ERRCODE='GP003'; END IF;
 SELECT count(*)::INTEGER INTO actual_count FROM megapot_owner_snapshot_leaves WHERE snapshot_id=p_snapshot;
 SELECT count(*)::INTEGER INTO source_count FROM megapot_owner_shares WHERE pool_leg_id=s.pool_leg_id AND drawing_id=s.drawing_id;
 IF d.frozen_share_count IS DISTINCT FROM source_count OR actual_count<>s.leaf_count
  OR EXISTS(SELECT 1 FROM megapot_owner_snapshot_leaves l WHERE snapshot_id=p_snapshot AND
    (l.pool_leg_id<>s.pool_leg_id OR l.drawing_id<>s.drawing_id OR l.beneficiary_version<>3 OR l.ordinal>=s.leaf_count))
 THEN RAISE EXCEPTION 'owner snapshot inventory invalid' USING ERRCODE='GP003'; END IF;
 IF s.fallback THEN
  IF source_count<>0 OR actual_count<>1 OR NOT EXISTS(
   SELECT 1 FROM megapot_owner_snapshot_leaves l JOIN participation_owners o ON o.owner_id=l.owner_id
   WHERE l.snapshot_id=p_snapshot AND l.ordinal=0 AND l.owner_kind='account' AND l.qualification_id='fallback'
    AND o.kind='account' AND o.account_id=l.original_account_id AND l.original_account_id=leg.fallback_beneficiary_account_id
    AND (leg.funding_source='shared_sponsor_budget' OR l.original_persona_id=leg.fallback_payout_persona_id)
    AND l.leaf_salt=d.owner_fallback_leaf_salt)
  THEN RAISE EXCEPTION 'owner fallback snapshot source invalid' USING ERRCODE='GP003'; END IF;
 ELSE
  IF actual_count<>source_count OR EXISTS(
   SELECT 1 FROM megapot_owner_snapshot_leaves l
   LEFT JOIN megapot_owner_shares sh ON sh.pool_leg_id=l.pool_leg_id AND sh.drawing_id=l.drawing_id AND sh.owner_id=l.owner_id AND sh.qualification_id=l.qualification_id
   LEFT JOIN activity_qualifications q ON q.qualification_id=sh.qualification_id
   LEFT JOIN participation_owners o ON o.owner_id=sh.owner_id
   WHERE l.snapshot_id=p_snapshot AND (sh.owner_id IS NULL OR l.leaf_salt IS DISTINCT FROM sh.leaf_salt
    OR q.participation_owner_id IS DISTINCT FROM l.owner_id OR q.participation_owner_kind IS DISTINCT FROM l.owner_kind
    OR o.kind IS DISTINCT FROM l.owner_kind OR q.account_id IS DISTINCT FROM l.original_account_id
    OR q.persona_id IS DISTINCT FROM l.original_persona_id OR (l.owner_kind='account' AND o.account_id IS DISTINCT FROM l.original_account_id)))
  THEN RAISE EXCEPTION 'owner snapshot share source invalid' USING ERRCODE='GP003'; END IF;
 END IF;
 SELECT jsonb_agg(jsonb_build_object('ownerId',l.owner_id,'ownerKind',l.owner_kind,'qualificationId',l.qualification_id,
  'originalPersonaId',l.original_persona_id,'leafSalt','0x'||encode(l.leaf_salt,'hex')) ORDER BY l.ordinal)
 INTO leaves FROM megapot_owner_snapshot_leaves l WHERE snapshot_id=p_snapshot;
 expected:=build_owner_megapot_snapshot_private_v1(s.pool_leg_id,s.drawing_id,s.terms_hash,s.fallback,leaves);
 IF s.published_artifact IS DISTINCT FROM expected->'published' OR s.snapshot_hash IS DISTINCT FROM expected#>>'{published,snapshotHash}'
  OR EXISTS(SELECT 1 FROM megapot_owner_snapshot_leaves l JOIN jsonb_array_elements(expected->'privateLeaves') WITH ORDINALITY x(value,n)
   ON l.ordinal=x.n-1 WHERE l.snapshot_id=p_snapshot AND (l.owner_id IS DISTINCT FROM x.value->>'ownerId'
    OR l.order_key IS DISTINCT FROM x.value->>'orderKey' OR l.leaf_commitment IS DISTINCT FROM x.value->>'leafCommitment'))
 THEN RAISE EXCEPTION 'owner snapshot bytes invalid' USING ERRCODE='GP003'; END IF;
END $$;

-- Source: retained-megapot-clock-window-proposal-0761d789/freeze-private.d887-clock-successor.sql
-- Assemble into ONE reviewed financial successor only. No ordinal/grant/activation.
-- The exact original domain constraint remains closed per persisted version.
-- Existing v2 rows keep their original domain; v3 has only the accepted domain.
DO $owner_snapshot_domain_version$
DECLARE name TEXT; matches INTEGER;
BEGIN
 SELECT count(*)::INTEGER,min(conname::TEXT) INTO matches,name FROM pg_constraint
 WHERE conrelid='megapot_pool_beneficiary_snapshots'::regclass AND contype='c'
  AND pg_get_constraintdef(oid)='CHECK ((domain = ''pirate.megapot-pool-beneficiary-snapshot.v2''::text))';
 IF matches<>1 THEN RAISE EXCEPTION 'expected original snapshot domain constraint unavailable' USING ERRCODE='GP003'; END IF;
 EXECUTE format('ALTER TABLE megapot_pool_beneficiary_snapshots DROP CONSTRAINT %I',name);
END $owner_snapshot_domain_version$;
ALTER TABLE megapot_pool_beneficiary_snapshots ADD CONSTRAINT owner_snapshot_domain_version_closed CHECK(
 (beneficiary_version=2 AND domain='pirate.megapot-pool-beneficiary-snapshot.v2')
 OR (beneficiary_version=3 AND domain='pirate.megapot-pool-beneficiary-snapshot.v3'));
ALTER TABLE megapot_pool_drawings ADD COLUMN owner_fallback_leaf_salt BYTEA;
-- Genuine prospective v3 birth stores this salt before any freeze/retry.
ALTER TABLE megapot_pool_drawings ADD CONSTRAINT owner_draw_fallback_salt_closed CHECK(
 (beneficiary_version=2 AND owner_fallback_leaf_salt IS NULL)
 OR (beneficiary_version=3 AND owner_fallback_leaf_salt IS NOT NULL AND octet_length(owner_fallback_leaf_salt)=32));
DO $owner_raw_order_tie_break$
DECLARE name TEXT; matches INTEGER;
BEGIN
 SELECT count(*)::INTEGER,min(conname::TEXT) INTO matches,name FROM pg_constraint
 WHERE conrelid='megapot_owner_snapshot_leaves'::regclass AND contype='u'
  AND pg_get_constraintdef(oid)='UNIQUE (snapshot_id, order_key)';
 IF matches<>1 THEN RAISE EXCEPTION 'expected disabled264 raw order uniqueness unavailable' USING ERRCODE='GP003'; END IF;
 EXECUTE format('ALTER TABLE megapot_owner_snapshot_leaves DROP CONSTRAINT %I',name);
END $owner_raw_order_tie_break$;
CREATE FUNCTION guard_owner_draw_salt_private_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW.owner_fallback_leaf_salt IS DISTINCT FROM OLD.owner_fallback_leaf_salt
 THEN RAISE EXCEPTION 'original prospective fallback salt is immutable' USING ERRCODE='GP003'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER owner_draw_salt_immutable BEFORE UPDATE ON megapot_pool_drawings
FOR EACH ROW EXECUTE FUNCTION guard_owner_draw_salt_private_v1();

CREATE FUNCTION close_owner_megapot_cutoff_private_v1(p_pool TEXT,p_draw NUMERIC,p_version BIGINT,p_status TEXT,p_reason TEXT,p_at TIMESTAMPTZ,p_count INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE row megapot_pool_drawings%ROWTYPE;
BEGIN
 IF p_status NOT IN('closed_no_entries','closed_unfunded','closed_fallback_ineligible','closed_fallback_unavailable','closed_fallback_ceiling')
 THEN RAISE EXCEPTION 'cutoff terminal outcome invalid' USING ERRCODE='GP003'; END IF;
 INSERT INTO megapot_pool_drawing_transitions(pool_leg_id,drawing_id,target_version,event_type,event)
 VALUES(p_pool,p_draw,p_version+1,'cutoff',jsonb_build_object('type','cutoff','outcome',p_status,'reason',p_reason));
 UPDATE megapot_pool_drawings SET status=p_status,version=p_version+1,frozen_share_count=p_count,
  fallback_beneficiary=FALSE,terminal_reason=p_reason,cutoff_frozen_at=p_at,terminal_at=p_at,updated_at=clock_timestamp()
 WHERE pool_leg_id=p_pool AND drawing_id=p_draw AND beneficiary_version=3 AND status='entry_open' AND version=p_version
 RETURNING * INTO row;
 IF NOT FOUND THEN RAISE EXCEPTION 'original cutoff state changed' USING ERRCODE='GP005'; END IF;
 RETURN jsonb_build_object('poolLegId',p_pool,'drawingId',trunc(p_draw)::TEXT,'version',row.version,'status',row.status,
  'frozenShareCount',row.frozen_share_count,'fallback',FALSE,'reservedTicketCostAtomic',row.reserved_ticket_cost_atomic::TEXT,
  'snapshotId',NULL,'snapshotHash',NULL,'terminalReason',p_reason);
END $$;

CREATE FUNCTION freeze_owner_megapot_drawing_private_v1(p_pool TEXT,p_draw NUMERIC,p_ceilings JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE d megapot_pool_drawings%ROWTYPE; leg song_reward_offer_legs%ROWTYPE; offer song_reward_offers%ROWTYPE;
 budget platform_sponsorship_budgets%ROWTYPE; decision reward_eligibility_decisions%ROWTYPE;
 actual_at TIMESTAMPTZ; source_count INTEGER; leaves JSONB; codec JSONB; snapshot TEXT; fallback BOOLEAN;
 sponsor TEXT; v_sponsor_kind TEXT; v_sponsor_day DATE; v_ticket_ceiling INTEGER; v_spend_ceiling NUMERIC;
 reserve NUMERIC; affected INTEGER; fallback_owner TEXT; fallback_persona TEXT;
 observations JSONB; public_hash TEXT; availability_hash TEXT;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'owner freeze requires READ COMMITTED' USING ERRCODE='GP003'; END IF;
 -- Existing topology precedes drawing/FK/funding locks; never acquire it late.
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 -- One row lock, then a fresh READ COMMITTED hold query, then source-set read.
 -- Never topology/owner/account locks after this lock; immutable FK KEY SHARE
 -- remains compatible with the producer group's NO KEY UPDATE locks.
 SELECT * INTO STRICT d FROM megapot_pool_drawings WHERE pool_leg_id=p_pool AND drawing_id=p_draw FOR UPDATE;
 IF d.beneficiary_version<>3 THEN RAISE EXCEPTION 'prospective owner draw required' USING ERRCODE='GP003'; END IF;
 PERFORM require_megapot_drawing_admission_resolved_v1(p_pool,p_draw);
 IF d.status<>'entry_open' THEN
  IF d.snapshot_id IS NOT NULL THEN
   PERFORM require_owner_megapot_snapshot_private_v1(d.snapshot_id);
   RETURN jsonb_build_object('poolLegId',p_pool,'drawingId',trunc(p_draw)::TEXT,'version',d.version,'status','cutoff_frozen',
    'frozenShareCount',d.frozen_share_count,'fallback',d.fallback_beneficiary,'reservedTicketCostAtomic',d.reserved_ticket_cost_atomic::TEXT,
    'snapshotId',d.snapshot_id,'snapshotHash',(SELECT snapshot_hash FROM megapot_pool_beneficiary_snapshots WHERE snapshot_id=d.snapshot_id),'terminalReason',d.terminal_reason);
  END IF;
  IF d.status IN('closed_no_entries','closed_unfunded','closed_fallback_ineligible','closed_fallback_unavailable','closed_fallback_ceiling') THEN
   RETURN jsonb_build_object('poolLegId',p_pool,'drawingId',trunc(p_draw)::TEXT,'version',d.version,'status',d.status,
    'frozenShareCount',d.frozen_share_count,'fallback',FALSE,'reservedTicketCostAtomic',d.reserved_ticket_cost_atomic::TEXT,
    'snapshotId',NULL,'snapshotHash',NULL,'terminalReason',d.terminal_reason);
  END IF;
  RAISE EXCEPTION 'draw cannot freeze from unresolved state' USING ERRCODE='GP005';
 END IF;
 IF p_ceilings IS NULL OR jsonb_typeof(p_ceilings) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p_ceilings))<>4
  OR (SELECT array_agg(k ORDER BY k COLLATE "C") FROM jsonb_object_keys(p_ceilings) k)
   IS DISTINCT FROM ARRAY['externalSpendAtomic','externalTickets','sharedSpendAtomic','sharedTickets']::TEXT[]
  OR jsonb_typeof(p_ceilings->'externalTickets') IS DISTINCT FROM 'number' OR jsonb_typeof(p_ceilings->'sharedTickets') IS DISTINCT FROM 'number'
  OR jsonb_typeof(p_ceilings->'externalSpendAtomic') IS DISTINCT FROM 'string' OR jsonb_typeof(p_ceilings->'sharedSpendAtomic') IS DISTINCT FROM 'string'
  OR p_ceilings->>'externalTickets' !~ '^[1-9][0-9]{0,9}$' OR p_ceilings->>'sharedTickets' !~ '^[1-9][0-9]{0,9}$'
  OR p_ceilings->>'externalSpendAtomic' !~ '^[1-9][0-9]{0,77}$' OR p_ceilings->>'sharedSpendAtomic' !~ '^[1-9][0-9]{0,77}$'
  OR (p_ceilings->>'externalTickets')::NUMERIC>2147483647 OR (p_ceilings->>'sharedTickets')::NUMERIC>2147483647
 THEN RAISE EXCEPTION 'trusted cutoff ceilings unavailable' USING ERRCODE='GP003'; END IF;
 SELECT * INTO STRICT leg FROM song_reward_offer_legs WHERE leg_id=p_pool FOR UPDATE;
 SELECT * INTO STRICT offer FROM song_reward_offers WHERE offer_id=leg.offer_id;
 actual_at:=clock_timestamp();
 IF actual_at<d.entry_cutoff_at THEN RAISE EXCEPTION 'original cutoff has not arrived' USING ERRCODE='GP005'; END IF;
 SELECT count(*)::INTEGER,jsonb_agg(jsonb_build_object('ownerId',sh.owner_id,'ownerKind',q.participation_owner_kind,
  'qualificationId',sh.qualification_id,'originalPersonaId',q.persona_id,'leafSalt','0x'||encode(sh.leaf_salt,'hex'))
  ORDER BY convert_to(sh.owner_id,'UTF8')) INTO source_count,leaves
 FROM megapot_owner_shares sh JOIN activity_qualifications q ON q.qualification_id=sh.qualification_id
 WHERE sh.pool_leg_id=p_pool AND sh.drawing_id=p_draw AND sh.beneficiary_version=3
  AND q.participation_owner_id=sh.owner_id;
 IF source_count<>(SELECT count(*) FROM megapot_owner_shares WHERE pool_leg_id=p_pool AND drawing_id=p_draw)
 THEN RAISE EXCEPTION 'committed owner source set differs' USING ERRCODE='GP003'; END IF;
 fallback:=source_count=0;
 IF fallback AND leg.empty_pool_policy='no_purchase' THEN
  RETURN close_owner_megapot_cutoff_private_v1(p_pool,p_draw,d.version,'closed_no_entries','no_entries',actual_at,0);
 END IF;
 IF fallback THEN
  SELECT * INTO decision FROM reward_eligibility_decisions WHERE leg_id=p_pool AND purpose='fallback_cutoff' AND drawing_id=p_draw
   ORDER BY decided_at DESC,eligibility_decision_id DESC LIMIT 1 FOR SHARE;
  actual_at:=clock_timestamp();
  IF NOT FOUND OR decision.outcome<>'eligible' OR decision.expires_at<=actual_at
  THEN RETURN close_owner_megapot_cutoff_private_v1(p_pool,p_draw,d.version,'closed_fallback_ineligible','fallback_ineligible',actual_at,0); END IF;
  SELECT o.owner_id,coalesce(leg.fallback_payout_persona_id,p.persona_id) INTO fallback_owner,fallback_persona
  FROM participation_owners o LEFT JOIN LATERAL(SELECT persona_id FROM personas WHERE account_id=o.account_id
    ORDER BY is_first_persona DESC,created_at,persona_id LIMIT 1) p ON TRUE
  WHERE o.kind='account' AND o.account_id=leg.fallback_beneficiary_account_id;
  IF fallback_owner IS NULL OR fallback_persona IS NULL OR decision.account_id IS DISTINCT FROM leg.fallback_beneficiary_account_id
   OR (leg.funding_source='leg_budget' AND decision.persona_id IS DISTINCT FROM fallback_persona)
  THEN RETURN close_owner_megapot_cutoff_private_v1(p_pool,p_draw,d.version,'closed_fallback_ineligible','fallback_source_unavailable',actual_at,0); END IF;
  IF NOT EXISTS(SELECT 1 FROM posts WHERE community_id=offer.community_id AND post_id=offer.post_id
   AND post_type='song' AND status='published' AND visibility='public')
  THEN RETURN close_owner_megapot_cutoff_private_v1(p_pool,p_draw,d.version,'closed_fallback_unavailable','fallback_unavailable',actual_at,0); END IF;
  SELECT jsonb_agg(to_jsonb(latest)||jsonb_build_object('activity_key',requested.activity_key) ORDER BY requested.ordinal)
  INTO observations FROM unnest(leg.eligible_activities) WITH ORDINALITY requested(activity_key,ordinal)
  LEFT JOIN LATERAL(SELECT availability_observation_id,state,observed_at,expires_at FROM reward_activity_availability_observations
    WHERE community_id=offer.community_id AND post_id=offer.post_id AND audio_revision=offer.audio_revision
     AND activity_key=requested.activity_key ORDER BY observed_at DESC,availability_observation_id DESC LIMIT 1) latest ON TRUE;
  IF observations IS NULL OR jsonb_array_length(observations)<>cardinality(leg.eligible_activities) OR EXISTS(
   SELECT 1 FROM jsonb_array_elements(observations) x WHERE x->>'availability_observation_id' IS NULL OR x->>'state'<>'available'
    OR (x->>'observed_at')::TIMESTAMPTZ>actual_at OR (x->>'expires_at')::TIMESTAMPTZ<=actual_at)
  THEN RETURN close_owner_megapot_cutoff_private_v1(p_pool,p_draw,d.version,'closed_fallback_unavailable','fallback_unavailable',actual_at,0); END IF;
  leaves:=jsonb_build_array(jsonb_build_object('ownerId',fallback_owner,'ownerKind','account','qualificationId','fallback',
   'originalPersonaId',fallback_persona,'leafSalt','0x'||encode(d.owner_fallback_leaf_salt,'hex')));
 END IF;
 reserve:=leg.max_ticket_price_atomic; sponsor:=leg.funder_account_id;
 IF leg.funding_source='leg_budget' THEN
  IF leg.funded_atomic-leg.reserved_atomic-leg.spent_atomic-leg.fulfilled_atomic-leg.refunded_atomic<reserve
  THEN RETURN close_owner_megapot_cutoff_private_v1(p_pool,p_draw,d.version,'closed_unfunded','insufficient_budget',actual_at,source_count); END IF;
 ELSE
  SELECT * INTO budget FROM platform_sponsorship_budgets WHERE sponsor_account_id=sponsor AND chain_id=leg.chain_id AND token_address=leg.token_address FOR UPDATE;
  actual_at:=clock_timestamp();
  IF NOT FOUND THEN RETURN close_owner_megapot_cutoff_private_v1(p_pool,p_draw,d.version,'closed_unfunded','sponsor_budget_missing',actual_at,source_count); END IF;
  IF budget.funded_atomic+budget.winnings_credited_atomic-budget.reserved_atomic-budget.spent_atomic-budget.withdrawn_atomic<reserve
  THEN RETURN close_owner_megapot_cutoff_private_v1(p_pool,p_draw,d.version,'closed_unfunded','sponsor_budget_exhausted',actual_at,source_count); END IF;
 END IF;
 v_sponsor_day:=(actual_at AT TIME ZONE 'UTC')::DATE;
 IF leg.funding_source='shared_sponsor_budget' OR fallback THEN
  v_sponsor_kind:=CASE WHEN leg.funding_source='shared_sponsor_budget' THEN 'shared_platform' ELSE 'external_fallback' END;
  v_ticket_ceiling:=(p_ceilings->>(CASE WHEN v_sponsor_kind='shared_platform' THEN 'sharedTickets' ELSE 'externalTickets' END))::INTEGER;
  v_spend_ceiling:=(p_ceilings->>(CASE WHEN v_sponsor_kind='shared_platform' THEN 'sharedSpendAtomic' ELSE 'externalSpendAtomic' END))::NUMERIC;
  INSERT INTO sponsor_daily_ticket_totals(sponsor_account_id,sponsor_day,sponsor_kind,ticket_ceiling,spend_ceiling_atomic)
   VALUES(sponsor,v_sponsor_day,v_sponsor_kind,v_ticket_ceiling,v_spend_ceiling) ON CONFLICT(sponsor_account_id,sponsor_day,sponsor_kind) DO NOTHING;
  UPDATE sponsor_daily_ticket_totals SET reserved_ticket_count=reserved_ticket_count+1,reserved_spend_atomic=reserved_spend_atomic+reserve,updated_at=clock_timestamp()
   WHERE sponsor_account_id=sponsor AND sponsor_day=v_sponsor_day AND sponsor_kind=v_sponsor_kind
    AND sponsor_daily_ticket_totals.ticket_ceiling=v_ticket_ceiling
    AND spend_ceiling_atomic=v_spend_ceiling AND confirmed_ticket_count+reserved_ticket_count-released_ticket_count+1<=sponsor_daily_ticket_totals.ticket_ceiling
    AND confirmed_spend_atomic+reserved_spend_atomic-released_spend_atomic+reserve<=spend_ceiling_atomic;
  GET DIAGNOSTICS affected=ROW_COUNT;
  actual_at:=clock_timestamp();
  IF (actual_at AT TIME ZONE 'UTC')::DATE<>v_sponsor_day THEN
   RAISE EXCEPTION 'cutoff sponsor day changed during reservation wait' USING ERRCODE='GP005'; END IF;
  IF affected<>1 THEN RETURN close_owner_megapot_cutoff_private_v1(p_pool,p_draw,d.version,
   CASE WHEN v_sponsor_kind='external_fallback' THEN 'closed_fallback_ceiling' ELSE 'closed_unfunded' END,'sponsor_daily_ceiling',actual_at,source_count); END IF;
 END IF;
 IF leg.funding_source='leg_budget' THEN
  UPDATE song_reward_offer_legs SET reserved_atomic=reserved_atomic+reserve,updated_at=clock_timestamp() WHERE leg_id=p_pool
   AND funded_atomic-reserved_atomic-spent_atomic-fulfilled_atomic-refunded_atomic>=reserve;
 ELSE
  UPDATE platform_sponsorship_budgets SET reserved_atomic=reserved_atomic+reserve,updated_at=clock_timestamp()
   WHERE sponsor_account_id=sponsor AND chain_id=leg.chain_id AND token_address=leg.token_address
    AND funded_atomic+winnings_credited_atomic-reserved_atomic-spent_atomic-withdrawn_atomic>=reserve;
  GET DIAGNOSTICS affected=ROW_COUNT;
  IF affected<>1 THEN RAISE EXCEPTION 'cutoff funding changed' USING ERRCODE='GP005'; END IF;
  INSERT INTO platform_sponsorship_budget_entries(budget_entry_id,sponsor_account_id,entry_kind,amount_atomic,source_reference,balance_hash)
   VALUES('owner_reserve_'||encode(sha256(owner_megapot_lp_private_v1(p_pool)||owner_megapot_u256_private_v1(p_draw)),'hex'),sponsor,
    'purchase_reserved',reserve,p_pool||':'||trunc(p_draw)::TEXT,
    encode(sha256(convert_to(jsonb_build_object('domain','pirate.owner-cutoff-sponsorship.v3','sponsor',sponsor,
     'pool',p_pool,'drawing',trunc(p_draw)::TEXT,'reserved',(budget.reserved_atomic+reserve)::TEXT,'funded',budget.funded_atomic::TEXT,
     'winnings',budget.winnings_credited_atomic::TEXT,'spent',budget.spent_atomic::TEXT,'withdrawn',budget.withdrawn_atomic::TEXT)::TEXT,'UTF8')),'hex'));
 END IF;
 GET DIAGNOSTICS affected=ROW_COUNT;
 IF affected<>1 THEN RAISE EXCEPTION 'cutoff funding changed' USING ERRCODE='GP005'; END IF;
 -- Last funding/daily waits are now over. Refusal rolls back EVERY reserve,
 -- daily counter and sponsorship entry in this owning transaction. Never write
 -- a snapshot or expiry witness using the earlier pre-wait time.
 actual_at:=clock_timestamp();
 IF (leg.funding_source='shared_sponsor_budget' OR fallback)
  AND (actual_at AT TIME ZONE 'UTC')::DATE<>v_sponsor_day
 THEN RAISE EXCEPTION 'cutoff sponsor day changed after funding wait' USING ERRCODE='GP005'; END IF;
 IF fallback AND (decision.expires_at<=actual_at OR EXISTS(
  SELECT 1 FROM jsonb_array_elements(observations) x
   WHERE (x->>'observed_at')::TIMESTAMPTZ>actual_at OR (x->>'expires_at')::TIMESTAMPTZ<=actual_at))
 THEN RAISE EXCEPTION 'captured fallback evidence expired during funding wait' USING ERRCODE='GP005'; END IF;
 IF fallback THEN
  public_hash:=encode(sha256(convert_to(jsonb_build_object('community_id',offer.community_id,'post_id',offer.post_id,
   'audio_revision',offer.audio_revision,'status','published','visibility','public','checked_at',actual_at)::TEXT,'UTF8')),'hex');
  availability_hash:=encode(sha256(convert_to(observations::TEXT,'UTF8')),'hex');
  INSERT INTO megapot_fallback_cutoff_evidence(pool_leg_id,drawing_id,sponsor_account_id,payout_persona_id,eligibility_decision_id,
   sponsor_day,sponsor_kind,public_discovery_evidence_hash,availability_set_hash,checked_at)
  VALUES(p_pool,p_draw,sponsor,leg.fallback_payout_persona_id,decision.eligibility_decision_id,v_sponsor_day,v_sponsor_kind,public_hash,availability_hash,actual_at);
  INSERT INTO megapot_fallback_cutoff_activity_evidence(pool_leg_id,drawing_id,activity_key,availability_observation_id)
  SELECT p_pool,p_draw,x->>'activity_key',x->>'availability_observation_id' FROM jsonb_array_elements(observations) x;
 END IF;
 codec:=build_owner_megapot_snapshot_private_v1(p_pool,p_draw,leg.leg_terms_hash,fallback,leaves);
 snapshot:='megapot_snapshot_'||substr(codec#>>'{published,snapshotHash}',3);
 INSERT INTO megapot_pool_beneficiary_snapshots(snapshot_id,pool_leg_id,drawing_id,domain,terms_hash,algorithm_version,
  fallback,leaf_count,snapshot_hash,published_artifact,frozen_at,beneficiary_version)
 VALUES(snapshot,p_pool,p_draw,'pirate.megapot-pool-beneficiary-snapshot.v3',leg.leg_terms_hash,'equal_v1',fallback,
  jsonb_array_length(codec->'privateLeaves'),codec#>>'{published,snapshotHash}',codec->'published',actual_at,3);
 INSERT INTO megapot_owner_snapshot_leaves(snapshot_id,pool_leg_id,drawing_id,beneficiary_version,ordinal,owner_id,owner_kind,
  qualification_id,original_account_id,original_persona_id,leaf_salt,order_key,leaf_commitment)
 SELECT snapshot,p_pool,p_draw,3,x.n-1,x.value->>'ownerId',x.value->>'ownerKind',x.value->>'qualificationId',o.account_id,
  x.value->>'originalPersonaId',decode(substr(x.value->>'leafSalt',3),'hex'),x.value->>'orderKey',x.value->>'leafCommitment'
 FROM jsonb_array_elements(codec->'privateLeaves') WITH ORDINALITY x(value,n)
 JOIN participation_owners o ON o.owner_id=x.value->>'ownerId';
 INSERT INTO megapot_pool_drawing_transitions(pool_leg_id,drawing_id,target_version,event_type,event)
 VALUES(p_pool,p_draw,d.version+1,'cutoff',jsonb_build_object('type','cutoff','snapshot_hash',codec#>>'{published,snapshotHash}',
  'fallback',fallback,'share_count',source_count));
 UPDATE megapot_pool_drawings SET status='cutoff_frozen',version=d.version+1,reserved_ticket_cost_atomic=reserve,frozen_share_count=source_count,
  fallback_beneficiary=fallback,snapshot_id=snapshot,cutoff_frozen_at=actual_at,updated_at=clock_timestamp()
 WHERE pool_leg_id=p_pool AND drawing_id=p_draw AND version=d.version AND status='entry_open';
 IF NOT FOUND THEN RAISE EXCEPTION 'original freeze changed' USING ERRCODE='GP005'; END IF;
 PERFORM require_owner_megapot_snapshot_private_v1(snapshot);
 RETURN jsonb_build_object('poolLegId',p_pool,'drawingId',trunc(p_draw)::TEXT,'version',d.version+1,'status','cutoff_frozen',
  'frozenShareCount',source_count,'fallback',fallback,'reservedTicketCostAtomic',reserve::TEXT,'snapshotId',snapshot,
  'snapshotHash',codec#>>'{published,snapshotHash}','terminalReason',NULL);
END $$;

-- Source: owner-megapot-settlement-proposal-v2/commitment-private.sql
-- Private native leaves; Root full phase/ACL installer must bind before serving.
-- Signing/publication happens outside SQL. Only exact public commitments leave it.
CREATE FUNCTION project_owner_megapot_commitment_private_v1(p_pool TEXT,p_draw NUMERIC)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE d megapot_pool_drawings%ROWTYPE; s megapot_pool_beneficiary_snapshots%ROWTYPE; c megapot_pool_commitment_effects%ROWTYPE;
BEGIN
 SELECT * INTO STRICT d FROM megapot_pool_drawings WHERE pool_leg_id=p_pool AND drawing_id=p_draw;
 IF d.beneficiary_version<>3 OR d.snapshot_id IS NULL THEN RAISE EXCEPTION 'owner snapshot unavailable' USING ERRCODE='GP003'; END IF;
 PERFORM require_owner_megapot_snapshot_private_v1(d.snapshot_id);
 SELECT * INTO STRICT s FROM megapot_pool_beneficiary_snapshots WHERE snapshot_id=d.snapshot_id;
 SELECT * INTO c FROM megapot_pool_commitment_effects WHERE snapshot_id=s.snapshot_id;
 RETURN jsonb_build_object('poolLegId',p_pool,'drawingId',trunc(p_draw)::TEXT,'drawingVersion',d.version,
  'canPrepare',d.status='cutoff_frozen','snapshotId',s.snapshot_id,'snapshot',s.published_artifact,
  'progress',CASE WHEN c.commitment_effect_id IS NULL THEN NULL ELSE jsonb_build_object(
   'commitmentEffectId',c.commitment_effect_id,'payloadHash',c.payload_hash,'signingKeyId',c.signing_key_id,
   'signature',c.signature,'state',c.state,'preparedAt',c.prepared_at,'publishedAt',c.published_at,'publicReference',c.public_reference) END);
END $$;

CREATE FUNCTION read_owner_megapot_commitment_private_v1(p_pool TEXT,p_draw NUMERIC)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 RETURN project_owner_megapot_commitment_private_v1(p_pool,p_draw);
END $$;

CREATE FUNCTION prepare_owner_megapot_commitment_private_v1(p_pool TEXT,p_draw NUMERIC,p_snapshot TEXT,p_payload TEXT,p_hash TEXT,p_key TEXT,p_signature TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE d megapot_pool_drawings%ROWTYPE; s megapot_pool_beneficiary_snapshots%ROWTYPE; c megapot_pool_commitment_effects%ROWTYPE;
 id TEXT; prepared TIMESTAMPTZ;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'owner commitment requires READ COMMITTED' USING ERRCODE='GP003'; END IF;
 -- Existing topology precedes drawing/FK/funding locks; never acquire it late.
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT * INTO STRICT d FROM megapot_pool_drawings WHERE pool_leg_id=p_pool AND drawing_id=p_draw FOR UPDATE;
 IF d.beneficiary_version<>3 OR d.snapshot_id IS DISTINCT FROM p_snapshot
 THEN RAISE EXCEPTION 'original owner commitment source changed' USING ERRCODE='GP005'; END IF;
 PERFORM require_megapot_drawing_admission_resolved_v1(p_pool,p_draw);
 PERFORM require_owner_megapot_snapshot_private_v1(p_snapshot);
 SELECT * INTO STRICT s FROM megapot_pool_beneficiary_snapshots WHERE snapshot_id=p_snapshot;
 IF p_payload IS NULL OR p_payload::JSONB IS DISTINCT FROM s.published_artifact OR p_hash IS NULL
  OR p_hash !~ '^[0-9a-f]{64}$' OR encode(sha256(convert_to(p_payload,'UTF8')),'hex') IS DISTINCT FROM p_hash
  OR p_key IS NULL OR btrim(p_key)='' OR p_signature IS NULL OR btrim(p_signature)=''
 THEN RAISE EXCEPTION 'exact public commitment signature facts required' USING ERRCODE='GP003'; END IF;
 id:='megapot_commitment_'||p_hash;
 SELECT * INTO c FROM megapot_pool_commitment_effects WHERE snapshot_id=p_snapshot;
 IF FOUND THEN
  IF c.commitment_effect_id<>id OR c.payload_hash<>p_hash THEN RAISE EXCEPTION 'original commitment payload changed' USING ERRCODE='GP005'; END IF;
  RETURN project_owner_megapot_commitment_private_v1(p_pool,p_draw);
 END IF;
 IF d.status<>'cutoff_frozen' THEN RAISE EXCEPTION 'drawing is not frozen for commitment' USING ERRCODE='GP005'; END IF;
 prepared:=clock_timestamp();
 INSERT INTO megapot_pool_commitment_effects(commitment_effect_id,snapshot_id,payload_hash,signing_key_id,signature,state,prepared_at)
 VALUES(id,p_snapshot,p_hash,p_key,p_signature,'prepared',prepared);
 RETURN project_owner_megapot_commitment_private_v1(p_pool,p_draw);
END $$;

CREATE FUNCTION confirm_owner_megapot_commitment_private_v1(p_pool TEXT,p_draw NUMERIC,p_id TEXT,p_hash TEXT,p_reference TEXT,p_published TIMESTAMPTZ)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE d megapot_pool_drawings%ROWTYPE; c megapot_pool_commitment_effects%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION 'owner publication requires READ COMMITTED' USING ERRCODE='GP003'; END IF;
 -- Existing topology precedes drawing/FK/funding locks; never acquire it late.
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT * INTO STRICT d FROM megapot_pool_drawings WHERE pool_leg_id=p_pool AND drawing_id=p_draw FOR UPDATE;
 IF d.beneficiary_version<>3 OR (d.commitment_effect_id IS NOT NULL AND d.commitment_effect_id<>p_id)
 THEN RAISE EXCEPTION 'original commitment source required' USING ERRCODE='GP005'; END IF;
 PERFORM require_megapot_drawing_admission_resolved_v1(p_pool,p_draw);
 PERFORM require_owner_megapot_snapshot_private_v1(d.snapshot_id);
 SELECT * INTO STRICT c FROM megapot_pool_commitment_effects WHERE commitment_effect_id=p_id AND snapshot_id=d.snapshot_id FOR UPDATE;
 IF c.payload_hash IS DISTINCT FROM p_hash OR p_reference IS NULL OR btrim(p_reference)='' OR octet_length(p_reference)>2048
  OR p_published IS NULL OR p_published<c.prepared_at
 THEN RAISE EXCEPTION 'actual public publication result required' USING ERRCODE='GP005'; END IF;
 IF c.state='published' THEN
  IF c.public_reference IS DISTINCT FROM p_reference THEN RAISE EXCEPTION 'original publication reference differs' USING ERRCODE='GP005'; END IF;
  RETURN project_owner_megapot_commitment_private_v1(p_pool,p_draw);
 END IF;
 IF d.status<>'cutoff_frozen' THEN RAISE EXCEPTION 'original publication state changed' USING ERRCODE='GP005'; END IF;
 UPDATE megapot_pool_commitment_effects SET state='published',public_reference=p_reference,published_at=p_published
 WHERE commitment_effect_id=p_id AND state='prepared';
 INSERT INTO megapot_pool_drawing_transitions(pool_leg_id,drawing_id,target_version,event_type,event)
 VALUES(p_pool,p_draw,d.version+1,'commitment_published',jsonb_build_object('commitment_effect_id',p_id,'public_reference',p_reference));
 UPDATE megapot_pool_drawings SET status='committed',version=d.version+1,commitment_effect_id=p_id,updated_at=clock_timestamp()
 WHERE pool_leg_id=p_pool AND drawing_id=p_draw AND version=d.version AND status='cutoff_frozen';
 IF NOT FOUND THEN RAISE EXCEPTION 'original publication draw changed' USING ERRCODE='GP005'; END IF;
 RETURN project_owner_megapot_commitment_private_v1(p_pool,p_draw);
END $$;

-- Source: owner-megapot-settlement-proposal-v2/allocation-private.sql
-- Root-scoped successor: exact source families, no ordinal/runtime grant/activation.
-- Integrate atomically with the full financial closure, never after disabling264 guards alone.
ALTER TABLE megapot_allocation_batches
 ADD COLUMN zero_sweep_id TEXT REFERENCES megapot_drawing_sweeps(sweep_id),
 ALTER COLUMN claim_effect_id DROP NOT NULL,
 ADD CONSTRAINT owner_allocation_settlement_origin_closed CHECK(
  (beneficiary_version=2 AND claim_effect_id IS NOT NULL AND zero_sweep_id IS NULL)
  OR (beneficiary_version=3 AND
   ((net_winnings_atomic>0 AND claim_effect_id IS NOT NULL AND zero_sweep_id IS NULL)
    OR (net_winnings_atomic=0 AND claim_effect_id IS NULL AND zero_sweep_id IS NOT NULL))));
ALTER TABLE megapot_owner_allocations
 ADD COLUMN participant_credit_owner_id TEXT GENERATED ALWAYS AS(
  CASE WHEN allocation_kind='participant' THEN owner_id ELSE NULL END) STORED;
DO $source_exact_credit_fk$
DECLARE constraint_name TEXT; matches INTEGER;
BEGIN
 SELECT count(*)::INTEGER,min(conname::TEXT) INTO matches,constraint_name FROM pg_constraint
 WHERE conrelid='megapot_owner_allocations'::regclass AND contype='f'
  AND pg_get_constraintdef(oid) LIKE 'FOREIGN KEY (credit_id, owner_id, amount_atomic) REFERENCES %reward_ledger_credits%';
 IF matches<>1 THEN RAISE EXCEPTION 'expected disabled264 credit FK unavailable' USING ERRCODE='GP003'; END IF;
 EXECUTE format('ALTER TABLE megapot_owner_allocations DROP CONSTRAINT %I',constraint_name);
END $source_exact_credit_fk$;
ALTER TABLE megapot_owner_allocations
 ADD CONSTRAINT owner_allocation_credit_reference FOREIGN KEY(credit_id) REFERENCES reward_ledger_credits(credit_id) DEFERRABLE INITIALLY DEFERRED,
 ADD CONSTRAINT participant_allocation_owner_credit FOREIGN KEY(credit_id,participant_credit_owner_id,amount_atomic)
 REFERENCES reward_ledger_credits(credit_id,participation_owner_id,amount_atomic) DEFERRABLE INITIALLY DEFERRED;
-- External fallback deliberately retains account_v1/external_fallback and the
-- old ordinary reader/payout. The deferred native validator below proves exact
-- original Account/persona/source/amount; no participant claim is fabricated.

CREATE FUNCTION require_owner_megapot_allocation_private_v1(p_batch TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE b megapot_allocation_batches%ROWTYPE; d megapot_pool_drawings%ROWTYPE;
 s megapot_pool_beneficiary_snapshots%ROWTYPE; leg song_reward_offer_legs%ROWTYPE;
 n INTEGER; total NUMERIC; base NUMERIC; remainder NUMERIC; expected_batch TEXT; origin TEXT; preimage BYTEA; a_row megapot_owner_allocations%ROWTYPE; expected_credit TEXT;
BEGIN
 SELECT * INTO STRICT b FROM megapot_allocation_batches WHERE allocation_batch_id=p_batch;
 SELECT * INTO STRICT d FROM megapot_pool_drawings WHERE pool_leg_id=b.pool_leg_id AND drawing_id=b.drawing_id;
 SELECT * INTO STRICT s FROM megapot_pool_beneficiary_snapshots WHERE snapshot_id=b.snapshot_id;
 SELECT * INTO STRICT leg FROM song_reward_offer_legs WHERE leg_id=b.pool_leg_id;
 PERFORM require_owner_megapot_snapshot_private_v1(b.snapshot_id);
 IF b.beneficiary_version<>3 OR d.beneficiary_version<>3 OR s.beneficiary_version<>3
  OR b.state<>'credited' OR b.algorithm_version<>'equal_v1'
  OR b.snapshot_id IS DISTINCT FROM d.snapshot_id OR b.net_winnings_atomic IS DISTINCT FROM d.net_winnings_atomic
  OR EXISTS(SELECT 1 FROM megapot_allocations WHERE allocation_batch_id=p_batch)
 THEN RAISE EXCEPTION 'owner allocation lineage unavailable' USING ERRCODE='GP003'; END IF;
 IF b.net_winnings_atomic>0 THEN
  IF b.zero_sweep_id IS NOT NULL OR d.status<>'credited' OR d.allocation_batch_id IS DISTINCT FROM p_batch
   OR d.claim_effect_id IS DISTINCT FROM b.claim_effect_id OR NOT EXISTS(
    SELECT 1 FROM megapot_claim_effects c JOIN megapot_claim_receipt_evidence r ON r.claim_effect_id=c.claim_effect_id
     JOIN reward_chain_effects effect ON effect.effect_id=c.claim_effect_id
    WHERE c.claim_effect_id=b.claim_effect_id AND c.pool_leg_id=b.pool_leg_id AND c.drawing_id=b.drawing_id
     AND effect.state='confirmed' AND effect.effect_kind='winnings_claim' AND effect.receipt_status='success' AND c.received_atomic=b.net_winnings_atomic
     AND r.net_winnings_atomic=b.net_winnings_atomic AND r.transaction_hash=effect.transaction_hash
     AND r.attestation_id=c.attestation_id AND r.ticket_id=c.ticket_id AND c.attestation_id=leg.attestation_id
     AND c.ticket_id=d.ticket_id AND effect.chain_id=leg.chain_id AND r.receipt_hash=effect.receipt_hash
     AND r.block_number=effect.receipt_block_number AND r.block_hash=effect.receipt_block_hash)
  THEN RAISE EXCEPTION 'owner allocation lacks original confirmed custody receipt' USING ERRCODE='GP003'; END IF;
 ELSE
  IF b.claim_effect_id IS NOT NULL OR d.claim_effect_id IS NOT NULL OR EXISTS(SELECT 1 FROM megapot_claim_effects WHERE pool_leg_id=b.pool_leg_id AND drawing_id=b.drawing_id) OR d.status NOT IN('no_win','winnings_detected') OR NOT EXISTS(
   SELECT 1 FROM megapot_drawing_sweeps sw JOIN megapot_sweep_ticket_evidence ev USING(sweep_id)
    JOIN megapot_ticket_inventory ticket ON ticket.attestation_id=ev.attestation_id AND ticket.ticket_id=ev.ticket_id
   WHERE sw.sweep_id=b.zero_sweep_id AND sw.pool_leg_id=b.pool_leg_id AND sw.drawing_id=b.drawing_id
    AND sw.state='complete' AND sw.completed_at IS NOT NULL AND sw.ticket_count=1
    AND ev.attestation_id=sw.attestation_id AND ev.ticket_id=d.ticket_id AND ticket.pool_leg_id=b.pool_leg_id
    AND ticket.drawing_id=b.drawing_id AND ev.net_winnings_atomic=0
    AND ev.gross_winnings_atomic=ev.referral_accrual_atomic AND ev.gross_winnings_atomic=d.gross_winnings_atomic
    AND ((d.status='no_win' AND sw.winning_ticket_count=0 AND ev.tier_id IN(0,2) AND ticket.status='no_win')
     OR (d.status='winnings_detected' AND sw.winning_ticket_count=1 AND ev.tier_id NOT IN(0,2) AND ticket.status='custodied')))
  THEN RAISE EXCEPTION 'zero allocation lacks sealed original zero sweep' USING ERRCODE='GP003'; END IF;
 END IF;
 SELECT count(*)::INTEGER,coalesce(sum(amount_atomic),0) INTO n,total FROM megapot_owner_allocations WHERE allocation_batch_id=p_batch;
 base:=trunc(b.net_winnings_atomic/s.leaf_count); remainder:=mod(b.net_winnings_atomic,s.leaf_count);
 IF n<>s.leaf_count OR n<>b.allocation_count OR total<>b.net_winnings_atomic OR EXISTS(
  SELECT 1 FROM megapot_owner_allocations a LEFT JOIN megapot_owner_snapshot_leaves l
   ON l.snapshot_id=b.snapshot_id AND l.ordinal=a.ordinal AND l.owner_id=a.owner_id
  WHERE a.allocation_batch_id=p_batch AND (l.owner_id IS NULL OR a.snapshot_id<>b.snapshot_id OR a.beneficiary_version<>3
   OR a.amount_atomic<>base+(CASE WHEN a.ordinal<remainder THEN 1 ELSE 0 END)
   OR a.allocation_kind IS DISTINCT FROM (CASE WHEN NOT s.fallback THEN 'participant' WHEN leg.funding_source='leg_budget' THEN 'external_fallback' ELSE 'platform_sponsorship' END)))
 THEN RAISE EXCEPTION 'owner allocation does not conserve every frozen ordinal' USING ERRCODE='GP003'; END IF;
 origin:=CASE WHEN b.net_winnings_atomic=0 THEN b.zero_sweep_id ELSE b.claim_effect_id END;
 expected_batch:='owner_allocation_'||encode(sha256(convert_to('pirate.megapot-owner-allocation-batch.v3','UTF8')||decode('00','hex')
  ||owner_megapot_lp_private_v1(b.pool_leg_id)||owner_megapot_u256_private_v1(b.drawing_id)||owner_megapot_lp_private_v1(origin)),'hex');
 IF b.allocation_batch_id IS DISTINCT FROM expected_batch THEN RAISE EXCEPTION 'original allocation identity differs' USING ERRCODE='GP003'; END IF;
 preimage:=convert_to('pirate.megapot-owner-allocation.v3','UTF8')||decode('00','hex')||owner_megapot_lp_private_v1(b.allocation_batch_id)
  ||owner_megapot_lp_private_v1(b.pool_leg_id)||owner_megapot_u256_private_v1(b.drawing_id)||owner_megapot_lp_private_v1(b.snapshot_id)
  ||owner_megapot_lp_private_v1(origin)||owner_megapot_lp_private_v1(b.net_winnings_atomic::TEXT);
 FOR a_row IN SELECT * FROM megapot_owner_allocations WHERE allocation_batch_id=p_batch ORDER BY ordinal LOOP
  expected_credit:=CASE WHEN a_row.amount_atomic=0 OR a_row.allocation_kind='platform_sponsorship' THEN NULL ELSE
   'owner_credit_'||encode(sha256(convert_to('pirate.megapot-owner-allocation-credit.v3','UTF8')||decode('00','hex')
    ||owner_megapot_lp_private_v1(p_batch)||int4send(a_row.ordinal)||owner_megapot_lp_private_v1(a_row.owner_id)),'hex') END;
  IF a_row.credit_id IS DISTINCT FROM expected_credit THEN RAISE EXCEPTION 'original allocation credit identity differs' USING ERRCODE='GP003'; END IF;
  preimage:=preimage||int4send(a_row.ordinal)||owner_megapot_lp_private_v1(a_row.owner_id)
   ||owner_megapot_lp_private_v1(a_row.amount_atomic::TEXT)||owner_megapot_lp_private_v1(a_row.allocation_kind)||owner_megapot_lp_private_v1(coalesce(a_row.credit_id,''));
 END LOOP;
 IF b.allocation_hash IS DISTINCT FROM encode(sha256(preimage),'hex') THEN RAISE EXCEPTION 'original allocation bytes differ' USING ERRCODE='GP003'; END IF;
 IF EXISTS(
  SELECT 1 FROM megapot_owner_allocations a JOIN megapot_owner_snapshot_leaves l
   ON l.snapshot_id=a.snapshot_id AND l.ordinal=a.ordinal AND l.owner_id=a.owner_id
   LEFT JOIN reward_ledger_credits c ON c.credit_id=a.credit_id
   LEFT JOIN reward_credit_persona_bindings binding ON binding.credit_id=c.credit_id
  WHERE a.allocation_batch_id=p_batch AND
   ((a.amount_atomic=0 AND a.credit_id IS NOT NULL)
    OR (a.allocation_kind='platform_sponsorship' AND a.credit_id IS NOT NULL)
    OR (a.amount_atomic>0 AND a.allocation_kind='participant' AND
     (c.credit_id IS NULL OR c.identity_version<>'owner_v1' OR c.participation_owner_id IS DISTINCT FROM l.owner_id
      OR c.account_id IS NOT NULL OR c.payout_persona_id IS NOT NULL OR c.source_kind<>'megapot_allocation'
      OR c.source_reference<>p_batch||':'||a.ordinal::TEXT OR c.amount_atomic<>a.amount_atomic
      OR c.chain_id<>leg.chain_id OR c.token_address<>leg.token_address
      OR (l.owner_kind='account' AND (binding.credit_id IS NULL OR binding.owner_id<>l.owner_id OR binding.owner_kind<>'account'
       OR binding.account_id<>l.original_account_id OR binding.persona_id<>l.original_persona_id
       OR binding.binding_source<>'account_original' OR binding.selection_revision IS NOT NULL))
      OR (l.owner_kind='guest' AND binding.credit_id IS NOT NULL AND
       (binding.owner_id<>l.owner_id OR binding.owner_kind<>'guest' OR binding.binding_source<>'guest_claim'))))
    OR (a.amount_atomic>0 AND a.allocation_kind='external_fallback' AND
     (c.credit_id IS NULL OR l.owner_kind<>'account' OR c.identity_version<>'account_v1' OR c.participation_owner_id IS NOT NULL
      OR c.account_id IS DISTINCT FROM l.original_account_id OR c.payout_persona_id IS DISTINCT FROM l.original_persona_id
      OR c.source_kind<>'external_fallback' OR c.source_reference<>p_batch||':'||a.ordinal::TEXT
      OR c.amount_atomic<>a.amount_atomic OR c.chain_id<>leg.chain_id OR c.token_address<>leg.token_address
      OR binding.credit_id IS NOT NULL))))
 THEN RAISE EXCEPTION 'owner allocation credit identity/recipient source differs' USING ERRCODE='GP003'; END IF;
 IF s.fallback AND leg.funding_source='shared_sponsor_budget' AND b.net_winnings_atomic>0 AND NOT EXISTS(
  SELECT 1 FROM platform_sponsorship_budget_entries e JOIN megapot_owner_snapshot_leaves l ON l.snapshot_id=s.snapshot_id AND l.ordinal=0
  WHERE e.entry_kind='winnings_credited' AND e.source_reference=p_batch AND e.sponsor_account_id=l.original_account_id
   AND e.amount_atomic=b.net_winnings_atomic)
 THEN RAISE EXCEPTION 'platform fallback lacks sponsorship budget evidence' USING ERRCODE='GP003'; END IF;
END $$;

CREATE FUNCTION allocate_owner_megapot_winnings_private_v1(p_pool TEXT,p_drawing NUMERIC)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE d megapot_pool_drawings%ROWTYPE; s megapot_pool_beneficiary_snapshots%ROWTYPE; leg song_reward_offer_legs%ROWTYPE;
 batch megapot_allocation_batches%ROWTYPE; leaf megapot_owner_snapshot_leaves%ROWTYPE;
 budget platform_sponsorship_budgets%ROWTYPE; origin TEXT; zero_sweep TEXT; batch_id TEXT; allocation_hash TEXT;
 preimage BYTEA; base NUMERIC; remainder NUMERIC; amount NUMERIC; kind TEXT; credit TEXT; v_allocation_rows JSONB:='[]'; captured_at TIMESTAMPTZ;
BEGIN
 -- The final full closure owns this prerequisite; no disabled264 guard is
 -- removed or positive authority granted by this packet alone.
 IF current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION 'owner settlement requires READ COMMITTED' USING ERRCODE='GP003'; END IF;
 -- Existing topology precedes drawing/FK/funding locks; never acquire it late.
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT * INTO STRICT d FROM megapot_pool_drawings WHERE pool_leg_id=p_pool AND drawing_id=p_drawing FOR UPDATE;
 IF d.beneficiary_version<>3 THEN RAISE EXCEPTION 'owner settlement version mismatch' USING ERRCODE='GP003'; END IF;
 PERFORM require_megapot_drawing_admission_resolved_v1(p_pool,p_drawing);
 -- Replay is by the actual original drawing's unique committed batch, never a
 -- caller-selected replacement batch/owner/credit or a newly selected draw.
 SELECT * INTO batch FROM megapot_allocation_batches WHERE pool_leg_id=p_pool AND drawing_id=p_drawing;
 IF FOUND THEN
  PERFORM require_owner_megapot_allocation_private_v1(batch.allocation_batch_id);
  RETURN jsonb_build_object('allocationBatchId',batch.allocation_batch_id,'state','credited');
 END IF;
 SELECT * INTO STRICT s FROM megapot_pool_beneficiary_snapshots WHERE snapshot_id=d.snapshot_id;
 PERFORM require_owner_megapot_snapshot_private_v1(s.snapshot_id);
 SELECT * INTO STRICT leg FROM song_reward_offer_legs WHERE leg_id=p_pool FOR UPDATE;
 IF d.net_winnings_atomic>0 THEN
  IF d.status<>'claimed' OR NOT EXISTS(
   SELECT 1 FROM megapot_claim_effects c JOIN megapot_claim_receipt_evidence r ON r.claim_effect_id=c.claim_effect_id
    JOIN reward_chain_effects e ON e.effect_id=c.claim_effect_id
   WHERE c.claim_effect_id=d.claim_effect_id AND c.pool_leg_id=p_pool AND c.drawing_id=p_drawing 
    AND e.effect_kind='winnings_claim' AND e.receipt_status='success' AND c.received_atomic=d.net_winnings_atomic AND r.net_winnings_atomic=d.net_winnings_atomic AND e.state='confirmed'
    AND r.transaction_hash=e.transaction_hash AND r.attestation_id=c.attestation_id AND r.ticket_id=c.ticket_id
    AND c.attestation_id=leg.attestation_id AND c.ticket_id=d.ticket_id AND e.chain_id=leg.chain_id
    AND r.receipt_hash=e.receipt_hash AND r.block_number=e.receipt_block_number AND r.block_hash=e.receipt_block_hash)
  THEN RAISE EXCEPTION 'original confirmed custody receipt required' USING ERRCODE='GP003'; END IF;
  origin:=d.claim_effect_id;
 ELSIF d.net_winnings_atomic=0 THEN
  IF d.claim_effect_id IS NOT NULL OR EXISTS(SELECT 1 FROM megapot_claim_effects WHERE pool_leg_id=p_pool AND drawing_id=p_drawing) OR d.status NOT IN('no_win','winnings_detected')
  THEN RAISE EXCEPTION 'zero draw source unavailable' USING ERRCODE='GP003'; END IF;
  SELECT sw.sweep_id INTO STRICT zero_sweep FROM megapot_drawing_sweeps sw
   JOIN megapot_sweep_ticket_evidence ev USING(sweep_id)
   JOIN megapot_ticket_inventory ticket ON ticket.attestation_id=ev.attestation_id AND ticket.ticket_id=ev.ticket_id
   WHERE sw.pool_leg_id=p_pool AND sw.drawing_id=p_drawing AND sw.state='complete' AND sw.completed_at IS NOT NULL
    AND sw.ticket_count=1 AND ev.attestation_id=sw.attestation_id AND ev.ticket_id=d.ticket_id
    AND ticket.pool_leg_id=p_pool AND ticket.drawing_id=p_drawing AND ev.net_winnings_atomic=0
    AND ev.gross_winnings_atomic=ev.referral_accrual_atomic AND ev.gross_winnings_atomic=d.gross_winnings_atomic
    AND ((d.status='no_win' AND sw.winning_ticket_count=0 AND ev.tier_id IN(0,2) AND ticket.status='no_win')
     OR (d.status='winnings_detected' AND sw.winning_ticket_count=1 AND ev.tier_id NOT IN(0,2) AND ticket.status='custodied'));
  origin:=zero_sweep;
 ELSE RAISE EXCEPTION 'confirmed settlement amount absent' USING ERRCODE='GP003'; END IF;
 captured_at:=clock_timestamp();
 batch_id:='owner_allocation_'||encode(sha256(convert_to('pirate.megapot-owner-allocation-batch.v3','UTF8')||decode('00','hex')
  ||owner_megapot_lp_private_v1(p_pool)||owner_megapot_u256_private_v1(p_drawing)||owner_megapot_lp_private_v1(origin)),'hex');
 base:=trunc(d.net_winnings_atomic/s.leaf_count); remainder:=mod(d.net_winnings_atomic,s.leaf_count);
 kind:=CASE WHEN NOT s.fallback THEN 'participant' WHEN leg.funding_source='leg_budget' THEN 'external_fallback' ELSE 'platform_sponsorship' END;
 preimage:=convert_to('pirate.megapot-owner-allocation.v3','UTF8')||decode('00','hex')||owner_megapot_lp_private_v1(batch_id)
  ||owner_megapot_lp_private_v1(p_pool)||owner_megapot_u256_private_v1(p_drawing)||owner_megapot_lp_private_v1(s.snapshot_id)
  ||owner_megapot_lp_private_v1(origin)||owner_megapot_lp_private_v1(d.net_winnings_atomic::TEXT);
 FOR leaf IN SELECT * FROM megapot_owner_snapshot_leaves WHERE snapshot_id=s.snapshot_id ORDER BY ordinal LOOP
  amount:=base+(CASE WHEN leaf.ordinal<remainder THEN 1 ELSE 0 END);
  credit:=CASE WHEN amount=0 OR kind='platform_sponsorship' THEN NULL ELSE
   'owner_credit_'||encode(sha256(convert_to('pirate.megapot-owner-allocation-credit.v3','UTF8')||decode('00','hex')
    ||owner_megapot_lp_private_v1(batch_id)||int4send(leaf.ordinal)||owner_megapot_lp_private_v1(leaf.owner_id)),'hex') END;
  preimage:=preimage||int4send(leaf.ordinal)||owner_megapot_lp_private_v1(leaf.owner_id)
   ||owner_megapot_lp_private_v1(amount::TEXT)||owner_megapot_lp_private_v1(kind)||owner_megapot_lp_private_v1(coalesce(credit,''));
  v_allocation_rows:=v_allocation_rows||jsonb_build_array(jsonb_build_object('ordinal',leaf.ordinal,'ownerId',leaf.owner_id,'amountAtomic',amount::TEXT,'allocationKind',kind,'creditId',credit));
 END LOOP;
 allocation_hash:=encode(sha256(preimage),'hex');
 INSERT INTO megapot_allocation_batches(allocation_batch_id,pool_leg_id,drawing_id,snapshot_id,claim_effect_id,
  algorithm_version,net_winnings_atomic,allocation_count,allocation_hash,state,created_at,beneficiary_version,zero_sweep_id)
 VALUES(batch_id,p_pool,p_drawing,s.snapshot_id,d.claim_effect_id,'equal_v1',d.net_winnings_atomic,s.leaf_count,
  allocation_hash,'prepared',captured_at,3,zero_sweep);
 FOR leaf IN SELECT * FROM megapot_owner_snapshot_leaves WHERE snapshot_id=s.snapshot_id ORDER BY ordinal LOOP
  amount:=base+(CASE WHEN leaf.ordinal<remainder THEN 1 ELSE 0 END);
  credit:=v_allocation_rows->leaf.ordinal->>'creditId';
  IF amount>0 AND kind='participant' THEN
   INSERT INTO reward_ledger_credits(credit_id,account_id,payout_persona_id,chain_id,token_address,amount_atomic,
    source_kind,source_reference,state,identity_version,participation_owner_id)
   VALUES(credit,NULL,NULL,leg.chain_id,leg.token_address,amount,'megapot_allocation',batch_id||':'||leaf.ordinal::TEXT,
    'credited','owner_v1',leaf.owner_id);
  ELSIF amount>0 AND kind='external_fallback' THEN
   IF leaf.owner_kind<>'account' THEN RAISE EXCEPTION 'external sponsor must retain Account source' USING ERRCODE='GP003'; END IF;
   INSERT INTO reward_ledger_credits(credit_id,account_id,payout_persona_id,chain_id,token_address,amount_atomic,
    source_kind,source_reference,state,identity_version,participation_owner_id)
   VALUES(credit,leaf.original_account_id,leaf.original_persona_id,leg.chain_id,leg.token_address,amount,
    'external_fallback',batch_id||':'||leaf.ordinal::TEXT,'credited','account_v1',NULL);
  END IF;
  INSERT INTO megapot_owner_allocations(allocation_batch_id,snapshot_id,beneficiary_version,ordinal,owner_id,amount_atomic,allocation_kind,credit_id)
  VALUES(batch_id,s.snapshot_id,3,leaf.ordinal,leaf.owner_id,amount,kind,credit);
  IF amount>0 AND kind='participant' AND leaf.owner_kind='account' THEN
   INSERT INTO reward_credit_persona_bindings(credit_id,owner_id,owner_kind,account_id,persona_id,binding_source,selection_revision,bound_at)
   VALUES(credit,leaf.owner_id,'account',leaf.original_account_id,leaf.original_persona_id,'account_original',NULL,captured_at);
  END IF;
 END LOOP;
 IF kind='platform_sponsorship' AND d.net_winnings_atomic>0 THEN
  SELECT b.* INTO STRICT budget FROM platform_sponsorship_budgets b JOIN megapot_owner_snapshot_leaves l
   ON l.snapshot_id=s.snapshot_id AND l.ordinal=0 AND l.original_account_id=b.sponsor_account_id
   WHERE b.chain_id=leg.chain_id AND b.token_address=leg.token_address FOR UPDATE OF b;
  UPDATE platform_sponsorship_budgets SET winnings_credited_atomic=winnings_credited_atomic+d.net_winnings_atomic,updated_at=clock_timestamp()
   WHERE sponsor_account_id=budget.sponsor_account_id AND chain_id=budget.chain_id AND token_address=budget.token_address;
  -- The original private budget-entry shape requires a deterministic native
  -- balance hash. It carries no participant credit/claim/recipient authority.
  INSERT INTO platform_sponsorship_budget_entries(budget_entry_id,sponsor_account_id,entry_kind,amount_atomic,source_reference,balance_hash)
  VALUES('owner_sponsorship_'||allocation_hash,budget.sponsor_account_id,'winnings_credited',d.net_winnings_atomic,batch_id,
   encode(sha256(convert_to(jsonb_build_object('domain','pirate.platform-sponsorship-owner-balance.v3',
    'sponsor',budget.sponsor_account_id,'chain',budget.chain_id::TEXT,'token',budget.token_address,'funded',budget.funded_atomic::TEXT,
    'winnings',(budget.winnings_credited_atomic+d.net_winnings_atomic)::TEXT,'reserved',budget.reserved_atomic::TEXT,
    'spent',budget.spent_atomic::TEXT,'withdrawn',budget.withdrawn_atomic::TEXT)::TEXT,'UTF8')),'hex'));
 END IF;
 IF d.net_winnings_atomic>0 THEN
  INSERT INTO megapot_pool_drawing_transitions(pool_leg_id,drawing_id,target_version,event_type,event)
  VALUES(p_pool,p_drawing,d.version+1,'allocated',jsonb_build_object('allocation_batch_id',batch_id,'allocation_hash',allocation_hash));
  UPDATE megapot_pool_drawings SET status='allocated',version=d.version+1,allocation_batch_id=batch_id,updated_at=clock_timestamp()
   WHERE pool_leg_id=p_pool AND drawing_id=p_drawing AND version=d.version AND status='claimed';
  IF NOT FOUND THEN RAISE EXCEPTION 'original allocation draw changed' USING ERRCODE='GP005'; END IF;
 END IF;
 UPDATE megapot_allocation_batches SET state='credited',credited_at=captured_at WHERE allocation_batch_id=batch_id AND state='prepared';
 IF d.net_winnings_atomic>0 THEN
  INSERT INTO megapot_pool_drawing_transitions(pool_leg_id,drawing_id,target_version,event_type,event)
  VALUES(p_pool,p_drawing,d.version+2,'credited',jsonb_build_object('allocation_batch_id',batch_id));
  UPDATE megapot_pool_drawings SET status='credited',version=d.version+2,terminal_at=captured_at,updated_at=clock_timestamp()
   WHERE pool_leg_id=p_pool AND drawing_id=p_drawing AND version=d.version+1 AND status='allocated';
  IF NOT FOUND THEN RAISE EXCEPTION 'original credit draw changed' USING ERRCODE='GP005'; END IF;
 END IF;
 -- For sealed zero evidence the original no_win/winnings_detected draw and
 -- genuine ticket/claim state stay untouched. Zero does not fabricate receipts
 -- or mark a referral-claim operation paid/complete.
 PERFORM require_owner_megapot_allocation_private_v1(batch_id);
 RETURN jsonb_build_object('allocationBatchId',batch_id,'state','credited');
END $$;

-- Source: owner-megapot-settlement-proposal-v2/versioned-validators.sql
-- One complete successor ONLY. Exact retained0053 bodies below are unchanged after each new v3 branch.

CREATE OR REPLACE FUNCTION validate_megapot_beneficiary_snapshot() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  target_snapshot_id TEXT;
  snapshot_record megapot_pool_beneficiary_snapshots%ROWTYPE;
  drawing_record megapot_pool_drawings%ROWTYPE;
  leg_record song_reward_offer_legs%ROWTYPE;
  leaf_total INTEGER;
  share_total INTEGER;
  commitments JSONB;
BEGIN

  IF EXISTS(SELECT 1 FROM megapot_pool_beneficiary_snapshots s WHERE s.snapshot_id=NEW.snapshot_id AND s.beneficiary_version=3) THEN
    PERFORM require_owner_megapot_snapshot_private_v1(NEW.snapshot_id); RETURN NULL;
  END IF;
  target_snapshot_id := CASE
    WHEN TG_TABLE_NAME = 'megapot_pool_beneficiary_snapshots' THEN NEW.snapshot_id
    ELSE NEW.snapshot_id
  END;
  SELECT * INTO snapshot_record FROM megapot_pool_beneficiary_snapshots
   WHERE snapshot_id = target_snapshot_id;
  IF snapshot_record.snapshot_id IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT * INTO drawing_record FROM megapot_pool_drawings
   WHERE pool_leg_id = snapshot_record.pool_leg_id
     AND drawing_id = snapshot_record.drawing_id;
  SELECT * INTO leg_record FROM song_reward_offer_legs
   WHERE leg_id = snapshot_record.pool_leg_id;
  SELECT count(*), jsonb_agg(leaf_commitment ORDER BY ordinal)
    INTO leaf_total, commitments
    FROM megapot_pool_snapshot_private_leaves
   WHERE snapshot_id = snapshot_record.snapshot_id;
  SELECT count(*) INTO share_total FROM megapot_pool_shares
   WHERE pool_leg_id = snapshot_record.pool_leg_id
     AND drawing_id = snapshot_record.drawing_id;
  IF drawing_record.snapshot_id IS DISTINCT FROM snapshot_record.snapshot_id
     OR drawing_record.frozen_share_count IS DISTINCT FROM share_total
     OR snapshot_record.leaf_count <> leaf_total
     OR reward_json_contains_private_identity(snapshot_record.published_artifact)
     OR snapshot_record.published_artifact <> jsonb_build_object(
       'domain', snapshot_record.domain,
       'poolLegId', snapshot_record.pool_leg_id,
       'drawingId', snapshot_record.drawing_id::text,
       'termsHash', snapshot_record.terms_hash,
       'algorithmVersion', snapshot_record.algorithm_version,
       'fallback', snapshot_record.fallback,
       'leafCount', snapshot_record.leaf_count,
       'leafCommitments', commitments,
       'snapshotHash', snapshot_record.snapshot_hash
     ) THEN
    RAISE EXCEPTION 'Megapot beneficiary snapshot artifact is not exact';
  END IF;
  IF snapshot_record.fallback THEN
    IF share_total <> 0 OR snapshot_record.leaf_count <> 1
       OR drawing_record.fallback_beneficiary IS DISTINCT FROM TRUE
       OR NOT EXISTS (
         SELECT 1 FROM megapot_pool_snapshot_private_leaves leaf
          WHERE leaf.snapshot_id = snapshot_record.snapshot_id
            AND leaf.ordinal = 0
            AND leaf.account_id = leg_record.fallback_beneficiary_account_id
            AND (leg_record.funding_source = 'shared_sponsor_budget'
              OR leaf.persona_id = leg_record.fallback_payout_persona_id)
       ) THEN
      RAISE EXCEPTION 'Megapot fallback beneficiary snapshot is not exact';
    END IF;
  ELSE
    IF snapshot_record.leaf_count <> share_total
       OR drawing_record.fallback_beneficiary IS DISTINCT FROM FALSE
       OR EXISTS (
         (SELECT share.account_id, share.persona_id
            FROM megapot_pool_shares share
           WHERE share.pool_leg_id = snapshot_record.pool_leg_id
             AND share.drawing_id = snapshot_record.drawing_id)
         EXCEPT
         (SELECT leaf.account_id, leaf.persona_id
            FROM megapot_pool_snapshot_private_leaves leaf
           WHERE leaf.snapshot_id = snapshot_record.snapshot_id)
       ) OR EXISTS (
         (SELECT leaf.account_id, leaf.persona_id
            FROM megapot_pool_snapshot_private_leaves leaf
           WHERE leaf.snapshot_id = snapshot_record.snapshot_id)
         EXCEPT
         (SELECT share.account_id, share.persona_id
            FROM megapot_pool_shares share
           WHERE share.pool_leg_id = snapshot_record.pool_leg_id
             AND share.drawing_id = snapshot_record.drawing_id)
       ) THEN
      RAISE EXCEPTION 'Megapot participant beneficiary snapshot is not exact';
    END IF;
  END IF;
  RETURN NULL;
END
$$;

CREATE OR REPLACE FUNCTION validate_megapot_allocation_batch() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  target_batch_id TEXT;
  batch_record megapot_allocation_batches%ROWTYPE;
  snapshot_record megapot_pool_beneficiary_snapshots%ROWTYPE;
  leg_record song_reward_offer_legs%ROWTYPE;
  drawing_record megapot_pool_drawings%ROWTYPE;
  allocation_total NUMERIC(78, 0);
  base_amount NUMERIC(78, 0);
  remainder_amount NUMERIC(78, 0);
  row_total INTEGER;
BEGIN

  IF EXISTS(SELECT 1 FROM megapot_allocation_batches b WHERE b.allocation_batch_id=NEW.allocation_batch_id AND b.beneficiary_version=3) THEN
    PERFORM require_owner_megapot_allocation_private_v1(NEW.allocation_batch_id); RETURN NULL;
  END IF;
  target_batch_id := NEW.allocation_batch_id;
  SELECT * INTO batch_record FROM megapot_allocation_batches
   WHERE allocation_batch_id = target_batch_id;
  IF batch_record.allocation_batch_id IS NULL THEN
    RETURN NULL;
  END IF;
  SELECT * INTO snapshot_record FROM megapot_pool_beneficiary_snapshots
   WHERE snapshot_id = batch_record.snapshot_id;
  SELECT * INTO leg_record FROM song_reward_offer_legs
   WHERE leg_id = batch_record.pool_leg_id;
  SELECT * INTO drawing_record FROM megapot_pool_drawings
   WHERE pool_leg_id = batch_record.pool_leg_id
     AND drawing_id = batch_record.drawing_id;
  base_amount := trunc(batch_record.net_winnings_atomic / snapshot_record.leaf_count);
  remainder_amount := batch_record.net_winnings_atomic
    - base_amount * snapshot_record.leaf_count;
  SELECT count(*), COALESCE(sum(amount_atomic), 0)
    INTO row_total, allocation_total FROM megapot_allocations
   WHERE allocation_batch_id = target_batch_id;
  IF row_total <> batch_record.allocation_count
     OR allocation_total <> batch_record.net_winnings_atomic
     OR row_total <> snapshot_record.leaf_count
     OR drawing_record.status <> 'credited'
     OR drawing_record.snapshot_id <> batch_record.snapshot_id
     OR drawing_record.claim_effect_id <> batch_record.claim_effect_id
     OR drawing_record.allocation_batch_id <> batch_record.allocation_batch_id
     OR drawing_record.net_winnings_atomic <> batch_record.net_winnings_atomic
     OR EXISTS (
       SELECT 1 FROM megapot_allocations allocation
       LEFT JOIN megapot_pool_snapshot_private_leaves leaf
         ON leaf.snapshot_id = snapshot_record.snapshot_id
        AND leaf.ordinal = allocation.ordinal
        AND leaf.account_id = allocation.account_id
        AND leaf.persona_id = allocation.persona_id
       WHERE allocation.allocation_batch_id = target_batch_id
         AND (leaf.account_id IS NULL
           OR allocation.amount_atomic <> base_amount
             + CASE WHEN allocation.ordinal < remainder_amount THEN 1 ELSE 0 END)
     ) THEN
    RAISE EXCEPTION 'Megapot allocation batch does not conserve exact snapshot winnings';
  END IF;
  IF snapshot_record.fallback THEN
    IF row_total <> 1 OR NOT EXISTS (
      SELECT 1 FROM megapot_allocations allocation
       WHERE allocation.allocation_batch_id = target_batch_id
         AND allocation.account_id = leg_record.fallback_beneficiary_account_id
         AND ((leg_record.funding_source = 'leg_budget'
             AND allocation.allocation_kind = 'external_fallback')
           OR (leg_record.funding_source = 'shared_sponsor_budget'
             AND allocation.allocation_kind = 'platform_sponsorship'))
    ) THEN
      RAISE EXCEPTION 'Megapot fallback allocation is not exact';
    END IF;
    IF leg_record.funding_source = 'shared_sponsor_budget' AND NOT EXISTS (
      SELECT 1 FROM megapot_allocations allocation
      JOIN platform_sponsorship_budget_entries entry
        ON entry.source_reference = batch_record.allocation_batch_id
       AND entry.sponsor_account_id = allocation.account_id
       AND entry.entry_kind = 'winnings_credited'
       AND entry.amount_atomic = allocation.amount_atomic
      WHERE allocation.allocation_batch_id = target_batch_id
        AND allocation.allocation_kind = 'platform_sponsorship'
    ) THEN
      RAISE EXCEPTION 'Megapot platform fallback lacks exact sponsorship credit';
    END IF;
  ELSIF EXISTS (
    SELECT 1 FROM megapot_allocations allocation
     WHERE allocation.allocation_batch_id = target_batch_id
       AND allocation.allocation_kind <> 'participant'
  ) THEN
    RAISE EXCEPTION 'Megapot participant allocation contains fallback beneficiary';
  END IF;
  RETURN NULL;
END
$$;

CREATE OR REPLACE FUNCTION validate_reward_ledger_credit_source() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN

  IF EXISTS(SELECT 1 FROM megapot_owner_allocations a JOIN megapot_allocation_batches b USING(allocation_batch_id)
    WHERE a.credit_id=NEW.credit_id AND b.beneficiary_version=3) THEN
    PERFORM require_owner_megapot_allocation_private_v1((SELECT allocation_batch_id FROM megapot_owner_allocations WHERE credit_id=NEW.credit_id));
    RETURN NULL;
  END IF;
  IF NEW.identity_version='owner_v1' THEN RAISE EXCEPTION 'owner credit lacks original v3 participant allocation' USING ERRCODE='GP003'; END IF;
  IF NEW.source_kind IN ('megapot_allocation', 'external_fallback') THEN
    IF NOT EXISTS (
      SELECT 1 FROM megapot_allocations allocation
       WHERE allocation.credit_id = NEW.credit_id
         AND allocation.account_id = NEW.account_id
         AND allocation.persona_id = NEW.payout_persona_id
         AND allocation.amount_atomic = NEW.amount_atomic
         AND ((NEW.source_kind = 'megapot_allocation'
              AND allocation.allocation_kind = 'participant')
           OR (NEW.source_kind = 'external_fallback'
              AND allocation.allocation_kind = 'external_fallback'))
    ) THEN
      RAISE EXCEPTION 'reward ledger credit lacks exact Megapot allocation';
    END IF;
  ELSIF NEW.source_kind = 'asset_bonus' AND NOT EXISTS (
    SELECT 1 FROM song_reward_bundle_claim_legs claim_leg
     WHERE claim_leg.credit_id = NEW.credit_id
       AND claim_leg.account_id = NEW.account_id
       AND claim_leg.amount_atomic = NEW.amount_atomic
  ) THEN
    RAISE EXCEPTION 'reward ledger credit lacks exact asset claim';
  END IF;
  RETURN NULL;
END
$$;

CREATE OR REPLACE FUNCTION guard_reward_ledger_credit() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN

  IF TG_OP='UPDATE' AND ROW(NEW.identity_version,NEW.participation_owner_id)
    IS DISTINCT FROM ROW(OLD.identity_version,OLD.participation_owner_id) THEN
    RAISE EXCEPTION 'original credit identity is immutable' USING ERRCODE='GP003';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'reward ledger credits cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.credit_id, NEW.account_id, NEW.payout_persona_id, NEW.chain_id,
      NEW.token_address, NEW.amount_atomic, NEW.source_kind,
      NEW.source_reference, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.credit_id, OLD.account_id, OLD.payout_persona_id, OLD.chain_id,
      OLD.token_address, OLD.amount_atomic, OLD.source_kind,
      OLD.source_reference, OLD.created_at
    ) OR NEW.reserved_atomic < 0 OR NEW.paid_atomic < OLD.paid_atomic
       OR NEW.updated_at <= OLD.updated_at
       OR NOT (
         (OLD.state = 'credited' AND NEW.state = 'payout_reserved'
           AND OLD.reserved_atomic = 0
           AND NEW.reserved_atomic = OLD.amount_atomic - OLD.paid_atomic
           AND NEW.paid_atomic = OLD.paid_atomic)
         OR (OLD.state = 'payout_reserved' AND NEW.state = 'credited'
           AND NEW.reserved_atomic = 0 AND NEW.paid_atomic = OLD.paid_atomic)
         OR (OLD.state = 'payout_reserved'
           AND NEW.state IN ('payout_pending', 'reconciliation_required')
           AND NEW.reserved_atomic = OLD.reserved_atomic
           AND NEW.paid_atomic = OLD.paid_atomic)
         OR (OLD.state = 'payout_pending' AND NEW.state = 'reconciliation_required'
           AND NEW.reserved_atomic = OLD.reserved_atomic
           AND NEW.paid_atomic = OLD.paid_atomic)
         OR (OLD.state IN ('payout_pending', 'reconciliation_required')
           AND NEW.state = 'sent' AND NEW.reserved_atomic = 0
           AND NEW.paid_atomic = OLD.amount_atomic)
         OR (OLD.state = 'reconciliation_required'
           AND NEW.state IN ('credited', 'payout_reserved', 'payout_pending')
           AND NEW.paid_atomic = OLD.paid_atomic
           AND ((NEW.state = 'credited' AND NEW.reserved_atomic = 0)
             OR (NEW.state <> 'credited'
               AND NEW.reserved_atomic = OLD.reserved_atomic)))
       ) THEN
      RAISE EXCEPTION 'invalid reward ledger credit transition';
    END IF;
  END IF;
  RETURN NEW;
END
$$;


-- Existing snapshot/batch constraint triggers now dispatch versions; new leaf/row
-- triggers independently recheck the exact same secured native validators.
CREATE CONSTRAINT TRIGGER owner_snapshot_leaf_exact AFTER INSERT ON megapot_owner_snapshot_leaves
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_megapot_beneficiary_snapshot();
CREATE CONSTRAINT TRIGGER owner_allocation_row_exact AFTER INSERT ON megapot_owner_allocations
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_megapot_allocation_batch();
CREATE TRIGGER owner_snapshot_leaves_immutable BEFORE UPDATE OR DELETE ON megapot_owner_snapshot_leaves
FOR EACH ROW EXECUTE FUNCTION reject_reward_append_only_change();
CREATE TRIGGER owner_allocations_immutable BEFORE UPDATE OR DELETE ON megapot_owner_allocations
FOR EACH ROW EXECUTE FUNCTION reject_reward_append_only_change();

-- These replace the specific disabled264 row witnesses ONLY inside Root's
-- complete positive closure transaction; they are not an independent activation.
CREATE OR REPLACE FUNCTION guard_disabled_beneficiary_dispatch_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF TG_OP='UPDATE' AND NEW.beneficiary_version IS DISTINCT FROM OLD.beneficiary_version THEN
  RAISE EXCEPTION 'beneficiary version is immutable' USING ERRCODE='GP003'; END IF;
 IF NEW.beneficiary_version=2 THEN RETURN NEW; END IF;
 IF NEW.beneficiary_version IS DISTINCT FROM 3 THEN RAISE EXCEPTION 'beneficiary version unavailable' USING ERRCODE='GP003'; END IF;
 PERFORM require_owner_accounting_ready_private_v1();
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION guard_disabled_owner_credit_dispatch_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF TG_OP='UPDATE' AND ROW(NEW.identity_version,NEW.participation_owner_id)
   IS DISTINCT FROM ROW(OLD.identity_version,OLD.participation_owner_id) THEN
  RAISE EXCEPTION 'ledger source identity is immutable' USING ERRCODE='GP003'; END IF;
 IF NEW.identity_version='account_v1' AND NEW.participation_owner_id IS NULL THEN RETURN NEW; END IF;
 IF NEW.identity_version IS DISTINCT FROM 'owner_v1' OR NEW.participation_owner_id IS NULL
  OR NEW.account_id IS NOT NULL OR NEW.payout_persona_id IS NOT NULL OR NEW.source_kind<>'megapot_allocation'
 THEN RAISE EXCEPTION 'owner participant credit source invalid' USING ERRCODE='GP003'; END IF;
 PERFORM require_owner_accounting_ready_private_v1();
 RETURN NEW;
END $$;

CREATE FUNCTION reject_owner_settlement_truncate_private_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN RAISE EXCEPTION 'immutable original settlement history cannot be truncated' USING ERRCODE='GP003'; END $$;
CREATE TRIGGER owner_snapshot_leaves_no_truncate BEFORE TRUNCATE ON megapot_owner_snapshot_leaves
FOR EACH STATEMENT EXECUTE FUNCTION reject_owner_settlement_truncate_private_v1();
CREATE TRIGGER owner_allocations_no_truncate BEFORE TRUNCATE ON megapot_owner_allocations
FOR EACH STATEMENT EXECUTE FUNCTION reject_owner_settlement_truncate_private_v1();

-- Source: owner-megapot-settlement-proposal-v2/version-dispatch-private.sql
CREATE FUNCTION read_megapot_beneficiary_version_private_v1(p_pool TEXT,p_draw NUMERIC)
RETURNS SMALLINT LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE version SMALLINT;
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT beneficiary_version INTO STRICT version FROM megapot_pool_drawings WHERE pool_leg_id=p_pool AND drawing_id=p_draw;
 IF version NOT IN(2,3) THEN RAISE EXCEPTION 'beneficiary source version unavailable' USING ERRCODE='GP003'; END IF;
 RETURN version;
END $$;
CREATE FUNCTION list_versioned_megapot_cutoff_due_private_v1(p_before TIMESTAMPTZ,p_limit INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE result JSONB;
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_before IS NULL OR p_limit IS NULL OR p_limit<1 OR p_limit>500
 THEN RAISE EXCEPTION 'bounded cutoff request required' USING ERRCODE='GP003'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('poolLegId',pool_leg_id,'drawingId',drawing_id::TEXT,
  'beneficiaryVersion',beneficiary_version,'entryCutoffAt',entry_cutoff_at)
  ORDER BY entry_cutoff_at,convert_to(pool_leg_id,'UTF8'),drawing_id),'[]'::JSONB) INTO result
 FROM (SELECT pool_leg_id,drawing_id,beneficiary_version,entry_cutoff_at FROM megapot_pool_drawings
  WHERE status='entry_open' AND entry_cutoff_at<=p_before AND beneficiary_version IN(2,3)
  ORDER BY entry_cutoff_at,convert_to(pool_leg_id,'UTF8'),drawing_id LIMIT p_limit) due;
 RETURN result;
END $$;

