CREATE FUNCTION owner_reward_choice_component_has_history_private_v1(p_component TEXT[])
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT EXISTS(SELECT 1 FROM owner_captured_guest_choice_commands WHERE source_owner_id=ANY(p_component))
$$;
-- Root's complete positive financial-history successor MUST include this actual
-- relation in its closed owner/FK inventory and include the predicate above in
-- whole-component emptiness. Any retained command, including a known refused
-- answer, is history. It is never cleanup-authorized by state/age/no winnings.

-- Source: owner-study-reward-producer-proposal-v2/read-locked-source-group.sql
-- PRIVATE: callers already hold shared topology and complete source locks.
-- No topology/account/owner lock is acquired after drawing/funding.
CREATE FUNCTION read_locked_owner_participation_group_private_v1(p_source TEXT)
RETURNS TEXT[] LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_ids TEXT[]; account_ids TEXT[]; count_accounts INTEGER;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 IF NOT EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=p_source) THEN
  RAISE EXCEPTION 'immutable source owner missing' USING ERRCODE='GP002'; END IF;
 WITH RECURSIVE group_members(owner_id) AS (
  SELECT p_source
  UNION
  SELECT next_member.owner_id FROM group_members prior CROSS JOIN LATERAL (
   SELECT a.canonical_owner_id AS owner_id FROM guest_empty_owner_aliases a WHERE a.source_owner_id=prior.owner_id
   UNION SELECT a.source_owner_id FROM guest_empty_owner_aliases a WHERE a.canonical_owner_id=prior.owner_id
   UNION SELECT a.account_owner_id FROM guest_owner_associations a WHERE a.guest_owner_id=prior.owner_id
   UNION SELECT a.guest_owner_id FROM guest_owner_associations a WHERE a.account_owner_id=prior.owner_id
   UNION SELECT other_owner.owner_id FROM participation_owners current_owner
    JOIN account_aliases a ON a.source_user_id=current_owner.account_id OR a.canonical_user_id=current_owner.account_id
    JOIN participation_owners other_owner ON other_owner.account_id IN(a.source_user_id,a.canonical_user_id)
    WHERE current_owner.owner_id=prior.owner_id AND current_owner.kind='account'
     AND ((a.kind='alias' AND a.status='active') OR (a.kind='merge' AND a.status IN('finalizing','completed')))
  ) next_member
 ) SELECT array_agg(owner_id ORDER BY convert_to(owner_id,'UTF8')) INTO source_ids FROM group_members;
 IF source_ids IS NULL OR cardinality(source_ids)>10000 OR EXISTS(SELECT 1 FROM unnest(source_ids) source_id
  WHERE NOT EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=source_id)) THEN
  RAISE EXCEPTION 'source group closure unavailable' USING ERRCODE='GP003'; END IF;
 SELECT array_agg(account_id ORDER BY convert_to(account_id,'UTF8')) INTO account_ids
 FROM participation_owners WHERE owner_id=ANY(source_ids) AND kind='account';
 IF EXISTS(SELECT 1 FROM account_aliases WHERE source_user_id=ANY(coalesce(account_ids,'{}'::TEXT[])) AND kind='merge' AND status='finalizing') THEN
  RAISE EXCEPTION 'account topology is unsettled' USING ERRCODE='GP003'; END IF;
 IF account_ids IS NOT NULL THEN
  SELECT count(*) INTO count_accounts FROM unnest(account_ids) id WHERE NOT EXISTS(SELECT 1 FROM account_aliases a WHERE a.source_user_id=id AND((a.kind='alias' AND a.status='active') OR(a.kind='merge' AND a.status='completed')));
  IF count_accounts<>1 THEN RAISE EXCEPTION 'canonical account group is unsettled' USING ERRCODE='GP003'; END IF;
 END IF;
 RETURN source_ids;
END $$;

-- Source: owner-study-reward-producer-proposal-v2/resource-source-group-successor.sql
CREATE OR REPLACE FUNCTION lock_guest_resource_budget_v1(p_source_id TEXT,p_fingerprint TEXT)
RETURNS TEXT[] LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE component_ids TEXT[]; root_id TEXT;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM 1 FROM guest_resource_global_lock WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'resource global anchor unavailable' USING ERRCODE='GP006'; END IF;
 IF p_fingerprint IS NULL OR char_length(p_fingerprint) NOT BETWEEN 1 AND 256
  THEN RAISE EXCEPTION 'trusted edge unavailable' USING ERRCODE='GP006'; END IF;
 INSERT INTO guest_resource_edge_locks VALUES(p_fingerprint) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM guest_resource_edge_locks WHERE guest_resource_edge_locks.fingerprint=lock_guest_resource_budget_v1.p_fingerprint FOR UPDATE;
 PERFORM lock_owner_participation_group_private_v1(p_source_id);
 SELECT resolve_guest_empty_owner_root_v1(p_source_id) INTO root_id;
 IF root_id IS DISTINCT FROM p_source_id THEN RAISE EXCEPTION 'owner mismatch' USING ERRCODE='GP002'; END IF;
 WITH RECURSIVE component(owner_id) AS (
  SELECT root_id UNION SELECT a.source_owner_id FROM guest_empty_owner_aliases a JOIN component c ON a.canonical_owner_id=c.owner_id
 ) SELECT array_agg(owner_id ORDER BY owner_id COLLATE "C") INTO component_ids FROM component;
 PERFORM 1 FROM participation_owners WHERE owner_id=ANY(component_ids) ORDER BY owner_id COLLATE "C" FOR NO KEY UPDATE;
 IF NOT EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=p_source_id AND kind='guest' AND state<>'aliased_empty')
  THEN RAISE EXCEPTION 'owner mismatch' USING ERRCODE='GP002'; END IF;
 RETURN component_ids;
END $$;

-- Source: owner-study-reward-producer-proposal-v2/selected-guest-lock-successors.sql
-- Source-derived narrow common-order successors. Owner IDs are immutable;
-- state/fence serialization retains row non-key locking, compatible with freeze FK KEY SHARE.
CREATE OR REPLACE FUNCTION lock_guest_authority_sources_v1(expected_origin TEXT, proved_ids TEXT[])
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
  IF expected_origin IS NULL OR expected_origin NOT LIKE 'https://%'
     OR octet_length(expected_origin)>2048 OR proved_ids IS NULL
     OR cardinality(proved_ids)>4
     OR EXISTS(SELECT 1 FROM unnest(proved_ids) id WHERE id IS NULL OR id !~ '^[A-Za-z0-9_-]{21}[AQgw]$')
     OR cardinality(proved_ids)<>(SELECT count(DISTINCT id) FROM unnest(proved_ids) id)
  THEN RAISE EXCEPTION 'invalid trusted proof context' USING ERRCODE='22023'; END IF;
  -- The caller taking EXCLUSIVE first (bootstrap) never upgrades a shared lock.
  -- Other operations keep aliases stable for their complete transaction.
  PERFORM pg_advisory_xact_lock_shared(83000003,1);
  PERFORM 1 FROM participation_owners o WHERE o.owner_id IN (
    WITH RECURSIVE component(owner_id) AS (
      SELECT DISTINCT resolve_guest_empty_owner_root_v1(c.owner_id)
        FROM guest_credentials c WHERE c.credential_id=ANY(proved_ids) AND c.origin=expected_origin
      UNION
      SELECT a.source_owner_id FROM guest_empty_owner_aliases a
        JOIN component x ON a.canonical_owner_id=x.owner_id
    ) SELECT owner_id FROM component
  ) ORDER BY o.owner_id COLLATE "C" FOR NO KEY UPDATE;
  -- Owner component before all credentials; deterministic order prevents
  -- cross-proof rotation/confirmation locks from reversing the owner order.
  PERFORM 1 FROM guest_credentials c WHERE c.owner_id IN (
    WITH RECURSIVE component(owner_id) AS (
      SELECT DISTINCT resolve_guest_empty_owner_root_v1(c0.owner_id)
        FROM guest_credentials c0 WHERE c0.credential_id=ANY(proved_ids) AND c0.origin=expected_origin
      UNION SELECT a.source_owner_id FROM guest_empty_owner_aliases a
        JOIN component x ON a.canonical_owner_id=x.owner_id
    ) SELECT owner_id FROM component
  ) ORDER BY c.credential_id COLLATE "C" FOR UPDATE;
END $$;

CREATE OR REPLACE FUNCTION lock_learner_audio_sources_private_v1(expected_owners TEXT[]) RETURNS VOID
 LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_id TEXT; component_ids TEXT[];
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 -- Caller may first lock separate account-authority rows in raw UTF8 order.
 -- Never pre-lock an incomplete owner singleton: this helper expands the whole
 -- owner component before taking any owner row; an already locked component
 -- must have been complete and acquired in the same raw UTF8 order.
 component_ids:=learner_audio_source_component_private_v1(expected_owners);
 FOR source_id IN SELECT owner_id FROM participation_owners WHERE owner_id=ANY(component_ids)
   ORDER BY convert_to(owner_id,'UTF8') FOR NO KEY UPDATE LOOP
   -- Actual aliased_empty children are legitimate immutable lock targets. Their
   -- resolved canonical root is already in component_ids; do not reparent them.
   IF EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=source_id AND state='aliased_empty')
      AND NOT resolve_guest_empty_owner_root_v1(source_id)=ANY(component_ids) THEN
     RAISE EXCEPTION 'alias root missing from locked component'; END IF;
   PERFORM pg_advisory_xact_lock(hashtextextended(source_id,83000004));
 END LOOP;
 -- Pure locking/reads create NO fence row and establish NO owner. New history
 -- creation below validates only its active source and persists its own fence.
END $$;

CREATE OR REPLACE FUNCTION reserve_guest_prepared_study_start_v1(
 p_access JSONB,p_operation JSONB,p_community TEXT,p_post TEXT,p_session_id TEXT,
 p_target TEXT,p_band TEXT,p_fingerprint TEXT,p_policy JSONB,p_operation_id TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_id TEXT:=p_operation->>'sourceOwnerId';
 existing guest_resource_session_reservations%ROWTYPE;
 stored_operation guest_participation_operations%ROWTYPE;
 component_ids TEXT[]; fingerprint TEXT; plan JSONB; budget JSONB;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_guest_study_composition_v1();
 PERFORM validate_guest_resource_operation_v1(source_id,p_operation,'study_start');
 PERFORM 1 FROM guest_resource_global_lock WHERE singleton FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'resource global anchor unavailable' USING ERRCODE='GP006'; END IF;
 -- Immutable original edge precedes GLOBAL/EDGE/full component acquisition.
 -- No fresh edge/catalogue/policy/session draw replaces original receipt identity.
 SELECT * INTO existing FROM guest_resource_session_reservations
  WHERE source_owner_id=source_id AND operation_kind='study_start'
   AND idempotency_key=p_operation->>'idempotencyKey';
 -- A retained original abort/held key without resource has no edge to lock.
 -- Its read-only recovery must not insert a fresh edge or reserve a new plan.
 IF existing.reservation_id IS NULL THEN
  SELECT * INTO stored_operation FROM guest_participation_operations
   WHERE source_owner_id=source_id AND operation_kind='study_start'
    AND idempotency_key=p_operation->>'idempotencyKey';
  IF FOUND THEN
   -- GLOBAL was acquired before the actual credential/full-C proof helper.
   -- This original-source read permits the accepted empty-alias lookup only;
   -- NEW allocation below still uses canonical-only resource locking.
   PERFORM require_guest_study_learning_access_v1(p_access,source_id);
   SELECT * INTO STRICT stored_operation FROM guest_participation_operations
    WHERE source_owner_id=source_id AND operation_kind='study_start'
     AND idempotency_key=p_operation->>'idempotencyKey' FOR UPDATE;
   IF ROW(stored_operation.request_hash,stored_operation.resource_scope)
     IS DISTINCT FROM ROW(p_operation->>'requestHash',guest_study_start_resource_scope_v1(p_community,p_post)) THEN
    RAISE EXCEPTION 'start operation identity changed' USING ERRCODE='GP005'; END IF;
   -- Original rights/clock/receipt remain; completed lesson content still needs
   -- the current public, published, general-audience resource authority.
   IF stored_operation.state='completed' AND NOT can_guest_access_activity_song_v1(p_community,p_post) THEN
    RAISE EXCEPTION 'public resource unavailable' USING ERRCODE='GP010'; END IF;
   RETURN jsonb_build_object('kind','start_outcome','outcome',jsonb_build_object(
    'state',stored_operation.state,'operationId',stored_operation.operation_id,'result',stored_operation.result_snapshot));
  END IF;
 END IF;
 fingerprint:=CASE WHEN existing.reservation_id IS NOT NULL THEN existing.edge_fingerprint ELSE p_fingerprint END;
 component_ids:=lock_guest_resource_budget_v1(source_id,fingerprint);
 PERFORM require_guest_study_learning_access_v1(p_access,source_id);
 SELECT * INTO existing FROM guest_resource_session_reservations
  WHERE source_owner_id=source_id AND operation_kind='study_start'
   AND idempotency_key=p_operation->>'idempotencyKey' FOR UPDATE;
 IF FOUND AND existing.request_hash IS DISTINCT FROM p_operation->>'requestHash' THEN
  RAISE EXCEPTION 'start operation identity changed' USING ERRCODE='GP005'; END IF;
 SELECT * INTO stored_operation FROM guest_participation_operations
  WHERE source_owner_id=source_id AND operation_kind='study_start'
   AND idempotency_key=p_operation->>'idempotencyKey' FOR UPDATE;
 IF FOUND THEN
  IF ROW(stored_operation.request_hash,stored_operation.resource_scope)
    IS DISTINCT FROM ROW(p_operation->>'requestHash',guest_study_start_resource_scope_v1(p_community,p_post)) THEN
   RAISE EXCEPTION 'start operation identity changed' USING ERRCODE='GP005'; END IF;
  IF existing.reservation_id IS NOT NULL AND existing.state='refused' THEN
   IF stored_operation.state<>'known_aborted' THEN
    RAISE EXCEPTION 'refused resource contradicts original start' USING ERRCODE='GP006'; END IF;
   RETURN jsonb_build_object('kind','resource_refused','operationId',stored_operation.operation_id,'plan',NULL,
    'reservation',jsonb_build_object('state','completed','outcome_id',existing.reservation_id,'result',existing.original_result));
  END IF;
  -- Positive main-row evidence, never absence or transport ambiguity. Original
  -- accepted/held/definitely aborted outcome wins before fresh source admission.
  -- Original rights/clock/receipt remain; completed lesson content still needs
  -- the current public, published, general-audience resource authority.
  IF stored_operation.state='completed' AND NOT can_guest_access_activity_song_v1(p_community,p_post) THEN
   RAISE EXCEPTION 'public resource unavailable' USING ERRCODE='GP010'; END IF;
  RETURN jsonb_build_object('kind','start_outcome','outcome',jsonb_build_object(
   'state',stored_operation.state,'operationId',stored_operation.operation_id,'result',stored_operation.result_snapshot));
 END IF;
 IF existing.reservation_id IS NOT NULL THEN
  -- A historical standalone resource receipt is retained, not overwritten or
  -- silently converted into a fabricated new main-abort row. Its original refusal
  -- is positive evidence; no absence of main is called an abort here.
  budget:=reserve_guest_resource_session_v1(source_id,p_operation,existing.session_id,
   existing.initial_units,existing.worst_case_cost_micros::TEXT,existing.edge_fingerprint,p_policy);
  RETURN jsonb_build_object('kind',CASE WHEN existing.state='refused' THEN 'resource_refused' ELSE 'reservation' END,
   'reservation',budget,'plan',NULL,'operationId',NULL);
 END IF;
 -- NEW only: current public resource, complete audio fence, exact current policy,
 -- one actual selector and no IO. Any later projection/disclosure/source refusal
 -- rolls the NEW resource back with the SAME outer transaction.
 IF NOT can_guest_access_activity_song_v1(p_community,p_post) THEN
  RAISE EXCEPTION 'public resource unavailable' USING ERRCODE='GP010'; END IF;
 PERFORM lock_learner_audio_sources_private_v1(component_ids);
 IF EXISTS(SELECT 1 FROM learner_audio_owner_fences WHERE owner_id=ANY(component_ids)
   AND active_delete_command_id IS NOT NULL) THEN
  RAISE EXCEPTION 'learner audio deletion in progress' USING ERRCODE='GP009'; END IF;
 PERFORM validate_guest_resource_policy_v1(p_policy);
 IF p_operation_id IS NULL OR char_length(p_operation_id) NOT BETWEEN 1 AND 128 THEN
  RAISE EXCEPTION 'server start operation identity unavailable' USING ERRCODE='22023'; END IF;
 plan:=select_guest_study_start_plan_v1(source_id,p_community,p_post,p_target,p_band);
 budget:=reserve_guest_resource_session_v1(source_id,p_operation,p_session_id,
  (plan->>'paidAttemptUnits')::INTEGER,
  ((plan->>'paidAttemptUnits')::NUMERIC*(p_policy->>'maximumProviderCallCostMicros')::NUMERIC)::TEXT,
  p_fingerprint,p_policy);
 IF budget#>>'{result,state}'='reserved' THEN
  RETURN jsonb_build_object('kind','reservation','reservation',budget,'plan',plan,'operationId',NULL);
 END IF;
 IF budget#>>'{result,state}' IS NULL OR budget#>>'{result,state}' NOT IN('rate_limited','budget_refused') THEN
  RAISE EXCEPTION 'unexpected resource refusal' USING ERRCODE='GP006'; END IF;
 -- Definite refusal and its durable main-status witness are atomic. Refusal
 -- response is emitted only after actual outer COMMIT acknowledgment. Unknown
 -- COMMIT remains pending; exact status can later recover this ORIGINAL abort.
 SELECT * INTO STRICT existing FROM guest_resource_session_reservations
  WHERE reservation_id=budget->>'outcome_id' AND source_owner_id=source_id AND state='refused';
 INSERT INTO guest_participation_operations(operation_id,source_owner_id,operation_kind,resource_scope,
  idempotency_key,request_hash,state,created_at,resolved_at)
 VALUES(p_operation_id,source_id,'study_start',guest_study_start_resource_scope_v1(p_community,p_post),
  p_operation->>'idempotencyKey',p_operation->>'requestHash','known_aborted',existing.created_at,clock_timestamp());
 RETURN jsonb_build_object('kind','resource_refused','reservation',budget,'plan',plan,'operationId',p_operation_id);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/controlled-session-mode-successor.sql
CREATE OR REPLACE FUNCTION guard_controlled_guest_study_session_v1() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE operation guest_participation_operations%ROWTYPE;
 reservation guest_resource_session_reservations%ROWTYPE;
BEGIN
 IF NEW.participation_owner_kind IS DISTINCT FROM 'guest' OR NEW.account_id IS NOT NULL
   OR NEW.persona_id IS NOT NULL
   OR NOT((NEW.guest_reward_mode='practice_only' AND NEW.guest_reward_terms IS NULL AND NEW.guest_reward_purchase_safety_deadline_at IS NULL)
    OR(NEW.guest_reward_mode='megapot_guest_v1' AND NEW.guest_reward_terms IS NOT NULL AND NEW.guest_reward_purchase_safety_deadline_at IS NOT NULL)) OR NEW.guest_disclosure_accepted IS NOT TRUE
   OR NEW.telegram_practice_only IS NOT FALSE
   OR (TG_OP='INSERT' AND NEW.guest_spoken_call_plan IS NULL) THEN
   RAISE EXCEPTION 'closed guest practice source required' USING ERRCODE='GP003'; END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.community_id,NEW.post_id,NEW.audio_revision,NEW.lyrics_revision,NEW.learning_language,
      NEW.target_language,NEW.learner_band,NEW.study_profile_revision,NEW.source_set_revision,
      NEW.selection_policy_revision,NEW.qualification_policy_revision,NEW.timezone,
      NEW.language_profile_revision,NEW.created_at,NEW.expires_at,
      NEW.guest_reward_mode,NEW.guest_reward_terms,NEW.guest_start_operation_id,
      NEW.guest_disclosure_version,NEW.guest_disclosure_accepted,NEW.guest_resource_reservation_id,NEW.guest_spoken_call_plan,NEW.guest_reward_purchase_safety_deadline_at)
    IS DISTINCT FROM ROW(OLD.community_id,OLD.post_id,OLD.audio_revision,OLD.lyrics_revision,OLD.learning_language,
      OLD.target_language,OLD.learner_band,OLD.study_profile_revision,OLD.source_set_revision,
      OLD.selection_policy_revision,OLD.qualification_policy_revision,OLD.timezone,
      OLD.language_profile_revision,OLD.created_at,OLD.expires_at,
      OLD.guest_reward_mode,OLD.guest_reward_terms,OLD.guest_start_operation_id,
      OLD.guest_disclosure_version,OLD.guest_disclosure_accepted,OLD.guest_resource_reservation_id,OLD.guest_spoken_call_plan,OLD.guest_reward_purchase_safety_deadline_at) THEN
    RAISE EXCEPTION 'captured guest session admission is immutable' USING ERRCODE='GP003'; END IF;
  -- Do not recheck current public visibility, proof lease/revocation or resource
  -- liveness while recording an already accepted provider/grade checkpoint.
  RETURN NEW;
 END IF;
 SELECT * INTO STRICT operation FROM guest_participation_operations WHERE operation_id=NEW.guest_start_operation_id;
 SELECT * INTO STRICT reservation FROM guest_resource_session_reservations WHERE reservation_id=NEW.guest_resource_reservation_id;
 IF ROW(operation.source_owner_id,operation.operation_kind,operation.idempotency_key,operation.request_hash,operation.resource_scope)
   IS DISTINCT FROM ROW(NEW.participation_owner_id,'study_start'::TEXT,NEW.idempotency_key,NEW.request_hash,
    guest_study_start_resource_scope_v1(NEW.community_id,NEW.post_id))
   OR operation.state NOT IN('reserved','completed')
   OR ROW(reservation.source_owner_id,reservation.operation_kind,reservation.session_id,reservation.idempotency_key,reservation.request_hash)
     IS DISTINCT FROM ROW(NEW.participation_owner_id,'study_start'::TEXT,NEW.session_id,NEW.idempotency_key,NEW.request_hash)
   OR reservation.initial_units<(NEW.guest_spoken_call_plan->>'maximum_paid_calls')::INTEGER
   OR reservation.state<>'active' OR reservation.reservation_expires_at<=clock_timestamp()
   OR NEW.created_at IS DISTINCT FROM reservation.created_at
   OR NEW.expires_at IS DISTINCT FROM reservation.reservation_expires_at
   OR NOT can_guest_access_activity_song_v1(NEW.community_id,NEW.post_id) THEN
   RAISE EXCEPTION 'captured guest start/resource source mismatch' USING ERRCODE='GP003'; END IF;
 IF NEW.guest_reward_mode='megapot_guest_v1' THEN
  PERFORM require_owner_accounting_ready_private_v1();
  PERFORM validate_guest_reward_terms_shape_private_v1(NEW.guest_reward_terms,NEW.community_id,NEW.post_id,
   NEW.audio_revision,NEW.lyrics_revision,NEW.qualification_policy_revision,NEW.guest_disclosure_version);
 END IF;
 RETURN NEW;
END $$;

-- Source: owner-study-reward-producer-proposal-v2/start-terms-leaf.sql
CREATE FUNCTION read_guest_reward_start_terms_v1(p_community TEXT,p_post TEXT,p_audio BIGINT,p_lyrics BIGINT,p_disclosure TEXT,p_safety_margin INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE terms JSONB;
BEGIN
 terms:=read_guest_owner_reward_terms_private_v1(p_community,p_post,p_audio,p_lyrics,p_disclosure,p_safety_margin);
 IF terms IS NULL THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('terms',terms,'reward_preview_terms_hash',encode(sha256(convert_to(terms::TEXT,'UTF8')),'hex'));
END $$;

-- Source: owner-study-reward-producer-proposal-v2/commit_guest_study_start_with_rewards_v1.sql
CREATE FUNCTION commit_guest_study_start_with_rewards_v1(
 p_access JSONB,p_operation JSONB,p_community TEXT,p_post TEXT,p_reservation TEXT,
 p_target TEXT,p_band TEXT,p_policy JSONB,p_candidate JSONB,p_items JSONB,
 p_operation_id TEXT,p_timezone TEXT,p_disclosure_version TEXT,p_accepted_version TEXT,p_accepted BOOLEAN,
 p_requested_mode TEXT,p_accepted_reward_terms JSONB,p_purchase_safety_margin INTEGER
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE checked JSONB; item JSONB; exercise JSONB; ordinal INTEGER:=0; review_id TEXT;
 captured_created TIMESTAMPTZ; captured_expires TIMESTAMPTZ;
 session_id TEXT; source_id TEXT; at_time TIMESTAMPTZ; timezone_name TEXT; result JSONB; reward_terms JSONB; safety_deadline TIMESTAMPTZ;
BEGIN
 checked:=prepare_guest_study_start_v1(p_access,p_operation,p_community,p_post,p_reservation,p_target,p_band,p_policy);
 IF checked->>'state'<>'candidate' THEN RETURN checked; END IF;
 IF checked IS DISTINCT FROM p_candidate THEN
  RAISE EXCEPTION 'prepared source changed before capture' USING ERRCODE='GP006'; END IF;
 IF p_accepted IS DISTINCT FROM TRUE OR p_accepted_version IS DISTINCT FROM p_disclosure_version
  OR p_disclosure_version IS NULL OR char_length(p_disclosure_version) NOT BETWEEN 1 AND 128 THEN
  RAISE EXCEPTION 'accepted microphone disclosure unavailable' USING ERRCODE='GP006'; END IF;
 IF p_items IS NULL OR jsonb_typeof(p_items)<>'array'
  OR jsonb_array_length(p_items)<>jsonb_array_length(checked->'rows')
  OR jsonb_array_length(p_items) NOT BETWEEN 4 AND 10 THEN
  RAISE EXCEPTION 'prepared public items invalid' USING ERRCODE='GP006'; END IF;
 session_id:=checked->>'sessionId';source_id:=checked->>'sourceOwnerId';at_time:=clock_timestamp();
 SELECT created_at,reservation_expires_at INTO STRICT captured_created,captured_expires
  FROM guest_resource_session_reservations WHERE reservation_id=p_reservation;
 SELECT timezone INTO timezone_name FROM participation_owner_clocks WHERE owner_id=source_id FOR UPDATE;
 IF NOT FOUND THEN
  IF NOT EXISTS(SELECT 1 FROM pg_timezone_names WHERE name=p_timezone) THEN
   RAISE EXCEPTION 'timezone unavailable' USING ERRCODE='GP006'; END IF;
  timezone_name:=p_timezone;
  INSERT INTO participation_owner_clocks(owner_id,timezone,timezone_updated_at,next_change_allowed_at,created_at)
   VALUES(source_id,timezone_name,at_time,at_time+INTERVAL '168 hours',at_time);
 END IF;
 reward_terms:=freeze_new_guest_study_reward_terms_private_v1(p_requested_mode,p_accepted_reward_terms,
  p_community,p_post,(checked->'rows'->0->>'audio_revision')::BIGINT,
  (checked->'rows'->0->>'lyrics_revision')::BIGINT,p_disclosure_version,p_purchase_safety_margin);
 IF p_requested_mode='megapot_guest_v1' THEN
  IF p_purchase_safety_margin IS NULL OR p_purchase_safety_margin NOT BETWEEN 1 AND 86400 THEN
   RAISE EXCEPTION 'explicit NEW source safety policy required' USING ERRCODE='GP006'; END IF;
  SELECT obs.drawing_time-make_interval(secs=>p_purchase_safety_margin) INTO STRICT safety_deadline
   FROM megapot_pool_drawings d JOIN megapot_drawing_observations obs ON obs.observation_id=d.observation_id
   WHERE d.pool_leg_id=reward_terms->>'pool_leg_id' AND d.drawing_id=(reward_terms->>'original_drawing_id')::NUMERIC;
 END IF;
 -- Root must wire the controlled row-admission guard for these definer writes;
 -- the deliberately closed composition helper above is not an admission bypass.
 INSERT INTO guest_participation_operations(operation_id,source_owner_id,operation_kind,resource_scope,
   idempotency_key,request_hash,state,created_at)
  VALUES(p_operation_id,source_id,'study_start',guest_study_start_resource_scope_v1(p_community,p_post),
   p_operation->>'idempotencyKey',p_operation->>'requestHash','reserved',at_time);
 INSERT INTO study_sessions_v2(session_id,account_id,persona_id,participation_owner_id,participation_owner_kind,
   community_id,post_id,audio_revision,lyrics_revision,learning_language,target_language,learner_band,
   language_profile_revision,study_profile_revision,source_set_revision,selection_policy_revision,
   qualification_policy_revision,timezone,idempotency_key,request_hash,created_at,expires_at,
   current_session_item_id,current_presented_at,guest_reward_mode,guest_reward_terms,
   guest_start_operation_id,guest_disclosure_version,guest_disclosure_accepted,telegram_practice_only,guest_resource_reservation_id,guest_reward_purchase_safety_deadline_at,guest_spoken_call_plan)
  VALUES(session_id,NULL,NULL,source_id,'guest',p_community,p_post,
   (checked->'rows'->0->>'audio_revision')::BIGINT,(checked->'rows'->0->>'lyrics_revision')::BIGINT,
   'en',checked->>'targetLanguage',checked->>'learnerBand',
   (checked->'rows'->0->>'language_profile_revision')::BIGINT,1,1,'study_selection_v1',
   'study_session_first_pass_v2@1',timezone_name,p_operation->>'idempotencyKey',p_operation->>'requestHash',
   captured_created,captured_expires,p_items->0->>'session_item_id',at_time,
   p_requested_mode,reward_terms,p_operation_id,p_disclosure_version,TRUE,FALSE,p_reservation,safety_deadline,
   jsonb_build_object('policy_revision','study_spoken_rerecord_v1',
    'graded_presentation_cap',(checked->>'paidAttemptUnits')::INTEGER/2,
    'ungraded_rerecord_per_presentation',1,'maximum_paid_calls',(checked->>'paidAttemptUnits')::INTEGER));
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  exercise:=checked->'rows'->ordinal;
  -- SQL validates the shared projection's COMPLETE whitelist. Unknown fields,
  -- private grader leakage or a forged public item cannot pass this comparison.
  IF item IS DISTINCT FROM jsonb_build_object(
    'object','study_session_item_v2','session_item_id',session_id||'_item_'||(ordinal+1),
    'ordinal',ordinal,'exercise_review_key',exercise->'exercise_review_key',
    'exercise_version_id',exercise->'exercise_version_id','exercise_type',exercise->'exercise_type',
    'exercise_variant',exercise->'exercise_variant',
    'line',jsonb_build_object('post_id',exercise->'post_id','audio_revision',exercise->'audio_revision',
      'lyrics_revision',exercise->'lyrics_revision','lyric_line_id',exercise->'lyric_line_id',
      'study_unit_id',exercise->'study_unit_id','line_version',exercise->'line_version',
      'line_source_hash',exercise->'line_source_hash'),
    'languages',jsonb_build_object('learning_language',exercise->'learning_language','target_language',exercise->'target_language'),
    'learner_band',exercise->'learner_band','language_profile_revision',exercise->'language_profile_revision',
    'presentation',exercise->'presentation','answer_visibility',exercise->'answer_visibility',
    'feedback_release',exercise->'feedback_release','grader_policy_revision',exercise->'grader_policy_revision',
    'feedback_policy_revision',exercise->'feedback_policy_revision','quality_policy_revision',exercise->'quality_policy_revision',
    'maximum_attempts',3) THEN RAISE EXCEPTION 'public item projection changed' USING ERRCODE='GP006'; END IF;
  review_id:=session_id||'_review_'||(ordinal+1);
  INSERT INTO study_review_items(review_item_id,account_id,participation_owner_id,participation_owner_kind,
    exercise_review_key,current_exercise_version_id,scheduler_policy_revision,scheduler_state,
    community_id,post_id,study_unit_id,exercise_kind,learning_language,target_language,learner_band)
   VALUES(review_id,NULL,source_id,'guest',item->>'exercise_review_key',item->>'exercise_version_id',
    'study_review_schedule_v1','{}',p_community,p_post,item->'line'->>'study_unit_id',item->>'exercise_type',
    item->'languages'->>'learning_language',item->'languages'->>'target_language',item->>'learner_band')
   ON CONFLICT(participation_owner_id,exercise_review_key) DO UPDATE
    SET current_exercise_version_id=excluded.current_exercise_version_id,updated_at=clock_timestamp()
   RETURNING review_item_id INTO review_id;
  INSERT INTO study_session_items_v2(session_item_id,session_id,ordinal,exercise_review_key,exercise_version_id,
    review_item_id,item_snapshot,maximum_attempts,account_id,participation_owner_id,participation_owner_kind)
   VALUES(item->>'session_item_id',session_id,ordinal,item->>'exercise_review_key',item->>'exercise_version_id',
    review_id,item,3,NULL,source_id,'guest');
  INSERT INTO study_lesson_item_state_v2(session_item_id,session_id,original_ordinal)
   VALUES(item->>'session_item_id',session_id,ordinal);
  ordinal:=ordinal+1;
 END LOOP;
 UPDATE participation_owners SET state='established' WHERE owner_id=source_id AND state='empty';
 result:=read_guest_study_session_snapshot_v1(p_access,p_community,session_id);
 UPDATE guest_participation_operations SET state='completed',resolved_at=clock_timestamp(),result_snapshot=result
  WHERE operation_id=p_operation_id;
 RETURN jsonb_build_object('state','completed','operationId',p_operation_id,'result',result);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/prepared-reward-preview-leaf.sql
-- The actual source/catalogue/public predicate and server reward preview are
-- read in ONE SQL statement/MVCC snapshot. No private grader/claim/owner fields.
CREATE FUNCTION read_guest_reward_prepared_content_v1(p_community TEXT,p_post TEXT,p_disclosure TEXT,p_safety_margin INTEGER)
RETURNS JSONB LANGUAGE sql SECURITY DEFINER AS $$
SELECT to_jsonb(snapshot)||jsonb_build_object('reward_preview_terms_hash',
 CASE WHEN snapshot.reward_preview IS NULL THEN NULL ELSE encode(sha256(convert_to(snapshot.reward_preview::TEXT,'UTF8')),'hex') END) FROM (
WITH public_resource AS (
  SELECT can_guest_access_activity_song_v1(p_community,p_post) AS accessible
), source AS (
SELECT coalesce(publication.lyrics_status='ready'
                    AND submission.status='published'
                    AND publication.audio_revision=submission.audio_revision
                    AND publication.lyrics_revision=submission.current_lyrics_revision
                    AND lyrics.lyrics_revision IS NOT NULL, false) AS lyrics_ready,
                    coalesce(publication.language_status='ready', false) AS language_ready,
                    EXISTS(SELECT 1 FROM media_song_stems stem
                      WHERE stem.submission_id=publication.submission_id
                        AND stem.community_id=publication.community_id
                        AND stem.slot='instrumental_audio')
                    AND EXISTS(SELECT 1 FROM media_song_stems stem
                      WHERE stem.submission_id=publication.submission_id
                        AND stem.community_id=publication.community_id
                        AND stem.slot='vocal_audio') AS stems_ready
               FROM media_publication_projections publication
               JOIN media_post_submissions submission
                 ON submission.submission_id=publication.submission_id
                AND submission.community_id=publication.community_id
                AND submission.post_id=publication.post_id
               LEFT JOIN media_song_lyrics_revisions lyrics
                 ON lyrics.submission_id=submission.submission_id
                AND lyrics.lyrics_revision=publication.lyrics_revision
              WHERE publication.community_id=p_community AND publication.post_id=p_post
                AND (SELECT accessible FROM public_resource)
), latest AS (
            SELECT DISTINCT ON (exercise.exercise_review_key)
              exercise.exercise_review_key, exercise.exercise_type, exercise.learning_language,
              exercise.target_language, exercise.learner_band
              FROM study_exercise_versions exercise
              JOIN media_publication_projections publication
                ON publication.community_id=exercise.community_id AND publication.post_id=exercise.post_id
              JOIN media_post_submissions submission
                ON submission.submission_id=publication.submission_id
               AND submission.community_id=publication.community_id AND submission.post_id=publication.post_id
               AND submission.audio_revision=exercise.audio_revision
               AND submission.current_lyrics_revision=exercise.lyrics_revision
              JOIN media_song_lyrics_revisions lyrics
                ON lyrics.submission_id=submission.submission_id AND lyrics.lyrics_revision=exercise.lyrics_revision
              JOIN localization_lyrics_revision_lines membership
                ON membership.community_id=exercise.community_id AND membership.post_id=exercise.post_id
               AND membership.lyrics_revision=exercise.lyrics_revision AND membership.lyric_line_id=exercise.lyric_line_id
               AND membership.line_version=exercise.line_version
              JOIN localization_lyric_line_versions line
                ON line.community_id=membership.community_id AND line.post_id=membership.post_id
               AND line.lyric_line_id=membership.lyric_line_id AND line.line_version=membership.line_version
               AND line.source_hash=exercise.line_source_hash
              JOIN localization_lyric_line_study_units unit_binding
                ON unit_binding.community_id=membership.community_id AND unit_binding.post_id=membership.post_id
               AND unit_binding.lyric_line_id=membership.lyric_line_id AND unit_binding.line_version=membership.line_version
               AND unit_binding.study_unit_id=exercise.study_unit_id
              JOIN LATERAL (
                SELECT profile.language_profile_revision FROM study_language_profiles profile
                 WHERE profile.community_id=exercise.community_id AND profile.post_id=exercise.post_id
                   AND profile.lyrics_revision=exercise.lyrics_revision AND profile.source_hash=lyrics.lyrics_sha256
                   AND (exercise.language_profile_revision IS NULL OR profile.language_profile_revision=exercise.language_profile_revision)
                 ORDER BY profile.language_profile_revision DESC LIMIT 1
              ) accepted_profile ON TRUE
              JOIN study_language_profile_units unit
                ON unit.community_id=exercise.community_id AND unit.post_id=exercise.post_id
               AND unit.lyrics_revision=exercise.lyrics_revision AND unit.study_unit_id=exercise.study_unit_id
               AND unit.language_profile_revision=accepted_profile.language_profile_revision
             WHERE exercise.community_id=p_community AND exercise.post_id=p_post AND exercise.retired_at IS NULL
               AND publication.audio_revision=exercise.audio_revision AND publication.lyrics_revision=exercise.lyrics_revision
               AND publication.lyrics_status='ready' AND submission.status='published'
               AND EXISTS(SELECT 1 FROM source WHERE lyrics_ready AND language_ready AND stems_ready)
               AND (SELECT accessible FROM public_resource)
             ORDER BY exercise.exercise_review_key, exercise.content_revision DESC
), catalogue AS (
  SELECT exercise_type, learning_language, target_language, learner_band,
                   count(DISTINCT exercise_review_key)::integer AS count
              FROM latest GROUP BY exercise_type, learning_language, target_language, learner_band
             ORDER BY exercise_type, target_language NULLS FIRST, learner_band NULLS FIRST
)
SELECT public_resource.accessible,
       coalesce((SELECT jsonb_agg(source) FROM source), '[]'::jsonb) AS source_rows,
       CASE WHEN public_resource.accessible AND EXISTS(SELECT 1 FROM source WHERE lyrics_ready AND language_ready AND stems_ready)
        AND EXISTS(SELECT 1 FROM song_reward_offers offer JOIN song_reward_offer_legs leg USING(offer_id)
         WHERE offer.community_id=p_community AND offer.post_id=p_post AND offer.status='active' AND leg.status='active' AND leg.beneficiary_version=3)
        THEN (SELECT read_guest_owner_reward_terms_private_v1(p_community,p_post,publication.audio_revision,publication.lyrics_revision,p_disclosure,p_safety_margin)
         FROM media_publication_projections publication WHERE publication.community_id=p_community AND publication.post_id=p_post)
        ELSE NULL END AS reward_preview,
       coalesce((SELECT jsonb_agg(catalogue ORDER BY exercise_type,
                   target_language NULLS FIRST, learner_band NULLS FIRST)
                   FROM catalogue), '[]'::jsonb) AS prepared_rows
  FROM public_resource
) snapshot
$$;

-- Source: owner-study-reward-producer-proposal-v2/open-owner-drawing.sql
-- Fallback salt column/version3 shape and immutable dispatch belong to Consumer's
-- source piece. This function never overwrites an original version2 drawing.
CREATE FUNCTION open_owner_megapot_drawing_v1(p_leg TEXT,p_observation TEXT,p_fallback_salt BYTEA)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE observed megapot_drawing_observations%ROWTYPE; leg song_reward_offer_legs%ROWTYPE;
 existing megapot_pool_drawings%ROWTYPE; offer song_reward_offers%ROWTYPE;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT * INTO STRICT observed FROM megapot_drawing_observations WHERE observation_id=p_observation;
 SELECT * INTO existing FROM megapot_pool_drawings WHERE pool_leg_id=p_leg AND drawing_id=observed.drawing_id;
 IF FOUND THEN
  IF existing.beneficiary_version<>3 OR existing.owner_fallback_leaf_salt IS NULL OR octet_length(existing.owner_fallback_leaf_salt)<>32 THEN
   RAISE EXCEPTION 'prospective original drawing version differs' USING ERRCODE='GP003'; END IF;
  -- Immutable creation replay only. Never claim the existing drawing is open,
  -- replace its observation/time/salt, or acquire draw locks AFTER funding locks.
  RETURN jsonb_build_object('poolLegId',existing.pool_leg_id,'drawingId',existing.drawing_id::TEXT,'beneficiaryVersion',3);
 END IF;
 IF p_fallback_salt IS NULL OR octet_length(p_fallback_salt)<>32 THEN
  RAISE EXCEPTION 'server CSPRNG fallback salt required' USING ERRCODE='22023'; END IF;
 -- NEW only: a leg lock serializes creations. If another creation won while we
 -- waited, read its immutable identity without locking its drawing after this leg.
 SELECT * INTO STRICT leg FROM song_reward_offer_legs WHERE leg_id=p_leg FOR UPDATE;
 SELECT * INTO existing FROM megapot_pool_drawings WHERE pool_leg_id=p_leg AND drawing_id=observed.drawing_id;
 IF FOUND THEN
  IF existing.beneficiary_version<>3 OR existing.owner_fallback_leaf_salt IS NULL OR octet_length(existing.owner_fallback_leaf_salt)<>32 THEN
   RAISE EXCEPTION 'prospective original drawing version differs' USING ERRCODE='GP003'; END IF;
  RETURN jsonb_build_object('poolLegId',existing.pool_leg_id,'drawingId',existing.drawing_id::TEXT,'beneficiaryVersion',3);
 END IF;
 SELECT * INTO STRICT offer FROM song_reward_offers WHERE offer_id=leg.offer_id;
 IF leg.beneficiary_version<>3 OR leg.kind<>'megapot_pool' OR leg.status<>'active' OR offer.status<>'active'
  OR observed.attestation_id IS DISTINCT FROM leg.attestation_id OR observed.drawing_locked IS DISTINCT FROM FALSE
  OR observed.expires_at<=clock_timestamp() OR observed.drawing_id<leg.participation_starts_drawing_id
  OR observed.drawing_time-make_interval(secs=>leg.entry_cutoff_seconds)<=clock_timestamp()
  OR observed.drawing_time-make_interval(secs=>leg.entry_cutoff_seconds)>offer.ends_at
  OR NOT EXISTS(SELECT 1 FROM megapot_deployment_attestations WHERE attestation_id=leg.attestation_id AND status='active')
 THEN RAISE EXCEPTION 'new prospective drawing unavailable' USING ERRCODE='GP006'; END IF;
 INSERT INTO megapot_pool_drawings(pool_leg_id,drawing_id,observation_id,status,entry_cutoff_at,ticket_price_ceiling_atomic,
  beneficiary_version,owner_fallback_leaf_salt)
 VALUES(leg.leg_id,observed.drawing_id,observed.observation_id,'entry_open',
  observed.drawing_time-make_interval(secs=>leg.entry_cutoff_seconds),leg.max_ticket_price_atomic,3,p_fallback_salt);
 RETURN jsonb_build_object('poolLegId',leg.leg_id,'drawingId',observed.drawing_id::TEXT,'beneficiaryVersion',3);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/drawing-opening-leaves.sql
CREATE FUNCTION list_owner_megapot_openings_v1(p_observation TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE result JSONB;
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT coalesce(jsonb_agg(jsonb_build_object('poolLegId',leg.leg_id,'drawingId',obs.drawing_id::TEXT)
  ORDER BY leg.leg_id COLLATE "C"),'[]'::JSONB) INTO result
 FROM megapot_drawing_observations obs JOIN song_reward_offer_legs leg ON leg.attestation_id=obs.attestation_id
 JOIN song_reward_offers offer USING(offer_id)
 WHERE obs.observation_id=p_observation AND leg.beneficiary_version=3 AND leg.kind='megapot_pool'
  AND leg.status='active' AND offer.status='active' AND obs.drawing_locked IS FALSE
  AND obs.expires_at>clock_timestamp() AND obs.drawing_id>=leg.participation_starts_drawing_id
  AND obs.drawing_time-make_interval(secs=>leg.entry_cutoff_seconds)>clock_timestamp()
  AND obs.drawing_time-make_interval(secs=>leg.entry_cutoff_seconds)<=offer.ends_at;
 IF jsonb_array_length(result)>256 THEN RAISE EXCEPTION 'bounded opening inventory exceeded' USING ERRCODE='GP006'; END IF;
 RETURN result;
END $$;
CREATE FUNCTION find_owner_megapot_original_drawing_v1(p_leg TEXT,p_observation TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE drawing megapot_pool_drawings%ROWTYPE;
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT d.* INTO drawing FROM megapot_pool_drawings d JOIN megapot_drawing_observations obs ON obs.drawing_id=d.drawing_id
  WHERE d.pool_leg_id=p_leg AND obs.observation_id=p_observation;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF drawing.beneficiary_version<>3 OR octet_length(drawing.owner_fallback_leaf_salt) IS DISTINCT FROM 32 THEN
  RAISE EXCEPTION 'original owner drawing differs' USING ERRCODE='GP003'; END IF;
 RETURN jsonb_build_object('poolLegId',drawing.pool_leg_id,'drawingId',drawing.drawing_id::TEXT,'beneficiaryVersion',3);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/original-answer-source.sql
-- This is an ORIGINAL INTENT, not qualification or a chance. A reserved action
-- can be held before grading, so the acknowledged hold precedes owning COMMIT.
CREATE FUNCTION read_guest_original_reward_answer_source_private_v1(p_source TEXT,p_session TEXT,p_main TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE s study_sessions_v2%ROWTYPE; op guest_participation_operations%ROWTYPE; scope JSONB;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT s FROM study_sessions_v2 WHERE session_id=p_session AND participation_owner_id=p_source
  AND participation_owner_kind='guest';
 SELECT * INTO STRICT op FROM guest_participation_operations WHERE operation_id=p_main AND source_owner_id=p_source
  AND operation_kind='study_answer';
 IF s.account_id IS NOT NULL OR s.persona_id IS NOT NULL OR s.telegram_practice_only IS DISTINCT FROM FALSE
  OR s.guest_reward_mode IS DISTINCT FROM 'megapot_guest_v1' OR s.guest_disclosure_accepted IS DISTINCT FROM TRUE
  OR op.state NOT IN('reserved','completed') THEN RAISE EXCEPTION 'original guest action unavailable' USING ERRCODE='GP003'; END IF;
 PERFORM validate_guest_reward_terms_shape_private_v1(s.guest_reward_terms,s.community_id,s.post_id,s.audio_revision,
  s.lyrics_revision,s.qualification_policy_revision,s.guest_disclosure_version);
 scope:=op.resource_scope::JSONB;
 IF jsonb_typeof(scope) IS DISTINCT FROM 'array' OR jsonb_array_length(scope)<>6
  OR scope->>0 IS DISTINCT FROM 'guest_study_answer_v1' OR scope->>1 IS DISTINCT FROM s.community_id
  OR scope->>2 IS DISTINCT FROM s.session_id OR scope->>4 IS NULL OR scope->>4 !~ '^[1-3]$'
  OR scope->>5 IS NULL OR scope->>5 NOT IN('choice','spoken')
  OR NOT EXISTS(SELECT 1 FROM study_session_items_v2 WHERE session_item_id=scope->>3 AND session_id=s.session_id
   AND participation_owner_id=p_source) THEN RAISE EXCEPTION 'original action scope changed' USING ERRCODE='GP005'; END IF;
 RETURN jsonb_build_object('state','original','sourceOwnerId',p_source,'sessionId',p_session,
  'mainOperationId',op.operation_id,'operationKind',op.operation_kind,'idempotencyKey',op.idempotency_key,
  'requestHash',op.request_hash,'terms',s.guest_reward_terms,'purchaseSafetyDeadlineAt',s.guest_reward_purchase_safety_deadline_at,
  'policyRevision',s.qualification_policy_revision,'scope',scope);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/prepare-original-intent-hold.sql
CREATE FUNCTION prepare_owner_admission_hold_private_v1(p_source TEXT,p_session TEXT,p_main_operation TEXT,
 p_qualification TEXT,p_new_id TEXT,p_fence TEXT,p_salt BYTEA,p_safety_margin INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE facts JSONB; terms JSONB; prior owner_participation_admission_operations%ROWTYPE;
 drawing megapot_pool_drawings%ROWTYPE; observation megapot_drawing_observations%ROWTYPE;
 source_ids TEXT[];
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 -- Controlled caller already owns global/edge/complete source group/session;
 -- raw primitive is not granted and may not reacquire owners after drawing.
 source_ids:=read_locked_owner_participation_group_private_v1(p_source);
 PERFORM 1 FROM study_sessions_v2 WHERE session_id=p_session AND participation_owner_id=p_source FOR SHARE;
 SELECT * INTO prior FROM owner_participation_admission_operations WHERE source_owner_id=p_source AND main_operation_id=p_main_operation;
 IF FOUND THEN
  IF prior.session_id IS DISTINCT FROM p_session THEN
   RAISE EXCEPTION 'original admission key changed' USING ERRCODE='GP005'; END IF;
  RETURN owner_admission_private_receipt_v1(prior.admission_id);
 END IF;
 facts:=read_guest_original_reward_answer_source_private_v1(p_source,p_session,p_main_operation);
 IF facts->>'state' IS DISTINCT FROM 'original' THEN RAISE EXCEPTION 'original reserved action required' USING ERRCODE='GP003'; END IF;
 terms:=facts->'terms';
 IF p_new_id IS NULL OR octet_length(p_new_id) NOT BETWEEN 1 AND 110 OR p_qualification IS NULL
  OR p_fence IS NULL OR p_fence !~ '^[0-9a-f]{64}$' OR p_salt IS NULL OR octet_length(p_salt)<>32
  OR facts->>'purchaseSafetyDeadlineAt' IS NULL THEN
  RAISE EXCEPTION 'explicit trusted admission capture required' USING ERRCODE='22023'; END IF;
 SELECT * INTO STRICT drawing FROM megapot_pool_drawings WHERE pool_leg_id=terms->>'pool_leg_id' AND drawing_id=(terms->>'original_drawing_id')::NUMERIC FOR UPDATE;
 IF drawing.beneficiary_version<>3 OR drawing.status<>'entry_open' OR clock_timestamp()>=drawing.entry_cutoff_at OR clock_timestamp()>=(facts->>'purchaseSafetyDeadlineAt')::TIMESTAMPTZ THEN RETURN jsonb_build_object('state','entry_closed'); END IF;
 IF drawing.entry_cutoff_at IS DISTINCT FROM (terms->>'entry_cutoff_at')::TIMESTAMPTZ THEN
  RAISE EXCEPTION 'original source drawing changed' USING ERRCODE='GP005'; END IF;
 SELECT * INTO STRICT observation FROM megapot_drawing_observations WHERE observation_id=drawing.observation_id;
 -- No salt generation on replay. Salt/fence are server CSPRNG inputs and become
 -- immutable HERE, before an owning admission can be attempted or COMMIT sent.
 INSERT INTO owner_participation_admission_operations(admission_id,source_owner_id,source_owner_kind,source_session_kind,guest_main_operation_id,guest_study_session_id,account_main_operation_id,main_operation_id,operation_kind,idempotency_key,request_hash,
  session_id,qualification_id,pool_leg_id,drawing_id,terms_hash,policy_hash,qualification_policy_revision,entry_cutoff_at,purchase_safety_deadline_at,original_attempt_fence,current_attempt_fence,leaf_salt,state)
 VALUES(p_new_id,p_source,'guest','study_v2',p_main_operation,p_session,NULL,p_main_operation,facts->>'operationKind',facts->>'idempotencyKey',facts->>'requestHash',p_session,p_qualification,
  drawing.pool_leg_id,drawing.drawing_id,terms->>'terms_hash',terms->>'policy_hash',facts->>'policyRevision',drawing.entry_cutoff_at,
  (facts->>'purchaseSafetyDeadlineAt')::TIMESTAMPTZ,p_fence,p_fence,p_salt,'pending');
 INSERT INTO owner_participation_admission_attempts(admission_id,attempt_number,attempt_fence,state) VALUES(p_new_id,1,p_fence,'pending');
 RETURN owner_admission_private_receipt_v1(p_new_id);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/validate-choice-grade.sql
CREATE FUNCTION validate_captured_guest_choice_grade_private_v1(checked JSONB,p_decision JSONB)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE correct BOOLEAN; spent BOOLEAN; attempt INTEGER; accepted TIMESTAMPTZ; schedule JSONB;
BEGIN
 NULL;
 attempt:=(checked->>'attemptNumber')::INTEGER;accepted:=(checked->>'acceptedAt')::TIMESTAMPTZ;
 correct:=checked->'answer'->>'choice_key'=checked->'grader'->>'correctChoiceKey';spent:=correct OR attempt>=3;
 IF p_decision IS NULL OR jsonb_typeof(p_decision)<>'object'
  OR p_decision->>'outcome' IS DISTINCT FROM (CASE WHEN correct THEN 'correct' ELSE 'incorrect' END)
  OR p_decision->>'attemptState' IS DISTINCT FROM (CASE WHEN spent THEN 'spent' ELSE 'retryable' END)
  OR (p_decision->>'correct')::BOOLEAN IS DISTINCT FROM correct
  OR (p_decision->>'spent')::BOOLEAN IS DISTINCT FROM spent
  OR (p_decision->>'resolved')::BOOLEAN IS DISTINCT FROM spent
  OR (p_decision->>'firstPass')::BOOLEAN IS DISTINCT FROM (attempt=1)
  OR (NOT spent AND p_decision->'feedback' IS DISTINCT FROM '{"kind":"none"}'::JSONB)
  OR (spent AND p_decision->'feedback' IS DISTINCT FROM
    jsonb_build_object('kind','choice_reveal','correct_choice_key',checked->'grader'->'correctChoiceKey',
      'correct_text',checked->'grader'->'correctText')||CASE WHEN checked->'grader'->'explanation' IS NULL
      OR checked->'grader'->'explanation'='null'::JSONB THEN '{}'::JSONB ELSE
      jsonb_build_object('explanation',checked->'grader'->'explanation') END) THEN
  RAISE EXCEPTION 'shared choice decision invalid' USING ERRCODE='GP003'; END IF;
 schedule:=p_decision->'review';
 PERFORM require_guest_review_schedule_private_v1(schedule,accepted);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/prepare_guest_reward_json_answer_v1.sql
CREATE FUNCTION prepare_guest_reward_json_answer_v1(
 p_access JSONB,p_operation JSONB,p_community TEXT,p_session TEXT,p_item TEXT,p_attempt INTEGER,p_answer JSONB
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE session study_sessions_v2%ROWTYPE; reservation guest_resource_session_reservations%ROWTYPE;
 operation guest_participation_operations%ROWTYPE; selected RECORD; total INTEGER; remaining INTEGER;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 PERFORM require_guest_study_composition_v1();
 -- Resolve actual immutable source BEFORE accepting caller operation/access.
 SELECT * INTO session FROM study_sessions_v2 WHERE session_id=p_session AND community_id=p_community;
 IF NOT FOUND OR session.participation_owner_kind<>'guest' THEN
  RAISE EXCEPTION 'guest lesson unavailable' USING ERRCODE='GP010'; END IF;
 SELECT * INTO STRICT reservation FROM guest_resource_session_reservations WHERE reservation_id=session.guest_resource_reservation_id;
 PERFORM lock_guest_resource_budget_v1(session.participation_owner_id,reservation.edge_fingerprint);
 PERFORM require_guest_study_learning_access_v1(p_access,session.participation_owner_id);
 PERFORM validate_guest_resource_operation_v1(session.participation_owner_id,p_operation,'study_answer');
 IF NOT can_guest_access_activity_song_v1(p_community,session.post_id) THEN
  RAISE EXCEPTION 'guest lesson unavailable' USING ERRCODE='GP010'; END IF;
 SELECT * INTO operation FROM guest_participation_operations WHERE source_owner_id=session.participation_owner_id
  AND operation_kind='study_answer' AND idempotency_key=p_operation->>'idempotencyKey' FOR UPDATE;
 IF FOUND THEN
  IF ROW(operation.request_hash,operation.resource_scope) IS DISTINCT FROM
   ROW(p_operation->>'requestHash',guest_study_answer_resource_scope_v1(p_community,p_session,p_item,p_attempt,'choice')) THEN
   RAISE EXCEPTION 'original answer changed' USING ERRCODE='GP005'; END IF;
  RETURN jsonb_build_object('state',operation.state,'operationId',operation.operation_id,'result',operation.result_snapshot);
 END IF;
 SELECT * INTO STRICT session FROM study_sessions_v2 WHERE session_id=p_session FOR UPDATE;
 IF session.status<>'active' OR session.expires_at<=clock_timestamp()
  OR session.guest_reward_mode IS DISTINCT FROM 'megapot_guest_v1' OR session.guest_reward_terms IS NULL
  OR session.current_session_item_id IS DISTINCT FROM p_item THEN
  RAISE EXCEPTION 'lesson attempt unavailable' USING ERRCODE='GP003'; END IF;
 SELECT i.item_snapshot,i.maximum_attempts,i.review_item_id,e.content_revision,e.private_grader,
  state.presentation_count,state.lesson_resolved,review.difficulty,review.lapses,review.repetitions,review.stability
 INTO selected FROM study_session_items_v2 i
 JOIN study_exercise_versions e ON e.exercise_version_id=i.exercise_version_id
 JOIN study_lesson_item_state_v2 state ON state.session_item_id=i.session_item_id AND state.session_id=i.session_id
 JOIN study_review_items review ON review.review_item_id=i.review_item_id AND review.participation_owner_id=i.participation_owner_id
 WHERE i.session_item_id=p_item AND i.session_id=p_session AND i.participation_owner_id=session.participation_owner_id
 FOR UPDATE OF i,state,review;
 IF NOT FOUND OR selected.item_snapshot->>'exercise_type' IS DISTINCT FROM 'translation_choice'
  OR selected.private_grader->>'kind' IS DISTINCT FROM 'exact_choice_v1' OR selected.maximum_attempts IS DISTINCT FROM 3
  OR selected.lesson_resolved IS DISTINCT FROM FALSE OR p_attempt IS NULL OR p_attempt NOT BETWEEN 1 AND 3 OR p_attempt<>selected.presentation_count+1
  OR p_answer IS NULL OR jsonb_typeof(p_answer)<>'object' OR p_answer->>'kind' IS DISTINCT FROM 'single_select'
  OR p_answer-'kind'-'choice_key'<>'{}'::JSONB OR jsonb_typeof(p_answer->'choice_key') IS DISTINCT FROM 'string'
  OR jsonb_typeof(selected.private_grader->'correct_choice_key') IS DISTINCT FROM 'string'
  OR jsonb_typeof(selected.private_grader->'correct_text') IS DISTINCT FROM 'string'
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(selected.item_snapshot->'presentation'->'choices') choice
    WHERE choice->>'choice_key'=p_answer->>'choice_key') THEN
  RAISE EXCEPTION 'lesson attempt unavailable' USING ERRCODE='GP003'; END IF;
 SELECT count(*)::INTEGER,count(*) FILTER(WHERE NOT lesson_resolved)::INTEGER INTO total,remaining
  FROM study_lesson_item_state_v2 WHERE session_id=p_session;
 RETURN jsonb_build_object('state','candidate','sourceOwnerId',session.participation_owner_id,
  'communityId',p_community,'sessionId',p_session,'sessionItemId',p_item,'attemptNumber',p_attempt,'answer',p_answer,
  'item',selected.item_snapshot,'reviewItemId',selected.review_item_id,'contentRevision',selected.content_revision,
  'grader',jsonb_build_object('correctChoiceKey',selected.private_grader->'correct_choice_key',
    'correctText',selected.private_grader->'correct_text','explanation',selected.private_grader->'explanation'),
  'review',jsonb_build_object('difficulty',selected.difficulty,'lapses',selected.lapses,'repetitions',selected.repetitions,'stability',selected.stability),
  'priorPresentationCount',session.presentation_count,'currentPresentedAt',session.current_presented_at,
  'acceptedAt',transaction_timestamp(),'totalCards',total,'remainingCards',remaining,
  'resourceReservationId',reservation.reservation_id);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/reserve-choice-with-original-hold.sql
CREATE FUNCTION reserve_guest_reward_choice_with_hold_v1(p_access JSONB,p_operation JSONB,
 p_capture JSONB,p_decision JSONB,p_main TEXT,p_attempt TEXT,p_command TEXT,p_nonce TEXT,
 p_admission TEXT,p_fence TEXT,p_salt BYTEA,p_safety_margin INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE checked JSONB; existing owner_captured_guest_choice_commands%ROWTYPE;
 hold JSONB; source_id TEXT; qualification TEXT;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 checked:=prepare_guest_reward_json_answer_v1(p_access,p_operation,p_capture->>'communityId',p_capture->>'sessionId',
  p_capture->>'sessionItemId',(p_capture->>'attemptNumber')::INTEGER,p_capture->'answer');
 IF checked->>'state'<>'candidate' THEN
  SELECT * INTO STRICT existing FROM owner_captured_guest_choice_commands WHERE operation_id=checked->>'operationId';
  IF existing.source_owner_id IS DISTINCT FROM p_operation->>'sourceOwnerId' THEN
   RAISE EXCEPTION 'original captured source changed' USING ERRCODE='GP005'; END IF;
  IF checked->>'state'='completed' THEN RETURN checked; END IF;
  RETURN jsonb_build_object('state','captured','operationId',existing.operation_id,'commandId',existing.command_id,
   'originalContinuationNonce',existing.original_continuation_nonce);
 END IF;
 IF checked IS DISTINCT FROM p_capture THEN RAISE EXCEPTION 'original choice source changed' USING ERRCODE='GP005'; END IF;
 PERFORM validate_captured_guest_choice_grade_private_v1(checked,p_decision);
 IF p_main IS NULL OR char_length(p_main) NOT BETWEEN 1 AND 128 OR p_attempt IS NULL OR char_length(p_attempt) NOT BETWEEN 1 AND 128
  OR p_command IS NULL OR char_length(p_command) NOT BETWEEN 1 AND 128 OR p_nonce IS NULL OR p_nonce !~ '^[0-9a-f]{64}$' THEN
  RAISE EXCEPTION 'server original choice identifiers required' USING ERRCODE='22023'; END IF;
 source_id:=checked->>'sourceOwnerId';
 IF EXISTS(SELECT 1 FROM owner_captured_guest_choice_commands WHERE source_owner_id=source_id AND session_id=checked->>'sessionId' AND state='reserved')
  OR EXISTS(SELECT 1 FROM study_spoken_answer_commands WHERE participation_owner_id=source_id AND session_id=checked->>'sessionId' AND state='reserved') THEN
  RAISE EXCEPTION 'original session command unresolved' USING ERRCODE='GP003'; END IF;
 INSERT INTO guest_participation_operations(operation_id,source_owner_id,operation_kind,resource_scope,
  idempotency_key,request_hash,state,created_at)
 VALUES(p_main,source_id,'study_answer',guest_study_answer_resource_scope_v1(checked->>'communityId',checked->>'sessionId',
  checked->>'sessionItemId',(checked->>'attemptNumber')::INTEGER,'choice'),p_operation->>'idempotencyKey',p_operation->>'requestHash','reserved',clock_timestamp());
 qualification:='guest_qualification_'||encode(sha256(convert_to(jsonb_build_array(source_id,checked->>'sessionId')::TEXT,'UTF8')),'hex');
 -- A known ordinary preparation refusal never fabricates admission. The actual
 -- chosen grade/capture remains accepted and can be finalized without new money.
 BEGIN
  hold:=prepare_owner_admission_hold_private_v1(source_id,checked->>'sessionId',p_main,qualification,
   p_admission,p_fence,p_salt,p_safety_margin);
 EXCEPTION WHEN lock_not_available THEN
  hold:=jsonb_build_object('state','unavailable');
 END;
 INSERT INTO owner_captured_guest_choice_commands(command_id,source_owner_id,operation_id,session_id,session_item_id,
  attempt_number,attempt_id,original_continuation_nonce,original_capture,original_grade,original_admission_result,state)
 VALUES(p_command,source_id,p_main,checked->>'sessionId',checked->>'sessionItemId',(checked->>'attemptNumber')::INTEGER,
  p_attempt,p_nonce,checked,p_decision-'review',hold,'reserved');
 RETURN jsonb_build_object('state','captured','operationId',p_main,'commandId',p_command,
  'originalContinuationNonce',p_nonce);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/choice-original-recovery.sql
-- Foreground lookup needs confirmed same-origin recovery proof, never a live
-- learning lease after an accepted capture. Source is resolved from real lesson.
CREATE FUNCTION find_owner_guest_reward_choice_for_answer_v1(p_access JSONB,p_operation JSONB,
 p_community TEXT,p_session TEXT,p_item TEXT,p_attempt INTEGER,p_answer JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE s study_sessions_v2%ROWTYPE; cmd owner_captured_guest_choice_commands%ROWTYPE;
 main guest_participation_operations%ROWTYPE; rsv guest_resource_session_reservations%ROWTYPE;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 SELECT * INTO s FROM study_sessions_v2 WHERE session_id=p_session AND community_id=p_community AND participation_owner_kind='guest';
 IF NOT FOUND THEN RAISE EXCEPTION 'guest lesson unavailable' USING ERRCODE='GP010'; END IF;
 -- Preflight proof before component/source locks follows actual258 lock ordering;
 -- helper then locks/rechecks full correlated authority, without learning age.
 PERFORM validate_guest_resource_operation_v1(s.participation_owner_id,p_operation,'study_answer');
 SELECT * INTO STRICT rsv FROM guest_resource_session_reservations WHERE reservation_id=s.guest_resource_reservation_id;
 PERFORM lock_guest_resource_budget_v1(s.participation_owner_id,rsv.edge_fingerprint);
 PERFORM require_guest_audio_recovery_access_private_v1(p_access,s.participation_owner_id);
 IF s.guest_reward_mode='practice_only' AND s.guest_reward_terms IS NULL THEN RETURN jsonb_build_object('state','practice_only'); END IF;
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT * INTO STRICT s FROM study_sessions_v2 WHERE session_id=p_session FOR UPDATE;
 -- Fresh statement after original source/session waits serializes sent-COMMIT
 -- unknown preparation. Never restart from an earlier speculative absence.
 SELECT * INTO main FROM guest_participation_operations WHERE source_owner_id=s.participation_owner_id
  AND operation_kind='study_answer' AND idempotency_key=p_operation->>'idempotencyKey';
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF main.request_hash IS DISTINCT FROM p_operation->>'requestHash'
  OR main.resource_scope IS DISTINCT FROM guest_study_answer_resource_scope_v1(p_community,p_session,p_item,p_attempt,'choice') THEN
  RAISE EXCEPTION 'original answer key changed' USING ERRCODE='GP005'; END IF;
 SELECT * INTO cmd FROM owner_captured_guest_choice_commands WHERE operation_id=main.operation_id AND source_owner_id=s.participation_owner_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'reserved main lacks its atomic captured choice' USING ERRCODE='GP003'; END IF;
 IF cmd.original_capture->'answer' IS DISTINCT FROM p_answer OR cmd.session_id IS DISTINCT FROM p_session
  OR cmd.session_item_id IS DISTINCT FROM p_item OR cmd.attempt_number IS DISTINCT FROM p_attempt THEN
  RAISE EXCEPTION 'original choice payload changed' USING ERRCODE='GP005'; END IF;
 IF cmd.state='completed' THEN
  IF main.state<>'completed' OR cmd.result_snapshot IS DISTINCT FROM main.result_snapshot THEN
   RAISE EXCEPTION 'actual original result differs' USING ERRCODE='GP003'; END IF;
  RETURN jsonb_build_object('state','completed','operationId',main.operation_id,'result',main.result_snapshot); END IF;
 RETURN jsonb_build_object('state','captured','operationId',cmd.operation_id,'commandId',cmd.command_id,
  'originalContinuationNonce',cmd.original_continuation_nonce);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/owning-drawing-lock.sql
-- Called after original full source-group/resource/media/session locks but
-- BEFORE grade writes/qualification, so no owner locks are acquired after draw.
-- It does not manufacture a hold if the separate acknowledged preparation failed.
CREATE FUNCTION lock_guest_reward_owning_draw_private_v1(p_source TEXT,p_main TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE hold owner_participation_admission_operations%ROWTYPE; leg song_reward_offer_legs%ROWTYPE;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT * INTO hold FROM owner_participation_admission_operations WHERE source_owner_id=p_source AND main_operation_id=p_main;
 IF NOT FOUND THEN RETURN; END IF;
 PERFORM 1 FROM megapot_pool_drawings WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id FOR UPDATE;
 SELECT * INTO STRICT leg FROM song_reward_offer_legs WHERE leg_id=hold.pool_leg_id FOR UPDATE;
 IF leg.funding_source='shared_sponsor_budget' THEN
  PERFORM 1 FROM platform_sponsorship_budgets WHERE sponsor_account_id=leg.funder_account_id
   AND chain_id=leg.chain_id AND token_address=leg.token_address FOR UPDATE;
 END IF;
 PERFORM 1 FROM owner_participation_admission_operations WHERE admission_id=hold.admission_id FOR UPDATE;
END $$;

-- Source: owner-study-reward-producer-proposal-v2/read-captured-choice.sql
-- Called only by the owning continuation after original reservation ACK, or the
-- controlled original-capture reconciliation actor. No browser read grant.
CREATE FUNCTION read_captured_guest_reward_choice_v1(p_command TEXT,p_nonce TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE cmd owner_captured_guest_choice_commands%ROWTYPE; main guest_participation_operations%ROWTYPE;
 rsv guest_resource_session_reservations%ROWTYPE; s study_sessions_v2%ROWTYPE;
 item study_session_items_v2%ROWTYPE; state study_lesson_item_state_v2%ROWTYPE;
 review study_review_items%ROWTYPE; captured JSONB; effective_review TIMESTAMPTZ;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 SELECT * INTO STRICT cmd FROM owner_captured_guest_choice_commands WHERE command_id=p_command;
 IF p_nonce IS NULL OR cmd.original_continuation_nonce IS DISTINCT FROM p_nonce THEN
  RAISE EXCEPTION 'original server choice continuation changed' USING ERRCODE='GP005'; END IF;
 SELECT * INTO STRICT s FROM study_sessions_v2 WHERE session_id=cmd.session_id AND participation_owner_id=cmd.source_owner_id;
 SELECT * INTO STRICT rsv FROM guest_resource_session_reservations WHERE reservation_id=s.guest_resource_reservation_id;
 -- The complete budget/group primitive is replaced atomically by this full
 -- successor: topology→global/edge→sorted users/owners, same original counters.
 PERFORM lock_guest_resource_budget_v1(cmd.source_owner_id,rsv.edge_fingerprint);
 SELECT * INTO STRICT s FROM study_sessions_v2 WHERE session_id=cmd.session_id FOR UPDATE;
 SELECT * INTO STRICT cmd FROM owner_captured_guest_choice_commands WHERE command_id=p_command FOR UPDATE;
 SELECT * INTO STRICT main FROM guest_participation_operations WHERE operation_id=cmd.operation_id FOR UPDATE;
 IF main.source_owner_id IS DISTINCT FROM cmd.source_owner_id OR main.operation_kind<>'study_answer'
  OR main.resource_scope IS DISTINCT FROM guest_study_answer_resource_scope_v1(s.community_id,s.session_id,cmd.session_item_id,cmd.attempt_number,'choice')
  OR cmd.original_capture->>'sourceOwnerId' IS DISTINCT FROM cmd.source_owner_id
  OR cmd.original_capture->>'sessionId' IS DISTINCT FROM cmd.session_id
  OR cmd.original_capture->>'sessionItemId' IS DISTINCT FROM cmd.session_item_id
  OR (cmd.original_capture->>'attemptNumber')::INTEGER IS DISTINCT FROM cmd.attempt_number
  OR cmd.original_capture->>'resourceReservationId' IS DISTINCT FROM rsv.reservation_id
  OR ROW(rsv.source_owner_id,rsv.session_id) IS DISTINCT FROM ROW(cmd.source_owner_id,cmd.session_id)
 THEN RAISE EXCEPTION 'original source command changed' USING ERRCODE='GP005'; END IF;
 IF cmd.state='completed' THEN
  IF main.state<>'completed' OR main.result_snapshot IS DISTINCT FROM cmd.result_snapshot THEN
   RAISE EXCEPTION 'original completed choice outcome differs' USING ERRCODE='GP003'; END IF;
  RETURN jsonb_build_object('state','completed','operationId',main.operation_id,'result',cmd.result_snapshot); END IF;
 IF main.state<>'reserved' OR s.status<>'active' OR s.current_session_item_id IS DISTINCT FROM cmd.session_item_id
  OR s.presentation_count IS DISTINCT FROM (cmd.original_capture->>'priorPresentationCount')::BIGINT THEN
  RAISE EXCEPTION 'original owned choice slot changed' USING ERRCODE='GP003'; END IF;
 SELECT * INTO STRICT item FROM study_session_items_v2 WHERE session_item_id=cmd.session_item_id AND session_id=cmd.session_id FOR UPDATE;
 SELECT * INTO STRICT state FROM study_lesson_item_state_v2 WHERE session_item_id=cmd.session_item_id AND session_id=cmd.session_id FOR UPDATE;
 SELECT * INTO STRICT review FROM study_review_items WHERE review_item_id=item.review_item_id AND participation_owner_id=cmd.source_owner_id FOR UPDATE;
 IF item.item_snapshot IS DISTINCT FROM cmd.original_capture->'item' OR item.review_item_id IS DISTINCT FROM cmd.original_capture->>'reviewItemId'
  OR state.lesson_resolved IS DISTINCT FROM FALSE OR state.presentation_count+1<>cmd.attempt_number THEN
  RAISE EXCEPTION 'original choice item changed' USING ERRCODE='GP003'; END IF;
 captured:=cmd.original_capture||jsonb_build_object('review',jsonb_build_object('difficulty',review.difficulty,'lapses',review.lapses,
  'repetitions',review.repetitions,'stability',review.stability));
 -- A different genuine lesson may advance the same review between reservation
 -- and continuation. Preserve original grade/acceptedAt and schedule from current
 -- review at a monotone effective instant, never rewind accepted review history.
 effective_review:=greatest((captured->>'acceptedAt')::TIMESTAMPTZ,review.last_reviewed_at);
 RETURN jsonb_build_object('state','candidate','commandId',cmd.command_id,'operationId',main.operation_id,
  'attemptId',cmd.attempt_id,'capture',captured,'grade',cmd.original_grade,'originalAdmissionResult',cmd.original_admission_result,
  'effectiveReviewAt',to_char(effective_review AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
END $$;

-- Source: owner-study-reward-producer-proposal-v2/apply-captured-choice.sql
CREATE FUNCTION apply_captured_guest_reward_choice_v1(
 p_command TEXT,p_nonce TEXT,p_capture JSONB,p_decision JSONB,p_expected_fence TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE checked JSONB; item JSONB; correct BOOLEAN; spent BOOLEAN; accepted TIMESTAMPTZ; schedule JSONB;
 source_id TEXT; sid TEXT; iid TEXT; attempt INTEGER; remaining INTEGER; total INTEGER; retained JSONB; p_operation_id TEXT; p_attempt_id TEXT; p_operation JSONB; review_at TIMESTAMPTZ;
BEGIN
 retained:=read_captured_guest_reward_choice_v1(p_command,p_nonce);
 IF retained->>'state'<>'candidate' THEN RETURN retained; END IF;
 checked:=retained->'capture';
 IF checked IS DISTINCT FROM p_capture OR p_decision-'review' IS DISTINCT FROM retained->'grade' THEN
  RAISE EXCEPTION 'accepted choice grade/source changed' USING ERRCODE='GP005'; END IF;
 p_operation_id:=retained->>'operationId';p_attempt_id:=retained->>'attemptId';
 SELECT jsonb_build_object('sourceOwnerId',source_owner_id,'kind',operation_kind,'idempotencyKey',idempotency_key,'requestHash',request_hash)
 INTO STRICT p_operation FROM guest_participation_operations WHERE operation_id=p_operation_id;
 review_at:=(retained->>'effectiveReviewAt')::TIMESTAMPTZ;
 PERFORM lock_guest_reward_owning_draw_private_v1(checked->>'sourceOwnerId',p_operation_id);
 PERFORM require_guest_reward_owning_attempt_private_v1(checked->>'sourceOwnerId',p_operation_id,p_expected_fence);
 item:=checked->'item';source_id:=checked->>'sourceOwnerId';sid:=checked->>'sessionId';iid:=checked->>'sessionItemId';
 attempt:=(checked->>'attemptNumber')::INTEGER;accepted:=(checked->>'acceptedAt')::TIMESTAMPTZ;
 correct:=checked->'answer'->>'choice_key'=checked->'grader'->>'correctChoiceKey';spent:=correct OR attempt>=3;
 IF p_decision IS NULL OR jsonb_typeof(p_decision)<>'object'
  OR p_decision->>'outcome' IS DISTINCT FROM (CASE WHEN correct THEN 'correct' ELSE 'incorrect' END)
  OR p_decision->>'attemptState' IS DISTINCT FROM (CASE WHEN spent THEN 'spent' ELSE 'retryable' END)
  OR (p_decision->>'correct')::BOOLEAN IS DISTINCT FROM correct
  OR (p_decision->>'spent')::BOOLEAN IS DISTINCT FROM spent
  OR (p_decision->>'resolved')::BOOLEAN IS DISTINCT FROM spent
  OR (p_decision->>'firstPass')::BOOLEAN IS DISTINCT FROM (attempt=1)
  OR (NOT spent AND p_decision->'feedback' IS DISTINCT FROM '{"kind":"none"}'::JSONB)
  OR (spent AND p_decision->'feedback' IS DISTINCT FROM
    jsonb_build_object('kind','choice_reveal','correct_choice_key',checked->'grader'->'correctChoiceKey',
      'correct_text',checked->'grader'->'correctText')||CASE WHEN checked->'grader'->'explanation' IS NULL
      OR checked->'grader'->'explanation'='null'::JSONB THEN '{}'::JSONB ELSE
      jsonb_build_object('explanation',checked->'grader'->'explanation') END) THEN
  RAISE EXCEPTION 'shared choice decision invalid' USING ERRCODE='GP003'; END IF;
 schedule:=p_decision->'review';
 PERFORM require_guest_review_schedule_private_v1(schedule,review_at);
 INSERT INTO study_attempts_v2(attempt_id,session_item_id,attempt_number,submission_kind,submission_evidence,outcome,first_pass,
  attempt_state,feedback_kind,feedback_evidence,grader_policy_revision,feedback_policy_revision,accepted_at,idempotency_key,request_hash,
  study_unit_id,exercise_kind,learning_language,target_language,learner_band,source_line_revision,language_profile_revision,
  localization_revision,grading_revision,review_schedule_version,presented_at,answered_at)
 VALUES(p_attempt_id,iid,attempt,'single_select',checked->'answer',CASE WHEN correct THEN 'correct' ELSE 'incorrect' END,attempt=1,
  CASE WHEN spent THEN 'spent' ELSE 'retryable' END,p_decision->'feedback'->>'kind',p_decision->'feedback',
  item->>'grader_policy_revision',item->>'feedback_policy_revision',accepted,p_operation->>'idempotencyKey',p_operation->>'requestHash',
  item->'line'->>'study_unit_id','translation_choice',item->'languages'->>'learning_language',item->'languages'->>'target_language',item->>'learner_band',
  (item->'line'->>'line_version')::BIGINT,(item->>'language_profile_revision')::BIGINT,(checked->>'contentRevision')::BIGINT,
  item->>'grader_policy_revision','study_review_schedule_v1',(checked->>'currentPresentedAt')::TIMESTAMPTZ,accepted);
 INSERT INTO study_presentations_v2(presentation_id,session_id,session_item_id,presentation_number,queue_ordinal,presented_at,answered_at,outcome)
 VALUES('study-presentation-'||p_attempt_id,sid,iid,attempt,(checked->>'priorPresentationCount')::BIGINT,
  (checked->>'currentPresentedAt')::TIMESTAMPTZ,accepted,CASE WHEN correct THEN 'correct' ELSE 'incorrect' END);
 UPDATE study_review_items SET difficulty=(schedule->>'difficulty')::NUMERIC,due_at=(schedule->>'dueAt')::TIMESTAMPTZ,
  lapses=(schedule->>'lapses')::BIGINT,repetitions=(schedule->>'repetitions')::BIGINT,stability=(schedule->>'stability')::NUMERIC,
  review_state=schedule->>'state',last_reviewed_at=review_at,updated_at=review_at,
  scheduler_state=jsonb_build_object('difficulty',schedule->'difficulty','due_at',schedule->'dueAt','lapses',schedule->'lapses',
    'repetitions',schedule->'repetitions','stability',schedule->'stability','state',schedule->'state')
 WHERE review_item_id=checked->>'reviewItemId' AND participation_owner_id=source_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'review source changed' USING ERRCODE='GP003'; END IF;
 UPDATE study_lesson_item_state_v2 SET presentation_count=attempt,last_queue_ordinal=(checked->>'priorPresentationCount')::BIGINT,
  mastered=correct,lesson_resolved=spent,updated_at=accepted WHERE session_item_id=iid AND session_id=sid AND presentation_count=attempt-1;
 IF NOT FOUND THEN RAISE EXCEPTION 'presentation source changed' USING ERRCODE='GP003'; END IF;
 SELECT count(*)::INTEGER,count(*) FILTER(WHERE NOT lesson_resolved)::INTEGER INTO total,remaining FROM study_lesson_item_state_v2 WHERE session_id=sid;
 RETURN jsonb_build_object('state','mutated','operationId',p_operation_id,'capture',checked,'decision',p_decision,
  'totalCards',total,'remainingCards',remaining,'priorPresentationCount',(checked->>'priorPresentationCount')::INTEGER);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/qualified-owning-guest-facts.sql
-- Exact owning-transaction learning receipts. Reserved main is accepted only
-- with its real captured choice command or immutable successful provider CP.
-- No caller result/session/score substitutes these persisted source facts.
CREATE OR REPLACE FUNCTION read_qualified_guest_study_facts_private_v1(p_source TEXT,p_session TEXT,p_main_operation TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE s study_sessions_v2%ROWTYPE; op guest_participation_operations%ROWTYPE;
 scope JSONB; total INTEGER; presented INTEGER; correct INTEGER; needed INTEGER;
BEGIN
 SELECT * INTO STRICT s FROM study_sessions_v2 WHERE session_id=p_session AND participation_owner_id=p_source AND participation_owner_kind='guest';
 SELECT * INTO STRICT op FROM guest_participation_operations WHERE operation_id=p_main_operation AND source_owner_id=p_source AND operation_kind='study_answer';
 IF s.account_id IS NOT NULL OR s.persona_id IS NOT NULL OR s.telegram_practice_only IS DISTINCT FROM FALSE
  OR s.guest_reward_mode IS DISTINCT FROM 'megapot_guest_v1' OR s.guest_disclosure_accepted IS DISTINCT FROM TRUE
  OR op.state NOT IN('reserved','completed') THEN
  RAISE EXCEPTION 'original rewarded lesson required' USING ERRCODE='GP003'; END IF;
 PERFORM validate_guest_reward_terms_shape_private_v1(s.guest_reward_terms,s.community_id,s.post_id,
  s.audio_revision,s.lyrics_revision,s.qualification_policy_revision,s.guest_disclosure_version);
 IF NOT EXISTS(SELECT 1 FROM qualification_policy_versions WHERE qualification_policy_version_id=s.qualification_policy_revision
  AND activity_key='study' AND policy_kind='study_session_first_pass_v2' AND policy_document='{"required_correct_bps":7000}'::JSONB) THEN
  RAISE EXCEPTION 'accepted qualification policy unavailable' USING ERRCODE='GP003'; END IF;
 scope:=op.resource_scope::JSONB;
 IF jsonb_typeof(scope) IS DISTINCT FROM 'array' OR jsonb_array_length(scope)<>6
  OR scope->>0 IS DISTINCT FROM 'guest_study_answer_v1' OR scope->>1 IS DISTINCT FROM s.community_id
  OR scope->>2 IS DISTINCT FROM s.session_id OR scope->>4 IS NULL OR scope->>4 !~ '^[1-3]$'
  OR scope->>5 IS NULL OR scope->>5 NOT IN('choice','spoken') THEN
  RAISE EXCEPTION 'original answer scope changed' USING ERRCODE='GP005'; END IF;
 IF scope->>5='choice' THEN
  IF NOT EXISTS(SELECT 1 FROM owner_captured_guest_choice_commands c WHERE c.source_owner_id=p_source
   AND c.session_id=p_session AND c.operation_id=op.operation_id AND c.session_item_id=scope->>3
   AND c.attempt_number=(scope->>4)::INTEGER) THEN
   RAISE EXCEPTION 'accepted original choice capture missing' USING ERRCODE='GP003'; END IF;
 ELSE
  IF NOT EXISTS(SELECT 1 FROM guest_study_spoken_captures c JOIN guest_study_spoken_checkpoints cp USING(capture_id)
   JOIN guest_resource_provider_calls call ON call.call_id=c.provider_call_id AND call.checkpoint_id=cp.checkpoint_id
   WHERE c.source_owner_id=p_source AND c.session_id=p_session AND c.operation_id=op.operation_id
    AND c.session_item_id=scope->>3 AND c.attempt_number=(scope->>4)::INTEGER
    AND c.idempotency_key=op.idempotency_key AND c.request_hash=op.request_hash AND call.disposition='completed') THEN
   RAISE EXCEPTION 'accepted original provider checkpoint missing' USING ERRCODE='GP003'; END IF;
 END IF;
 IF s.status='active' AND s.completed_at IS NULL THEN RETURN jsonb_build_object('state','not_yet_qualified'); END IF;
 IF s.status IS DISTINCT FROM 'completed' OR s.completed_at IS NULL THEN
  RAISE EXCEPTION 'actual lesson completion unavailable' USING ERRCODE='GP003'; END IF;
 IF NOT EXISTS(SELECT 1 FROM study_session_items_v2 i JOIN study_attempts_v2 a USING(session_item_id)
  WHERE i.session_id=p_session AND i.participation_owner_id=p_source AND i.session_item_id=scope->>3
   AND a.attempt_number=(scope->>4)::INTEGER AND a.attempt_state='spent' AND a.answered_at=s.completed_at
   AND a.request_hash=op.request_hash AND (
    (scope->>5='choice' AND a.idempotency_key=op.idempotency_key
     AND EXISTS(SELECT 1 FROM owner_captured_guest_choice_commands c WHERE c.operation_id=op.operation_id AND c.attempt_id=a.attempt_id
      AND c.original_capture->'answer'=a.submission_evidence AND c.original_grade->>'outcome'=a.outcome))
    OR (scope->>5='spoken' AND EXISTS(SELECT 1 FROM guest_study_spoken_captures c
     JOIN guest_study_spoken_checkpoints cp USING(capture_id) WHERE c.operation_id=op.operation_id
      AND c.command_id=a.idempotency_key AND c.attempt_id=a.attempt_id AND c.artifact_id=a.learner_audio_artifact_id)))) THEN
  RAISE EXCEPTION 'owning completion lacks its actual spent receipt' USING ERRCODE='GP005'; END IF;
 IF op.state='completed' AND (op.result_snapshot#>>'{answer,session,session_id}' IS DISTINCT FROM p_session
  OR op.result_snapshot#>>'{answer,session,status}' IS DISTINCT FROM 'completed') THEN
  RAISE EXCEPTION 'immutable completed answer differs' USING ERRCODE='GP005'; END IF;
 SELECT count(*)::INTEGER,
  count(*) FILTER(WHERE EXISTS(SELECT 1 FROM study_attempts_v2 a WHERE a.session_item_id=i.session_item_id AND a.attempt_state='spent'))::INTEGER,
  count(*) FILTER(WHERE EXISTS(SELECT 1 FROM study_attempts_v2 a WHERE a.session_item_id=i.session_item_id AND a.attempt_number=1 AND a.outcome='correct'))::INTEGER
 INTO total,presented,correct FROM study_session_items_v2 i WHERE i.session_id=p_session AND i.participation_owner_id=p_source;
 needed:=greatest(1,ceil(7.0*total/10)::INTEGER);
 IF total=0 OR presented<>total OR correct<needed THEN RETURN jsonb_build_object('state','ineligible'); END IF;
 RETURN jsonb_build_object('state','qualified','sourceOwnerId',p_source,'sessionId',p_session,
  'mainOperationId',op.operation_id,'operationKind',op.operation_kind,'idempotencyKey',op.idempotency_key,
  'requestHash',op.request_hash,'communityId',s.community_id,'postId',s.post_id,'audioRevision',s.audio_revision,
  'policyRevision',s.qualification_policy_revision,'scoreBps',floor(10000.0*correct/total)::INTEGER,
  'qualifiedAt',s.completed_at,'streakDay',(s.completed_at AT TIME ZONE s.timezone)::DATE,
  'evidence',jsonb_build_object('kind','study_session_first_pass_v2','qualifying_exercise_count',total,
   'first_pass_correct',correct,'required_correct',needed),'terms',s.guest_reward_terms);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/admit-owning-successor.sql
CREATE FUNCTION admit_guest_owner_participation_private_v1(p_id TEXT,p_expected_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE hold owner_participation_admission_operations%ROWTYPE; source_ids TEXT[];
 facts JSONB; terms JSONB; drawing megapot_pool_drawings%ROWTYPE; leg song_reward_offer_legs%ROWTYPE;
 offer song_reward_offers%ROWTYPE; observation megapot_drawing_observations%ROWTYPE;
 policy RECORD; funding platform_sponsorship_budgets%ROWTYPE; now_at TIMESTAMPTZ; result JSONB; eligibility_id TEXT;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT hold FROM owner_participation_admission_operations WHERE admission_id=p_id;
 source_ids:=read_locked_owner_participation_group_private_v1(hold.source_owner_id);
 SELECT * INTO STRICT drawing FROM megapot_pool_drawings WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id FOR UPDATE;
 SELECT * INTO STRICT leg FROM song_reward_offer_legs WHERE leg_id=hold.pool_leg_id FOR UPDATE;
 -- Journal/qualification/evidence locks are AFTER source/session/drawing/funding.
 SELECT * INTO STRICT hold FROM owner_participation_admission_operations WHERE admission_id=p_id FOR UPDATE;
 IF hold.state<>'pending' THEN
  IF p_expected_fence IS NOT NULL THEN RAISE EXCEPTION 'old owning admission is fenced' USING ERRCODE='GP005'; END IF;
  RETURN hold.result_snapshot;
 END IF;
 PERFORM require_original_owner_admission_attempt_started_v1(hold.admission_id,p_expected_fence);
 facts:=read_qualified_guest_study_facts_private_v1(hold.source_owner_id,hold.session_id,hold.main_operation_id);
 IF facts->>'state' IN('not_yet_qualified','ineligible') THEN
  result:=jsonb_build_object('state',facts->>'state');
  UPDATE owner_participation_admission_operations SET state='not_admitted',result_snapshot=result,resolved_at=clock_timestamp() WHERE admission_id=p_id AND state='pending';
  UPDATE owner_participation_admission_attempts SET state='not_admitted',resolved_at=clock_timestamp() WHERE admission_id=p_id AND attempt_fence=p_expected_fence AND state='pending';
  RETURN result;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM activity_qualifications q WHERE q.qualification_id=hold.qualification_id
  AND q.participation_owner_id=hold.source_owner_id AND q.participation_owner_kind='guest'
  AND q.guest_main_operation_id=hold.main_operation_id AND q.study_session_id=hold.session_id) THEN
  RAISE EXCEPTION 'owning immutable qualification missing' USING ERRCODE='GP003'; END IF;
 terms:=facts->'terms';
 SELECT * INTO STRICT offer FROM song_reward_offers WHERE offer_id=leg.offer_id;
 SELECT obs.* INTO observation FROM megapot_drawing_observations obs
 JOIN megapot_deployment_attestations att ON att.attestation_id=obs.attestation_id AND att.status='active'
 WHERE obs.attestation_id=leg.attestation_id AND obs.drawing_id=drawing.drawing_id
 ORDER BY obs.block_number DESC,obs.observation_id COLLATE "C" LIMIT 1;
 IF leg.funding_source='shared_sponsor_budget' THEN
  SELECT * INTO funding FROM platform_sponsorship_budgets WHERE sponsor_account_id=leg.funder_account_id AND chain_id=leg.chain_id AND token_address=leg.token_address FOR UPDATE;
 END IF;
 SELECT policy_hash,policy_version_id INTO policy FROM policy_versions WHERE community_id=offer.community_id
  AND policy_version_id=offer.reward_policy_version_id AND policy_purpose='reward' AND uniqueness_authority_id=offer.offer_id;
 -- Validate all source terms/server-frozen policy and funding. No client flag,
 -- fabricated account, persona or new drawing selection supplies this authority.
 IF drawing.status<>'entry_open' OR clock_timestamp()>=drawing.entry_cutoff_at OR clock_timestamp()>=hold.purchase_safety_deadline_at THEN result:=jsonb_build_object('state','entry_closed');
 ELSIF facts->>'state' IS DISTINCT FROM 'qualified' OR drawing.beneficiary_version<>3 OR offer.status<>'active' OR leg.status<>'active' OR leg.kind<>'megapot_pool'
  OR terms->>'offer_id' IS DISTINCT FROM offer.offer_id OR terms->>'pool_leg_id' IS DISTINCT FROM leg.leg_id
  OR terms->>'original_drawing_id' IS DISTINCT FROM drawing.drawing_id::TEXT
  OR terms->>'policy_hash' IS DISTINCT FROM regexp_replace(policy.policy_hash,'^0x','')
  OR terms->>'terms_hash' IS DISTINCT FROM regexp_replace(leg.leg_terms_hash,'^0x','')
  OR terms->>'entry_cutoff_at' IS NULL OR (terms->>'entry_cutoff_at')::TIMESTAMPTZ IS DISTINCT FROM drawing.entry_cutoff_at
  OR facts->>'communityId' IS DISTINCT FROM offer.community_id OR facts->>'postId' IS DISTINCT FROM offer.post_id
  OR (facts->>'audioRevision')::BIGINT IS DISTINCT FROM offer.audio_revision
  OR NOT reward_leg_accepts_qualification(leg.leg_id,'study',facts->>'policyRevision') OR NOT 'study'=ANY(leg.eligible_activities)
  OR (facts->>'scoreBps')::INTEGER<leg.min_score_bps
  OR (facts->>'qualifiedAt')::TIMESTAMPTZ<offer.starts_at OR (facts->>'qualifiedAt')::TIMESTAMPTZ>=offer.ends_at
  OR (facts->>'qualifiedAt')::TIMESTAMPTZ<leg.participation_starts_at OR drawing.drawing_id<leg.participation_starts_drawing_id
  OR observation.observation_id IS NULL OR policy.policy_version_id IS NULL
  OR observation.attestation_id IS DISTINCT FROM leg.attestation_id
  OR observation.drawing_id IS DISTINCT FROM drawing.drawing_id OR observation.drawing_locked IS DISTINCT FROM FALSE
  OR observation.drawing_time-make_interval(secs=>leg.entry_cutoff_seconds) IS DISTINCT FROM drawing.entry_cutoff_at
  OR observation.ticket_price_atomic>drawing.ticket_price_ceiling_atomic
  OR observation.drawing_time<=clock_timestamp()
  OR observation.expires_at<=clock_timestamp() THEN result:=jsonb_build_object('state','unavailable');
 ELSIF leg.funding_source='leg_budget' AND leg.funded_atomic-leg.reserved_atomic-leg.spent_atomic<observation.ticket_price_atomic THEN result:=jsonb_build_object('state','unavailable');
 ELSIF leg.funding_source='shared_sponsor_budget' AND (funding.sponsor_account_id IS NULL OR funding.funded_atomic+funding.winnings_credited_atomic-funding.reserved_atomic-funding.spent_atomic-funding.withdrawn_atomic<observation.ticket_price_atomic) THEN result:=jsonb_build_object('state','unavailable');
 ELSIF EXISTS(SELECT 1 FROM megapot_owner_shares WHERE pool_leg_id=leg.leg_id AND drawing_id=drawing.drawing_id AND owner_id=ANY(source_ids))
  OR EXISTS(SELECT 1 FROM megapot_pool_shares s JOIN participation_owners o ON o.kind='account' AND o.account_id=s.account_id WHERE s.pool_leg_id=leg.leg_id AND s.drawing_id=drawing.drawing_id AND o.owner_id=ANY(source_ids))
 THEN result:=jsonb_build_object('state','already_participating');
 ELSE
  -- Exact AFTER-lock clock, immediately before guarded INSERT, is the
  -- conditional-on-eventual-COMMIT linearization point. Never use prepared time.
  now_at:=clock_timestamp();
  IF now_at>=drawing.entry_cutoff_at OR now_at>=hold.purchase_safety_deadline_at OR (facts->>'qualifiedAt')::TIMESTAMPTZ>=drawing.entry_cutoff_at THEN result:=jsonb_build_object('state','entry_closed');
  ELSE
   BEGIN
   eligibility_id:='owner_eligibility_'||hold.admission_id;
   INSERT INTO participation_eligibility_decisions(eligibility_id,owner_id,qualification_id,pool_leg_id,drawing_id,policy_version,policy_hash,evidence_reference,disclosure_reference,outcome,decided_at)
   VALUES(eligibility_id,hold.source_owner_id,hold.qualification_id,leg.leg_id,drawing.drawing_id,policy.policy_version_id,policy.policy_hash,hold.main_operation_id,terms->>'disclosure_version','eligible',now_at);
   -- SQLSTATEOA001 is PRIVATE subtransaction control ONLY. It is emitted
   -- solely for authoritative zero-row guarded INSERT, never guessed from
   -- an unknown/native error, and is never sent/mapped as a new wire reason.
   WITH sampled AS MATERIALIZED(SELECT clock_timestamp() AS admitted)
   INSERT INTO megapot_owner_shares(pool_leg_id,drawing_id,owner_id,qualification_id,eligibility_id,admitted_at,leaf_salt)
   SELECT leg.leg_id,drawing.drawing_id,hold.source_owner_id,hold.qualification_id,eligibility_id,sampled.admitted,hold.leaf_salt
   FROM sampled WHERE sampled.admitted<drawing.entry_cutoff_at AND sampled.admitted<hold.purchase_safety_deadline_at RETURNING admitted_at INTO now_at;
   IF NOT FOUND THEN RAISE EXCEPTION 'guarded admission window closed' USING ERRCODE='OA001'; END IF;
   result:=jsonb_build_object('state','admitted','share_id',hold.admission_id,'original_drawing_id',drawing.drawing_id::TEXT,'pool_leg_id',leg.leg_id);
   EXCEPTION WHEN SQLSTATE 'OA001' THEN
    -- Roll back ONLY uncommitted eligibility/share statements. The same owning
    -- grade and immutable qualification remain in this transaction and commit.
    result:=jsonb_build_object('state','entry_closed');
   END;
  END IF;
 END IF;
 UPDATE owner_participation_admission_operations SET state=CASE WHEN result->>'state'='admitted' THEN 'admitted' ELSE 'not_admitted' END,
  result_snapshot=result,resolved_at=clock_timestamp() WHERE admission_id=p_id AND state='pending';
 UPDATE owner_participation_admission_attempts SET state=CASE WHEN result->>'state'='admitted' THEN 'admitted' ELSE 'not_admitted' END,resolved_at=clock_timestamp()
  WHERE admission_id=p_id AND attempt_fence=p_expected_fence AND state='pending';
 RETURN result;
END $$;

-- Source: owner-study-reward-producer-proposal-v2/complete-owning-admission.sql
CREATE FUNCTION complete_guest_reward_admission_private_v1(p_source TEXT,p_session TEXT,p_main TEXT,p_expected_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE sess study_sessions_v2%ROWTYPE; facts JSONB; hold owner_participation_admission_operations%ROWTYPE;
 qid TEXT; q activity_qualifications%ROWTYPE; original_choice owner_captured_guest_choice_commands%ROWTYPE;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT sess FROM study_sessions_v2 WHERE session_id=p_session AND participation_owner_id=p_source AND participation_owner_kind='guest';
 IF sess.guest_reward_mode='practice_only' AND sess.guest_reward_terms IS NULL THEN RETURN jsonb_build_object('state','practice_only'); END IF;
 PERFORM require_owner_accounting_ready_private_v1();
 PERFORM require_guest_reward_owning_attempt_private_v1(p_source,p_main,p_expected_fence);
 facts:=read_qualified_guest_study_facts_private_v1(p_source,p_session,p_main);
 SELECT * INTO hold FROM owner_participation_admission_operations WHERE source_owner_id=p_source AND main_operation_id=p_main;
 IF facts->>'state'='qualified' THEN
  qid:=coalesce(hold.qualification_id,'guest_qualification_'||encode(sha256(convert_to(jsonb_build_array(p_source,p_session)::TEXT,'UTF8')),'hex'));
  -- Source qualification belongs to lesson completion, independent of monetary
  -- refusal. It is never rolled back merely because cutoff/funding/share refuses.
  SELECT * INTO q FROM activity_qualifications WHERE participation_owner_id=p_source AND study_session_id=p_session AND participation_owner_kind='guest';
  IF NOT FOUND THEN
   INSERT INTO activity_qualifications(qualification_id,participation_owner_id,participation_owner_kind,guest_main_operation_id,account_id,persona_id,
    community_id,post_id,audio_revision,activity_key,study_session_id,score_bps,qualification_policy_version_id,qualified_at,streak_day,evidence_summary,created_at)
   VALUES(qid,p_source,'guest',p_main,NULL,NULL,facts->>'communityId',facts->>'postId',(facts->>'audioRevision')::BIGINT,'study',p_session,
    (facts->>'scoreBps')::INTEGER,facts->>'policyRevision',(facts->>'qualifiedAt')::TIMESTAMPTZ,(facts->>'streakDay')::DATE,facts->'evidence',(facts->>'qualifiedAt')::TIMESTAMPTZ)
   RETURNING * INTO q;
  END IF;
  IF q.qualification_id IS DISTINCT FROM qid OR q.guest_main_operation_id IS DISTINCT FROM p_main THEN
   RAISE EXCEPTION 'original lesson qualification changed' USING ERRCODE='GP005'; END IF;
  PERFORM validate_qualified_guest_activity_private_v1(q);
 END IF;
 IF hold.admission_id IS NOT NULL THEN
  -- Caller prelocked full original drawing/funding before any grade writes.
  -- Raw admit is private and may only be reached through captured owning leaves.
  RETURN admit_guest_owner_participation_private_v1(hold.admission_id,p_expected_fence);
 END IF;
 IF facts->>'state' IN('not_yet_qualified','ineligible') THEN RETURN jsonb_build_object('state',facts->>'state'); END IF;
 SELECT * INTO original_choice FROM owner_captured_guest_choice_commands WHERE operation_id=p_main AND source_owner_id=p_source;
 IF FOUND AND original_choice.original_admission_result->>'state' IN('entry_closed','unavailable') THEN
  RETURN original_choice.original_admission_result;
 END IF;
 IF clock_timestamp()>=sess.guest_reward_purchase_safety_deadline_at OR clock_timestamp()>=(sess.guest_reward_terms->>'entry_cutoff_at')::TIMESTAMPTZ THEN
  RETURN jsonb_build_object('state','entry_closed'); END IF;
 -- An accepted provider CP remains owed if separate hold preparation refused.
 -- No pending journal means this branch NEVER attempts financial admission.
 -- The completion persists this known no-admission outcome with its real grade.
 RETURN jsonb_build_object('state','unavailable');
END $$;

-- Source: owner-study-reward-producer-proposal-v2/owning-participation-validator.sql
-- Readonly guard for a locally computed owning projection, before the main
-- operation result is stored. Never expose caller-controlled result authority.
CREATE FUNCTION validate_guest_owning_participation_private_v1(p_source TEXT,p_session TEXT,p_main TEXT,p_part JSONB)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE s study_sessions_v2%ROWTYPE; hold owner_participation_admission_operations%ROWTYPE; facts JSONB;
 choice owner_captured_guest_choice_commands%ROWTYPE; expected JSONB;
BEGIN
 SELECT * INTO STRICT s FROM study_sessions_v2 WHERE session_id=p_session AND participation_owner_id=p_source AND participation_owner_kind='guest';
 IF s.guest_reward_mode='practice_only' AND s.guest_reward_terms IS NULL THEN expected:=jsonb_build_object('state','practice_only');
 ELSE
  facts:=read_qualified_guest_study_facts_private_v1(p_source,p_session,p_main);
  SELECT * INTO hold FROM owner_participation_admission_operations WHERE source_owner_id=p_source AND main_operation_id=p_main;
  IF FOUND THEN
   IF hold.state='pending' OR hold.result_snapshot IS NULL THEN RAISE EXCEPTION 'owning admission not resolved' USING ERRCODE='GP003'; END IF;
   expected:=hold.result_snapshot;
  ELSIF facts->>'state' IN('not_yet_qualified','ineligible') THEN expected:=jsonb_build_object('state',facts->>'state');
  ELSE
   SELECT * INTO choice FROM owner_captured_guest_choice_commands WHERE operation_id=p_main AND source_owner_id=p_source;
   IF FOUND AND choice.original_admission_result->>'state' IN('entry_closed','unavailable') THEN expected:=choice.original_admission_result;
   ELSIF p_part=jsonb_build_object('state','entry_closed') AND (clock_timestamp()>=s.guest_reward_purchase_safety_deadline_at OR clock_timestamp()>=(s.guest_reward_terms->>'entry_cutoff_at')::TIMESTAMPTZ) THEN expected:=jsonb_build_object('state','entry_closed');
   ELSE expected:=jsonb_build_object('state','unavailable'); END IF;
   IF NOT EXISTS(SELECT 1 FROM activity_qualifications WHERE participation_owner_id=p_source AND study_session_id=p_session
    AND participation_owner_kind='guest' AND guest_main_operation_id=p_main) THEN
    RAISE EXCEPTION 'qualified owning lesson has no immutable qualification' USING ERRCODE='GP003'; END IF;
  END IF;
 END IF;
 IF p_part IS DISTINCT FROM expected THEN RAISE EXCEPTION 'owning generated participation changed' USING ERRCODE='GP005'; END IF;
END $$;

-- Source: owner-study-reward-producer-proposal-v2/participation-projection.sql
-- Source-owned current participation overlay; never rewrites an immutable grade
-- or completed main-operation result. Browser access remains outside this private
-- projector; public readers must retain their actual current proof/content checks.
CREATE FUNCTION read_guest_study_participation_private_v1(p_source TEXT,p_session TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE s study_sessions_v2%ROWTYPE; journal owner_participation_admission_operations%ROWTYPE;
 original guest_participation_operations%ROWTYPE; projected JSONB;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT s FROM study_sessions_v2 WHERE session_id=p_session AND participation_owner_id=p_source
  AND participation_owner_kind='guest';
 IF s.guest_reward_mode='practice_only' AND s.guest_reward_terms IS NULL THEN
  RETURN jsonb_build_object('state','practice_only'); END IF;
 IF s.guest_reward_mode IS DISTINCT FROM 'megapot_guest_v1' THEN
  RAISE EXCEPTION 'closed stored guest mode required' USING ERRCODE='GP003'; END IF;
 PERFORM require_owner_accounting_ready_private_v1();
 PERFORM validate_guest_reward_terms_shape_private_v1(s.guest_reward_terms,s.community_id,s.post_id,s.audio_revision,
  s.lyrics_revision,s.qualification_policy_revision,s.guest_disclosure_version);
 SELECT j.* INTO journal FROM owner_participation_admission_operations j
  JOIN guest_participation_operations main ON main.operation_id=j.guest_main_operation_id AND main.source_owner_id=j.source_owner_id
  WHERE j.source_owner_id=p_source AND j.source_owner_kind='guest' AND j.source_session_kind='study_v2' AND j.session_id=p_session
   AND ((s.status='active' AND j.state='pending') OR (s.status='completed' AND main.state='completed'
    AND main.result_snapshot#>>'{answer,session,session_id}'=p_session
    AND main.result_snapshot#>>'{answer,session,status}'='completed'))
  ORDER BY j.created_at DESC,j.admission_id COLLATE "C" DESC LIMIT 1;
 IF FOUND THEN
  IF journal.pool_leg_id IS DISTINCT FROM s.guest_reward_terms->>'pool_leg_id'
   OR journal.drawing_id::TEXT IS DISTINCT FROM s.guest_reward_terms->>'original_drawing_id'
   OR journal.terms_hash IS DISTINCT FROM s.guest_reward_terms->>'terms_hash' THEN
   RAISE EXCEPTION 'original participation source changed' USING ERRCODE='GP003'; END IF;
  IF journal.state='pending' THEN RETURN jsonb_build_object('state','pending_confirmation','operation',
   jsonb_build_object('operation_kind',journal.operation_kind,'idempotency_key',journal.idempotency_key,'operation_id',journal.main_operation_id)); END IF;
  IF journal.state='admitted' AND NOT EXISTS(SELECT 1 FROM megapot_owner_shares share WHERE share.pool_leg_id=journal.pool_leg_id
   AND share.drawing_id=journal.drawing_id AND share.owner_id=p_source AND share.qualification_id=journal.qualification_id
   AND share.leaf_salt=journal.leaf_salt) THEN
   RAISE EXCEPTION 'committed original participation evidence missing' USING ERRCODE='GP003'; END IF;
  RETURN journal.result_snapshot;
 END IF;
 IF s.status='active' THEN RETURN jsonb_build_object('state','not_yet_qualified'); END IF;
 -- A genuine committed non-admission receipt may exist when preparation itself
 -- was definitively refused. Absence, unknown COMMIT or an unrecognized snapshot
 -- is NEVER called ineligible/aborted/zero financial history.
 SELECT * INTO original FROM guest_participation_operations op WHERE source_owner_id=p_source AND operation_kind='study_answer'
  AND state='completed' AND result_snapshot#>>'{source,kind}'='guest'
  AND result_snapshot#>>'{source,ownerId}'=p_source
  AND result_snapshot#>>'{answer,session,session_id}'=p_session
  AND result_snapshot#>>'{answer,session,status}'='completed'
  AND result_snapshot#>>'{answer,session,reward_mode}'='megapot_guest_v1'
  AND result_snapshot#>'{answer,session,reward_terms}'=s.guest_reward_terms
  ORDER BY created_at,operation_id COLLATE "C" LIMIT 1;
 IF FOUND THEN
  projected:=original.result_snapshot->'participation';
  IF jsonb_typeof(projected)='object' AND projected-ARRAY['state']='{}'::JSONB
   AND projected->>'state' IN('ineligible','entry_closed','unavailable') THEN RETURN projected; END IF;
 END IF;
 RAISE EXCEPTION 'original completed participation outcome unresolved' USING ERRCODE='GP003';
END $$;

-- Source: owner-study-reward-producer-proposal-v2/project_owner_study_session_private_v1.successor.sql
CREATE OR REPLACE FUNCTION project_owner_study_session_private_v1(p_source TEXT,p_community TEXT,p_session TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE session study_sessions_v2%ROWTYPE; items JSONB; source JSONB; public_session JSONB;
 count_cards INTEGER; answered INTEGER; correct INTEGER; resolved INTEGER;
 current_presentations INTEGER; at_created TEXT; at_completed TEXT; at_presented TEXT;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 SELECT * INTO session FROM study_sessions_v2 WHERE session_id=p_session AND community_id=p_community
  AND participation_owner_id=p_source;
 IF NOT FOUND THEN RAISE EXCEPTION 'captured Study source missing' USING ERRCODE='GP010'; END IF;
 IF session.participation_owner_kind='guest' THEN
  source:=jsonb_build_object('kind','guest','ownerId',session.participation_owner_id);
 ELSE
  source:=jsonb_build_object('kind','account','ownerId',session.participation_owner_id,
   'accountId',session.account_id,'personaId',session.persona_id);
 END IF;
 -- Caller already proved original capture/source and owns component/session locks.
 -- No current cookie/proof/lease/publication predicate is evaluated here.
 -- One state snapshot for stored items, attempts and lesson progress, preserving
 -- the existing readSession calculations. No account-only descendant filters.
 WITH item_rows AS MATERIALIZED (
  SELECT i.* FROM study_session_items_v2 i WHERE i.session_id=session.session_id
   AND i.participation_owner_id=session.participation_owner_id
 ), progress AS (
  SELECT count(*)::INTEGER AS cards,
   count(*) FILTER(WHERE EXISTS(SELECT 1 FROM study_attempts_v2 a
     WHERE a.session_item_id=i.session_item_id AND a.attempt_state='spent'))::INTEGER AS answered,
   count(*) FILTER(WHERE EXISTS(SELECT 1 FROM study_attempts_v2 a
     WHERE a.session_item_id=i.session_item_id AND a.attempt_number=1 AND a.outcome='correct'))::INTEGER AS correct
  FROM item_rows i
 ), lesson AS (
  SELECT count(*) FILTER(WHERE lesson_resolved)::INTEGER AS resolved,
   COALESCE(max(presentation_count) FILTER(WHERE session_item_id=session.current_session_item_id),0)::INTEGER AS presented
  FROM study_lesson_item_state_v2 WHERE session_id=session.session_id
 ) SELECT COALESCE((SELECT jsonb_agg(item_snapshot ORDER BY ordinal) FROM item_rows),'[]'),
   progress.cards,progress.answered,progress.correct,lesson.resolved,lesson.presented
  INTO items,count_cards,answered,correct,resolved,current_presentations FROM progress CROSS JOIN lesson;
 IF count_cards NOT BETWEEN 4 AND 10 THEN
  RAISE EXCEPTION 'stored Study item closure invalid' USING ERRCODE='GP006'; END IF;
 at_created:=to_char(session.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
 at_completed:=CASE WHEN session.completed_at IS NULL THEN NULL ELSE
  to_char(session.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END;
 at_presented:=CASE WHEN session.current_presented_at IS NULL THEN NULL ELSE
  to_char(session.current_presented_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END;
 public_session:=jsonb_build_object(
  'object','study_session_v2','session_id',session.session_id,'persona_id',session.persona_id,
  'community_id',session.community_id,'post_id',session.post_id,
  'audio_revision',session.audio_revision,'lyrics_revision',session.lyrics_revision,
  'languages',jsonb_build_object('learning_language',session.learning_language,'target_language',session.target_language),
  'learner_band',session.learner_band,'study_profile_revision',session.study_profile_revision,
  'language_profile_revision',session.language_profile_revision,'source_set_revision',session.source_set_revision,
  'selection_policy_revision',session.selection_policy_revision,'qualification_policy_revision',session.qualification_policy_revision,
  'timezone',session.timezone,'status',session.status,'items',items,
  'progress',jsonb_build_object('qualifying_exercise_count',count_cards,'answered_exercise_count',answered,
   'first_pass_correct',correct,'required_correct',GREATEST(1,ceil(7.0*count_cards/10)::INTEGER),
   'score_bps',CASE WHEN answered=count_cards THEN floor(10000.0*correct/count_cards)::INTEGER ELSE NULL END),
  'lesson',jsonb_build_object('current',CASE WHEN session.current_session_item_id IS NULL THEN NULL ELSE
   jsonb_build_object('session_item_id',session.current_session_item_id,
    'presentation_number',current_presentations+1,'is_reappearance',current_presentations>0,
    'presented_at',at_presented) END,
   'resolved_card_count',resolved,'total_card_count',count_cards,
   'presentation_count',session.presentation_count,'presentation_cap',LEAST(20,3*count_cards),
   'completion_reason',session.completion_reason),
  'created_at',at_created,'completed_at',at_completed);
 IF session.participation_owner_kind='guest' THEN
  public_session:=(public_session-'persona_id')||jsonb_build_object(
   'object','guest_study_session_v1','actor',jsonb_build_object('kind','guest'),
   'owner_id',session.participation_owner_id,
   'expires_at',to_char(session.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
   'reward_mode',session.guest_reward_mode,'reward_terms',session.guest_reward_terms,
   'participation',read_guest_study_participation_private_v1(session.participation_owner_id,session.session_id));
 END IF;
 RETURN jsonb_build_object('source',source,'session',public_session);
END $$;

