-- Source: owner-study-reward-producer-proposal-v2/read_owner_study_session_snapshot_v1.successor.sql
CREATE OR REPLACE FUNCTION read_owner_study_session_snapshot_v1(p_access JSONB,p_community TEXT,p_session TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE session study_sessions_v2%ROWTYPE; items JSONB; source JSONB; public_session JSONB;
 count_cards INTEGER; answered INTEGER; correct INTEGER; resolved INTEGER;
 current_presentations INTEGER; at_created TEXT; at_completed TEXT; at_presented TEXT;
BEGIN
 -- Immutable source is read from resource, never supplied by caller.
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 SELECT * INTO session FROM study_sessions_v2 WHERE session_id=p_session AND community_id=p_community;
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF session.participation_owner_kind='guest' THEN
  IF p_access->>'kind' IS DISTINCT FROM 'guest'
   OR p_access->>'ownerId' IS DISTINCT FROM session.participation_owner_id
   OR NOT can_guest_access_activity_song_v1(session.community_id,session.post_id) THEN RETURN NULL; END IF;
  PERFORM require_guest_study_learning_access_v1(p_access,session.participation_owner_id);
  -- Every future guest answer/finalizer must hold this same component lock.
  -- Re-read after acquisition so session, items and progress cannot mix states.
  SELECT * INTO STRICT session FROM study_sessions_v2 WHERE session_id=p_session AND community_id=p_community;
  IF NOT can_guest_access_activity_song_v1(session.community_id,session.post_id) THEN RETURN NULL; END IF;
  source:=jsonb_build_object('kind','guest','ownerId',session.participation_owner_id);
 ELSE
  IF p_access->>'kind' IS DISTINCT FROM 'account'
   OR p_access->>'accountId' IS DISTINCT FROM session.account_id
   OR NOT active_activity_persona(session.account_id,session.persona_id,session.community_id)
   OR NOT can_account_access_activity_song(session.account_id,session.community_id,session.post_id)
   THEN RETURN NULL; END IF;
  source:=jsonb_build_object('kind','account','ownerId',session.participation_owner_id,
   'accountId',session.account_id,'personaId',session.persona_id);
 END IF;
 -- One state snapshot for stored items, attempts and lesson progress, preserving
 -- the existing readSession calculations. No account-only descendant filters.
 WITH item_rows AS MATERIALIZED (
  SELECT i.* FROM study_session_items_v2 i WHERE i.session_id=session.session_id
   AND i.participation_owner_id=session.participation_owner_id
 ), progress AS (
  SELECT count(*)::INTEGER AS cards,
   count(*) FILTER(WHERE EXISTS(SELECT 1 FROM study_attempts_v2 a
     WHERE a.session_item_id=i.session_item_id AND a.attempt_state='spent'))::INTEGER AS answered,
   count(*) FILTER(WHERE EXISTS(SELECT 1 FROM study_attempts_v2 a
     WHERE a.session_item_id=i.session_item_id AND a.attempt_number=1 AND a.outcome='correct'))::INTEGER AS correct
  FROM item_rows i
 ), lesson AS (
  SELECT count(*) FILTER(WHERE lesson_resolved)::INTEGER AS resolved,
   COALESCE(max(presentation_count) FILTER(WHERE session_item_id=session.current_session_item_id),0)::INTEGER AS presented
  FROM study_lesson_item_state_v2 WHERE session_id=session.session_id
 ) SELECT COALESCE((SELECT jsonb_agg(item_snapshot ORDER BY ordinal) FROM item_rows),'[]'),
   progress.cards,progress.answered,progress.correct,lesson.resolved,lesson.presented
  INTO items,count_cards,answered,correct,resolved,current_presentations FROM progress CROSS JOIN lesson;
 IF count_cards NOT BETWEEN 4 AND 10 THEN
  RAISE EXCEPTION 'stored Study item closure invalid' USING ERRCODE='GP006'; END IF;
 at_created:=to_char(session.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
 at_completed:=CASE WHEN session.completed_at IS NULL THEN NULL ELSE
  to_char(session.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END;
 at_presented:=CASE WHEN session.current_presented_at IS NULL THEN NULL ELSE
  to_char(session.current_presented_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END;
 public_session:=jsonb_build_object(
  'object','study_session_v2','session_id',session.session_id,'persona_id',session.persona_id,
  'community_id',session.community_id,'post_id',session.post_id,
  'audio_revision',session.audio_revision,'lyrics_revision',session.lyrics_revision,
  'languages',jsonb_build_object('learning_language',session.learning_language,'target_language',session.target_language),
  'learner_band',session.learner_band,'study_profile_revision',session.study_profile_revision,
  'language_profile_revision',session.language_profile_revision,'source_set_revision',session.source_set_revision,
  'selection_policy_revision',session.selection_policy_revision,'qualification_policy_revision',session.qualification_policy_revision,
  'timezone',session.timezone,'status',session.status,'items',items,
  'progress',jsonb_build_object('qualifying_exercise_count',count_cards,'answered_exercise_count',answered,
   'first_pass_correct',correct,'required_correct',GREATEST(1,ceil(7.0*count_cards/10)::INTEGER),
   'score_bps',CASE WHEN answered=count_cards THEN floor(10000.0*correct/count_cards)::INTEGER ELSE NULL END),
  'lesson',jsonb_build_object('current',CASE WHEN session.current_session_item_id IS NULL THEN NULL ELSE
   jsonb_build_object('session_item_id',session.current_session_item_id,
    'presentation_number',current_presentations+1,'is_reappearance',current_presentations>0,
    'presented_at',at_presented) END,
   'resolved_card_count',resolved,'total_card_count',count_cards,
   'presentation_count',session.presentation_count,'presentation_cap',LEAST(20,3*count_cards),
   'completion_reason',session.completion_reason),
  'created_at',at_created,'completed_at',at_completed);
 IF session.participation_owner_kind='guest' THEN
  public_session:=(public_session-'persona_id')||jsonb_build_object(
   'object','guest_study_session_v1','actor',jsonb_build_object('kind','guest'),
   'owner_id',session.participation_owner_id,
   'expires_at',to_char(session.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
   'reward_mode',session.guest_reward_mode,'reward_terms',session.guest_reward_terms,
   'participation',read_guest_study_participation_private_v1(session.participation_owner_id,session.session_id));
 END IF;
 RETURN jsonb_build_object('source',source,'session',public_session);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/finish_guest_json_answer_v1.owning-successor.sql
CREATE FUNCTION finish_captured_guest_reward_json_private_v1(p_operation JSONB,p_operation_id TEXT,p_capture JSONB,p_decision JSONB,p_expected_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE operation guest_participation_operations%ROWTYPE; owned JSONB; result JSONB; participation JSONB;
BEGIN
 SELECT * INTO STRICT operation FROM guest_participation_operations WHERE operation_id=p_operation_id FOR UPDATE;
 IF ROW(operation.source_owner_id,operation.operation_kind,operation.idempotency_key,operation.request_hash,operation.resource_scope)
  IS DISTINCT FROM ROW(p_capture->>'sourceOwnerId','study_answer',p_operation->>'idempotencyKey',p_operation->>'requestHash',
   guest_study_answer_resource_scope_v1(p_capture->>'communityId',p_capture->>'sessionId',p_capture->>'sessionItemId',(p_capture->>'attemptNumber')::INTEGER,'choice')) THEN
  RAISE EXCEPTION 'original answer identity changed' USING ERRCODE='GP005'; END IF;
 IF operation.state='completed' THEN RETURN jsonb_build_object('state','completed','operationId',operation.operation_id,'result',operation.result_snapshot); END IF;
 IF operation.state<>'reserved' OR NOT EXISTS(SELECT 1 FROM study_attempts_v2 a JOIN study_session_items_v2 i USING(session_item_id)
  WHERE a.idempotency_key=operation.idempotency_key AND a.request_hash=operation.request_hash
   AND i.participation_owner_id=operation.source_owner_id AND i.session_id=p_capture->>'sessionId'
   AND a.session_item_id=p_capture->>'sessionItemId' AND a.attempt_number=(p_capture->>'attemptNumber')::INTEGER) THEN
  RAISE EXCEPTION 'actual answer receipt missing' USING ERRCODE='GP003'; END IF;
 IF NOT EXISTS(SELECT 1 FROM study_sessions_v2 WHERE session_id=p_capture->>'sessionId'
   AND participation_owner_id=operation.source_owner_id
   AND presentation_count=(p_capture->>'priorPresentationCount')::BIGINT+1) THEN
  RAISE EXCEPTION 'shared lesson continuation receipt missing' USING ERRCODE='GP003'; END IF;
 participation:=complete_guest_reward_admission_private_v1(operation.source_owner_id,p_capture->>'sessionId',operation.operation_id,p_expected_fence);
 owned:=project_owner_study_owned_reward_session_private_v1(operation.source_owner_id,p_capture->>'communityId',p_capture->>'sessionId',operation.operation_id,participation);
 result:=jsonb_build_object('source',owned->'source','answer',jsonb_build_object('object','guest_study_answer_result_v1',
  'session_item_id',p_capture->'sessionItemId','attempt_number',p_capture->'attemptNumber','exercise_type','translation_choice',
  'outcome',p_decision->'outcome','first_pass',p_decision->'firstPass','attempt_state',p_decision->'attemptState',
  'feedback',p_decision->'feedback','session',owned->'session','participation',participation),
  'participation',participation);
 -- Release only the unspent plan after actual lesson completion. Existing
 -- reserved/unknown provider holds remain retained by the actual251 primitive.
 IF owned#>>'{session,status}'='completed' THEN
  PERFORM release_guest_resource_session_v1(operation.source_owner_id,p_operation,p_capture->>'sessionId',
   p_capture->>'resourceReservationId','completed'); END IF;
 UPDATE guest_participation_operations SET state='completed',result_snapshot=result,resolved_at=clock_timestamp() WHERE operation_id=p_operation_id;
 RETURN jsonb_build_object('state','completed','operationId',p_operation_id,'result',result);
END $$;

CREATE OR REPLACE FUNCTION finish_guest_json_answer_v1(p_operation JSONB,p_operation_id TEXT,p_capture JSONB,p_decision JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN RETURN finish_captured_guest_reward_json_private_v1(p_operation,p_operation_id,p_capture,p_decision,NULL); END $$;

-- Source: owner-study-reward-producer-proposal-v2/finish_guest_spoken_answer_v1.owning-successor.sql
CREATE FUNCTION finish_captured_guest_reward_spoken_private_v1(p_source TEXT,p_operation JSONB,p_checkpoint TEXT,
 p_capture JSONB,p_decision JSONB,p_feedback JSONB,p_spoken JSONB,p_expected_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE cp guest_study_spoken_checkpoints%ROWTYPE; cap guest_study_spoken_captures%ROWTYPE;
 main_op guest_participation_operations%ROWTYPE; cmd study_spoken_answer_commands%ROWTYPE; owned JSONB; result JSONB; participation JSONB;
BEGIN
 SELECT * INTO STRICT cp FROM guest_study_spoken_checkpoints WHERE checkpoint_id=p_checkpoint AND source_owner_id=p_source;
 SELECT * INTO STRICT cap FROM guest_study_spoken_captures WHERE capture_id=cp.capture_id;
 main_op:=require_guest_answer_operation_private_v1(p_source,p_operation,cap.operation_id,
  cap.grading_context->>'communityId',cap.session_id,cap.session_item_id,cap.attempt_number,'spoken');
 IF main_op.state='completed' THEN RETURN jsonb_build_object('state','completed','operationId',main_op.operation_id,'result',main_op.result_snapshot); END IF;
 SELECT * INTO STRICT cmd FROM study_spoken_answer_commands WHERE command_id=cap.command_id FOR UPDATE;
 IF main_op.state IS DISTINCT FROM 'reserved' OR cmd.state IS DISTINCT FROM 'reserved'
  OR cmd.lease_token IS DISTINCT FROM cap.original_lease_token OR p_capture->'result' IS DISTINCT FROM cp.success_result
  OR p_capture->>'captureId' IS DISTINCT FROM cap.capture_id OR p_capture->>'operationId' IS DISTINCT FROM main_op.operation_id
  OR (p_decision->>'kind'='graded' AND NOT EXISTS(SELECT 1 FROM study_attempts_v2 WHERE attempt_id=cap.attempt_id))
  OR p_decision->>'kind' IS NULL OR p_decision->>'kind' NOT IN('graded','ungraded_rerecord') THEN
  RAISE EXCEPTION 'accepted actual completion receipts unavailable' USING ERRCODE='GP003'; END IF;
 IF NOT EXISTS(SELECT 1 FROM study_sessions_v2 s JOIN study_lesson_item_state_v2 state
  ON state.session_id=s.session_id AND state.session_item_id=cap.session_item_id
  WHERE s.session_id=cap.session_id AND s.participation_owner_id=p_source
   AND ((p_decision->>'kind'='graded' AND state.presentation_count=cap.attempt_number
     AND s.presentation_count=(p_capture->>'priorPresentationCount')::BIGINT+1)
    OR (p_decision->>'kind'='ungraded_rerecord' AND state.presentation_count=cap.attempt_number-1
     AND s.presentation_count=(p_capture->>'priorPresentationCount')::BIGINT
     AND s.current_session_item_id=cap.session_item_id AND NOT state.lesson_resolved))) THEN
  RAISE EXCEPTION 'shared lesson continuation receipt missing' USING ERRCODE='GP003'; END IF;
 participation:=complete_guest_reward_admission_private_v1(p_source,cap.session_id,main_op.operation_id,p_expected_fence);
 owned:=project_owner_study_owned_reward_session_private_v1(p_source,cap.grading_context->>'communityId',cap.session_id,main_op.operation_id,participation);
 result:=jsonb_build_object('source',owned->'source','answer',jsonb_build_object('object','guest_study_answer_result_v1',
  'session_item_id',cap.session_item_id,'attempt_number',cap.attempt_number,'exercise_type','say_it_back',
  'outcome',p_decision->'outcome','first_pass',p_decision->'firstPass','attempt_state',p_decision->'attemptState',
  'feedback',p_feedback,'spoken',p_spoken,'session',owned->'session','participation',participation),
  'participation',participation);
 IF owned#>>'{session,status}'='completed' THEN
  PERFORM release_guest_resource_session_v1(p_source,p_operation,cap.session_id,cap.resource_reservation_id,'completed'); END IF;
 UPDATE study_spoken_answer_commands SET state='completed',result_kind=CASE WHEN p_decision->>'kind'='ungraded_rerecord' THEN 'rerecord' ELSE 'graded' END,
  result_snapshot=result,completed_at=(cp.success_result->>'acceptedAt')::TIMESTAMPTZ
  WHERE command_id=cap.command_id AND participation_owner_id=p_source AND lease_token=cap.original_lease_token AND state='reserved';
 IF NOT FOUND THEN RAISE EXCEPTION 'original command completion changed' USING ERRCODE='GP005'; END IF;
 UPDATE guest_participation_operations SET state='completed',result_snapshot=result,resolved_at=clock_timestamp()
  WHERE operation_id=main_op.operation_id AND state='reserved';
 RETURN jsonb_build_object('state','completed','operationId',main_op.operation_id,'result',result);
END $$;

CREATE OR REPLACE FUNCTION finish_guest_spoken_answer_v1(p_source TEXT,p_operation JSONB,p_checkpoint TEXT,p_capture JSONB,p_decision JSONB,p_feedback JSONB,p_spoken JSONB) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN RETURN finish_captured_guest_reward_spoken_private_v1(p_source,p_operation,p_checkpoint,p_capture,p_decision,p_feedback,p_spoken,NULL); END $$;

-- Source: owner-study-reward-producer-proposal-v2/choice-controlled-leaves.sql
CREATE FUNCTION require_owner_guest_reward_choice_private_v1(p_source JSONB,p_operation JSONB,p_command TEXT,p_nonce TEXT)
RETURNS owner_captured_guest_choice_commands LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE cmd owner_captured_guest_choice_commands%ROWTYPE;
BEGIN
 PERFORM require_owner_guest_source_private_v1(p_source);
 PERFORM validate_guest_resource_operation_v1(p_source->>'ownerId',p_operation,'study_answer');
 SELECT * INTO STRICT cmd FROM owner_captured_guest_choice_commands WHERE command_id=p_command;
 IF cmd.source_owner_id IS DISTINCT FROM p_source->>'ownerId' OR cmd.original_continuation_nonce IS DISTINCT FROM p_nonce
  OR NOT EXISTS(SELECT 1 FROM guest_participation_operations main WHERE main.operation_id=cmd.operation_id
   AND main.source_owner_id=cmd.source_owner_id AND main.operation_kind='study_answer'
   AND main.idempotency_key=p_operation->>'idempotencyKey' AND main.request_hash=p_operation->>'requestHash') THEN
  RAISE EXCEPTION 'captured choice source/operation changed' USING ERRCODE='GP005'; END IF;
 RETURN cmd;
END $$;
CREATE FUNCTION read_owner_guest_reward_choice_v1(p_source JSONB,p_operation JSONB,p_command TEXT,p_nonce TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 PERFORM require_owner_guest_reward_choice_private_v1(p_source,p_operation,p_command,p_nonce);
 RETURN read_captured_guest_reward_choice_v1(p_command,p_nonce);
END $$;
CREATE FUNCTION apply_owner_guest_reward_choice_v1(p_source JSONB,p_operation JSONB,p_command TEXT,p_nonce TEXT,p_capture JSONB,p_decision JSONB,p_expected_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 PERFORM require_owner_guest_reward_choice_private_v1(p_source,p_operation,p_command,p_nonce);
 RETURN apply_captured_guest_reward_choice_v1(p_command,p_nonce,p_capture,p_decision,p_expected_fence);
END $$;
CREATE FUNCTION finish_owner_guest_reward_choice_v1(p_source JSONB,p_operation JSONB,p_command TEXT,p_nonce TEXT,p_capture JSONB,p_decision JSONB,p_expected_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE cmd owner_captured_guest_choice_commands%ROWTYPE; result JSONB;
BEGIN
 cmd:=require_owner_guest_reward_choice_private_v1(p_source,p_operation,p_command,p_nonce);
 IF p_decision-'review' IS DISTINCT FROM cmd.original_grade THEN
  RAISE EXCEPTION 'immutable captured choice grade changed' USING ERRCODE='GP005'; END IF;
 result:=finish_captured_guest_reward_json_private_v1(p_operation,cmd.operation_id,p_capture,p_decision,p_expected_fence);
 IF result->>'state'<>'completed' THEN RAISE EXCEPTION 'actual completed choice required' USING ERRCODE='GP003'; END IF;
 IF cmd.state='completed' THEN
  IF cmd.result_snapshot IS DISTINCT FROM result->'result' THEN RAISE EXCEPTION 'immutable captured choice result changed' USING ERRCODE='GP005'; END IF;
 ELSE
  UPDATE owner_captured_guest_choice_commands SET state='completed',result_snapshot=result->'result',completed_at=clock_timestamp()
   WHERE command_id=cmd.command_id AND state='reserved';
  IF NOT FOUND THEN RAISE EXCEPTION 'captured choice completion changed' USING ERRCODE='GP005'; END IF;
 END IF;
 RETURN result;
END $$;

-- Source: owner-study-reward-producer-proposal-v2/owning-attempt-fence.sql
CREATE FUNCTION require_guest_reward_owning_attempt_private_v1(p_source TEXT,p_main TEXT,p_expected_fence TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE hold owner_participation_admission_operations%ROWTYPE;
BEGIN
 SELECT * INTO hold FROM owner_participation_admission_operations WHERE source_owner_id=p_source AND main_operation_id=p_main;
 IF NOT FOUND THEN
  IF p_expected_fence IS NOT NULL THEN RAISE EXCEPTION 'original hold token changed' USING ERRCODE='GP005'; END IF;
  RETURN;
 END IF;
 IF hold.state='pending' THEN
  PERFORM require_original_owner_admission_attempt_started_v1(hold.admission_id,p_expected_fence);
 ELSIF p_expected_fence IS NOT NULL THEN
  RAISE EXCEPTION 'old owning attempt is fenced' USING ERRCODE='GP005';
 END IF;
END $$;

-- Source: owner-study-reward-producer-proposal-v2/spoken-owning-fenced-leaves.sql
CREATE FUNCTION prepare_owner_guest_reward_spoken_v1(p_source JSONB,p_operation JSONB,p_checkpoint TEXT,p_expected_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_id TEXT; checked JSONB;
BEGIN
 source_id:=require_owner_guest_source_private_v1(p_source);
 checked:=prepare_guest_spoken_finalization_v1(source_id,p_operation,p_checkpoint);
 IF checked->>'state'='candidate' THEN
  PERFORM require_guest_reward_owning_attempt_private_v1(source_id,checked->>'operationId',p_expected_fence);
 END IF;
 RETURN checked;
END $$;
CREATE FUNCTION apply_owner_guest_reward_spoken_v1(p_source JSONB,p_operation JSONB,p_checkpoint TEXT,p_capture JSONB,p_decision JSONB,p_feedback JSONB,p_diff JSONB,p_spoken JSONB,p_expected_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_id TEXT; checked JSONB;
BEGIN
 source_id:=require_owner_guest_source_private_v1(p_source);
 checked:=prepare_owner_guest_reward_spoken_v1(p_source,p_operation,p_checkpoint,p_expected_fence);
 IF checked->>'state'<>'candidate' THEN RETURN checked; END IF;
 IF checked IS DISTINCT FROM p_capture THEN RAISE EXCEPTION 'actual fenced provider capture changed' USING ERRCODE='GP005'; END IF;
 RETURN apply_guest_spoken_item_mutation_v1(source_id,p_operation,p_checkpoint,p_capture,p_decision,p_feedback,p_diff,p_spoken);
END $$;
CREATE FUNCTION finish_owner_guest_reward_spoken_v1(p_source JSONB,p_operation JSONB,p_checkpoint TEXT,p_capture JSONB,p_decision JSONB,p_feedback JSONB,p_spoken JSONB,p_expected_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_id TEXT;
BEGIN
 source_id:=require_owner_guest_source_private_v1(p_source);
 RETURN finish_captured_guest_reward_spoken_private_v1(source_id,p_operation,p_checkpoint,p_capture,p_decision,p_feedback,p_spoken,p_expected_fence);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/choice-recovery-selector.sql
-- Only the finite controlled cron profile may receive EXECUTE; no raw rows or
-- public nonce/grade exposure. Candidates are locators, never authority by absence.
CREATE FUNCTION list_captured_owner_guest_reward_choices_v1(p_maximum INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE result JSONB;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_maximum IS NULL OR p_maximum<1 OR p_maximum>32 THEN
  RAISE EXCEPTION 'bounded captured choice recovery required' USING ERRCODE='GP003'; END IF;
 SELECT coalesce(jsonb_agg(x.value ORDER BY x.created_at,x.command_id COLLATE "C"),'[]'::JSONB) INTO result FROM(
  SELECT c.created_at,c.command_id,jsonb_build_object(
   'source',jsonb_build_object('kind','guest','ownerId',c.source_owner_id),
   'operation',jsonb_build_object('sourceOwnerId',m.source_owner_id,'kind',m.operation_kind,'idempotencyKey',m.idempotency_key,'requestHash',m.request_hash),
   'communityId',c.original_capture->'communityId','sessionId',c.session_id,'sessionItemId',c.session_item_id,'attemptNumber',c.attempt_number,
   'captured',jsonb_build_object('state','captured','operationId',c.operation_id,'commandId',c.command_id,'originalContinuationNonce',c.original_continuation_nonce)) AS value
  FROM owner_captured_guest_choice_commands c JOIN guest_participation_operations m ON m.operation_id=c.operation_id AND m.source_owner_id=c.source_owner_id
  JOIN study_sessions_v2 s ON s.session_id=c.session_id AND s.participation_owner_id=c.source_owner_id AND s.participation_owner_kind='guest'
  WHERE c.state='reserved' AND m.state='reserved' AND m.operation_kind='study_answer' AND s.guest_reward_mode='megapot_guest_v1'
  ORDER BY c.created_at,c.command_id COLLATE "C" LIMIT p_maximum
 ) x;
 RETURN result;
END $$;

-- Source: owner-study-reward-producer-proposal-v2/captured-original-hold-retry.sql
-- ACK this preparation BEFORE T2. An already-started pending generation must
-- first be authoritatively reconciled under the original source/session/draw
-- locks, even if a retry discovers no committed share. It cannot simply reuse
-- that fence. A delayed old T2 carries its old token and refuses after fencing.
CREATE FUNCTION prepare_captured_original_owning_attempt_private_v1(p_source TEXT,p_main TEXT,p_new_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE hold owner_participation_admission_operations%ROWTYPE; drawing megapot_pool_drawings%ROWTYPE;
 started TIMESTAMPTZ;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO hold FROM owner_participation_admission_operations WHERE source_owner_id=p_source AND main_operation_id=p_main;
 IF NOT FOUND THEN RETURN NULL; END IF;
 -- Controlled caller already owns global/edge/whole group/media/session.
 SELECT * INTO STRICT drawing FROM megapot_pool_drawings WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id FOR UPDATE;
 SELECT * INTO STRICT hold FROM owner_participation_admission_operations WHERE admission_id=hold.admission_id FOR UPDATE;
 SELECT started_at INTO STRICT started FROM owner_participation_admission_attempts
  WHERE admission_id=hold.admission_id AND attempt_fence=hold.current_attempt_fence;
 IF hold.state='pending' AND started IS NOT NULL THEN
  -- Fresh statements after original lock waits inspect actual committed state.
  -- No owned T2 can still commit under this fenced generation after we resolve it.
  IF EXISTS(SELECT 1 FROM megapot_owner_shares WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id
   AND owner_id=hold.source_owner_id AND qualification_id=hold.qualification_id)
   OR EXISTS(SELECT 1 FROM guest_participation_operations WHERE operation_id=p_main AND state='completed') THEN
   RAISE EXCEPTION 'grade/share/outcome atomicity differs' USING ERRCODE='GP003'; END IF;
  UPDATE owner_participation_admission_attempts SET state='authoritative_no_commit',resolved_at=clock_timestamp()
   WHERE admission_id=hold.admission_id AND attempt_fence=hold.current_attempt_fence AND state='pending';
  UPDATE owner_participation_admission_operations SET state='reconciled_no_commit',resolved_at=clock_timestamp(),
   result_snapshot=jsonb_build_object('state',CASE WHEN clock_timestamp()>=hold.entry_cutoff_at OR clock_timestamp()>=hold.purchase_safety_deadline_at THEN 'entry_closed' ELSE 'unavailable' END)
   WHERE admission_id=hold.admission_id AND state='pending';
  SELECT * INTO STRICT hold FROM owner_participation_admission_operations WHERE admission_id=hold.admission_id;
 END IF;
 IF hold.state='reconciled_no_commit' THEN
  IF NOT EXISTS(SELECT 1 FROM owner_participation_admission_attempts WHERE admission_id=hold.admission_id
   AND attempt_fence=hold.current_attempt_fence AND state='authoritative_no_commit') THEN
   RAISE EXCEPTION 'authoritative old attempt fence missing' USING ERRCODE='GP003'; END IF;
  IF drawing.beneficiary_version<>3 OR drawing.status<>'entry_open'
   OR clock_timestamp()>=hold.entry_cutoff_at OR clock_timestamp()>=hold.purchase_safety_deadline_at THEN RETURN NULL; END IF;
  IF p_new_fence IS NULL OR p_new_fence !~ '^[0-9a-f]{64}$' OR p_new_fence=hold.current_attempt_fence THEN
   RAISE EXCEPTION 'fresh same-original fence required' USING ERRCODE='GP005'; END IF;
  INSERT INTO owner_participation_admission_attempts(admission_id,attempt_number,attempt_fence,state)
   VALUES(hold.admission_id,hold.current_attempt_number+1,p_new_fence,'pending');
  UPDATE owner_participation_admission_operations SET state='pending',current_attempt_number=hold.current_attempt_number+1,
   current_attempt_fence=p_new_fence,result_snapshot=NULL,resolved_at=NULL WHERE admission_id=hold.admission_id AND state='reconciled_no_commit';
  SELECT * INTO STRICT hold FROM owner_participation_admission_operations WHERE admission_id=hold.admission_id;
 END IF;
 IF hold.state<>'pending' THEN RETURN NULL; END IF;
 PERFORM mark_original_owner_admission_attempt_started_v1(hold.admission_id,hold.current_attempt_fence);
 RETURN jsonb_build_object('admissionId',hold.admission_id,'attemptFence',hold.current_attempt_fence);
END $$;
CREATE FUNCTION resume_owner_guest_reward_choice_hold_v1(p_source JSONB,p_operation JSONB,p_command TEXT,p_nonce TEXT,p_new_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE cmd owner_captured_guest_choice_commands%ROWTYPE; checked JSONB;
BEGIN
 cmd:=require_owner_guest_reward_choice_private_v1(p_source,p_operation,p_command,p_nonce);
 checked:=read_captured_guest_reward_choice_v1(p_command,p_nonce);
 IF checked->>'state'='completed' THEN RETURN NULL; END IF;
 RETURN prepare_captured_original_owning_attempt_private_v1(cmd.source_owner_id,cmd.operation_id,p_new_fence);
END $$;
CREATE FUNCTION resume_owner_guest_reward_spoken_hold_v1(p_source JSONB,p_operation JSONB,p_checkpoint TEXT,p_new_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_id TEXT; checked JSONB; cap guest_study_spoken_captures%ROWTYPE;
BEGIN
 source_id:=require_owner_guest_source_private_v1(p_source);
 checked:=prepare_guest_spoken_finalization_v1(source_id,p_operation,p_checkpoint);
 IF checked->>'state'<>'candidate' THEN RETURN NULL; END IF;
 SELECT c.* INTO STRICT cap FROM guest_study_spoken_captures c JOIN guest_study_spoken_checkpoints cp USING(capture_id)
  WHERE cp.checkpoint_id=p_checkpoint AND cp.source_owner_id=source_id;
 RETURN prepare_captured_original_owning_attempt_private_v1(source_id,cap.operation_id,p_new_fence);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/spoken-dispatch-mode-successors.sql
CREATE OR REPLACE FUNCTION read_guest_spoken_context_v1(p_access JSONB,p_community TEXT,p_session TEXT,p_item TEXT,p_key TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE sess study_sessions_v2%ROWTYPE; rsv guest_resource_session_reservations%ROWTYPE;
 item study_session_items_v2%ROWTYPE; exercise study_exercise_versions%ROWTYPE; profile study_language_profile_units%ROWTYPE;
 dominant TEXT; provenance JSONB;
BEGIN
 PERFORM require_guest_study_composition_v1();
 SELECT * INTO sess FROM study_sessions_v2 WHERE session_id=p_session AND community_id=p_community
  AND participation_owner_kind='guest';
 IF NOT FOUND THEN RAISE EXCEPTION 'guest spoken lesson unavailable' USING ERRCODE='GP010'; END IF;
 SELECT * INTO STRICT rsv FROM guest_resource_session_reservations WHERE reservation_id=sess.guest_resource_reservation_id;
 PERFORM lock_guest_resource_budget_v1(sess.participation_owner_id,rsv.edge_fingerprint);
 PERFORM require_guest_study_learning_access_v1(p_access,sess.participation_owner_id);
 SELECT * INTO STRICT sess FROM study_sessions_v2 WHERE session_id=p_session FOR UPDATE;
 IF NOT can_guest_access_activity_song_v1(p_community,sess.post_id)
  OR NOT((sess.status='active' AND sess.expires_at>clock_timestamp() AND sess.current_session_item_id=p_item)
    OR EXISTS(SELECT 1 FROM study_spoken_answer_commands WHERE session_id=p_session AND session_item_id=p_item
      AND participation_owner_id=sess.participation_owner_id AND idempotency_key=p_key AND state='completed')) THEN
  RAISE EXCEPTION 'guest spoken lesson unavailable' USING ERRCODE='GP010'; END IF;
 IF EXISTS(SELECT 1 FROM owner_captured_guest_choice_commands WHERE source_owner_id=sess.participation_owner_id
  AND session_id=sess.session_id AND state='reserved') THEN RAISE EXCEPTION 'accepted choice continuation pending' USING ERRCODE='GP003'; END IF;
 IF sess.guest_reward_mode='megapot_guest_v1' THEN PERFORM require_owner_accounting_ready_private_v1(); END IF;
 SELECT * INTO STRICT item FROM study_session_items_v2 WHERE session_id=p_session AND session_item_id=p_item
  AND participation_owner_id=sess.participation_owner_id;
 SELECT * INTO STRICT exercise FROM study_exercise_versions WHERE exercise_version_id=item.exercise_version_id;
 IF item.item_snapshot->>'exercise_type' IS DISTINCT FROM 'say_it_back'
  OR jsonb_typeof(exercise.private_grader->'reference_text') IS DISTINCT FROM 'string'
  OR NOT((exercise.private_grader->>'kind'='source_token_diff_v1' AND item.item_snapshot->>'grader_policy_revision'='script_aware_token_diff_v1')
    OR (exercise.private_grader->>'kind'='source_token_phonetic_v2' AND item.item_snapshot->>'grader_policy_revision'='script_aware_token_phonetic_v2')
    OR (exercise.private_grader->>'kind'='source_token_phonetic_v3' AND item.item_snapshot->>'grader_policy_revision'='script_aware_token_phonetic_v3')
    OR (exercise.private_grader->>'kind'='source_token_phonetic_v4' AND item.item_snapshot->>'grader_policy_revision'='script_aware_token_phonetic_v4')) THEN
  RAISE EXCEPTION 'supported spoken source required' USING ERRCODE='GP003'; END IF;
 SELECT * INTO profile FROM study_language_profile_units WHERE community_id=sess.community_id AND post_id=sess.post_id
  AND lyrics_revision=sess.lyrics_revision AND language_profile_revision=sess.language_profile_revision AND study_unit_id=exercise.study_unit_id;
 dominant:=CASE WHEN profile.mixed IS FALSE AND profile.confidence>=0.8 THEN profile.dominant_language END;
 provenance:=CASE WHEN dominant IS NULL THEN jsonb_build_object('kind','no_authoritative_evidence') ELSE
  jsonb_build_object('kind','unit_profile','community_id',profile.community_id,'post_id',profile.post_id,
   'lyrics_revision',profile.lyrics_revision,'language_profile_revision',profile.language_profile_revision,
   'study_unit_id',profile.study_unit_id,'confidence',profile.confidence,'dominant_language',dominant) END;
 RETURN jsonb_build_object('source',jsonb_build_object('kind','guest','ownerId',sess.participation_owner_id),
  'context',jsonb_build_object('item',item.item_snapshot,'referenceText',exercise.private_grader->>'reference_text',
    'dominantLanguage',dominant,'languageProvenance',provenance));
END $$;

CREATE OR REPLACE FUNCTION reserve_guest_spoken_answer_v1(p_access JSONB,p_operation JSONB,p_source TEXT,
 p_payload JSONB,p_reservation TEXT,p_fence BIGINT,p_policy JSONB,p_disclosure_version TEXT,
 p_rerecord_enabled BOOLEAN,p_provider_retention TEXT,p_operation_id TEXT,p_upload_id TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE sess study_sessions_v2%ROWTYPE; item study_session_items_v2%ROWTYPE; state study_lesson_item_state_v2%ROWTYPE;
 rsv guest_resource_session_reservations%ROWTYPE; main_op guest_participation_operations%ROWTYPE;
 cmd study_spoken_answer_commands%ROWTYPE; artifact learner_audio_artifacts%ROWTYPE;
 component TEXT[]; stored_policy JSONB; provider JSONB; captured JSONB; original_cmd TEXT; original_attempt TEXT; original_artifact TEXT;
 expected_ref TEXT; at_time TIMESTAMPTZ; retention_mode TEXT; artifact_expires TIMESTAMPTZ;
BEGIN
 PERFORM require_guest_study_composition_v1();
 PERFORM validate_guest_resource_operation_v1(p_source,p_operation,'study_answer');
 IF p_payload IS NULL OR jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
  OR (SELECT count(*) FROM jsonb_object_keys(p_payload))<>13
  OR NOT(p_payload ?& ARRAY['sessionId','sessionItemId','attemptNumber','audioDigest','audioContentType','audioByteSize','audioDurationMs',
    'commandId','attemptId','artifactId','leaseToken','providerRetention','requestHash'])
  OR jsonb_typeof(p_payload->'audioDigest') IS DISTINCT FROM 'string' OR p_payload->>'audioDigest' !~ '^[0-9a-f]{64}$'
  OR p_payload->>'requestHash' IS DISTINCT FROM p_operation->>'requestHash'
  OR p_payload->>'audioContentType' IS NULL OR p_payload->>'audioContentType' NOT IN('audio/webm','audio/ogg','audio/mp4','audio/wav')
  OR p_provider_retention IS NULL OR p_provider_retention NOT IN('stored','not_stored')
  OR p_payload->>'providerRetention' IS DISTINCT FROM p_provider_retention
  OR jsonb_typeof(p_payload->'attemptNumber') IS DISTINCT FROM 'number' OR (p_payload->>'attemptNumber')::NUMERIC NOT BETWEEN 1 AND 3
  OR trunc((p_payload->>'attemptNumber')::NUMERIC)<>(p_payload->>'attemptNumber')::NUMERIC
  OR jsonb_typeof(p_payload->'audioByteSize') IS DISTINCT FROM 'number' OR (p_payload->>'audioByteSize')::NUMERIC NOT BETWEEN 1 AND 524288
  OR trunc((p_payload->>'audioByteSize')::NUMERIC)<>(p_payload->>'audioByteSize')::NUMERIC
  OR jsonb_typeof(p_payload->'audioDurationMs') IS DISTINCT FROM 'number' OR (p_payload->>'audioDurationMs')::NUMERIC NOT BETWEEN 1 AND 60000
  OR trunc((p_payload->>'audioDurationMs')::NUMERIC)<>(p_payload->>'audioDurationMs')::NUMERIC THEN
  RAISE EXCEPTION 'closed spoken request required' USING ERRCODE='GP003'; END IF;
 SELECT * INTO sess FROM study_sessions_v2 WHERE session_id=p_payload->>'sessionId' AND participation_owner_id=p_source
  AND participation_owner_kind='guest';
 IF NOT FOUND THEN RAISE EXCEPTION 'guest spoken lesson unavailable' USING ERRCODE='GP010'; END IF;
 SELECT * INTO STRICT rsv FROM guest_resource_session_reservations WHERE reservation_id=sess.guest_resource_reservation_id;
 component:=lock_guest_resource_budget_v1(p_source,rsv.edge_fingerprint);
 PERFORM require_guest_study_learning_access_v1(p_access,p_source);
 SELECT * INTO main_op FROM guest_participation_operations WHERE source_owner_id=p_source
  AND operation_kind='study_answer' AND idempotency_key=p_operation->>'idempotencyKey' FOR UPDATE;
 IF FOUND THEN
  IF ROW(main_op.request_hash,main_op.resource_scope) IS DISTINCT FROM ROW(p_operation->>'requestHash',
   guest_study_answer_resource_scope_v1(sess.community_id,sess.session_id,p_payload->>'sessionItemId',(p_payload->>'attemptNumber')::INTEGER,'spoken')) THEN
   RAISE EXCEPTION 'original spoken request changed' USING ERRCODE='GP005'; END IF;
  -- Any existing key is observation only; it never reissues its old dispatch.
  IF main_op.state='completed' THEN RETURN jsonb_build_object('state','completed','result',main_op.result_snapshot); END IF;
  RETURN jsonb_build_object('state','pending_confirmation','operation',p_operation);
 END IF;
 IF EXISTS(SELECT 1 FROM owner_captured_guest_choice_commands WHERE source_owner_id=sess.participation_owner_id
  AND session_id=sess.session_id AND state='reserved') THEN RAISE EXCEPTION 'accepted choice continuation pending' USING ERRCODE='GP003'; END IF;
 IF sess.guest_reward_mode='megapot_guest_v1' THEN PERFORM require_owner_accounting_ready_private_v1(); END IF;
 PERFORM lock_learner_audio_sources_private_v1(component);
 IF EXISTS(SELECT 1 FROM learner_audio_owner_fences WHERE owner_id=ANY(component) AND active_delete_command_id IS NOT NULL) THEN
  RAISE EXCEPTION 'learner audio deletion in progress' USING ERRCODE='GP009'; END IF;
 INSERT INTO learner_audio_owner_fences(owner_id) VALUES(p_source) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM learner_audio_owner_fences WHERE owner_id=p_source AND revision=p_fence AND active_delete_command_id IS NULL FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'new dispatch deletion fence changed' USING ERRCODE='GP009'; END IF;
 SELECT * INTO STRICT sess FROM study_sessions_v2 WHERE session_id=sess.session_id FOR UPDATE;
 SELECT * INTO item FROM study_session_items_v2 WHERE session_id=sess.session_id AND session_item_id=p_payload->>'sessionItemId'
  AND participation_owner_id=p_source FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'spoken item unavailable' USING ERRCODE='GP003'; END IF;
 SELECT * INTO STRICT state FROM study_lesson_item_state_v2 WHERE session_item_id=item.session_item_id AND session_id=sess.session_id FOR UPDATE;
 IF sess.status<>'active' OR sess.expires_at<=clock_timestamp() OR sess.current_session_item_id IS DISTINCT FROM item.session_item_id
  OR item.item_snapshot->>'exercise_type' IS DISTINCT FROM 'say_it_back' OR item.maximum_attempts IS DISTINCT FROM 3
  OR state.lesson_resolved OR (p_payload->>'attemptNumber')::INTEGER<>state.presentation_count+1
  OR NOT((sess.guest_reward_mode='practice_only' AND sess.guest_reward_terms IS NULL)
   OR(sess.guest_reward_mode='megapot_guest_v1' AND sess.guest_reward_terms IS NOT NULL))
  OR NOT can_guest_access_activity_song_v1(sess.community_id,sess.post_id)
  OR ROW(rsv.reservation_id,rsv.source_owner_id,rsv.session_id) IS DISTINCT FROM ROW(p_reservation,p_source,sess.session_id)
  OR sess.guest_disclosure_accepted IS DISTINCT FROM TRUE OR sess.guest_disclosure_version IS DISTINCT FROM p_disclosure_version THEN
  RAISE EXCEPTION 'current spoken admission unavailable' USING ERRCODE='GP003'; END IF;
 PERFORM validate_guest_resource_policy_v1(p_policy);
 SELECT policy INTO STRICT stored_policy FROM guest_resource_policy_snapshots WHERE policy_version=rsv.policy_version;
 IF stored_policy IS DISTINCT FROM p_policy OR rsv.cost_policy_version IS DISTINCT FROM p_policy->>'costPolicyVersion'
  OR rsv.unit_hold_micros IS DISTINCT FROM (p_policy->>'maximumProviderCallCostMicros')::NUMERIC THEN
  RAISE EXCEPTION 'captured resource policy changed' USING ERRCODE='GP006'; END IF;
 -- Required private plan closure owned by the separately reviewed forty-unit
 -- successor. It checks the ORIGINAL stored selected spoken-card allowance
 -- and policy: enabled rerecord needs two paid invocations per graded slot,
 -- while the shared graded presentation cap remains twenty. This helper is
 -- an explicit prerequisite and must stay closed on the actual old20 module.
 -- No permanent policy downgrade and no caller flag manufactures allowance.
 PERFORM require_guest_spoken_resource_plan_v1(p_source,sess.session_id,rsv.reservation_id,p_rerecord_enabled);
 SELECT * INTO cmd FROM study_spoken_answer_commands WHERE session_id=sess.session_id AND participation_owner_id=p_source
  AND session_item_id=item.session_item_id AND attempt_number=(p_payload->>'attemptNumber')::INTEGER AND result_kind='graded' FOR UPDATE;
 IF FOUND THEN
  -- No clock-expiry reclaim. Every retained dispatch must be definitively
  -- terminal, without accepted success, and its actual object absence closed.
  IF cmd.state='completed' OR NOT EXISTS(SELECT 1 FROM guest_study_spoken_captures WHERE command_id=cmd.command_id)
   OR EXISTS(SELECT 1 FROM guest_study_spoken_captures c JOIN guest_resource_provider_calls call_row ON call_row.call_id=c.provider_call_id
     JOIN learner_audio_upload_attempts u ON u.upload_attempt_id=c.upload_attempt_id
     LEFT JOIN guest_study_spoken_checkpoints cp ON cp.capture_id=c.capture_id
     WHERE c.command_id=cmd.command_id AND (cp.checkpoint_id IS NOT NULL OR call_row.disposition NOT IN('failed','not_invoked')
       OR u.io_state<>'closed' OR u.storage_disposition IS DISTINCT FROM 'absent' OR u.cleanup_required)) THEN
   RETURN jsonb_build_object('state','pending_confirmation','operation',p_operation); END IF;
  SELECT * INTO STRICT artifact FROM learner_audio_artifacts WHERE learner_audio_artifact_id=cmd.learner_audio_artifact_id FOR UPDATE;
  IF artifact.recording_state NOT IN('pending','failed') OR artifact.deleted_at IS NOT NULL
   OR artifact.provider_retention IS DISTINCT FROM p_provider_retention
   OR EXISTS(SELECT 1 FROM study_attempts_v2 WHERE learner_audio_artifact_id=artifact.learner_audio_artifact_id) THEN
   RAISE EXCEPTION 'accepted artifact cannot be reclaimed' USING ERRCODE='GP003'; END IF;
  original_cmd:=cmd.command_id;original_attempt:=cmd.attempt_id;original_artifact:=cmd.learner_audio_artifact_id;
 ELSE
  original_cmd:=p_payload->>'commandId';original_attempt:=p_payload->>'attemptId';original_artifact:=p_payload->>'artifactId';
 END IF;
 IF p_payload->>'leaseToken' IS NULL OR char_length(p_payload->>'leaseToken') NOT BETWEEN 1 AND 256
  OR p_operation_id IS NULL OR char_length(p_operation_id) NOT BETWEEN 1 AND 128
  OR p_upload_id IS NULL OR char_length(p_upload_id) NOT BETWEEN 1 AND 128 THEN
  RAISE EXCEPTION 'private generated command identity required' USING ERRCODE='GP003'; END IF;
 -- FUTURE recording generation uses the actual source preference. Exact
 -- accepted-key replay above performs no preference/expiry mutation. The whole
 -- source component is already locked, serializing the retention producer.
 SELECT mode INTO retention_mode FROM guest_learning_preferences WHERE owner_id=p_source FOR UPDATE;
 IF NOT FOUND THEN retention_mode:='private_learning'; END IF;
 IF retention_mode IS NULL OR retention_mode NOT IN('private_learning','ephemeral') THEN
  RAISE EXCEPTION 'closed learning retention preference required' USING ERRCODE='GP006'; END IF;
 at_time:=clock_timestamp();artifact_expires:=CASE WHEN retention_mode='ephemeral'
  THEN at_time+INTERVAL '24 hours' ELSE at_time+INTERVAL '24 months' END;
 expected_ref:='learner-audio/study/'||original_attempt||'/'||(p_payload->>'audioDigest');
 INSERT INTO guest_participation_operations(operation_id,source_owner_id,operation_kind,resource_scope,idempotency_key,request_hash,state,created_at)
  VALUES(p_operation_id,p_source,'study_answer',guest_study_answer_resource_scope_v1(sess.community_id,sess.session_id,item.session_item_id,
    (p_payload->>'attemptNumber')::INTEGER,'spoken'),p_operation->>'idempotencyKey',p_operation->>'requestHash','reserved',at_time);
 IF cmd.command_id IS NULL THEN
  INSERT INTO study_spoken_answer_commands(command_id,account_id,participation_owner_id,participation_owner_kind,session_id,session_item_id,
   attempt_number,idempotency_key,request_hash,audio_digest,audio_content_type,audio_byte_size,audio_duration_ms,attempt_id,
   learner_audio_artifact_id,lease_token,lease_expires_at,state,reserved_at)
  VALUES(original_cmd,NULL,p_source,'guest',sess.session_id,item.session_item_id,(p_payload->>'attemptNumber')::INTEGER,
   p_operation->>'idempotencyKey',p_operation->>'requestHash',p_payload->>'audioDigest',p_payload->>'audioContentType',
   (p_payload->>'audioByteSize')::INTEGER,(p_payload->>'audioDurationMs')::INTEGER,original_attempt,original_artifact,
   p_payload->>'leaseToken',at_time+INTERVAL '60 seconds','reserved',at_time);
  INSERT INTO learner_audio_artifacts(learner_audio_artifact_id,account_id,participation_owner_id,participation_owner_kind,
   source_kind,attempt_ref,expected_object_ref,object_ref,content_digest,content_type,byte_size,duration_ms,platform_retention,
   provider_retention,recording_state,expires_at,created_at)
  VALUES(original_artifact,NULL,p_source,'guest','study',original_attempt,expected_ref,NULL,p_payload->>'audioDigest',p_payload->>'audioContentType',
   (p_payload->>'audioByteSize')::INTEGER,(p_payload->>'audioDurationMs')::INTEGER,retention_mode,p_provider_retention,'pending',artifact_expires,at_time);
 ELSE
  UPDATE study_spoken_answer_commands SET idempotency_key=p_operation->>'idempotencyKey',request_hash=p_operation->>'requestHash',
   audio_digest=p_payload->>'audioDigest',audio_content_type=p_payload->>'audioContentType',audio_byte_size=(p_payload->>'audioByteSize')::INTEGER,
   audio_duration_ms=(p_payload->>'audioDurationMs')::INTEGER,lease_token=p_payload->>'leaseToken',lease_expires_at=at_time+INTERVAL '60 seconds',
   state='reserved',provider_failure_kind=NULL,result_snapshot=NULL,completed_at=NULL,reserved_at=at_time WHERE command_id=original_cmd;
  UPDATE learner_audio_artifacts SET expected_object_ref=expected_ref,object_ref=NULL,content_digest=p_payload->>'audioDigest',
   content_type=p_payload->>'audioContentType',byte_size=(p_payload->>'audioByteSize')::INTEGER,duration_ms=(p_payload->>'audioDurationMs')::INTEGER,
   recording_state='pending',platform_retention=retention_mode,expires_at=artifact_expires WHERE learner_audio_artifact_id=original_artifact;
 END IF;
 provider:=reserve_guest_provider_call_v1(p_source,p_operation,sess.session_id,p_reservation,1,
  p_policy->>'maximumProviderCallCostMicros',p_policy->>'costPolicyVersion');
 IF provider#>>'{result,state}' IS DISTINCT FROM 'reserved' THEN
  RAISE EXCEPTION 'first fresh provider reservation required' USING ERRCODE='GP006'; END IF;
 PERFORM register_learner_audio_upload_private_v1(p_source,original_artifact,'study',original_attempt,original_cmd,p_reservation,expected_ref,p_upload_id,p_fence);
 captured:=capture_guest_spoken_dispatch_private_v1(p_source,p_operation,original_cmd,p_payload->>'leaseToken',
  provider#>>'{result,callId}',p_reservation,p_upload_id,p_fence,p_rerecord_enabled);
 IF captured->'fresh' IS DISTINCT FROM 'true'::JSONB THEN
  RAISE EXCEPTION 'first fresh captured dispatch required' USING ERRCODE='GP006'; END IF;
 RETURN jsonb_build_object('state','reserved','commandId',original_cmd,'leaseToken',p_payload->>'leaseToken',
  'attemptId',original_attempt,'artifactId',original_artifact,'resourceReservationId',p_reservation,'deletionFenceRevision',p_fence);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/prepare-spoken-mode-successor.sql
CREATE OR REPLACE FUNCTION prepare_guest_spoken_finalization_v1(p_source TEXT,p_operation JSONB,p_checkpoint TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE cp guest_study_spoken_checkpoints%ROWTYPE; cap guest_study_spoken_captures%ROWTYPE;
 rsv guest_resource_session_reservations%ROWTYPE; call_row guest_resource_provider_calls%ROWTYPE;
 main_op guest_participation_operations%ROWTYPE; cmd study_spoken_answer_commands%ROWTYPE;
 sess study_sessions_v2%ROWTYPE; item study_session_items_v2%ROWTYPE; state study_lesson_item_state_v2%ROWTYPE;
 review study_review_items%ROWTYPE; upload learner_audio_upload_attempts%ROWTYPE; artifact learner_audio_artifacts%ROWTYPE;
 fence learner_audio_owner_fences%ROWTYPE; prior_rerecord BOOLEAN; archive JSONB; total INTEGER; remaining INTEGER;
BEGIN
 PERFORM require_guest_study_composition_v1();
 PERFORM validate_guest_resource_operation_v1(p_source,p_operation,'study_answer');
 SELECT * INTO cp FROM guest_study_spoken_checkpoints WHERE checkpoint_id=p_checkpoint AND source_owner_id=p_source;
 IF NOT FOUND THEN RAISE EXCEPTION 'accepted successful checkpoint unavailable' USING ERRCODE='GP010'; END IF;
 SELECT * INTO STRICT cap FROM guest_study_spoken_captures WHERE capture_id=cp.capture_id;
 IF ROW(cap.source_owner_id,cap.idempotency_key,cap.request_hash,cp.provider_call_id,cp.resource_reservation_id)
  IS DISTINCT FROM ROW(p_source,p_operation->>'idempotencyKey',p_operation->>'requestHash',cap.provider_call_id,cap.resource_reservation_id) THEN
  RAISE EXCEPTION 'original checkpoint identity changed' USING ERRCODE='GP005'; END IF;
 SELECT * INTO STRICT rsv FROM guest_resource_session_reservations WHERE reservation_id=cap.resource_reservation_id;
 PERFORM lock_guest_resource_budget_v1(p_source,rsv.edge_fingerprint);
 PERFORM lock_learner_audio_sources_private_v1(ARRAY[p_source]);
 main_op:=require_guest_answer_operation_private_v1(p_source,p_operation,cap.operation_id,
  cap.grading_context->>'communityId',cap.session_id,cap.session_item_id,cap.attempt_number,'spoken');
 SELECT * INTO STRICT cmd FROM study_spoken_answer_commands WHERE command_id=cap.command_id FOR UPDATE;
 SELECT * INTO STRICT sess FROM study_sessions_v2 WHERE session_id=cap.session_id FOR UPDATE;
 SELECT * INTO STRICT call_row FROM guest_resource_provider_calls WHERE call_id=cap.provider_call_id FOR UPDATE;
 IF ROW(cmd.participation_owner_id,cmd.participation_owner_kind,cmd.account_id,cmd.session_id,cmd.session_item_id,
    cmd.attempt_number,cmd.attempt_id,cmd.learner_audio_artifact_id,cmd.idempotency_key,cmd.request_hash,cmd.lease_token)
  IS DISTINCT FROM ROW(p_source,'guest'::TEXT,NULL::TEXT,cap.session_id,cap.session_item_id,
    cap.attempt_number::BIGINT,cap.attempt_id,cap.artifact_id,cap.idempotency_key,cap.request_hash,cap.original_lease_token)
  OR ROW(sess.participation_owner_id,sess.participation_owner_kind,sess.guest_resource_reservation_id,sess.community_id)
    IS DISTINCT FROM ROW(p_source,'guest'::TEXT,cap.resource_reservation_id,cap.grading_context->>'communityId')
  OR ROW(call_row.source_owner_id,call_row.reservation_id,call_row.session_id,call_row.disposition,call_row.checkpoint_id)
    IS DISTINCT FROM ROW(p_source,cap.resource_reservation_id,cap.session_id,'completed'::TEXT,cp.checkpoint_id)
  OR cp.charged_cost_micros IS DISTINCT FROM call_row.actual_cost_micros
  OR cp.charged_cost_micros IS DISTINCT FROM call_row.maximum_provider_cost_micros
  OR cp.charge_basis IS DISTINCT FROM 'reserved_ceiling_v1' THEN
  RAISE EXCEPTION 'retained command/source/lease/call correlation changed' USING ERRCODE='GP005'; END IF;
 IF main_op.state='completed' THEN
  IF cmd.state IS DISTINCT FROM 'completed' OR cmd.result_snapshot IS DISTINCT FROM main_op.result_snapshot THEN
   RAISE EXCEPTION 'immutable completion receipts disagree' USING ERRCODE='GP005'; END IF;
  RETURN jsonb_build_object('state','completed','operationId',main_op.operation_id,'result',main_op.result_snapshot); END IF;
 IF main_op.state IS DISTINCT FROM 'reserved' OR cmd.state IS DISTINCT FROM 'reserved'
  OR sess.status IS DISTINCT FROM 'active' OR sess.current_session_item_id IS DISTINCT FROM cap.session_item_id
  OR NOT ((sess.guest_reward_mode='practice_only' AND sess.guest_reward_terms IS NULL)
   OR (sess.guest_reward_mode='megapot_guest_v1' AND sess.guest_reward_terms IS NOT NULL)) THEN
  RAISE EXCEPTION 'accepted lesson finalization state unavailable' USING ERRCODE='GP003'; END IF;
 -- Original hold was committed/acknowledged before this owning continuation.
 -- Acquire original draw/funding BEFORE item mutation/q/share writes.
 PERFORM lock_guest_reward_owning_draw_private_v1(p_source,main_op.operation_id);
 SELECT * INTO STRICT item FROM study_session_items_v2 WHERE session_item_id=cap.session_item_id
  AND session_id=cap.session_id AND participation_owner_id=p_source FOR UPDATE;
 SELECT * INTO STRICT state FROM study_lesson_item_state_v2 WHERE session_item_id=cap.session_item_id AND session_id=cap.session_id FOR UPDATE;
 SELECT * INTO STRICT review FROM study_review_items WHERE review_item_id=item.review_item_id AND participation_owner_id=p_source FOR UPDATE;
 IF item.item_snapshot IS DISTINCT FROM cap.grading_context->'item' OR item.maximum_attempts IS DISTINCT FROM 3
  OR state.lesson_resolved IS DISTINCT FROM FALSE OR state.presentation_count+1<>cap.attempt_number THEN
  RAISE EXCEPTION 'captured lesson item changed' USING ERRCODE='GP003'; END IF;
 SELECT * INTO STRICT upload FROM learner_audio_upload_attempts WHERE upload_attempt_id=cap.upload_attempt_id FOR UPDATE;
 SELECT * INTO STRICT artifact FROM learner_audio_artifacts WHERE learner_audio_artifact_id=cap.artifact_id FOR UPDATE;
 SELECT * INTO STRICT fence FROM learner_audio_owner_fences WHERE owner_id=p_source FOR UPDATE;
 IF ROW(upload.owner_id,upload.artifact_id,upload.source_kind,upload.attempt_ref,upload.command_ref,upload.reservation_ref,upload.captured_revision)
  IS DISTINCT FROM ROW(p_source,cap.artifact_id,'study'::TEXT,cap.attempt_id,cap.command_id,cap.resource_reservation_id,cap.deletion_fence_revision)
  OR ROW(artifact.participation_owner_id,artifact.source_kind,artifact.attempt_ref,artifact.content_digest,artifact.content_type,artifact.byte_size,artifact.duration_ms)
    IS DISTINCT FROM ROW(p_source,'study'::TEXT,cap.attempt_id,cap.audio_digest,cap.audio_content_type,cap.audio_byte_size::BIGINT,cap.audio_duration_ms::BIGINT)
  OR upload.object_ref IS DISTINCT FROM artifact.expected_object_ref THEN
  RAISE EXCEPTION 'retained upload/artifact source changed' USING ERRCODE='GP005'; END IF;
 IF upload.io_state IS DISTINCT FROM 'closed' THEN
  RETURN jsonb_build_object('state','reserved','operationId',main_op.operation_id,'result',NULL); END IF;
 -- Actual durable253 storage disposition, never caller result.archive. A
 -- later delete may invalidate publication without erasing successful learning.
 archive:=CASE WHEN upload.storage_disposition='stored' AND NOT upload.cleanup_required
   AND fence.revision=cap.deletion_fence_revision AND fence.active_delete_command_id IS NULL
   AND artifact.recording_state<>'deleted'
   AND NOT EXISTS(SELECT 1 FROM learner_audio_deleted_objects WHERE object_ref=upload.object_ref)
  THEN jsonb_build_object('state','stored','objectRef',upload.object_ref)
  ELSE jsonb_build_object('state','failed','objectRef',NULL) END;
 SELECT EXISTS(SELECT 1 FROM study_spoken_answer_commands prior WHERE prior.session_id=cap.session_id
  AND prior.session_item_id=cap.session_item_id AND prior.attempt_number=cap.attempt_number
  AND prior.participation_owner_id=p_source AND prior.result_kind='rerecord' AND prior.state='completed') INTO prior_rerecord;
 SELECT count(*)::INTEGER,count(*) FILTER(WHERE NOT lesson_resolved)::INTEGER INTO total,remaining
  FROM study_lesson_item_state_v2 WHERE session_id=cap.session_id;
 RETURN jsonb_build_object('state','candidate','checkpointId',cp.checkpoint_id,'captureId',cap.capture_id,'operationId',cap.operation_id,
  'sourceOwnerId',p_source,'result',cp.success_result,'item',item.item_snapshot,'reviewItemId',item.review_item_id,
  'review',jsonb_build_object('difficulty',review.difficulty,'lapses',review.lapses,'repetitions',review.repetitions,'stability',review.stability),
  'priorRerecordRecorded',prior_rerecord,'priorPresentationCount',sess.presentation_count,'currentPresentedAt',sess.current_presented_at,
  'totalCards',total,'remainingCards',remaining,'archive',archive,'resourceReservationId',cap.resource_reservation_id);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/spoken-hold-reader.sql
CREATE FUNCTION find_guest_reward_spoken_hold_v1(p_source JSONB,p_operation JSONB,p_checkpoint TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_id TEXT; checked JSONB; cp guest_study_spoken_checkpoints%ROWTYPE; cap guest_study_spoken_captures%ROWTYPE;
 sess study_sessions_v2%ROWTYPE; hold owner_participation_admission_operations%ROWTYPE;
BEGIN
 source_id:=require_owner_guest_source_private_v1(p_source);
 checked:=prepare_guest_spoken_finalization_v1(source_id,p_operation,p_checkpoint);
 IF checked->>'state'<>'candidate' THEN RETURN checked; END IF;
 SELECT * INTO STRICT cp FROM guest_study_spoken_checkpoints WHERE checkpoint_id=p_checkpoint AND source_owner_id=source_id;
 SELECT * INTO STRICT cap FROM guest_study_spoken_captures WHERE capture_id=cp.capture_id;
 SELECT * INTO STRICT sess FROM study_sessions_v2 WHERE session_id=cap.session_id AND participation_owner_id=source_id;
 IF sess.guest_reward_mode='practice_only' AND sess.guest_reward_terms IS NULL THEN RETURN jsonb_build_object('state','practice_only'); END IF;
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT * INTO hold FROM owner_participation_admission_operations WHERE source_owner_id=source_id AND main_operation_id=cap.operation_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','prepare_required'); END IF;
 RETURN jsonb_build_object('state','hold_prepared','admissionId',hold.admission_id,'attemptFence',hold.current_attempt_fence);
END $$;

-- Source: owner-study-reward-producer-proposal-v2/spoken-original-hold.sql
-- Separate acknowledged preparation after immutable successful provider CP and
-- before the ONE owning grade/qualification/admission transaction. No provider,
-- archive, regrade or new charge is invoked here. Old accepted CP ignores current
-- cookie/one-hour lease/config; original hold replay ignores current margin.
CREATE FUNCTION prepare_guest_reward_spoken_hold_v1(p_source TEXT,p_operation JSONB,p_checkpoint TEXT,
 p_admission TEXT,p_fence TEXT,p_salt BYTEA,p_safety_margin INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE checked JSONB; reply JSONB; cp guest_study_spoken_checkpoints%ROWTYPE; cap guest_study_spoken_captures%ROWTYPE;
 sess study_sessions_v2%ROWTYPE; qid TEXT; old_hold JSONB;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 checked:=prepare_guest_spoken_finalization_v1(p_source,p_operation,p_checkpoint);
 IF checked->>'state'<>'candidate' THEN RETURN checked; END IF;
 SELECT * INTO STRICT cp FROM guest_study_spoken_checkpoints WHERE checkpoint_id=p_checkpoint AND source_owner_id=p_source;
 SELECT * INTO STRICT cap FROM guest_study_spoken_captures WHERE capture_id=cp.capture_id;
 SELECT * INTO STRICT sess FROM study_sessions_v2 WHERE session_id=cap.session_id AND participation_owner_id=p_source;
 IF sess.guest_reward_mode='practice_only' AND sess.guest_reward_terms IS NULL THEN RETURN jsonb_build_object('state','practice_only'); END IF;
 PERFORM require_owner_accounting_ready_private_v1();
 old_hold:=find_owner_admission_private_v1(p_source,cap.operation_id);
 IF old_hold IS NOT NULL THEN RETURN jsonb_build_object('state','hold_prepared','admissionId',old_hold->'admissionId','attemptFence',old_hold->'attemptFence'); END IF;
 qid:='guest_qualification_'||encode(sha256(convert_to(jsonb_build_array(p_source,cap.session_id)::TEXT,'UTF8')),'hex');
 reply:=prepare_owner_admission_hold_private_v1(p_source,cap.session_id,cap.operation_id,qid,
  p_admission,p_fence,p_salt,p_safety_margin);
 IF reply->>'admissionId' IS NULL THEN RETURN jsonb_build_object('state','hold_refused'); END IF;
 RETURN jsonb_build_object('state','hold_prepared','admissionId',reply->'admissionId','attemptFence',reply->'attemptFence');
END $$;

-- Source: owner-account-reward-producer-proposal-0cc7ef57/account-existing-owner-lock-successor.sql
-- Exact native0249 bookkeeping: compatible non-key lock, no late provisioning/reparenting/admission.
CREATE OR REPLACE FUNCTION require_existing_account_participation_owner_v1(expected_account_id TEXT) RETURNS TEXT
 LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE mapped_owner TEXT;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 -- This is original-source bookkeeping, not new account admission authority.
 -- Do not reparent historical aliases or refuse accepted recovery on status change.
 SELECT owner_id INTO mapped_owner FROM participation_owners
   WHERE kind='account' AND account_id=expected_account_id FOR NO KEY UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'account owner must be provisioned before activity'; END IF;
 RETURN mapped_owner;
END $$;

-- Source: owner-account-reward-producer-proposal-0cc7ef57/account-original-actions.sql
CREATE FUNCTION account_owner_reward_operation_receipt_private_v1(p_main TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE op account_owner_reward_operations%ROWTYPE; hold owner_participation_admission_operations%ROWTYPE; source account_owner_reward_sources%ROWTYPE; started BOOLEAN;
BEGIN
 SELECT * INTO STRICT op FROM account_owner_reward_operations WHERE operation_id=p_main;
 SELECT * INTO STRICT source FROM account_owner_reward_sources WHERE source_owner_id=op.source_owner_id AND session_kind=op.session_kind AND session_id=op.session_id;
 SELECT * INTO hold FROM owner_participation_admission_operations WHERE main_operation_id=op.operation_id AND source_owner_id=op.source_owner_id;
 SELECT started_at IS NOT NULL INTO started FROM owner_participation_admission_attempts
  WHERE admission_id=hold.admission_id AND attempt_fence=hold.current_attempt_fence;
 RETURN jsonb_build_object('mainOperationId',op.operation_id,'sourceOwnerId',op.source_owner_id,'sourceFamily',op.session_kind,
  'sessionId',op.session_id,'operationKind',op.operation_kind,'idempotencyKey',op.idempotency_key,'requestHash',op.request_hash,
  'accountId',source.account_id,'communityId',source.community_id,'producerKind',op.producer_kind,
  'commandRef',CASE WHEN op.producer_kind='v2_spoken' THEN op.captured_payload->>'commandId' END,
  'qualificationId',op.qualification_id,'state',op.state,'completion',op.completion_snapshot,
  'holdPresent',hold.admission_id IS NOT NULL,'holdState',hold.state,
  'attemptFence',CASE WHEN hold.state='pending' THEN hold.current_attempt_fence END,
  'attemptStarted',coalesce(started,FALSE),'noAdmission',op.original_admission_result);
END $$;

CREATE FUNCTION read_account_reward_session_private_v1(p_family TEXT,p_session TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE row_json JSONB;
BEGIN
 IF p_family='study_legacy' THEN SELECT to_jsonb(s) INTO row_json FROM study_sessions s WHERE session_id=p_session;
 ELSIF p_family='study_v2' THEN SELECT to_jsonb(s) INTO row_json FROM study_sessions_v2 s WHERE session_id=p_session;
 ELSIF p_family='karaoke' THEN SELECT to_jsonb(s) INTO row_json FROM karaoke_sessions s WHERE session_id=p_session;
 ELSE RAISE EXCEPTION 'closed Account source family required' USING ERRCODE='GP006'; END IF;
 RETURN row_json;
END $$;

CREATE FUNCTION validate_account_reward_source_parent_private_v1() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE actual JSONB;
BEGIN
 actual:=read_account_reward_session_private_v1(NEW.session_kind,NEW.session_id);
 IF actual IS NULL OR ROW(actual->>'account_id',actual->>'persona_id',actual->>'community_id',actual->>'post_id',actual->>'audio_revision',actual->>'lyrics_revision',
  coalesce(actual->>'qualification_policy_revision',actual->>'qualification_policy_version_id'),actual->>'owner_reward_preview_hash',actual->>'owner_reward_disclosure_version',actual->'owner_reward_disclosure_accepted')
  IS DISTINCT FROM ROW(NEW.account_id,NEW.persona_id,NEW.community_id,NEW.post_id,NEW.audio_revision::TEXT,NEW.lyrics_revision::TEXT,
   NEW.qualification_policy_revision,NEW.preview_terms_hash,NEW.disclosure_version,'true'::JSONB) THEN
  RAISE EXCEPTION 'actual immutable Account session source mismatch' USING ERRCODE='GP005'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER account_reward_source_exact_parent AFTER INSERT ON account_owner_reward_sources
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_account_reward_source_parent_private_v1();

CREATE FUNCTION retain_account_owner_reward_source_private_v1() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 RAISE EXCEPTION 'original Account reward source is retained' USING ERRCODE='GP005';
END $$;
CREATE TRIGGER account_owner_reward_source_immutable BEFORE UPDATE OR DELETE ON account_owner_reward_sources
 FOR EACH ROW EXECUTE FUNCTION retain_account_owner_reward_source_private_v1();
CREATE TRIGGER account_owner_reward_source_retained BEFORE TRUNCATE ON account_owner_reward_sources
 FOR EACH STATEMENT EXECUTE FUNCTION retain_account_owner_reward_source_private_v1();

CREATE FUNCTION retain_account_owner_reward_operation_private_v1() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 IF TG_OP IN('DELETE','TRUNCATE') THEN RAISE EXCEPTION 'original Account operation is retained' USING ERRCODE='GP005'; END IF;
 IF (to_jsonb(NEW)-ARRAY['state','completion_snapshot','completed_at']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['state','completion_snapshot','completed_at'])
  OR OLD.state<>'captured' OR NEW.state<>'completed' OR NEW.completed_at<OLD.created_at THEN
  RAISE EXCEPTION 'original Account operation source/outcome is immutable' USING ERRCODE='GP005'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER account_owner_reward_operation_immutable BEFORE UPDATE OR DELETE ON account_owner_reward_operations
 FOR EACH ROW EXECUTE FUNCTION retain_account_owner_reward_operation_private_v1();
CREATE TRIGGER account_owner_reward_operation_retained BEFORE TRUNCATE ON account_owner_reward_operations
 FOR EACH STATEMENT EXECUTE FUNCTION retain_account_owner_reward_operation_private_v1();

-- Transaction1 is independently ACKNOWLEDGED before any owning grade/attempt/
-- qualification/share transaction. Caller passes real server producer payload.
-- Missing source means this existing session is retained ordinary2, never quoted.
CREATE FUNCTION prepare_account_owner_reward_action_v1(p_account TEXT,p_community TEXT,p_family TEXT,p_session TEXT,
 p_producer TEXT,p_payload JSONB,p_new_main TEXT,p_new_admission TEXT,p_new_fence TEXT,p_new_salt BYTEA,p_new_margin INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source account_owner_reward_sources%ROWTYPE; prior account_owner_reward_operations%ROWTYPE;
 hold owner_participation_admission_operations%ROWTYPE; sess JSONB; action_kind TEXT; action_key TEXT; action_hash TEXT;
 qid TEXT; command study_spoken_answer_commands%ROWTYPE; cap learner_audio_account_producer_captures%ROWTYPE;
 drawing megapot_pool_drawings%ROWTYPE; observation megapot_drawing_observations%ROWTYPE; no_admission JSONB;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 SELECT * INTO source FROM account_owner_reward_sources WHERE session_kind=p_family AND session_id=p_session AND account_id=p_account AND community_id=p_community;
 IF NOT FOUND THEN RETURN NULL; END IF;
 PERFORM lock_owner_participation_group_private_v1(source.source_owner_id);
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_payload IS NULL OR jsonb_typeof(p_payload)<>'object' OR octet_length(p_payload::TEXT)>1048576
  OR p_payload->>'qualificationId' IS NULL THEN RAISE EXCEPTION 'actual original Account producer payload required' USING ERRCODE='GP006'; END IF;
 sess:=read_account_reward_session_private_v1(p_family,p_session);
 IF sess->>'account_id' IS DISTINCT FROM p_account OR sess->>'community_id' IS DISTINCT FROM p_community THEN
  RAISE EXCEPTION 'actual original Account session required' USING ERRCODE='GP005'; END IF;
 IF p_producer IN('legacy_choice','v2_choice') THEN
  IF(p_producer='legacy_choice' AND p_family<>'study_legacy') OR(p_producer='v2_choice' AND p_family<>'study_v2')
   OR ROW(p_payload->>'accountId',p_payload->>'communityId',p_payload->>'sessionId') IS DISTINCT FROM ROW(p_account,p_community,p_session)
   OR p_payload->>'sessionItemId' IS NULL OR p_payload->>'attemptNumber' IS NULL OR p_payload->>'attemptNumber' !~ '^[1-3]$'
   OR p_payload->'answer' IS NULL OR p_payload->>'idempotencyKey' IS NULL OR p_payload->>'requestHash' IS NULL OR p_payload->>'requestHash' !~ '^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'actual original Study choice tuple required' USING ERRCODE='GP005'; END IF;
  IF p_family='study_legacy' THEN
   PERFORM 1 FROM study_sessions WHERE session_id=p_session AND account_id=p_account FOR NO KEY UPDATE;
   IF NOT EXISTS(SELECT 1 FROM study_session_items WHERE session_id=p_session AND session_item_id=p_payload->>'sessionItemId') THEN
    RAISE EXCEPTION 'actual original legacy item required' USING ERRCODE='GP005'; END IF;
  ELSE
   PERFORM 1 FROM study_sessions_v2 WHERE session_id=p_session AND account_id=p_account FOR NO KEY UPDATE;
   IF NOT EXISTS(SELECT 1 FROM study_session_items_v2 WHERE session_id=p_session AND session_item_id=p_payload->>'sessionItemId' AND account_id=p_account
    AND item_snapshot->>'exercise_type'='translation_choice') THEN RAISE EXCEPTION 'actual original choice item required' USING ERRCODE='GP005'; END IF;
  END IF;
  action_kind:='study_answer';action_key:=p_payload->>'idempotencyKey';action_hash:=p_payload->>'requestHash';
 ELSIF p_producer='v2_spoken' THEN
  IF p_family<>'study_v2' THEN RAISE EXCEPTION 'actual original spoken family required' USING ERRCODE='GP005'; END IF;
  PERFORM lock_original_account_audio_source_private_v1(p_account);
  PERFORM 1 FROM study_sessions_v2 WHERE session_id=p_session AND account_id=p_account FOR NO KEY UPDATE;
  SELECT * INTO STRICT cap FROM learner_audio_account_producer_captures WHERE upload_attempt_id=p_payload->'capture'->>'uploadAttemptId'
   AND account_id=p_account AND owner_id=source.source_owner_id AND source_kind='study' AND session_id=p_session;
  SELECT * INTO STRICT command FROM study_spoken_answer_commands WHERE command_id=cap.command_ref;
  IF ROW(cap.command_ref,cap.session_item_id,cap.attempt_ref,cap.artifact_id,cap.request_hash,cap.content_digest,cap.content_type,cap.byte_size,cap.duration_ms)
   IS DISTINCT FROM ROW(p_payload->>'commandId',p_payload->>'sessionItemId',p_payload->>'attemptId',p_payload->>'artifactId',p_payload->>'requestHash',
    p_payload->>'audioDigest',p_payload->>'audioContentType',(p_payload->>'audioByteSize')::BIGINT,(p_payload->>'audioDurationMs')::INTEGER)
   OR NOT EXISTS(SELECT 1 FROM learner_audio_account_spoken_checkpoints WHERE upload_attempt_id=cap.upload_attempt_id AND owner_id=cap.owner_id) THEN
   RAISE EXCEPTION 'actual accepted provider checkpoint required' USING ERRCODE='GP005'; END IF;
  PERFORM require_account_spoken_success_private_v1(cap.upload_attempt_id,p_payload-ARRAY['archive','capture']);
  action_kind:='study_answer';action_key:=cap.idempotency_key;action_hash:=cap.request_hash;
 ELSIF p_producer='karaoke' THEN
  IF p_family<>'karaoke' OR ROW(p_payload->'authority'->>'accountId',p_payload->'authority'->>'communityId',p_payload->'authority'->>'sessionId',p_payload->'authority'->>'attemptId',p_payload->'authority'->>'personaId',p_payload->'authority'->>'postId')
   IS DISTINCT FROM ROW(p_account,p_community,p_session,sess->>'attempt_id',source.persona_id,source.post_id)
   OR p_payload->'summary' IS NULL OR p_payload->'transportFacts' IS NULL OR p_payload->>'completedAt' IS NULL THEN
   RAISE EXCEPTION 'actual original scored Karaoke payload required' USING ERRCODE='GP005'; END IF;
  PERFORM lock_original_account_audio_source_private_v1(p_account);
  PERFORM 1 FROM karaoke_sessions WHERE session_id=p_session AND account_id=p_account FOR NO KEY UPDATE;
  action_kind:='karaoke_finalize';action_key:='karaoke-finalize:'||(sess->>'attempt_id');
  -- Qualification ID is a server locator; preserve the first captured value.
  -- The actual durable DO completion/scoring/transport facts stay hash-bound.
  action_hash:=encode(sha256(convert_to((p_payload-'qualificationId')::TEXT,'UTF8')),'hex');
 ELSE RAISE EXCEPTION 'closed original Account producer required' USING ERRCODE='GP006'; END IF;
 -- Read existing capture before any fresh config/clock/salt or access check.
 SELECT * INTO prior FROM account_owner_reward_operations WHERE source_owner_id=source.source_owner_id AND session_kind=p_family AND session_id=p_session
  AND operation_kind=action_kind AND idempotency_key=action_key;
 IF FOUND THEN
  IF prior.request_hash IS DISTINCT FROM action_hash OR prior.producer_kind IS DISTINCT FROM p_producer THEN
   RAISE EXCEPTION 'original Account action key changed' USING ERRCODE='GP005'; END IF;
  RETURN account_owner_reward_operation_receipt_private_v1(prior.operation_id);
 END IF;
 IF p_producer IN('legacy_choice','v2_choice') AND(NOT active_activity_persona(p_account,source.persona_id,p_community)
  OR NOT can_account_access_activity_song(p_account,p_community,source.post_id)) THEN RAISE EXCEPTION 'new ordinary choice authority unavailable' USING ERRCODE='GP002'; END IF;
 IF p_new_main IS NULL AND p_new_admission IS NULL AND p_new_fence IS NULL AND p_new_salt IS NULL AND p_new_margin IS NULL THEN
  RAISE EXCEPTION 'new acknowledged Account capture required' USING ERRCODE='GP007'; END IF;
 IF p_new_main IS NULL OR char_length(p_new_main) NOT BETWEEN 1 AND 128 OR p_new_admission IS NULL OR octet_length(p_new_admission) NOT BETWEEN 1 AND 110
  OR p_new_fence IS NULL OR p_new_fence !~ '^[0-9a-f]{64}$' OR p_new_salt IS NULL OR octet_length(p_new_salt)<>32
  THEN RAISE EXCEPTION 'explicit new Account hold capture required' USING ERRCODE='GP006'; END IF;
 qid:=p_payload->>'qualificationId';
 -- All group/audio/session/source checks above precede this original draw.
 SELECT * INTO STRICT drawing FROM megapot_pool_drawings WHERE pool_leg_id=source.original_terms->>'pool_leg_id'
  AND drawing_id=(source.original_terms->>'original_drawing_id')::NUMERIC FOR UPDATE;
 SELECT * INTO STRICT observation FROM megapot_drawing_observations WHERE observation_id=drawing.observation_id;
 IF drawing.beneficiary_version<>3 OR drawing.entry_cutoff_at IS DISTINCT FROM(source.original_terms->>'entry_cutoff_at')::TIMESTAMPTZ THEN
  RAISE EXCEPTION 'original Account drawing identity changed' USING ERRCODE='GP005'; END IF;
 IF drawing.status<>'entry_open' OR clock_timestamp()>=drawing.entry_cutoff_at OR clock_timestamp()>=source.purchase_safety_deadline_at THEN
  no_admission:=jsonb_build_object('state','entry_closed'); END IF;
 INSERT INTO account_owner_reward_operations(operation_id,source_owner_id,session_kind,session_id,operation_kind,idempotency_key,request_hash,
  qualification_id,producer_kind,captured_payload,original_admission_result)
 VALUES(p_new_main,source.source_owner_id,p_family,p_session,action_kind,action_key,action_hash,qid,p_producer,p_payload,no_admission);
 IF no_admission IS NULL THEN
  INSERT INTO owner_participation_admission_operations(admission_id,source_owner_id,source_owner_kind,source_session_kind,guest_main_operation_id,guest_study_session_id,account_main_operation_id,
   main_operation_id,operation_kind,idempotency_key,request_hash,session_id,qualification_id,pool_leg_id,drawing_id,terms_hash,policy_hash,qualification_policy_revision,
   entry_cutoff_at,purchase_safety_deadline_at,original_attempt_fence,current_attempt_fence,leaf_salt,state)
  VALUES(p_new_admission,source.source_owner_id,'account',p_family,NULL,NULL,p_new_main,p_new_main,action_kind,action_key,action_hash,p_session,qid,
   drawing.pool_leg_id,drawing.drawing_id,source.original_terms->>'terms_hash',source.original_terms->>'policy_hash',source.qualification_policy_revision,
   drawing.entry_cutoff_at,source.purchase_safety_deadline_at,p_new_fence,p_new_fence,p_new_salt,'pending');
  INSERT INTO owner_participation_admission_attempts(admission_id,attempt_number,attempt_fence,state) VALUES(p_new_admission,1,p_new_fence,'pending');
 END IF;
 RETURN account_owner_reward_operation_receipt_private_v1(p_new_main);
END $$;

-- Source: owner-account-reward-producer-proposal-0cc7ef57/account-attempt-protocol.sql
-- Shared helpers are PRIVATE and are installed once in Root's complete packet.
-- Their caller already owns the complete source/session/original drawing locks.
CREATE FUNCTION mark_original_owner_admission_attempt_started_v1(p_id TEXT,p_expected_fence TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE hold owner_participation_admission_operations%ROWTYPE; attempt owner_participation_admission_attempts%ROWTYPE;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT hold FROM owner_participation_admission_operations WHERE admission_id=p_id FOR UPDATE;
 SELECT * INTO STRICT attempt FROM owner_participation_admission_attempts
  WHERE admission_id=p_id AND attempt_number=hold.current_attempt_number AND attempt_fence=hold.current_attempt_fence FOR UPDATE;
 IF p_expected_fence IS NULL OR hold.state<>'pending' OR hold.current_attempt_fence IS DISTINCT FROM p_expected_fence
  OR attempt.state<>'pending' OR attempt.started_at IS NOT NULL THEN
  RAISE EXCEPTION 'new acknowledged original attempt marker required' USING ERRCODE='GP005'; END IF;
 UPDATE owner_participation_admission_attempts SET started_at=clock_timestamp()
  WHERE admission_id=p_id AND attempt_fence=p_expected_fence AND state='pending' AND started_at IS NULL;
END $$;

CREATE FUNCTION require_original_owner_admission_attempt_started_v1(p_id TEXT,p_expected_fence TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE hold owner_participation_admission_operations%ROWTYPE; attempt owner_participation_admission_attempts%ROWTYPE; marker_xmin TEXT;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT hold FROM owner_participation_admission_operations WHERE admission_id=p_id;
 SELECT * INTO STRICT attempt FROM owner_participation_admission_attempts a
  WHERE a.admission_id=p_id AND a.attempt_number=hold.current_attempt_number AND a.attempt_fence=hold.current_attempt_fence;
 SELECT a.xmin::TEXT INTO STRICT marker_xmin FROM owner_participation_admission_attempts a
  WHERE a.admission_id=p_id AND a.attempt_number=hold.current_attempt_number AND a.attempt_fence=hold.current_attempt_fence;
 IF p_expected_fence IS NULL OR hold.state<>'pending' OR hold.current_attempt_fence IS DISTINCT FROM p_expected_fence
  OR attempt.state<>'pending' OR attempt.started_at IS NULL
  OR marker_xmin=(pg_current_xact_id()::TEXT::NUMERIC % 4294967296)::TEXT THEN
  RAISE EXCEPTION 'original owning attempt needs an independently committed marker and exact token' USING ERRCODE='GP005'; END IF;
END $$;

-- This is a separate bounded ACKed transaction before the existing owning
-- producer. A pending marker is never re-used. Complete source/session/draw
-- serialization first proves the prior owning transaction has ended; committed
-- completion returns its original receipt, otherwise the old attempt is fenced.
CREATE FUNCTION start_account_owner_reward_attempt_v1(p_main TEXT,p_account TEXT,p_community TEXT,
 p_family TEXT,p_session TEXT,p_producer TEXT,p_key TEXT,p_hash TEXT,p_expected_fence TEXT,p_new_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE op account_owner_reward_operations%ROWTYPE; hold owner_participation_admission_operations%ROWTYPE;
 attempt owner_participation_admission_attempts%ROWTYPE; drawing megapot_pool_drawings%ROWTYPE;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT op FROM account_owner_reward_operations WHERE operation_id=p_main AND session_kind=p_family
  AND session_id=p_session AND producer_kind=p_producer AND idempotency_key=p_key AND request_hash=p_hash;
 PERFORM enter_account_owner_reward_action_v1(p_main,p_account,p_community,p_session,p_expected_fence);
 SELECT * INTO hold FROM owner_participation_admission_operations WHERE source_owner_id=op.source_owner_id AND main_operation_id=p_main;
 IF NOT FOUND THEN RETURN account_owner_reward_operation_receipt_private_v1(p_main); END IF;
 SELECT * INTO STRICT drawing FROM megapot_pool_drawings WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id FOR UPDATE;
 SELECT * INTO STRICT hold FROM owner_participation_admission_operations WHERE admission_id=hold.admission_id FOR UPDATE;
 SELECT * INTO STRICT op FROM account_owner_reward_operations WHERE operation_id=p_main FOR UPDATE;
 IF op.state='completed' THEN RETURN account_owner_reward_operation_receipt_private_v1(p_main); END IF;
 IF hold.state NOT IN('pending','reconciled_no_commit') THEN RAISE EXCEPTION 'captured Account completion is inconsistent' USING ERRCODE='GP003'; END IF;
 SELECT * INTO STRICT attempt FROM owner_participation_admission_attempts
  WHERE admission_id=hold.admission_id AND attempt_fence=hold.current_attempt_fence FOR UPDATE;
 IF hold.state='pending' THEN
  IF p_expected_fence IS DISTINCT FROM hold.current_attempt_fence THEN
   RAISE EXCEPTION 'original attempt token changed' USING ERRCODE='GP005'; END IF;
  IF attempt.started_at IS NULL THEN
   PERFORM mark_original_owner_admission_attempt_started_v1(hold.admission_id,hold.current_attempt_fence);
   RETURN account_owner_reward_operation_receipt_private_v1(p_main);
  END IF;
  IF EXISTS(SELECT 1 FROM activity_qualifications WHERE account_main_operation_id=p_main)
   OR EXISTS(SELECT 1 FROM megapot_owner_shares WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id
    AND owner_id=hold.source_owner_id AND qualification_id=hold.qualification_id)
   OR(p_family='study_legacy' AND EXISTS(SELECT 1 FROM study_session_answers WHERE session_id=p_session AND idempotency_key=p_key))
   OR(p_family='study_v2' AND EXISTS(SELECT 1 FROM study_attempts_v2 WHERE session_item_id=op.captured_payload->>'sessionItemId' AND idempotency_key=p_key))
   OR(p_family='karaoke' AND EXISTS(SELECT 1 FROM karaoke_attempts WHERE session_id=p_session AND attempt_id=op.captured_payload->'authority'->>'attemptId')) THEN
   RAISE EXCEPTION 'actual owning grade/qualification/outcome atomicity differs' USING ERRCODE='GP003'; END IF;
  UPDATE owner_participation_admission_operations SET state='reconciled_no_commit',
   result_snapshot=jsonb_build_object('state',CASE WHEN clock_timestamp()>=hold.entry_cutoff_at OR clock_timestamp()>=hold.purchase_safety_deadline_at THEN 'entry_closed' ELSE 'unavailable' END),
   resolved_at=clock_timestamp() WHERE admission_id=hold.admission_id AND state='pending';
  UPDATE owner_participation_admission_attempts SET state='authoritative_no_commit',resolved_at=clock_timestamp()
   WHERE admission_id=hold.admission_id AND attempt_fence=hold.current_attempt_fence AND state='pending';
 END IF;
 -- Same original terms/draw/q/salt; a fresh marker+fence is committed before T2.
 IF drawing.beneficiary_version=3 AND drawing.status='entry_open' AND clock_timestamp()<hold.entry_cutoff_at
  AND clock_timestamp()<hold.purchase_safety_deadline_at THEN
  IF p_new_fence IS NULL OR p_new_fence !~ '^[0-9a-f]{64}$' OR p_new_fence=hold.current_attempt_fence THEN
   RAISE EXCEPTION 'fresh same-original attempt fence required' USING ERRCODE='GP005'; END IF;
  INSERT INTO owner_participation_admission_attempts(admission_id,attempt_number,attempt_fence,state)
   VALUES(hold.admission_id,hold.current_attempt_number+1,p_new_fence,'pending');
  UPDATE owner_participation_admission_operations SET state='pending',current_attempt_number=hold.current_attempt_number+1,
   current_attempt_fence=p_new_fence,result_snapshot=NULL,resolved_at=NULL WHERE admission_id=hold.admission_id AND state='reconciled_no_commit';
  PERFORM mark_original_owner_admission_attempt_started_v1(hold.admission_id,p_new_fence);
 END IF;
 RETURN account_owner_reward_operation_receipt_private_v1(p_main);
END $$;

-- Source: owner-account-reward-producer-proposal-0cc7ef57/account-owning-finalization.sql
ALTER TABLE activity_qualifications ADD COLUMN account_main_operation_id TEXT;
ALTER TABLE activity_qualifications ADD CONSTRAINT qualified_account_main_owner_fk
 FOREIGN KEY(account_main_operation_id,participation_owner_id) REFERENCES account_owner_reward_operations(operation_id,source_owner_id);
ALTER TABLE activity_qualifications ADD CONSTRAINT qualified_account_main_closed
 CHECK((account_main_operation_id IS NULL OR(participation_owner_kind='account' AND account_id IS NOT NULL AND persona_id IS NOT NULL AND guest_main_operation_id IS NULL)) IS TRUE);
CREATE UNIQUE INDEX qualified_account_one_main ON activity_qualifications(account_main_operation_id) WHERE account_main_operation_id IS NOT NULL;
CREATE FUNCTION bind_account_owner_qualification_private_v1() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE op account_owner_reward_operations%ROWTYPE; source account_owner_reward_sources%ROWTYPE;
BEGIN
 SELECT * INTO op FROM account_owner_reward_operations WHERE qualification_id=NEW.qualification_id;
 IF NOT FOUND THEN
  IF NEW.account_main_operation_id IS NOT NULL OR EXISTS(SELECT 1 FROM account_owner_reward_sources src
    WHERE src.account_id=NEW.account_id AND src.community_id=NEW.community_id
     AND((src.session_kind='karaoke' AND src.session_id=NEW.karaoke_session_id)
      OR(src.session_kind IN('study_legacy','study_v2') AND src.session_id=NEW.study_session_id))) THEN
   RAISE EXCEPTION 'captured Account action missing' USING ERRCODE='GP005'; END IF;
  RETURN NEW;
 END IF;
 SELECT * INTO STRICT source FROM account_owner_reward_sources WHERE source_owner_id=op.source_owner_id AND session_kind=op.session_kind AND session_id=op.session_id;
 IF NEW.account_id IS DISTINCT FROM source.account_id OR NEW.persona_id IS DISTINCT FROM source.persona_id
  OR NEW.community_id IS DISTINCT FROM source.community_id OR NEW.post_id IS DISTINCT FROM source.post_id
  OR NEW.audio_revision IS DISTINCT FROM source.audio_revision OR NEW.qualification_policy_version_id IS DISTINCT FROM source.qualification_policy_revision
  OR NEW.guest_main_operation_id IS NOT NULL OR op.state<>'captured'
  OR(NEW.account_main_operation_id IS NOT NULL AND NEW.account_main_operation_id<>op.operation_id)
  OR(op.session_kind='karaoke' AND(NEW.activity_key<>'karaoke' OR NEW.karaoke_session_id IS DISTINCT FROM op.session_id))
  OR(op.session_kind<>'karaoke' AND(NEW.activity_key<>'study' OR NEW.study_session_id IS DISTINCT FROM op.session_id)) THEN
  RAISE EXCEPTION 'actual captured Account qualification changed' USING ERRCODE='GP005'; END IF;
 NEW.account_main_operation_id:=op.operation_id;NEW.participation_owner_id:=op.source_owner_id;NEW.participation_owner_kind:='account';
 RETURN NEW;
END $$;
CREATE TRIGGER activity_005_captured_account_source BEFORE INSERT ON activity_qualifications
 FOR EACH ROW EXECUTE FUNCTION bind_account_owner_qualification_private_v1();

CREATE FUNCTION read_qualified_owner_account_facts_private_v1(p_source TEXT,p_family TEXT,p_session TEXT,p_main TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE op account_owner_reward_operations%ROWTYPE; source account_owner_reward_sources%ROWTYPE; q activity_qualifications%ROWTYPE; sess JSONB;
BEGIN
 SELECT * INTO STRICT op FROM account_owner_reward_operations WHERE operation_id=p_main AND source_owner_id=p_source AND session_kind=p_family AND session_id=p_session;
 SELECT * INTO STRICT source FROM account_owner_reward_sources WHERE source_owner_id=p_source AND session_kind=p_family AND session_id=p_session;
 sess:=read_account_reward_session_private_v1(p_family,p_session);
 SELECT * INTO q FROM activity_qualifications WHERE account_main_operation_id=op.operation_id AND participation_owner_id=p_source AND participation_owner_kind='account';
 IF NOT FOUND THEN RETURN jsonb_build_object('state',CASE WHEN sess->>'status'='completed' THEN 'ineligible' ELSE 'not_yet_qualified' END); END IF;
 IF q.qualification_id IS DISTINCT FROM op.qualification_id OR q.account_id IS DISTINCT FROM source.account_id OR q.persona_id IS DISTINCT FROM source.persona_id
  OR q.community_id IS DISTINCT FROM source.community_id OR q.post_id IS DISTINCT FROM source.post_id OR q.audio_revision IS DISTINCT FROM source.audio_revision
  OR q.qualification_policy_version_id IS DISTINCT FROM source.qualification_policy_revision
  OR(p_family='karaoke' AND(q.activity_key<>'karaoke' OR q.karaoke_session_id IS DISTINCT FROM p_session))
  OR(p_family<>'karaoke' AND(q.activity_key<>'study' OR q.study_session_id IS DISTINCT FROM p_session)) THEN
  RAISE EXCEPTION 'actual captured Account qualification source missing' USING ERRCODE='GP005'; END IF;
 -- Native0082 guard already derived this q from actual immutable attempts and
 -- terminal original session in this same owning transaction; no caller score.
 RETURN jsonb_build_object('state','qualified','sourceOwnerId',p_source,'mainOperationId',p_main,'operationKind',op.operation_kind,
  'idempotencyKey',op.idempotency_key,'requestHash',op.request_hash,'activityKind',q.activity_key,
  'communityId',q.community_id,'postId',q.post_id,'audioRevision',q.audio_revision,'policyRevision',q.qualification_policy_version_id,
  'scoreBps',q.score_bps,'qualifiedAt',q.qualified_at,'streakDay',q.streak_day,'evidence',q.evidence_summary,
  'terms',source.original_terms,'purchaseSafetyDeadlineAt',source.purchase_safety_deadline_at);
END $$;

-- ENTRY call is before every old selected producer's account/media/session lock.
CREATE FUNCTION enter_account_owner_reward_action_v1(p_main TEXT,p_account TEXT,p_community TEXT,p_session TEXT,p_expected_fence TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE op account_owner_reward_operations%ROWTYPE; source account_owner_reward_sources%ROWTYPE;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT op FROM account_owner_reward_operations WHERE operation_id=p_main AND session_id=p_session;
 SELECT * INTO STRICT source FROM account_owner_reward_sources WHERE source_owner_id=op.source_owner_id AND session_kind=op.session_kind AND session_id=p_session;
 IF source.account_id IS DISTINCT FROM p_account OR source.community_id IS DISTINCT FROM p_community THEN
  RAISE EXCEPTION 'actual original Account owning source required' USING ERRCODE='GP005'; END IF;
 PERFORM lock_account_reward_finalization_v1(p_account,p_community,p_session,op.session_kind);
 -- Preserve native262 account media/advisory-before-session order. The full
 -- common owner group is already locked; these are reentrant source locks.
 IF op.producer_kind IN('v2_spoken','karaoke') THEN PERFORM lock_original_account_audio_source_private_v1(p_account); END IF;
 IF op.session_kind='study_legacy' THEN PERFORM 1 FROM study_sessions WHERE session_id=p_session AND account_id=p_account FOR UPDATE;
 ELSIF op.session_kind='study_v2' THEN PERFORM 1 FROM study_sessions_v2 WHERE session_id=p_session AND account_id=p_account FOR UPDATE;
 ELSE PERFORM 1 FROM karaoke_sessions WHERE session_id=p_session AND account_id=p_account FOR UPDATE;
 END IF;
 PERFORM require_owner_accounting_ready_private_v1();
END $$;

-- Call AFTER actual existing media/admission/session prerequisites, BEFORE any
-- answer/attempt/terminal/qualification writes. This never invents a missing hold.
CREATE FUNCTION lock_account_owner_reward_draw_v1(p_main TEXT,p_expected_fence TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE op account_owner_reward_operations%ROWTYPE; hold owner_participation_admission_operations%ROWTYPE; leg song_reward_offer_legs%ROWTYPE;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT op FROM account_owner_reward_operations WHERE operation_id=p_main;
 PERFORM read_locked_owner_participation_group_private_v1(op.source_owner_id);
 SELECT * INTO hold FROM owner_participation_admission_operations WHERE main_operation_id=p_main AND source_owner_id=op.source_owner_id;
 IF NOT FOUND THEN RETURN; END IF;
 PERFORM 1 FROM megapot_pool_drawings WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id FOR UPDATE;
 SELECT * INTO STRICT leg FROM song_reward_offer_legs WHERE leg_id=hold.pool_leg_id FOR UPDATE;
 IF leg.funding_source='shared_sponsor_budget' THEN
  PERFORM 1 FROM platform_sponsorship_budgets WHERE sponsor_account_id=leg.funder_account_id AND chain_id=leg.chain_id AND token_address=leg.token_address FOR UPDATE;
 END IF;
 PERFORM 1 FROM owner_participation_admission_operations WHERE admission_id=hold.admission_id FOR UPDATE;
 IF hold.state='pending' THEN
  PERFORM require_original_owner_admission_attempt_started_v1(hold.admission_id,p_expected_fence);
 ELSIF p_expected_fence IS NOT NULL THEN RAISE EXCEPTION 'terminal original hold cannot accept a new attempt token' USING ERRCODE='GP005'; END IF;
END $$;

CREATE FUNCTION complete_account_owner_reward_action_v1(p_main TEXT,p_expected_fence TEXT,p_actual_result JSONB)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE op account_owner_reward_operations%ROWTYPE; hold owner_participation_admission_operations%ROWTYPE; result JSONB;
 attempt_row JSONB; actual_session JSONB;
BEGIN
 SELECT * INTO STRICT op FROM account_owner_reward_operations WHERE operation_id=p_main FOR UPDATE;
 IF op.state='completed' THEN RETURN op.completion_snapshot; END IF;
 IF p_actual_result IS NULL OR jsonb_typeof(p_actual_result)<>'object' THEN RAISE EXCEPTION 'actual committed producer result required' USING ERRCODE='GP005'; END IF;
 actual_session:=read_account_reward_session_private_v1(op.session_kind,op.session_id);
 IF op.producer_kind='karaoke' THEN
  SELECT to_jsonb(a) INTO attempt_row FROM karaoke_attempts a WHERE a.session_id=op.session_id AND a.attempt_id=op.captured_payload->'authority'->>'attemptId';
  IF attempt_row IS NULL OR ROW(p_actual_result->>'session_id',p_actual_result->>'attempt_id',p_actual_result->>'completion_reason',p_actual_result->>'final_score',p_actual_result->>'scored_line_count',p_actual_result->>'line_count')
   IS DISTINCT FROM ROW(op.session_id,attempt_row->>'attempt_id',attempt_row->>'completion_reason',attempt_row->>'final_score_bps',attempt_row->>'scored_line_count',attempt_row->>'line_count') THEN
   RAISE EXCEPTION 'actual saved Karaoke completion required' USING ERRCODE='GP005'; END IF;
 ELSE
  IF op.session_kind='study_legacy' THEN
   SELECT to_jsonb(a) INTO attempt_row FROM study_session_answers a WHERE session_id=op.session_id AND session_item_id=op.captured_payload->>'sessionItemId'
    AND attempt_number=(op.captured_payload->>'attemptNumber')::INTEGER AND idempotency_key=op.idempotency_key AND request_hash=op.request_hash;
  ELSE
   SELECT to_jsonb(a) INTO attempt_row FROM study_attempts_v2 a WHERE session_item_id=op.captured_payload->>'sessionItemId'
    AND attempt_number=(op.captured_payload->>'attemptNumber')::INTEGER AND idempotency_key=op.idempotency_key AND request_hash=op.request_hash;
  END IF;
  IF attempt_row IS NULL OR ROW(p_actual_result->>'session_item_id',p_actual_result->>'attempt_number',p_actual_result->>'outcome',p_actual_result->>'first_pass',p_actual_result->'session'->>'session_id',p_actual_result->'session'->>'status')
   IS DISTINCT FROM ROW(attempt_row->>'session_item_id',attempt_row->>'attempt_number',attempt_row->>'outcome',attempt_row->>'first_pass',op.session_id,actual_session->>'status') THEN
   RAISE EXCEPTION 'actual saved original Study completion required' USING ERRCODE='GP005'; END IF;
  IF op.producer_kind='v2_spoken' AND NOT EXISTS(SELECT 1 FROM study_spoken_answer_commands WHERE command_id=op.captured_payload->>'commandId'
   AND state='completed' AND result_snapshot=p_actual_result) THEN RAISE EXCEPTION 'actual saved provider success completion required' USING ERRCODE='GP005'; END IF;
 END IF;
 SELECT * INTO hold FROM owner_participation_admission_operations WHERE main_operation_id=p_main AND source_owner_id=op.source_owner_id;
 IF FOUND THEN
  IF hold.state='pending' THEN
   PERFORM require_original_owner_admission_attempt_started_v1(hold.admission_id,p_expected_fence);
   result:=admit_megapot_owner_participation_v1(hold.admission_id,p_expected_fence);
  ELSE
   IF p_expected_fence IS NOT NULL THEN RAISE EXCEPTION 'terminal original hold token changed' USING ERRCODE='GP005'; END IF;
   result:=hold.result_snapshot;
  END IF;
 ELSE result:=op.original_admission_result;
  IF result IS NULL THEN RAISE EXCEPTION 'acknowledged original Account admission decision required' USING ERRCODE='GP003'; END IF;
 END IF;
 UPDATE account_owner_reward_operations SET state='completed',completion_snapshot=jsonb_build_object('answer',p_actual_result,'participation',result),completed_at=clock_timestamp()
  WHERE operation_id=p_main AND state='captured';
 RETURN jsonb_build_object('answer',p_actual_result,'participation',result);
END $$;

-- Polymorphic dispatcher; source-specific routines never fabricate each other's
-- main operations, sessions, identities, or financial authority.
CREATE FUNCTION admit_megapot_owner_participation_v1(p_id TEXT,p_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE hold owner_participation_admission_operations%ROWTYPE;
BEGIN
 SELECT * INTO STRICT hold FROM owner_participation_admission_operations WHERE admission_id=p_id;
 IF hold.source_owner_kind='guest' THEN RETURN admit_guest_owner_participation_private_v1(p_id,p_fence);
 ELSIF hold.source_owner_kind='account' THEN RETURN admit_account_owner_participation_private_v1(p_id,p_fence);
 ELSE RAISE EXCEPTION 'closed actual admission source required' USING ERRCODE='GP005'; END IF;
END $$;

-- Source: owner-account-reward-producer-proposal-0cc7ef57/admit-account-owning-successor.sql
CREATE FUNCTION admit_account_owner_participation_private_v1(p_id TEXT,p_expected_fence TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE hold owner_participation_admission_operations%ROWTYPE; source_ids TEXT[];
 facts JSONB; terms JSONB; drawing megapot_pool_drawings%ROWTYPE; leg song_reward_offer_legs%ROWTYPE;
 offer song_reward_offers%ROWTYPE; observation megapot_drawing_observations%ROWTYPE;
 policy RECORD; funding platform_sponsorship_budgets%ROWTYPE; now_at TIMESTAMPTZ; result JSONB; eligibility_id TEXT;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT hold FROM owner_participation_admission_operations WHERE admission_id=p_id;
 source_ids:=read_locked_owner_participation_group_private_v1(hold.source_owner_id);
 SELECT * INTO STRICT drawing FROM megapot_pool_drawings WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id FOR UPDATE;
 SELECT * INTO STRICT leg FROM song_reward_offer_legs WHERE leg_id=hold.pool_leg_id FOR UPDATE;
 -- Journal/qualification/evidence locks are AFTER source/session/drawing/funding.
 SELECT * INTO STRICT hold FROM owner_participation_admission_operations WHERE admission_id=p_id FOR UPDATE;
 IF hold.current_attempt_fence IS DISTINCT FROM p_expected_fence THEN RAISE EXCEPTION 'original admission attempt changed' USING ERRCODE='GP005'; END IF;
 IF hold.state<>'pending' THEN RETURN hold.result_snapshot; END IF;
 IF hold.source_owner_kind IS DISTINCT FROM 'account' THEN RAISE EXCEPTION 'actual Account journal required' USING ERRCODE='GP005'; END IF;
 PERFORM require_original_owner_admission_attempt_started_v1(p_id,p_expected_fence);
 facts:=read_qualified_owner_account_facts_private_v1(hold.source_owner_id,hold.source_session_kind,hold.session_id,hold.main_operation_id);
 IF facts->>'state' IN('not_yet_qualified','ineligible') THEN
  result:=jsonb_build_object('state',facts->>'state');
  UPDATE owner_participation_admission_operations SET state='not_admitted',result_snapshot=result,resolved_at=clock_timestamp() WHERE admission_id=p_id AND state='pending';
  UPDATE owner_participation_admission_attempts SET state='not_admitted',resolved_at=clock_timestamp() WHERE admission_id=p_id AND attempt_fence=p_expected_fence AND state='pending';
  RETURN result;
 END IF;
 IF NOT EXISTS(SELECT 1 FROM activity_qualifications q WHERE q.qualification_id=hold.qualification_id
  AND q.participation_owner_id=hold.source_owner_id AND q.participation_owner_kind='account'
  AND q.account_main_operation_id=hold.main_operation_id
  AND((hold.source_session_kind='karaoke' AND q.karaoke_session_id=hold.session_id AND q.activity_key='karaoke')
   OR(hold.source_session_kind IN('study_legacy','study_v2') AND q.study_session_id=hold.session_id AND q.activity_key='study'))) THEN
  RAISE EXCEPTION 'owning immutable qualification missing' USING ERRCODE='GP003'; END IF;
 terms:=facts->'terms';
 SELECT * INTO STRICT offer FROM song_reward_offers WHERE offer_id=leg.offer_id;
 SELECT obs.* INTO observation FROM megapot_drawing_observations obs
 JOIN megapot_deployment_attestations att ON att.attestation_id=obs.attestation_id AND att.status='active'
 WHERE obs.attestation_id=leg.attestation_id AND obs.drawing_id=drawing.drawing_id
 ORDER BY obs.block_number DESC,obs.observation_id COLLATE "C" LIMIT 1;
 IF leg.funding_source='shared_sponsor_budget' THEN
  SELECT * INTO funding FROM platform_sponsorship_budgets WHERE sponsor_account_id=leg.funder_account_id AND chain_id=leg.chain_id AND token_address=leg.token_address FOR UPDATE;
 END IF;
 SELECT policy_hash,policy_version_id INTO policy FROM policy_versions WHERE community_id=offer.community_id
  AND policy_version_id=offer.reward_policy_version_id AND policy_purpose='reward' AND uniqueness_authority_id=offer.offer_id;
 -- Validate all source terms/server-frozen policy and funding. No client flag,
 -- fabricated account, persona or new drawing selection supplies this authority.
 IF drawing.status<>'entry_open' OR clock_timestamp()>=drawing.entry_cutoff_at OR clock_timestamp()>=hold.purchase_safety_deadline_at THEN result:=jsonb_build_object('state','entry_closed');
 ELSIF facts->>'state' IS DISTINCT FROM 'qualified' OR drawing.beneficiary_version<>3 OR offer.status<>'active' OR leg.status<>'active' OR leg.kind<>'megapot_pool'
  OR terms->>'offer_id' IS DISTINCT FROM offer.offer_id OR terms->>'pool_leg_id' IS DISTINCT FROM leg.leg_id
  OR terms->>'original_drawing_id' IS DISTINCT FROM drawing.drawing_id::TEXT
  OR terms->>'policy_hash' IS DISTINCT FROM regexp_replace(policy.policy_hash,'^0x','')
  OR terms->>'terms_hash' IS DISTINCT FROM regexp_replace(leg.leg_terms_hash,'^0x','')
  OR terms->>'entry_cutoff_at' IS NULL OR (terms->>'entry_cutoff_at')::TIMESTAMPTZ IS DISTINCT FROM drawing.entry_cutoff_at
  OR facts->>'communityId' IS DISTINCT FROM offer.community_id OR facts->>'postId' IS DISTINCT FROM offer.post_id
  OR (facts->>'audioRevision')::BIGINT IS DISTINCT FROM offer.audio_revision
  OR NOT reward_leg_accepts_qualification(leg.leg_id,facts->>'activityKind',facts->>'policyRevision') OR NOT (facts->>'activityKind')=ANY(leg.eligible_activities)
  OR (facts->>'scoreBps')::INTEGER<leg.min_score_bps
  OR (facts->>'qualifiedAt')::TIMESTAMPTZ<offer.starts_at OR (facts->>'qualifiedAt')::TIMESTAMPTZ>=offer.ends_at
  OR (facts->>'qualifiedAt')::TIMESTAMPTZ<leg.participation_starts_at OR drawing.drawing_id<leg.participation_starts_drawing_id
  OR observation.observation_id IS NULL OR policy.policy_version_id IS NULL
  OR observation.attestation_id IS DISTINCT FROM leg.attestation_id
  OR observation.drawing_id IS DISTINCT FROM drawing.drawing_id OR observation.drawing_locked IS DISTINCT FROM FALSE
  OR observation.drawing_time-make_interval(secs=>leg.entry_cutoff_seconds) IS DISTINCT FROM drawing.entry_cutoff_at
  OR observation.ticket_price_atomic>drawing.ticket_price_ceiling_atomic
  OR observation.drawing_time<=clock_timestamp()
  OR observation.expires_at<=clock_timestamp() THEN result:=jsonb_build_object('state','unavailable');
 ELSIF leg.funding_source='leg_budget' AND leg.funded_atomic-leg.reserved_atomic-leg.spent_atomic<observation.ticket_price_atomic THEN result:=jsonb_build_object('state','unavailable');
 ELSIF leg.funding_source='shared_sponsor_budget' AND (funding.sponsor_account_id IS NULL OR funding.funded_atomic+funding.winnings_credited_atomic-funding.reserved_atomic-funding.spent_atomic-funding.withdrawn_atomic<observation.ticket_price_atomic) THEN result:=jsonb_build_object('state','unavailable');
 ELSIF EXISTS(SELECT 1 FROM megapot_owner_shares WHERE pool_leg_id=leg.leg_id AND drawing_id=drawing.drawing_id AND owner_id=ANY(source_ids))
  OR EXISTS(SELECT 1 FROM megapot_pool_shares s JOIN participation_owners o ON o.kind='account' AND o.account_id=s.account_id WHERE s.pool_leg_id=leg.leg_id AND s.drawing_id=drawing.drawing_id AND o.owner_id=ANY(source_ids))
 THEN result:=jsonb_build_object('state','already_participating');
 ELSE
  -- Exact AFTER-lock clock, immediately before guarded INSERT, is the
  -- conditional-on-eventual-COMMIT linearization point. Never use prepared time.
  now_at:=clock_timestamp();
  IF now_at>=drawing.entry_cutoff_at OR now_at>=hold.purchase_safety_deadline_at OR (facts->>'qualifiedAt')::TIMESTAMPTZ>=drawing.entry_cutoff_at THEN result:=jsonb_build_object('state','entry_closed');
  ELSE
   BEGIN
   eligibility_id:='owner_eligibility_'||hold.admission_id;
   INSERT INTO participation_eligibility_decisions(eligibility_id,owner_id,qualification_id,pool_leg_id,drawing_id,policy_version,policy_hash,evidence_reference,disclosure_reference,outcome,decided_at)
   VALUES(eligibility_id,hold.source_owner_id,hold.qualification_id,leg.leg_id,drawing.drawing_id,policy.policy_version_id,policy.policy_hash,hold.main_operation_id,terms->>'disclosure_version','eligible',now_at);
   -- SQLSTATEOA001 is PRIVATE subtransaction control ONLY. It is emitted
   -- solely for authoritative zero-row guarded INSERT, never guessed from
   -- an unknown/native error, and is never sent/mapped as a new wire reason.
   WITH sampled AS MATERIALIZED(SELECT clock_timestamp() AS admitted)
   INSERT INTO megapot_owner_shares(pool_leg_id,drawing_id,owner_id,qualification_id,eligibility_id,admitted_at,leaf_salt)
   SELECT leg.leg_id,drawing.drawing_id,hold.source_owner_id,hold.qualification_id,eligibility_id,sampled.admitted,hold.leaf_salt
   FROM sampled WHERE sampled.admitted<drawing.entry_cutoff_at AND sampled.admitted<hold.purchase_safety_deadline_at RETURNING admitted_at INTO now_at;
   IF NOT FOUND THEN RAISE EXCEPTION 'guarded admission window closed' USING ERRCODE='OA001'; END IF;
   result:=jsonb_build_object('state','admitted','share_id',hold.admission_id,'original_drawing_id',drawing.drawing_id::TEXT,'pool_leg_id',leg.leg_id);
   EXCEPTION WHEN SQLSTATE 'OA001' THEN
    -- Roll back ONLY uncommitted eligibility/share statements. The same owning
    -- grade and immutable qualification remain in this transaction and commit.
    result:=jsonb_build_object('state','entry_closed');
   END;
  END IF;
 END IF;
 UPDATE owner_participation_admission_operations SET state=CASE WHEN result->>'state'='admitted' THEN 'admitted' ELSE 'not_admitted' END,
  result_snapshot=result,resolved_at=clock_timestamp() WHERE admission_id=p_id AND state='pending';
 UPDATE owner_participation_admission_attempts SET state=CASE WHEN result->>'state'='admitted' THEN 'admitted' ELSE 'not_admitted' END,resolved_at=clock_timestamp()
  WHERE admission_id=p_id AND attempt_fence=p_expected_fence AND state='pending';
 RETURN result;
END $$;

-- Source: owner-account-reward-producer-proposal-0cc7ef57/account-source-guard-and-readers.sql
-- Existing 118 producers retain their old sessions. NEW selected sources can
-- only write genuine grade/attempt rows through their captured original action.
CREATE FUNCTION guard_selected_account_reward_attempt_private_v1() RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE family TEXT; session_id_value TEXT; op account_owner_reward_operations%ROWTYPE; hold owner_participation_admission_operations%ROWTYPE;
BEGIN
 IF TG_TABLE_NAME='study_session_answers' THEN family:='study_legacy';session_id_value:=NEW.session_id;
 ELSIF TG_TABLE_NAME='study_attempts_v2' THEN
  family:='study_v2';SELECT session_id INTO STRICT session_id_value FROM study_session_items_v2 WHERE session_item_id=NEW.session_item_id;
 ELSIF TG_TABLE_NAME='karaoke_attempts' THEN family:='karaoke';session_id_value:=NEW.session_id;
 ELSE RAISE EXCEPTION 'closed selected Account attempt family required' USING ERRCODE='GP006'; END IF;
 IF NOT EXISTS(SELECT 1 FROM account_owner_reward_sources WHERE session_kind=family AND session_id=session_id_value) THEN RETURN NEW; END IF;
 IF family='karaoke' THEN
  SELECT * INTO STRICT op FROM account_owner_reward_operations WHERE session_kind=family AND session_id=session_id_value
   AND operation_kind='karaoke_finalize' AND captured_payload->'authority'->>'attemptId'=NEW.attempt_id AND state='captured';
 ELSE
  SELECT * INTO STRICT op FROM account_owner_reward_operations WHERE session_kind=family AND session_id=session_id_value
   AND operation_kind='study_answer' AND idempotency_key=NEW.idempotency_key AND request_hash=NEW.request_hash
   AND captured_payload->>'sessionItemId'=NEW.session_item_id AND (captured_payload->>'attemptNumber')::INTEGER=NEW.attempt_number
   AND state='captured';
 END IF;
 SELECT * INTO hold FROM owner_participation_admission_operations WHERE main_operation_id=op.operation_id AND source_owner_id=op.source_owner_id;
 IF FOUND AND hold.state='pending' THEN
  -- This guard confirms native committed-marker provenance. The selected outer
  -- owning draw checks the caller's exact expected token before reaching here.
  PERFORM require_original_owner_admission_attempt_started_v1(hold.admission_id,hold.current_attempt_fence);
 ELSIF NOT FOUND AND op.original_admission_result IS NULL THEN
  RAISE EXCEPTION 'selected original Account admission decision is missing' USING ERRCODE='GP003'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER a00_selected_owner_reward_attempt BEFORE INSERT ON study_session_answers
 FOR EACH ROW EXECUTE FUNCTION guard_selected_account_reward_attempt_private_v1();
CREATE TRIGGER a00_selected_owner_reward_attempt BEFORE INSERT ON study_attempts_v2
 FOR EACH ROW EXECUTE FUNCTION guard_selected_account_reward_attempt_private_v1();
CREATE TRIGGER a00_selected_owner_reward_attempt BEFORE INSERT ON karaoke_attempts
 FOR EACH ROW EXECUTE FUNCTION guard_selected_account_reward_attempt_private_v1();

CREATE FUNCTION read_account_owner_reward_participation_private_v1(p_source TEXT,p_session TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE src account_owner_reward_sources%ROWTYPE; op account_owner_reward_operations%ROWTYPE; hold owner_participation_admission_operations%ROWTYPE; sess JSONB;
BEGIN
 SELECT * INTO STRICT src FROM account_owner_reward_sources WHERE source_owner_id=p_source AND session_kind='study_v2' AND session_id=p_session;
 sess:=read_account_reward_session_private_v1('study_v2',p_session);
 -- An actual committed admission takes priority over any subsequent idempotent
 -- operation/status. It always exposes this immutable original leg and drawing.
 SELECT * INTO hold FROM owner_participation_admission_operations WHERE source_owner_id=p_source AND source_owner_kind='account'
  AND source_session_kind='study_v2' AND session_id=p_session AND state='admitted' ORDER BY created_at,admission_id COLLATE "C" LIMIT 1;
 IF FOUND THEN
  IF hold.pool_leg_id IS DISTINCT FROM src.original_terms->>'pool_leg_id' OR hold.drawing_id::TEXT IS DISTINCT FROM src.original_terms->>'original_drawing_id'
   OR NOT EXISTS(SELECT 1 FROM megapot_owner_shares WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id
    AND owner_id=p_source AND qualification_id=hold.qualification_id AND leaf_salt=hold.leaf_salt) THEN
   RAISE EXCEPTION 'actual original Account admission evidence missing' USING ERRCODE='GP003'; END IF;
  RETURN hold.result_snapshot;
 END IF;
 SELECT * INTO op FROM account_owner_reward_operations WHERE source_owner_id=p_source AND session_kind='study_v2' AND session_id=p_session
  ORDER BY created_at DESC,operation_id COLLATE "C" DESC LIMIT 1;
 IF FOUND THEN
  SELECT * INTO hold FROM owner_participation_admission_operations WHERE main_operation_id=op.operation_id AND source_owner_id=p_source;
  IF FOUND AND hold.state='pending' THEN RETURN jsonb_build_object('state','pending_confirmation','operation',
   jsonb_build_object('operation_kind','study_answer','idempotency_key',op.idempotency_key,'operation_id',op.operation_id)); END IF;
  IF op.state='completed' THEN RETURN op.completion_snapshot->'participation'; END IF;
  IF FOUND AND hold.state='reconciled_no_commit' THEN RETURN hold.result_snapshot; END IF;
  IF op.original_admission_result IS NOT NULL THEN RETURN op.original_admission_result; END IF;
  RAISE EXCEPTION 'original Account outcome is unresolved' USING ERRCODE='GP003';
 END IF;
 IF sess->>'status'='active' THEN RETURN jsonb_build_object('state','not_yet_qualified'); END IF;
 RAISE EXCEPTION 'completed selected Account source lacks original outcome' USING ERRCODE='GP003';
END $$;

-- These return only source metadata. Root composes with genuine ordinary
-- StudyV2Store.getSession/answer result and decodes its accepted119 wrapper.
CREATE FUNCTION read_account_owner_study_reward_v1(p_account TEXT,p_community TEXT,p_session TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE src account_owner_reward_sources%ROWTYPE;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT * INTO STRICT src FROM account_owner_reward_sources WHERE account_id=p_account AND community_id=p_community
  AND session_kind='study_v2' AND session_id=p_session;
 PERFORM lock_owner_participation_group_private_v1(src.source_owner_id);
 PERFORM require_owner_accounting_ready_private_v1();
 IF NOT active_activity_persona(p_account,src.persona_id,p_community) OR NOT can_account_access_activity_song(p_account,p_community,src.post_id) THEN
  RAISE EXCEPTION 'current ordinary Account egress unavailable' USING ERRCODE='GP002'; END IF;
 RETURN jsonb_build_object('sessionId',p_session,'accountId',p_account,'communityId',p_community,'postId',src.post_id,
  'rewardTerms',src.original_terms,'participation',read_account_owner_reward_participation_private_v1(src.source_owner_id,p_session));
END $$;

CREATE FUNCTION find_account_owner_study_start_v1(p_account TEXT,p_community TEXT,p_post TEXT,p_key TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_id TEXT; session_row study_sessions_v2%ROWTYPE;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 SELECT owner_id INTO STRICT source_id FROM participation_owners WHERE kind='account' AND account_id=p_account;
 PERFORM lock_owner_participation_group_private_v1(source_id);
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_key IS NULL OR char_length(p_key) NOT BETWEEN 1 AND 128 OR NOT can_account_access_activity_song(p_account,p_community,p_post) THEN
  RAISE EXCEPTION 'current ordinary Account start lookup unavailable' USING ERRCODE='GP002'; END IF;
 -- Group wait + fresh READ COMMITTED statement serializes actual selected birth
 -- COMMIT. No HTTP404 or unacknowledged client expectation proves absence.
 SELECT * INTO session_row FROM study_sessions_v2 WHERE account_id=p_account AND community_id=p_community AND idempotency_key=p_key;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','not_started','result',NULL); END IF;
 IF session_row.post_id IS DISTINCT FROM p_post OR session_row.owner_reward_preview_hash IS NULL THEN
  RAISE EXCEPTION 'original start key belongs to another source/mode' USING ERRCODE='GP005'; END IF;
 RETURN jsonb_build_object('state','completed','result',read_account_owner_study_reward_v1(p_account,p_community,session_row.session_id));
END $$;

CREATE FUNCTION account_owner_reward_component_has_history_private_v1(p_component TEXT[])
RETURNS BOOLEAN LANGUAGE sql SECURITY DEFINER AS $$
 SELECT EXISTS(SELECT 1 FROM account_owner_reward_sources WHERE source_owner_id=ANY(p_component))
  OR EXISTS(SELECT 1 FROM account_owner_reward_operations WHERE source_owner_id=ANY(p_component));
$$;

-- Source: retained-megapot-clock-window-proposal-0761d789/project_megapot_pool_share_from_qualification.successor.sql
CREATE OR REPLACE FUNCTION project_megapot_pool_share_from_qualification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  candidate RECORD;
  decided_at TIMESTAMPTZ := clock_timestamp();
  decision_id TEXT;
  eligibility_id TEXT;
  identity_digest TEXT;
  admission_hash TEXT;
BEGIN
  IF NEW.participation_owner_kind='guest' THEN RETURN NEW; END IF;
  -- Captured NEW3 Account sources admit only their retained original journal target.
  IF NEW.account_main_operation_id IS NOT NULL THEN RETURN NEW; END IF;
  IF NEW.account_id IS NULL OR NEW.persona_id IS NULL THEN RETURN NEW; END IF;
  IF NOT EXISTS(SELECT 1 FROM participation_owners WHERE kind='account' AND account_id=NEW.account_id) THEN
    RAISE EXCEPTION 'retained v2 account provenance unavailable' USING ERRCODE='GP003'; END IF;
  SELECT leg.leg_id, leg.offer_id, drawing.drawing_id, drawing.entry_cutoff_at,
         offer.community_id, offer.reward_policy_version_id,
         policy.policy_hash
    INTO candidate
    FROM song_reward_offers offer
    JOIN song_reward_offer_legs leg ON leg.offer_id = offer.offer_id
    JOIN megapot_pool_drawings drawing ON drawing.pool_leg_id = leg.leg_id
    JOIN policy_versions policy
      ON policy.community_id = offer.community_id
     AND policy.policy_version_id = offer.reward_policy_version_id
     AND policy.policy_purpose = 'reward'
     AND policy.uniqueness_authority_id = offer.offer_id
   WHERE offer.community_id = NEW.community_id
     AND offer.post_id = NEW.post_id
     AND offer.audio_revision = NEW.audio_revision
     AND offer.status = 'active'
     AND NEW.qualified_at >= offer.starts_at
     AND NEW.qualified_at < offer.ends_at
     AND leg.kind = 'megapot_pool'
     AND reward_leg_accepts_qualification(leg.leg_id, NEW.activity_key, NEW.qualification_policy_version_id)
     AND leg.status = 'active'
     AND NEW.qualified_at >= leg.participation_starts_at
     AND NEW.activity_key = ANY(leg.eligible_activities)
     AND NEW.score_bps >= leg.min_score_bps
     AND drawing.status = 'entry_open'
     AND drawing.beneficiary_version = 2
     AND drawing.drawing_id >= leg.participation_starts_drawing_id
     AND NEW.qualified_at < drawing.entry_cutoff_at
     AND decided_at < drawing.entry_cutoff_at
     AND NOT EXISTS (
       SELECT 1 FROM megapot_pool_shares share
        WHERE share.pool_leg_id = leg.leg_id
          AND share.drawing_id = drawing.drawing_id
          AND share.account_id = NEW.account_id
     )
   ORDER BY drawing.drawing_id DESC
   LIMIT 1
   FOR UPDATE OF drawing;

  IF candidate.leg_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- The drawing lock serializes producers that qualify the same account
  -- concurrently; recheck so only the first commit emits a decision and share.
  IF EXISTS (
    SELECT 1 FROM megapot_pool_shares share
     WHERE share.pool_leg_id = candidate.leg_id
       AND share.drawing_id = candidate.drawing_id
       AND share.account_id = NEW.account_id
  ) THEN
    RETURN NEW;
  END IF;

  -- Recheck AFTER the drawing lock wait, before a monetary decision.
  decided_at := clock_timestamp();
  IF decided_at >= candidate.entry_cutoff_at THEN RETURN NEW; END IF;

  identity_digest := md5(
    NEW.qualification_id || chr(31) || candidate.leg_id || chr(31) || candidate.drawing_id::text
  );
  decision_id := 'reward_decision_' || identity_digest;
  eligibility_id := 'reward_eligibility_' || identity_digest;
  -- The admitted facts, not provider evidence: entry requires none.
  admission_hash := encode(sha256(convert_to(jsonb_build_object(
    'admission', 'megapot_claim_time_verification_v1',
    'qualification_id', NEW.qualification_id,
    'pool_leg_id', candidate.leg_id,
    'drawing_id', candidate.drawing_id::text,
    'policy_hash', candidate.policy_hash
  )::text, 'UTF8')), 'hex');

  -- Only reward decision/eligibility/share writes use this savepoint.
  BEGIN
  INSERT INTO decision_records (
    decision_record_id,community_id,user_id,policy_version_id,policy_hash,
    evaluation_mode,outcome,winning_witness,trace,request_id,created_at
  ) VALUES (
    decision_id,candidate.community_id,NEW.account_id,candidate.reward_policy_version_id,
    candidate.policy_hash,'enforce','pass',
    -- A pass must name its witness: the qualification and admitted terms.
    jsonb_build_array(jsonb_build_object(
      'admission','megapot_claim_time_verification_v1',
      'qualification_id',NEW.qualification_id,
      'pool_leg_id',candidate.leg_id,
      'drawing_id',candidate.drawing_id::text
    )),
    jsonb_build_array(jsonb_build_object(
      'result','eligible','admission','megapot_claim_time_verification_v1'
    )),
    'pool-share:' || identity_digest,decided_at
  );
  INSERT INTO reward_eligibility_decisions (
    eligibility_decision_id,leg_id,account_id,persona_id,purpose,qualification_id,
    drawing_id,decision_record_id,outcome,policy_version,evidence_hash,decided_at,expires_at
  ) VALUES (
    eligibility_id,candidate.leg_id,NEW.account_id,NEW.persona_id,'pool_share',
    NEW.qualification_id,candidate.drawing_id,decision_id,'eligible',
    candidate.reward_policy_version_id,admission_hash,decided_at,
    candidate.entry_cutoff_at
  );
  INSERT INTO megapot_pool_shares (
    pool_leg_id,drawing_id,account_id,persona_id,qualification_id,
    eligibility_decision_id,qualified_at
  ) VALUES (
    candidate.leg_id,candidate.drawing_id,NEW.account_id,NEW.persona_id,
    NEW.qualification_id,eligibility_id,NEW.qualified_at
  ) ON CONFLICT (account_id,pool_leg_id,drawing_id) DO NOTHING;
  EXCEPTION WHEN SQLSTATE 'RM001' THEN
    -- The subtransaction rolls back its decisions and share; original grade and
    -- qualification survive. All other source/constraint failures propagate.
    RETURN NEW;
  END;
  RETURN NEW;
END
$$;

