  OR EXISTS(SELECT 1 FROM reward_credit_persona_bindings) OR EXISTS(SELECT 1 FROM reward_ledger_credits WHERE identity_version='owner_v1') THEN
  RAISE EXCEPTION 'alias recipient transition requires the disabled empty boundary'; END IF;
