   WHERE fk.conrelid=c.child AND fk.confrelid='guest_owner_associations'::regclass AND fk.contype='f'
    AND (SELECT array_agg(a.attname::TEXT ORDER BY key.ordinality) FROM unnest(fk.conkey) WITH ORDINALITY key(attnum,ordinality)
      JOIN pg_attribute a ON a.attrelid=fk.conrelid AND a.attnum=key.attnum)=c.fields);
