-- Source: owner-financial-consumer-successor-75faf734/intent-guard.successor.sql
-- Exact original 0248 guard plus consumed-state branch; terminal target/proof remains immutable.
CREATE OR REPLACE FUNCTION guard_guest_intent_v1() RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP='DELETE' THEN RAISE EXCEPTION 'ceremony evidence is retained'; END IF;
  IF TG_OP='INSERT' THEN
    IF NEW.state<>'awaiting_account' OR NEW.target_revision<>0 OR NEW.prepared_operation_id IS NOT NULL
       OR NEW.created_at>clock_timestamp() OR NEW.expires_at<=clock_timestamp()
       OR resolve_guest_empty_owner_root_v1(NEW.credential_source_owner_id)<>NEW.owner_id
       OR resolve_guest_empty_owner_root_v1(NEW.owner_id)<>NEW.owner_id
       OR NOT EXISTS(SELECT 1 FROM guest_credentials WHERE credential_id=NEW.credential_id
         AND owner_id=NEW.credential_source_owner_id AND origin=NEW.origin AND state='confirmed') THEN
      RAISE EXCEPTION 'new ceremony requires its original live empty-target protocol';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(NEW.intent_id,NEW.owner_id,NEW.credential_source_owner_id,NEW.credential_id,
         NEW.origin,NEW.nonce_digest,NEW.created_at,NEW.expires_at)
     IS DISTINCT FROM ROW(OLD.intent_id,OLD.owner_id,OLD.credential_source_owner_id,OLD.credential_id,
         OLD.origin,OLD.nonce_digest,OLD.created_at,OLD.expires_at) THEN
    RAISE EXCEPTION 'ceremony proof identity is immutable';
  END IF;
  IF OLD.state IN ('expired','superseded','consumed') THEN
    IF (to_jsonb(NEW)-'owner_kind') IS DISTINCT FROM (to_jsonb(OLD)-'owner_kind') THEN
      RAISE EXCEPTION 'ceremony terminal state is final';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.state='consumed' THEN
    IF OLD.state<>'awaiting_confirmation' OR clock_timestamp()>=OLD.expires_at
      OR ROW(NEW.target_revision,NEW.target_account_id,NEW.target_session_digest,NEW.prepared_operation_id)
        IS DISTINCT FROM ROW(OLD.target_revision,OLD.target_account_id,OLD.target_session_digest,OLD.prepared_operation_id)
      OR NOT EXISTS(SELECT 1 FROM guest_owner_associations a
        WHERE a.intent_id=OLD.intent_id AND a.guest_owner_id=OLD.owner_id
          AND a.account_id=OLD.target_account_id AND a.origin=OLD.origin) THEN
      RAISE EXCEPTION 'consumption requires the immutable prepared association'; END IF;
    RETURN NEW;
  END IF;
  IF NEW.state IN ('expired','superseded') THEN
    IF ROW(NEW.target_revision,NEW.target_account_id,NEW.target_session_digest,NEW.prepared_operation_id)
       IS DISTINCT FROM ROW(OLD.target_revision,OLD.target_account_id,OLD.target_session_digest,OLD.prepared_operation_id) THEN
      RAISE EXCEPTION 'terminal ceremony retains its displayed target';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.state<>'awaiting_confirmation' OR clock_timestamp()>=OLD.expires_at
     OR NEW.target_revision<OLD.target_revision OR NEW.prepared_operation_id IS NULL THEN
    RAISE EXCEPTION 'invalid ceremony preparation';
  END IF;
  IF ROW(NEW.target_account_id,NEW.target_session_digest) IS DISTINCT FROM ROW(OLD.target_account_id,OLD.target_session_digest) THEN
    IF NEW.target_revision<>OLD.target_revision+1 OR NEW.prepared_operation_id IS NOT DISTINCT FROM OLD.prepared_operation_id THEN
      RAISE EXCEPTION 'changed target requires next revision and operation'; END IF;
  ELSIF ROW(NEW.target_revision,NEW.prepared_operation_id) IS DISTINCT FROM ROW(OLD.target_revision,OLD.prepared_operation_id) THEN
    RAISE EXCEPTION 'same target preparation must replay';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM guest_participation_operations WHERE operation_id=NEW.prepared_operation_id
      AND source_owner_id=NEW.owner_id AND operation_kind='attachment_prepare'
      AND resource_scope=NEW.intent_id) THEN
    RAISE EXCEPTION 'preparation must retain its owner operation';
  END IF;
  RETURN NEW;
END $$;

-- Source: owner-financial-consumer-successor-75faf734/attachment-group-lock.sql
-- Exact admission recursive closure extended to all pre-association seeds; EXCLUSIVE FIRST.
-- Common group lock primitive, ungranted. Current schema still blocks financial
-- association writers; full future admission requires their same EXCLUSIVE barrier.
CREATE FUNCTION lock_owner_attachment_groups_private_v1(p_seeds TEXT[])
RETURNS TEXT[] LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_ids TEXT[]; account_ids TEXT[]; count_accounts INTEGER;
BEGIN
 PERFORM pg_advisory_xact_lock(83000003,1);
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
   RAISE EXCEPTION 'fresh attachment snapshot required' USING ERRCODE='GP003'; END IF;
 LOCK TABLE account_aliases IN SHARE MODE;
 IF p_seeds IS NULL OR cardinality(p_seeds)=0 OR cardinality(p_seeds)>6
   OR EXISTS(SELECT 1 FROM unnest(p_seeds) seed WHERE seed IS NULL
     OR NOT EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=seed)) THEN
  RAISE EXCEPTION 'immutable source owner missing' USING ERRCODE='GP002'; END IF;
 WITH RECURSIVE group_members(owner_id) AS (
  SELECT DISTINCT seed FROM unnest(p_seeds) seed
  UNION
  SELECT next_member.owner_id FROM group_members prior CROSS JOIN LATERAL (
   SELECT a.canonical_owner_id AS owner_id FROM guest_empty_owner_aliases a WHERE a.source_owner_id=prior.owner_id
   UNION SELECT a.source_owner_id FROM guest_empty_owner_aliases a WHERE a.canonical_owner_id=prior.owner_id
   UNION SELECT a.account_owner_id FROM guest_owner_associations a WHERE a.guest_owner_id=prior.owner_id
   UNION SELECT a.guest_owner_id FROM guest_owner_associations a WHERE a.account_owner_id=prior.owner_id
   UNION SELECT other_owner.owner_id FROM participation_owners current_owner
    JOIN account_aliases a ON a.source_user_id=current_owner.account_id OR a.canonical_user_id=current_owner.account_id
    JOIN participation_owners other_owner ON other_owner.account_id IN(a.source_user_id,a.canonical_user_id)
    WHERE current_owner.owner_id=prior.owner_id AND current_owner.kind='account'
     AND ((a.kind='alias' AND a.status='active') OR (a.kind='merge' AND a.status IN('finalizing','completed')))
  ) next_member
 ) SELECT array_agg(owner_id ORDER BY convert_to(owner_id,'UTF8')) INTO source_ids FROM group_members;
 IF source_ids IS NULL OR cardinality(source_ids)>10000 OR EXISTS(SELECT 1 FROM unnest(source_ids) source_id
  WHERE NOT EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=source_id)) THEN
  RAISE EXCEPTION 'source group closure unavailable' USING ERRCODE='GP003'; END IF;
 SELECT array_agg(account_id ORDER BY convert_to(account_id,'UTF8')) INTO account_ids
 FROM participation_owners WHERE owner_id=ANY(source_ids) AND kind='account';
 IF EXISTS(SELECT 1 FROM account_aliases WHERE source_user_id=ANY(coalesce(account_ids,'{}'::TEXT[])) AND kind='merge' AND status='finalizing') THEN
  RAISE EXCEPTION 'account topology is unsettled' USING ERRCODE='GP003'; END IF;
 IF account_ids IS NOT NULL THEN
  SELECT count(*) INTO count_accounts FROM unnest(account_ids) id WHERE NOT EXISTS(SELECT 1 FROM account_aliases a WHERE a.source_user_id=id AND((a.kind='alias' AND a.status='active') OR(a.kind='merge' AND a.status='completed')));
  IF count_accounts>2 THEN RAISE EXCEPTION 'canonical account group is unsettled' USING ERRCODE='GP003'; END IF;
 END IF;
 -- Compatible non-key state locks avoid freeze's immutable-FK KEY SHARE cycle.
 -- Every other owner/account business writer must use the same ordered protocol;
 -- old FOR UPDATE upgrades are NOT declared repaired by this helper alone.
 PERFORM 1 FROM users WHERE user_id=ANY(coalesce(account_ids,'{}'::TEXT[])) ORDER BY convert_to(user_id,'UTF8') FOR NO KEY UPDATE;
 PERFORM 1 FROM participation_owners WHERE owner_id=ANY(source_ids) ORDER BY convert_to(owner_id,'UTF8') FOR NO KEY UPDATE;
 RETURN source_ids;
END $$;

-- Source: owner-financial-consumer-successor-75faf734/owner-credit-readers.sql
-- ONE-row-per-credit liability inventory. No account/persona/auth join can erase debt.
CREATE FUNCTION unpaid_owner_credit_inventory_private_v1(p_chain BIGINT,p_token TEXT)
RETURNS TABLE(credit_id TEXT,identity_version TEXT,source_owner_id TEXT,account_id TEXT,
 owed_atomic NUMERIC,reserved_atomic NUMERIC,credit_state TEXT)
LANGUAGE sql STABLE SECURITY DEFINER AS $$
 SELECT credit_id,identity_version,participation_owner_id,account_id,
 amount_atomic-paid_atomic,reserved_atomic,state FROM reward_ledger_credits
 WHERE chain_id=p_chain AND token_address=p_token
   AND(amount_atomic<>paid_atomic OR reserved_atomic<>0)
$$;

-- Canonical account resolution is ACCESS only; never reparent source/binding/credit.
-- Same bounded, cycle-refusing forward alias traversal as actual identity repository.
CREATE FUNCTION owner_credit_canonical_account_private_v1(p_original TEXT)
RETURNS TEXT LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE resolved TEXT; terminals INTEGER;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM users WHERE user_id=p_original AND status='active') THEN RETURN NULL; END IF;
 WITH RECURSIVE chain(id,visited,depth,cycle) AS(
  SELECT p_original,ARRAY[p_original]::TEXT[],0,FALSE
  UNION ALL SELECT a.canonical_user_id,c.visited||a.canonical_user_id,c.depth+1,a.canonical_user_id=ANY(c.visited)
  FROM chain c JOIN account_aliases a ON a.source_user_id=c.id
    AND((a.kind='alias' AND a.status='active') OR(a.kind='merge' AND a.status IN('finalizing','completed')))
  WHERE c.depth<8 AND NOT c.cycle
 ), terminal AS(SELECT id FROM chain c WHERE NOT c.cycle AND NOT EXISTS(
    SELECT 1 FROM account_aliases a WHERE a.source_user_id=c.id
     AND((a.kind='alias' AND a.status='active') OR(a.kind='merge' AND a.status IN('finalizing','completed'))))
    AND NOT EXISTS(SELECT 1 FROM chain WHERE cycle)
    AND NOT EXISTS(SELECT 1 FROM chain c2 JOIN account_aliases a ON a.source_user_id=c2.id AND a.kind='merge' AND a.status='finalizing'))
 SELECT min(id),count(*) INTO resolved,terminals FROM terminal;
 IF terminals<>1 OR NOT EXISTS(SELECT 1 FROM users WHERE user_id=resolved AND status='active') THEN RETURN NULL; END IF;
 RETURN resolved;
END $$;

-- Closed exact v3 lineage; JSONB is private source metadata, not the public artifact.
CREATE FUNCTION read_owner_credit_lineage_private_v1(p_credit TEXT)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE result JSONB; rows_count INTEGER;
BEGIN
 SELECT count(*),jsonb_agg(jsonb_build_object('owner_id',credit.participation_owner_id,'owner_kind',o.kind,
   'source_account_id',o.account_id,'community_id',offer.community_id,'pool_leg_id',batch.pool_leg_id,
   'drawing_id',batch.drawing_id::TEXT,'allocation_kind',allocation.allocation_kind,
   'original_persona_id',leaf.original_persona_id,'original_account_id',leaf.original_account_id,
   'attestation_id',leg.attestation_id,'allocation_state',batch.state)) INTO rows_count,result
 FROM reward_ledger_credits credit
 JOIN participation_owners o ON o.owner_id=credit.participation_owner_id
 JOIN megapot_owner_allocations allocation ON allocation.credit_id=credit.credit_id
   AND allocation.owner_id=credit.participation_owner_id AND allocation.amount_atomic=credit.amount_atomic
   AND allocation.amount_atomic>0 AND allocation.allocation_kind='participant'
 JOIN megapot_allocation_batches batch ON batch.allocation_batch_id=allocation.allocation_batch_id
   AND batch.snapshot_id=allocation.snapshot_id AND batch.beneficiary_version=3
 JOIN megapot_owner_snapshot_leaves leaf ON leaf.snapshot_id=allocation.snapshot_id AND leaf.ordinal=allocation.ordinal
   AND leaf.owner_id=allocation.owner_id AND leaf.owner_kind=o.kind
   AND leaf.pool_leg_id=batch.pool_leg_id AND leaf.drawing_id=batch.drawing_id AND leaf.beneficiary_version=3
 JOIN megapot_pool_drawings drawing ON drawing.pool_leg_id=batch.pool_leg_id AND drawing.drawing_id=batch.drawing_id
   AND drawing.beneficiary_version=3
 JOIN song_reward_offer_legs leg ON leg.leg_id=batch.pool_leg_id
 JOIN song_reward_offers offer ON offer.offer_id=leg.offer_id
 WHERE credit.credit_id=p_credit AND credit.identity_version='owner_v1' AND credit.source_kind='megapot_allocation'
   AND credit.account_id IS NULL AND credit.payout_persona_id IS NULL;
 IF rows_count<>1 THEN RAISE EXCEPTION 'owner credit lineage unavailable' USING ERRCODE='GP003'; END IF;
 RETURN result->0;
END $$;

CREATE FUNCTION owner_credit_access_private_v1(p_credit TEXT,p_account TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE source JSONB;
BEGIN
 source:=read_owner_credit_lineage_private_v1(p_credit);
 IF NOT EXISTS(SELECT 1 FROM users WHERE user_id=p_account AND status='active')
   OR owner_credit_canonical_account_private_v1(p_account) IS DISTINCT FROM p_account THEN RETURN FALSE; END IF;
 IF source->>'owner_kind'='account' THEN
   RETURN coalesce(owner_credit_canonical_account_private_v1(source->>'source_account_id')=p_account,FALSE);
 END IF;
 -- Conflict association is dedup-only, never authenticated access to credit/history.
 RETURN EXISTS(SELECT 1 FROM guest_owner_associations a WHERE a.guest_owner_id=source->>'owner_id'
   AND a.state='bound' AND owner_credit_canonical_account_private_v1(a.account_id)=p_account);
END $$;

-- Uses the immutable first persona, its CURRENT active assignment, not a frozen wallet.
CREATE FUNCTION resolve_owner_credit_recipient_private_v1(p_credit TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE b reward_credit_persona_bindings%ROWTYPE; source JSONB; assignment TEXT;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 source:=read_owner_credit_lineage_private_v1(p_credit);
 IF source->>'allocation_state'<>'credited' THEN RAISE EXCEPTION 'committed allocation required' USING ERRCODE='GP003'; END IF;
 PERFORM lock_owner_participation_group_private_v1(source->>'owner_id');
 SELECT * INTO b FROM reward_credit_persona_bindings WHERE credit_id=p_credit;
 IF NOT FOUND THEN RETURN jsonb_build_object('state','held','reason','unbound'); END IF;
 PERFORM 1 FROM personas WHERE persona_id=b.persona_id AND account_id=b.account_id FOR NO KEY UPDATE;
 IF active_owned_community_persona(b.account_id,b.persona_id,source->>'community_id') IS DISTINCT FROM TRUE THEN
   RETURN jsonb_build_object('state','held','reason','persona_unavailable'); END IF;
 SELECT address INTO assignment FROM persona_wallet_assignments
 WHERE account_id=b.account_id AND persona_id=b.persona_id AND chain_account_kind='evm' AND status='active'
   AND address IS NOT NULL ORDER BY assigned_at,assignment_id LIMIT 1 FOR SHARE;
 IF assignment IS NULL THEN RETURN jsonb_build_object('state','held','reason','wallet_unavailable'); END IF;
 RETURN jsonb_build_object('state','bound','personaId',b.persona_id,'walletAddress',assignment);
END $$;

CREATE FUNCTION project_owner_reward_credit_private_v1(p_credit TEXT)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE c reward_ledger_credits%ROWTYPE; source JSONB; b reward_credit_persona_bindings%ROWTYPE;
 s reward_credit_recipient_selections%ROWTYPE; claim megapot_participant_claims%ROWTYPE;
 decimals INTEGER; recipient JSONB; payout_status TEXT; send_result JSONB;
BEGIN
 SELECT * INTO STRICT c FROM reward_ledger_credits WHERE credit_id=p_credit;
 source:=read_owner_credit_lineage_private_v1(p_credit);
 IF source->>'allocation_state'<>'credited' THEN RAISE EXCEPTION 'committed allocation required' USING ERRCODE='GP003'; END IF;
 SELECT asset.decimals INTO STRICT decimals FROM reward_asset_whitelist asset WHERE asset.chain_id=c.chain_id AND asset.token_address=c.token_address;
 SELECT * INTO b FROM reward_credit_persona_bindings WHERE credit_id=p_credit;
 SELECT * INTO claim FROM megapot_participant_claims WHERE credit_id=p_credit;
 IF b.credit_id IS NOT NULL THEN
   IF b.owner_id<>c.participation_owner_id OR b.owner_kind<>source->>'owner_kind' THEN
     RAISE EXCEPTION 'recipient provenance differs' USING ERRCODE='GP003'; END IF;
   IF b.owner_kind='account' THEN
     IF b.binding_source<>'account_original' OR b.account_id IS DISTINCT FROM source->>'original_account_id'
       OR b.persona_id IS DISTINCT FROM source->>'original_persona_id' OR b.selection_revision IS NOT NULL THEN
       RAISE EXCEPTION 'original account recipient differs' USING ERRCODE='GP003'; END IF;
     recipient:=jsonb_build_object('kind','account_owner','original_persona_id',b.persona_id,'selection',NULL,
      'binding',jsonb_build_object('persona_id',b.persona_id,'selection_revision',NULL,'bound_at',to_char(b.bound_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
   ELSE
     SELECT * INTO STRICT s FROM reward_credit_recipient_selections WHERE credit_id=p_credit AND selection_revision=b.selection_revision;
     IF b.binding_source<>'guest_claim' OR ROW(s.account_id,s.persona_id) IS DISTINCT FROM ROW(b.account_id,b.persona_id)
       OR claim.status IS DISTINCT FROM 'accepted' OR claim.owner_selection_revision IS DISTINCT FROM b.selection_revision THEN
       RAISE EXCEPTION 'accepted guest recipient differs' USING ERRCODE='GP003'; END IF;
   END IF;
 ELSE
   IF source->>'owner_kind'<>'guest' THEN RAISE EXCEPTION 'original account binding absent' USING ERRCODE='GP003'; END IF;
   SELECT * INTO s FROM reward_credit_recipient_selections WHERE credit_id=p_credit ORDER BY selection_revision DESC LIMIT 1;
 END IF;
 IF source->>'owner_kind'='guest' THEN
   recipient:=jsonb_build_object('kind','guest_owner','selection',CASE WHEN s.credit_id IS NULL THEN NULL ELSE jsonb_build_object(
     'revision',s.selection_revision,'persona_id',s.persona_id,'selected_at',to_char(s.selected_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) END,
     'binding',CASE WHEN b.credit_id IS NULL THEN NULL ELSE jsonb_build_object('persona_id',b.persona_id,
      'selection_revision',b.selection_revision,'bound_at',to_char(b.bound_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) END);
 END IF;
 IF claim.status='accepted' THEN
   payout_status:=CASE WHEN c.state='sent' THEN 'confirmed' WHEN c.state='payout_pending' THEN 'submitted'
     WHEN c.state='payout_reserved' THEN 'pending' WHEN c.state='reconciliation_required' THEN 'failed_retrying'
     WHEN active_owned_community_persona(b.account_id,b.persona_id,source->>'community_id') IS DISTINCT FROM TRUE OR NOT EXISTS(
       SELECT 1 FROM persona_wallet_assignments WHERE account_id=b.account_id AND persona_id=b.persona_id AND status='active' AND address IS NOT NULL)
       THEN 'recipient_pending'
     WHEN EXISTS(SELECT 1 FROM reward_payout_effects payout JOIN reward_chain_effects effect ON effect.effect_id=payout.payout_effect_id
       WHERE payout.credit_id=c.credit_id AND effect.state IN('reverted','replaced','reclaimable_failed','terminal_failed')) THEN 'failed_retrying' ELSE 'pending' END;
 END IF;
 SELECT jsonb_build_object('send_id',send_id,'status',status) INTO send_result FROM reward_winner_sends
 WHERE credit_id=p_credit AND account_id=b.account_id ORDER BY(status<>'cancelled') DESC,created_at DESC,send_id DESC LIMIT 1;
 RETURN jsonb_build_object('object','owner_reward_credit_v1','credit_id',c.credit_id,'identity_version','owner_v1',
  'owner_id',c.participation_owner_id,'community_id',source->>'community_id','pool_leg_id',source->>'pool_leg_id',
  'original_drawing_id',source->>'drawing_id','chain_id',c.chain_id,'token_address',c.token_address,'token_decimals',decimals,
  'amount_atomic',c.amount_atomic::TEXT,'available_atomic',(c.amount_atomic-c.reserved_atomic-c.paid_atomic)::TEXT,
  'reserved_atomic',c.reserved_atomic::TEXT,'paid_atomic',c.paid_atomic::TEXT,'source_kind',c.source_kind,'state',c.state,
  'created_at',to_char(c.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  'updated_at',to_char(c.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  'settled_at',CASE WHEN c.settled_at IS NULL THEN NULL ELSE to_char(c.settled_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') END,
  'claim',jsonb_build_object('status',coalesce(claim.status,'unclaimed'),'payout_status',payout_status),'send',send_result,'recipient',recipient);
END $$;

CREATE FUNCTION resolve_owner_credit_authority_v1(p_account TEXT,p_credit TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source JSONB; credit JSONB;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 IF NOT EXISTS(SELECT 1 FROM reward_ledger_credits WHERE credit_id=p_credit AND identity_version='owner_v1') THEN RETURN NULL; END IF;
 source:=read_owner_credit_lineage_private_v1(p_credit);
 PERFORM lock_owner_participation_group_private_v1(source->>'owner_id');
 IF owner_credit_access_private_v1(p_credit,p_account) IS DISTINCT FROM TRUE THEN RETURN NULL; END IF;
 credit:=project_owner_reward_credit_private_v1(p_credit);
 IF source->>'owner_kind'='account' THEN
  RETURN jsonb_build_object('kind','account_owner','ownerId',source->>'owner_id','accountId',p_account,'originalPersonaId',source->>'original_persona_id','credit',credit);
 END IF;
 RETURN jsonb_build_object('kind','guest_owner','ownerId',source->>'owner_id','boundAccountId',p_account,'credit',credit);
END $$;

CREATE FUNCTION owner_credit_financial_erasure_holds_private_v1(p_account TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE owner TEXT; sources TEXT[]; accounts TEXT[]; result JSONB;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT owner_id INTO STRICT owner FROM participation_owners WHERE kind='account' AND account_id=p_account;
 sources:=lock_owner_participation_group_private_v1(owner);
 SELECT array_agg(account_id) INTO accounts FROM participation_owners WHERE owner_id=ANY(sources) AND kind='account';
 -- Bound AND conflicted associations are retained financial evidence. Access has a
 -- separate bound-only predicate; this is the conservative erasure/operations gate.
 SELECT coalesce(jsonb_agg(jsonb_build_object('chain_id',chain_id,'token_address',token_address,
   'credit_count',credit_count,'owed_atomic',owed::TEXT,'reserved_atomic',reserved::TEXT)
   ORDER BY chain_id,token_address),'[]'::JSONB) INTO result
 FROM(SELECT chain_id,token_address,count(*) credit_count,sum(amount_atomic-paid_atomic) owed,sum(reserved_atomic) reserved
   FROM reward_ledger_credits WHERE(account_id=ANY(coalesce(accounts,'{}'::TEXT[])) OR participation_owner_id=ANY(sources))
    AND(amount_atomic<>paid_atomic OR reserved_atomic<>0) GROUP BY chain_id,token_address) totals;
 RETURN jsonb_build_object('credit_liabilities',result,
   'financial_history_retained',guest_financial_component_has_history_private_v1(sources));
END $$;

-- Source: owner-financial-consumer-successor-75faf734/very-refusal-classifier.sql
CREATE FUNCTION owner_credit_very_refusal_private_v1(p_account TEXT)
RETURNS TEXT LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE evidence RECORD; result_reason TEXT;
BEGIN
  SELECT * INTO evidence FROM reward_account_very_evidence_v1(p_account, NULL);
  IF evidence.subject_key_id IS NULL THEN
    IF EXISTS (
      SELECT 1
        FROM subject_keys subject
        JOIN active_subject_key_bindings active_binding
          ON active_binding.subject_key_id = subject.subject_key_id
         AND active_binding.user_id = p_account
        JOIN assertions personhood
          ON personhood.subject_key_id = subject.subject_key_id
         AND personhood.user_id = p_account
         AND personhood.claim_id = 'human.personhood'
         AND personhood.assertion_value = '{"personhood": true}'::jsonb
        JOIN assertions subject_unique
          ON subject_unique.binding_group_id = personhood.binding_group_id
         AND subject_unique.evidence_receipt_id = personhood.evidence_receipt_id
         AND subject_unique.subject_key_id = subject.subject_key_id
         AND subject_unique.user_id = p_account
         AND subject_unique.claim_id = 'credential.subject_unique'
         AND subject_unique.assertion_value = '{"subject_unique": true}'::jsonb
       WHERE subject.issuer = 'https://verify.very.org'
         AND subject.method = 'palm_web'
         AND subject.scope_kind = 'issuer_rp_scope'
         AND subject.issuer_rp_scope = 'pirate-social'
    ) THEN
      result_reason := 'verification_stale';
    ELSIF EXISTS (
      SELECT 1
        FROM subject_keys subject
        JOIN active_subject_key_bindings active_binding
          ON active_binding.subject_key_id = subject.subject_key_id
         AND active_binding.user_id = p_account
       WHERE subject.issuer = 'https://verify.very.org'
         AND subject.method = 'palm_web'
         AND subject.scope_kind = 'issuer_rp_scope'
         AND subject.issuer_rp_scope = 'pirate-social'
    ) THEN
      result_reason := 'verification_failed';
    ELSE
      result_reason := 'verification_missing';
    END IF;

    RETURN result_reason;
  END IF;
  IF evidence.evidence_count <> 1 THEN
    RETURN 'verification_failed';
  END IF;

 RETURN NULL;
END $$;

-- Source: financial-native-assembly-v5/attachment-canonical-corrected.sql
-- Controlled private attachment leaves. Installed ungranted; current disabled phase refuses.
-- Coordinator must supply the source-bound POSITIVE complete consumer inventory routine
-- require_owner_accounting_ready_private_v1(). This packet never defines a success stub.
CREATE FUNCTION confirm_guest_owner_attachment_v1(
 p_origin TEXT,p_proved_credentials TEXT[],p_selected TEXT,p_owner TEXT,
 p_proved_intents TEXT[],p_intent TEXT,p_account TEXT,p_session_digest TEXT,
 p_revision BIGINT,p_key TEXT,p_hash TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE target guest_attachment_intents%ROWTYPE; credential guest_credentials%ROWTYPE;
 assoc guest_owner_associations%ROWTYPE; original_op guest_participation_operations%ROWTYPE;
 target_owner TEXT; sources TEXT[]; source_group TEXT[]; target_group TEXT[];
 at_time TIMESTAMPTZ; outcome_id TEXT; overlap JSONB; result JSONB;
BEGIN
 -- FIRST lock, including before the readiness query or any owner/account/intent lock.
 PERFORM pg_advisory_xact_lock(83000003,1);
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
   RAISE EXCEPTION 'fresh attachment snapshot required' USING ERRCODE='GP003'; END IF;
 LOCK TABLE account_aliases IN SHARE MODE;
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_origin IS NULL OR p_origin NOT LIKE 'https://%' OR octet_length(p_origin)>2048
   OR p_proved_credentials IS NULL OR cardinality(p_proved_credentials)>4
   OR EXISTS(SELECT 1 FROM unnest(p_proved_credentials) id WHERE id IS NULL OR id !~ '^[A-Za-z0-9_-]{21}[AQgw]$')
   OR cardinality(p_proved_credentials)<>(SELECT count(DISTINCT id) FROM unnest(p_proved_credentials) id)
   OR p_selected IS NULL OR NOT p_selected=ANY(p_proved_credentials)
   OR p_proved_intents IS NULL OR cardinality(p_proved_intents)>4
   OR cardinality(p_proved_intents)<>(SELECT count(DISTINCT id) FROM unnest(p_proved_intents) id)
   OR p_intent IS NULL OR NOT p_intent=ANY(p_proved_intents)
   OR p_session_digest IS NULL OR p_session_digest!~'^[0-9a-f]{64}$'
   OR p_revision IS NULL OR p_revision NOT BETWEEN 1 AND 9007199254740991
   OR p_hash IS NULL OR p_hash!~'^[0-9a-f]{64}$'
   OR p_key IS DISTINCT FROM p_intent||':'||p_revision::TEXT THEN
   RAISE EXCEPTION 'invalid protected attachment context' USING ERRCODE='22023'; END IF;
 SELECT owner_id INTO target_owner FROM participation_owners WHERE kind='account' AND account_id=p_account;
 IF target_owner IS NULL THEN RAISE EXCEPTION 'target-changed' USING ERRCODE='GP008'; END IF;
 -- Capture the two groups before linking them. Nonlocking source discovery is stable
 -- under EXCLUSIVE topology + alias table lock. Lock their full UNION only once.
 WITH RECURSIVE component(id) AS (SELECT p_owner UNION SELECT next.id FROM component c CROSS JOIN LATERAL(
  SELECT a.canonical_owner_id id FROM guest_empty_owner_aliases a WHERE a.source_owner_id=c.id
  UNION SELECT a.source_owner_id FROM guest_empty_owner_aliases a WHERE a.canonical_owner_id=c.id
  UNION SELECT a.account_owner_id FROM guest_owner_associations a WHERE a.guest_owner_id=c.id
  UNION SELECT a.guest_owner_id FROM guest_owner_associations a WHERE a.account_owner_id=c.id
  UNION SELECT other.owner_id FROM participation_owners cur JOIN account_aliases a ON a.source_user_id=cur.account_id OR a.canonical_user_id=cur.account_id
   JOIN participation_owners other ON other.account_id IN(a.source_user_id,a.canonical_user_id)
   WHERE cur.owner_id=c.id AND((a.kind='alias' AND a.status='active') OR(a.kind='merge' AND a.status IN('finalizing','completed')))
 ) next) SELECT array_agg(id ORDER BY convert_to(id,'UTF8')) INTO source_group FROM component;
 WITH RECURSIVE component(id) AS (SELECT target_owner UNION SELECT next.id FROM component c CROSS JOIN LATERAL(
  SELECT a.canonical_owner_id id FROM guest_empty_owner_aliases a WHERE a.source_owner_id=c.id
  UNION SELECT a.source_owner_id FROM guest_empty_owner_aliases a WHERE a.canonical_owner_id=c.id
  UNION SELECT a.account_owner_id FROM guest_owner_associations a WHERE a.guest_owner_id=c.id
  UNION SELECT a.guest_owner_id FROM guest_owner_associations a WHERE a.account_owner_id=c.id
  UNION SELECT other.owner_id FROM participation_owners cur JOIN account_aliases a ON a.source_user_id=cur.account_id OR a.canonical_user_id=cur.account_id
   JOIN participation_owners other ON other.account_id IN(a.source_user_id,a.canonical_user_id)
   WHERE cur.owner_id=c.id AND((a.kind='alias' AND a.status='active') OR(a.kind='merge' AND a.status IN('finalizing','completed')))
 ) next) SELECT array_agg(id ORDER BY convert_to(id,'UTF8')) INTO target_group FROM component;
 SELECT lock_owner_attachment_groups_private_v1(array_agg(DISTINCT seed)) INTO sources FROM(
   SELECT p_owner seed UNION SELECT target_owner
   UNION SELECT resolve_guest_empty_owner_root_v1(c.owner_id) FROM guest_credentials c
     WHERE c.origin=p_origin AND c.credential_id=ANY(p_proved_credentials)
 ) seed_set;
 IF NOT EXISTS(SELECT 1 FROM users WHERE user_id=p_account AND status='active')
   OR EXISTS(SELECT 1 FROM account_aliases WHERE source_user_id=p_account
     AND((kind='alias' AND status='active') OR(kind='merge' AND status IN('finalizing','completed')))) THEN
   RAISE EXCEPTION 'target-changed' USING ERRCODE='GP008'; END IF;
 -- All proved sources were in the combined union before credential locks.
 -- Reuse the validated EXCLUSIVE union: NEVER upgrade owner NO KEY UPDATE to UPDATE.
 -- Such an upgrade conflicts with freeze's snapshot-leaf FK KEY SHARE after Draw lock.
 -- Credential rows still lock in the same complete-source deterministic order as 0250.
 PERFORM 1 FROM guest_credentials c WHERE c.owner_id=ANY(sources)
   ORDER BY convert_to(c.credential_id,'UTF8') FOR UPDATE;
 SELECT * INTO STRICT credential FROM guest_credentials WHERE credential_id=p_selected AND origin=p_origin;
 IF credential.state<>'confirmed' THEN RAISE EXCEPTION 'proof-revoked' USING ERRCODE='GP001'; END IF;
 IF resolve_guest_empty_owner_root_v1(credential.owner_id) IS DISTINCT FROM p_owner THEN
   RAISE EXCEPTION 'owner-mismatch' USING ERRCODE='GP002'; END IF;
 SELECT * INTO STRICT target FROM guest_attachment_intents WHERE intent_id=p_intent AND origin=p_origin FOR UPDATE;
 IF target.owner_id<>p_owner OR target.credential_id<>p_selected OR target.credential_source_owner_id<>credential.owner_id THEN
   RAISE EXCEPTION 'owner-mismatch' USING ERRCODE='GP002'; END IF;
 IF ROW(target.target_revision,target.target_account_id,target.target_session_digest)
   IS DISTINCT FROM ROW(p_revision,p_account,p_session_digest) THEN
   RAISE EXCEPTION 'target-changed' USING ERRCODE='GP008'; END IF;
 SELECT * INTO assoc FROM guest_owner_associations WHERE guest_owner_id=p_owner;
 -- Conflict replay keeps proof. Bound replay after proof revocation uses account-only lookup.
 IF FOUND THEN
   IF assoc.intent_id<>p_intent OR assoc.account_id<>p_account THEN
     RAISE EXCEPTION 'target-changed' USING ERRCODE='GP008'; END IF;
   SELECT * INTO STRICT original_op FROM guest_participation_operations
     WHERE source_owner_id=p_owner AND operation_kind='attachment_confirm' AND idempotency_key=p_key;
   IF original_op.request_hash<>p_hash OR original_op.resource_scope<>p_intent OR original_op.state<>'completed' THEN
     RAISE EXCEPTION 'idempotency-conflict' USING ERRCODE='GP005'; END IF;
   RETURN jsonb_build_object('state','completed','outcomeId',original_op.operation_id,
    'operation',jsonb_build_object('sourceOwnerId',p_owner,'kind','attachment_confirm','idempotencyKey',p_key,'requestHash',p_hash),
    'result',original_op.result_snapshot);
 END IF;
 at_time:=clock_timestamp();
 IF target.state<>'awaiting_confirmation' OR target.expires_at<=at_time THEN
   RAISE EXCEPTION 'intent-expired' USING ERRCODE='GP006'; END IF;
 -- Admitted shares, not a fallback gift or an uncommitted eligibility decision.
 -- Historical v2 source rows are retained; no replay/new share is created here.
 WITH scope_rows AS (
   SELECT owner_id,pool_leg_id,drawing_id FROM megapot_owner_shares
   UNION SELECT o.owner_id,s.pool_leg_id,s.drawing_id FROM megapot_pool_shares s
     JOIN participation_owners o ON o.kind='account' AND o.account_id=s.account_id
 ), overlap_rows AS (SELECT DISTINCT a.pool_leg_id,a.drawing_id FROM scope_rows a JOIN scope_rows b
   ON a.pool_leg_id=b.pool_leg_id AND a.drawing_id=b.drawing_id
   WHERE a.owner_id=ANY(source_group) AND b.owner_id=ANY(target_group)
    ORDER BY a.pool_leg_id COLLATE "C",a.drawing_id LIMIT 1)
 SELECT coalesce(jsonb_agg(jsonb_build_object('pool_leg_id',pool_leg_id,'drawing_id',drawing_id::TEXT)
   ORDER BY convert_to(pool_leg_id,'UTF8'),drawing_id),'[]'::JSONB) INTO overlap FROM overlap_rows;
 INSERT INTO guest_owner_associations(guest_owner_id,account_id,account_owner_id,state,intent_id,origin,proved_at)
 VALUES(p_owner,p_account,target_owner,CASE WHEN overlap='[]'::JSONB THEN 'bound' ELSE 'participation_conflict' END,p_intent,p_origin,at_time);
 INSERT INTO guest_owner_association_conflicts(guest_owner_id,pool_leg_id,drawing_id)
 SELECT p_owner,x.pool_leg_id,x.drawing_id::NUMERIC FROM jsonb_to_recordset(overlap) x(pool_leg_id TEXT,drawing_id TEXT);
 UPDATE guest_attachment_intents SET state='consumed' WHERE intent_id=p_intent;
 outcome_id:='guest_attachment_'||substring(p_intent FROM 5)||'_'||p_revision::TEXT;
 IF overlap='[]'::JSONB THEN
   -- Revoke EVERY credential in the source component, including pending successors;
   -- preserve original source IDs, digests, clocks and accepted provider commands.
   UPDATE guest_credentials SET state='revoked',revoked_at=at_time,revocation_reason='attachment_bound'
     WHERE owner_id=ANY(source_group) AND state<>'revoked';
   result:=jsonb_build_object('state','bound','binding',jsonb_build_object(
     'attachment_id',p_intent,'owner_id',p_owner,'account_id',p_account,'state','bound',
     'bound_at',to_char(at_time AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
     'cookieEffects',(SELECT coalesce(jsonb_agg(jsonb_build_object('kind','credential','action','expire','credentialId',c.credential_id)
      ORDER BY c.credential_id),'[]'::JSONB) FROM guest_credentials c
      WHERE c.owner_id=ANY(source_group) AND c.credential_id=ANY(p_proved_credentials)));
 ELSE result:=jsonb_build_object('state','participation_conflict','outcomeId',outcome_id); END IF;
 INSERT INTO guest_participation_operations(operation_id,source_owner_id,operation_kind,resource_scope,idempotency_key,request_hash,state,result_snapshot,created_at,resolved_at)
 VALUES(outcome_id,p_owner,'attachment_confirm',p_intent,p_key,p_hash,'completed',result,at_time,at_time);
 RETURN jsonb_build_object('state','completed','outcomeId',outcome_id,'operation',jsonb_build_object(
   'sourceOwnerId',p_owner,'kind','attachment_confirm','idempotencyKey',p_key,'requestHash',p_hash),'result',result);
END $$;

CREATE FUNCTION find_bound_guest_attachment_v1(p_account TEXT,p_attachment TEXT)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE a guest_owner_associations%ROWTYPE; original_owner TEXT;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 -- The real immutable intent supplies the source for original lock waiting even
 -- when successful confirm COMMIT has not yet become visible. Account proof
 -- never substitutes a new owner/intent or inferred no-commit classification.
 SELECT owner_id INTO original_owner FROM guest_attachment_intents WHERE intent_id=p_attachment;
 IF NOT FOUND THEN RETURN NULL; END IF;
 PERFORM lock_owner_participation_group_private_v1(original_owner);
 -- Fresh READ COMMITTED read AFTER complete original owner/account alias locks.
 SELECT * INTO a FROM guest_owner_associations WHERE intent_id=p_attachment AND state='bound';
 IF NOT FOUND THEN RETURN NULL; END IF;
 IF a.guest_owner_id IS DISTINCT FROM original_owner THEN
  RAISE EXCEPTION 'original attachment source differs' USING ERRCODE='GP003'; END IF;
 -- Actual current canonical caller may recover original A's binding. Both
 -- unresolved/inactive original and foreign caller remain definite denial.
 -- Conflict is dedup/history only, never access. No association is rewritten.
 IF account_owns_participation_source_v1(p_account,a.guest_owner_id) IS DISTINCT FROM TRUE THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('attachment_id',a.intent_id,'owner_id',a.guest_owner_id,'account_id',a.account_id,'state','bound',
   'bound_at',to_char(a.proved_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
END $$;

-- Source: owner-financial-consumer-successor-75faf734/recipient-claims.sql
CREATE FUNCTION complete_owner_credit_command_private_v1(
 p_source TEXT,p_kind TEXT,p_credit TEXT,p_key TEXT,p_hash TEXT,p_result JSONB
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE id TEXT; prior guest_participation_operations%ROWTYPE; at_time TIMESTAMPTZ:=clock_timestamp();
BEGIN
 SELECT * INTO prior FROM guest_participation_operations
 WHERE source_owner_id=p_source AND operation_kind=p_kind AND idempotency_key=p_key;
 IF FOUND THEN
   IF prior.resource_scope<>p_credit OR prior.request_hash<>p_hash OR prior.state<>'completed' THEN
     RAISE EXCEPTION 'idempotency-conflict' USING ERRCODE='GP005'; END IF;
   RETURN jsonb_build_object('state','completed','outcomeId',prior.operation_id,'operation',jsonb_build_object(
     'sourceOwnerId',prior.source_owner_id,'kind',prior.operation_kind,'idempotencyKey',prior.idempotency_key,'requestHash',prior.request_hash),'result',prior.result_snapshot);
 END IF;
 IF p_kind NOT IN('recipient_selection','owner_claim') OR p_key IS NULL OR length(p_key) NOT BETWEEN 1 AND 128
   OR p_hash IS NULL OR p_hash!~'^[0-9a-f]{64}$' THEN
   RAISE EXCEPTION 'invalid original credit operation' USING ERRCODE='22023'; END IF;
 id:='owner_credit_'||encode(sha256(convert_to(jsonb_build_array(p_source,p_kind,p_key)::TEXT,'UTF8')),'hex');
 INSERT INTO guest_participation_operations(operation_id,source_owner_id,operation_kind,resource_scope,
  idempotency_key,request_hash,state,result_snapshot,created_at,resolved_at)
 VALUES(id,p_source,p_kind,p_credit,p_key,p_hash,'completed',p_result,at_time,at_time);
 RETURN jsonb_build_object('state','completed','outcomeId',id,'operation',jsonb_build_object(
  'sourceOwnerId',p_source,'kind',p_kind,'idempotencyKey',p_key,'requestHash',p_hash),'result',p_result);
END $$;

CREATE FUNCTION select_owner_credit_recipient_v1(
 p_account TEXT,p_credit TEXT,p_persona TEXT,p_source TEXT,p_key TEXT,p_hash TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source JSONB; prior guest_participation_operations%ROWTYPE; revision BIGINT; at_time TIMESTAMPTZ;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 source:=read_owner_credit_lineage_private_v1(p_credit);
 PERFORM lock_owner_participation_group_private_v1(source->>'owner_id');
 IF source->>'owner_id' IS DISTINCT FROM p_source THEN RAISE EXCEPTION 'owner-mismatch' USING ERRCODE='GP002'; END IF;
 IF owner_credit_access_private_v1(p_credit,p_account) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'not-found' USING ERRCODE='GP009'; END IF;
 IF source->>'owner_kind'<>'guest' THEN RAISE EXCEPTION 'recipient-selection-conflict' USING ERRCODE='GP013'; END IF;
 -- Persona before credit/claim; lifecycle writers must take the same SHARED barrier.
 PERFORM 1 FROM personas WHERE persona_id=p_persona AND account_id=p_account FOR NO KEY UPDATE;
 PERFORM 1 FROM reward_ledger_credits WHERE credit_id=p_credit FOR NO KEY UPDATE;
 SELECT * INTO prior FROM guest_participation_operations WHERE source_owner_id=p_source
   AND operation_kind='recipient_selection' AND idempotency_key=p_key;
 IF FOUND THEN RETURN complete_owner_credit_command_private_v1(p_source,'recipient_selection',p_credit,p_key,p_hash,NULL); END IF;
 IF EXISTS(SELECT 1 FROM reward_credit_persona_bindings WHERE credit_id=p_credit)
   OR EXISTS(SELECT 1 FROM megapot_participant_claims WHERE credit_id=p_credit AND status='accepted')
   OR active_owned_community_persona(p_account,p_persona,source->>'community_id') IS DISTINCT FROM TRUE THEN
   RAISE EXCEPTION 'recipient-selection-conflict' USING ERRCODE='GP013'; END IF;
 SELECT coalesce(max(selection_revision),0)+1 INTO revision FROM reward_credit_recipient_selections WHERE credit_id=p_credit;
 IF revision>9007199254740991 THEN RAISE EXCEPTION 'recipient revision exhausted' USING ERRCODE='22023'; END IF;
 at_time:=clock_timestamp();
 INSERT INTO reward_credit_recipient_selections(credit_id,selection_revision,owner_id,account_id,persona_id,selected_at,association_account_id)
 VALUES(p_credit,revision,p_source,p_account,p_persona,at_time,(SELECT account_id FROM guest_owner_associations WHERE guest_owner_id=p_source AND state='bound'));
 RETURN complete_owner_credit_command_private_v1(p_source,'recipient_selection',p_credit,p_key,p_hash,
   project_owner_reward_credit_private_v1(p_credit));
END $$;

CREATE FUNCTION claim_owner_reward_credit_v1(
 p_account TEXT,p_credit TEXT,p_revision BIGINT,p_source TEXT,p_key TEXT,p_hash TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source JSONB; credit reward_ledger_credits%ROWTYPE; binding reward_credit_persona_bindings%ROWTYPE;
 selection reward_credit_recipient_selections%ROWTYPE; existing megapot_participant_claims%ROWTYPE;
 prior guest_participation_operations%ROWTYPE; evidence RECORD; guard_owner TEXT;
 persona TEXT; recipient_account TEXT; outcome TEXT; refusal TEXT; at_time TIMESTAMPTZ; locked_subject TEXT;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 source:=read_owner_credit_lineage_private_v1(p_credit);
 PERFORM lock_owner_participation_group_private_v1(source->>'owner_id');
 IF source->>'owner_id' IS DISTINCT FROM p_source THEN RAISE EXCEPTION 'owner-mismatch' USING ERRCODE='GP002'; END IF;
 IF owner_credit_access_private_v1(p_credit,p_account) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'not-found' USING ERRCODE='GP009'; END IF;
 IF source->>'owner_kind'='account' THEN
   IF p_revision IS NOT NULL THEN RAISE EXCEPTION 'recipient-selection-conflict' USING ERRCODE='GP013'; END IF;
   SELECT * INTO STRICT binding FROM reward_credit_persona_bindings WHERE credit_id=p_credit;
   persona:=binding.persona_id; recipient_account:=binding.account_id;
 ELSE
   SELECT * INTO selection FROM reward_credit_recipient_selections WHERE credit_id=p_credit ORDER BY selection_revision DESC LIMIT 1;
   persona:=selection.persona_id; recipient_account:=selection.account_id;
 END IF;
 -- Before acquiring credit/claim locks. No drawing/funding write on a claim.
 PERFORM 1 FROM personas WHERE persona_id=persona AND account_id=recipient_account FOR NO KEY UPDATE;
 SELECT * INTO STRICT credit FROM reward_ledger_credits WHERE credit_id=p_credit FOR NO KEY UPDATE;
 SELECT * INTO existing FROM megapot_participant_claims WHERE credit_id=p_credit FOR UPDATE;
 SELECT * INTO prior FROM guest_participation_operations WHERE source_owner_id=p_source AND operation_kind='owner_claim' AND idempotency_key=p_key;
 IF FOUND THEN RETURN complete_owner_credit_command_private_v1(p_source,'owner_claim',p_credit,p_key,p_hash,NULL); END IF;
 IF existing.status='accepted' THEN
   -- Exact accepted revision only; do not substitute a later candidate/persona.
   IF owner_credit_canonical_account_private_v1(existing.account_id) IS DISTINCT FROM p_account OR existing.owner_selection_revision IS DISTINCT FROM p_revision THEN
     RAISE EXCEPTION 'recipient-selection-conflict' USING ERRCODE='GP013'; END IF;
   RETURN complete_owner_credit_command_private_v1(p_source,'owner_claim',p_credit,p_key,p_hash,
     jsonb_build_object('outcome','accepted','credit',project_owner_reward_credit_private_v1(p_credit)));
 END IF;
 IF source->>'owner_kind'='guest' AND (p_revision IS NULL OR p_revision IS DISTINCT FROM selection.selection_revision
   OR selection.account_id IS DISTINCT FROM p_account OR selection.owner_id IS DISTINCT FROM p_source) THEN
   RAISE EXCEPTION 'recipient-selection-conflict' USING ERRCODE='GP013'; END IF;
 IF source->>'owner_kind'='account' AND (binding.owner_kind<>'account' OR binding.binding_source<>'account_original'
   OR binding.persona_id IS DISTINCT FROM source->>'original_persona_id' OR binding.account_id IS DISTINCT FROM source->>'original_account_id') THEN
   RAISE EXCEPTION 'original recipient lineage differs' USING ERRCODE='GP003'; END IF;
 IF credit.state<>'credited' OR credit.paid_atomic<>0 OR credit.reserved_atomic<>0
   OR active_owned_community_persona(recipient_account,persona,source->>'community_id') IS DISTINCT FROM TRUE
   OR owner_credit_canonical_account_private_v1(recipient_account) IS DISTINCT FROM p_account THEN outcome:='not_claimable';
 ELSE
   refusal:=owner_credit_very_refusal_private_v1(p_account);
   IF refusal IS NOT NULL THEN outcome:=refusal;
   ELSE
     SELECT * INTO STRICT evidence FROM reward_account_very_evidence_v1(p_account,NULL);
     locked_subject:=evidence.subject_key_id;
     PERFORM 1 FROM subject_keys WHERE subject_key_id=locked_subject FOR UPDATE;
     -- Re-evaluate after the subject lock, so a concurrent evidence revocation cannot
     -- turn a stale pre-wait projection into accepted authority.
     refusal:=owner_credit_very_refusal_private_v1(p_account);
     IF refusal IS NOT NULL THEN outcome:=refusal;
     ELSE
       SELECT * INTO STRICT evidence FROM reward_account_very_evidence_v1(p_account,NULL);
       IF evidence.subject_key_id IS DISTINCT FROM locked_subject THEN
         RAISE EXCEPTION 'verification evidence changed during claim' USING ERRCODE='GP003'; END IF;
       SELECT credit_id INTO guard_owner FROM megapot_participant_claim_guards
         WHERE pool_leg_id=source->>'pool_leg_id' AND drawing_id=(source->>'drawing_id')::NUMERIC AND subject_key_id=evidence.subject_key_id;
       at_time:=clock_timestamp();
       outcome:=CASE WHEN guard_owner IS NOT NULL AND guard_owner<>p_credit THEN 'subject_conflict' ELSE 'accepted' END;
       IF existing.credit_id IS NULL THEN
         INSERT INTO megapot_participant_claims(credit_id,account_id,pool_leg_id,drawing_id,status,subject_key_id,evidence_receipt_id,accepted_at,owner_selection_revision,owner_authenticated_account_id)
         VALUES(p_credit,p_account,source->>'pool_leg_id',(source->>'drawing_id')::NUMERIC,outcome,evidence.subject_key_id,
           CASE WHEN outcome='accepted' THEN evidence.evidence_receipt_id ELSE NULL END,
           CASE WHEN outcome='accepted' THEN at_time ELSE NULL END,p_revision,p_account);
       ELSE
         UPDATE megapot_participant_claims SET status=outcome,subject_key_id=evidence.subject_key_id,
           evidence_receipt_id=CASE WHEN outcome='accepted' THEN evidence.evidence_receipt_id ELSE NULL END,
           accepted_at=CASE WHEN outcome='accepted' THEN at_time ELSE NULL END,owner_selection_revision=p_revision,owner_authenticated_account_id=p_account,updated_at=at_time
           WHERE credit_id=p_credit;
       END IF;
       IF outcome='accepted' THEN
         IF guard_owner IS NULL THEN INSERT INTO megapot_participant_claim_guards(pool_leg_id,drawing_id,subject_key_id,credit_id,account_id,consumed_at)
           VALUES(source->>'pool_leg_id',(source->>'drawing_id')::NUMERIC,evidence.subject_key_id,p_credit,p_account,at_time); END IF;
         IF source->>'owner_kind'='guest' THEN INSERT INTO reward_credit_persona_bindings(credit_id,owner_id,owner_kind,account_id,persona_id,binding_source,selection_revision,bound_at,association_account_id)
           VALUES(p_credit,p_source,'guest',p_account,persona,'guest_claim',p_revision,at_time,(SELECT account_id FROM guest_owner_associations WHERE guest_owner_id=p_source AND state='bound')); END IF;
       END IF;
     END IF;
   END IF;
 END IF;
 RETURN complete_owner_credit_command_private_v1(p_source,'owner_claim',p_credit,p_key,p_hash,
   jsonb_build_object('outcome',outcome,'credit',project_owner_reward_credit_private_v1(p_credit)));
END $$;

CREATE FUNCTION operator_accept_owner_reward_credit_v1(
 p_credit TEXT,p_revision BIGINT,p_actor TEXT,p_reason TEXT,p_evidence TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source JSONB; existing megapot_participant_claims%ROWTYPE; current_selection reward_credit_recipient_selections%ROWTYPE;
 binding reward_credit_persona_bindings%ROWTYPE; persona TEXT; recipient_account TEXT; at_time TIMESTAMPTZ; credit_projection JSONB;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_actor IS NULL OR btrim(p_actor)='' OR octet_length(p_actor)>128
  OR p_reason IS NULL OR btrim(p_reason)='' OR octet_length(p_reason)>4096
  OR p_evidence IS NULL OR btrim(p_evidence)='' OR octet_length(p_evidence)>4096 THEN
   RAISE EXCEPTION 'audited operator decision required' USING ERRCODE='22023'; END IF;
 source:=read_owner_credit_lineage_private_v1(p_credit);
 PERFORM lock_owner_participation_group_private_v1(source->>'owner_id');
 SELECT * INTO STRICT existing FROM megapot_participant_claims WHERE credit_id=p_credit;
 IF source->>'owner_kind'='guest' THEN
   SELECT * INTO current_selection FROM reward_credit_recipient_selections WHERE credit_id=p_credit ORDER BY selection_revision DESC LIMIT 1;
   IF p_revision IS NULL OR current_selection.selection_revision IS DISTINCT FROM p_revision
     OR owner_credit_canonical_account_private_v1(current_selection.account_id) IS DISTINCT FROM owner_credit_canonical_account_private_v1(existing.account_id) THEN
     RAISE EXCEPTION 'recipient-selection-conflict' USING ERRCODE='GP013'; END IF;
   persona:=current_selection.persona_id; recipient_account:=current_selection.account_id;
 ELSE
   IF p_revision IS NOT NULL THEN RAISE EXCEPTION 'recipient-selection-conflict' USING ERRCODE='GP013'; END IF;
   SELECT * INTO STRICT binding FROM reward_credit_persona_bindings WHERE credit_id=p_credit;
   persona:=binding.persona_id; recipient_account:=binding.account_id;
 END IF;
 IF owner_credit_access_private_v1(p_credit,owner_credit_canonical_account_private_v1(existing.account_id)) IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'not-found' USING ERRCODE='GP009'; END IF;
 PERFORM 1 FROM personas WHERE persona_id=persona AND account_id=recipient_account FOR NO KEY UPDATE;
 PERFORM 1 FROM reward_ledger_credits WHERE credit_id=p_credit FOR NO KEY UPDATE;
 SELECT * INTO STRICT existing FROM megapot_participant_claims WHERE credit_id=p_credit FOR UPDATE;
 IF existing.status='accepted' THEN
   -- Only exact persisted original audit replays. No independent operator key/destination.
   IF ROW(existing.operator_actor_role,existing.operator_reason,existing.operator_evidence_reference,existing.owner_selection_revision)
     IS DISTINCT FROM ROW(p_actor,p_reason,p_evidence,p_revision) THEN
     RAISE EXCEPTION 'recipient-selection-conflict' USING ERRCODE='GP013'; END IF;
 ELSE
   IF existing.status<>'subject_conflict' OR active_owned_community_persona(recipient_account,persona,source->>'community_id') IS DISTINCT FROM TRUE
     OR NOT EXISTS(SELECT 1 FROM reward_ledger_credits WHERE credit_id=p_credit AND state='credited' AND reserved_atomic=0 AND paid_atomic=0) THEN
     RAISE EXCEPTION 'operator exception requires the recorded subject conflict' USING ERRCODE='GP013'; END IF;
   at_time:=clock_timestamp();
   UPDATE megapot_participant_claims SET status='accepted',operator_actor_role=p_actor,operator_reason=p_reason,
    operator_evidence_reference=p_evidence,operator_decided_at=at_time,accepted_at=at_time,updated_at=at_time,owner_selection_revision=p_revision,owner_authenticated_account_id=owner_credit_canonical_account_private_v1(recipient_account) WHERE credit_id=p_credit;
   IF source->>'owner_kind'='guest' THEN
     INSERT INTO reward_credit_persona_bindings(credit_id,owner_id,owner_kind,account_id,persona_id,binding_source,selection_revision,bound_at,association_account_id)
     VALUES(p_credit,source->>'owner_id','guest',recipient_account,persona,'guest_claim',p_revision,at_time,(SELECT account_id FROM guest_owner_associations WHERE guest_owner_id=source->>'owner_id' AND state='bound'));
   END IF;
 END IF;
 -- No new credit, no INSERT/DELETE of a subject guard. Natural original claim is the receipt.
 credit_projection:=project_owner_reward_credit_private_v1(p_credit);
 RETURN jsonb_build_object('state','completed','outcomeId','owner_operator_'||encode(sha256(convert_to(p_credit,'UTF8')),'hex'),
  'operation',jsonb_build_object('sourceOwnerId',source->>'owner_id','kind','owner_claim','idempotencyKey',p_credit,
    'requestHash',encode(sha256(convert_to(jsonb_build_array(p_credit,p_revision,p_actor,p_reason,p_evidence)::TEXT,'UTF8')),'hex')),
  'result',jsonb_build_object('outcome','accepted','credit',credit_projection));
END $$;

-- Source: owner-financial-consumer-successor-75faf734/evidence-guards.sql
CREATE FUNCTION reject_owner_recipient_evidence_change_private_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN RAISE EXCEPTION 'original owner accounting evidence is immutable' USING ERRCODE='GP003'; END $$;
CREATE TRIGGER owner_association_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON guest_owner_associations
 FOR EACH STATEMENT EXECUTE FUNCTION reject_owner_recipient_evidence_change_private_v1();
CREATE TRIGGER owner_conflict_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON guest_owner_association_conflicts
 FOR EACH STATEMENT EXECUTE FUNCTION reject_owner_recipient_evidence_change_private_v1();
CREATE TRIGGER owner_selection_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON reward_credit_recipient_selections
 FOR EACH STATEMENT EXECUTE FUNCTION reject_owner_recipient_evidence_change_private_v1();
CREATE TRIGGER owner_first_persona_immutable BEFORE UPDATE OR DELETE OR TRUNCATE ON reward_credit_persona_bindings
 FOR EACH STATEMENT EXECUTE FUNCTION reject_owner_recipient_evidence_change_private_v1();

CREATE FUNCTION validate_owner_first_persona_private_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source JSONB;
BEGIN
 source:=read_owner_credit_lineage_private_v1(NEW.credit_id);
 IF NEW.owner_id IS DISTINCT FROM source->>'owner_id' OR NEW.owner_kind IS DISTINCT FROM source->>'owner_kind' THEN
   RAISE EXCEPTION 'binding differs from original credit' USING ERRCODE='GP003'; END IF;
 IF NEW.owner_kind='account' THEN
   IF NEW.binding_source<>'account_original' OR NEW.selection_revision IS NOT NULL
    OR NEW.account_id IS DISTINCT FROM source->>'original_account_id' OR NEW.persona_id IS DISTINCT FROM source->>'original_persona_id' THEN
     RAISE EXCEPTION 'allocation must retain its original persona' USING ERRCODE='GP003'; END IF;
 ELSE
   IF NEW.binding_source<>'guest_claim' OR NOT EXISTS(SELECT 1 FROM megapot_participant_claims c
     JOIN reward_credit_recipient_selections s ON s.credit_id=c.credit_id AND s.selection_revision=c.owner_selection_revision
     WHERE c.credit_id=NEW.credit_id AND c.status='accepted' AND c.owner_authenticated_account_id=owner_credit_canonical_account_private_v1(NEW.account_id)
       AND s.selection_revision=NEW.selection_revision AND s.account_id=NEW.account_id AND s.persona_id=NEW.persona_id)
     OR NEW.selection_revision IS DISTINCT FROM(SELECT max(selection_revision) FROM reward_credit_recipient_selections WHERE credit_id=NEW.credit_id) THEN
     RAISE EXCEPTION 'successful claim must own its recorded current recipient' USING ERRCODE='GP003'; END IF;
 END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER owner_first_persona_lineage BEFORE INSERT ON reward_credit_persona_bindings
 FOR EACH ROW EXECUTE FUNCTION validate_owner_first_persona_private_v1();

CREATE FUNCTION validate_owner_claim_binding_private_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c reward_ledger_credits%ROWTYPE; claim megapot_participant_claims%ROWTYPE;
BEGIN
 SELECT * INTO STRICT c FROM reward_ledger_credits WHERE credit_id=NEW.credit_id;
 SELECT * INTO STRICT claim FROM megapot_participant_claims WHERE credit_id=NEW.credit_id;
 IF c.identity_version='owner_v1' AND claim.status='accepted' AND NOT EXISTS(
   SELECT 1 FROM reward_credit_persona_bindings b WHERE b.credit_id=c.credit_id
     AND b.owner_id=c.participation_owner_id
     AND owner_credit_canonical_account_private_v1(b.account_id) IS NOT DISTINCT FROM claim.owner_authenticated_account_id
     AND claim.owner_authenticated_account_id IS NOT NULL
     AND b.selection_revision IS NOT DISTINCT FROM claim.owner_selection_revision) THEN
   RAISE EXCEPTION 'claim acceptance requires the one immutable first binding' USING ERRCODE='GP003'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER owner_claim_binding_atomic AFTER INSERT OR UPDATE ON megapot_participant_claims
 DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION validate_owner_claim_binding_private_v1();

-- Source: owner-financial-consumer-successor-75faf734/credit-consumer-leaves.sql
-- Controlled bounded projection, staged permission contract only. It never changes
-- ledger account/persona fields. Original source and effective recipient remain distinct.
CREATE FUNCTION read_reward_credit_effect_identity_v1(p_credit TEXT)
RETURNS TABLE(effective_account_id TEXT,effective_persona_id TEXT,pinned_attestation_id TEXT,
 identity_version TEXT,original_owner_id TEXT,recipient_ready BOOLEAN)
LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c reward_ledger_credits%ROWTYPE; b reward_credit_persona_bindings%ROWTYPE;
 batch_id TEXT; original JSONB; receiver_account TEXT; receiver_persona TEXT; pin TEXT; ready BOOLEAN;
BEGIN
 SELECT * INTO c FROM reward_ledger_credits WHERE credit_id=p_credit;
 IF NOT FOUND THEN RETURN; END IF;
 IF c.identity_version='account_v1' THEN
  IF c.participation_owner_id IS NOT NULL OR c.account_id IS NULL OR c.payout_persona_id IS NULL THEN
   RAISE EXCEPTION 'closed original account identity required' USING ERRCODE='GP003'; END IF;
  receiver_account:=c.account_id;receiver_persona:=c.payout_persona_id;ready:=TRUE;
  -- Retained v2 source is exact. Prospective external fallback remains Account_v1
  -- and is validated against its frozen Account leaf, not an invented claim.
  SELECT allocation.allocation_batch_id INTO batch_id FROM megapot_owner_allocations allocation
   WHERE allocation.credit_id=c.credit_id;
  IF FOUND THEN
   PERFORM require_owner_megapot_allocation_private_v1(batch_id);
   SELECT leg.attestation_id INTO STRICT pin FROM megapot_owner_allocations allocation
    JOIN megapot_allocation_batches batch ON batch.allocation_batch_id=allocation.allocation_batch_id AND batch.beneficiary_version=3
    JOIN song_reward_offer_legs leg ON leg.leg_id=batch.pool_leg_id
    JOIN megapot_owner_snapshot_leaves leaf ON leaf.snapshot_id=allocation.snapshot_id AND leaf.ordinal=allocation.ordinal AND leaf.owner_id=allocation.owner_id
    WHERE allocation.credit_id=c.credit_id AND allocation.allocation_kind='external_fallback'
      AND c.source_kind='external_fallback' AND leaf.original_account_id=c.account_id AND leaf.original_persona_id=c.payout_persona_id AND allocation.amount_atomic=c.amount_atomic;
  ELSE
   SELECT leg.attestation_id INTO pin FROM megapot_allocations allocation
    JOIN megapot_allocation_batches batch ON batch.allocation_batch_id=allocation.allocation_batch_id AND batch.beneficiary_version=2
    JOIN song_reward_offer_legs leg ON leg.leg_id=batch.pool_leg_id
    WHERE allocation.credit_id=c.credit_id AND allocation.account_id=c.account_id AND allocation.persona_id=c.payout_persona_id
      AND allocation.amount_atomic=c.amount_atomic AND((allocation.allocation_kind='participant' AND c.source_kind='megapot_allocation') OR(allocation.allocation_kind='external_fallback' AND c.source_kind='external_fallback'));
   -- Asset bonus pinning remains in the existing caller/guard unchanged.
  END IF;
 ELSIF c.identity_version='owner_v1' THEN
  IF c.account_id IS NOT NULL OR c.payout_persona_id IS NOT NULL OR c.participation_owner_id IS NULL OR c.source_kind<>'megapot_allocation' THEN
   RAISE EXCEPTION 'closed original owner identity required' USING ERRCODE='GP003'; END IF;
  original:=read_owner_credit_lineage_private_v1(c.credit_id);
  SELECT allocation_batch_id INTO STRICT batch_id FROM megapot_owner_allocations WHERE credit_id=c.credit_id AND allocation_kind='participant';
  PERFORM require_owner_megapot_allocation_private_v1(batch_id);
  pin:=original->>'attestation_id';
  SELECT * INTO b FROM reward_credit_persona_bindings WHERE credit_id=c.credit_id;
  IF FOUND THEN
   receiver_account:=b.account_id;receiver_persona:=b.persona_id;
   ready:=EXISTS(SELECT 1 FROM megapot_participant_claims WHERE credit_id=c.credit_id AND status='accepted')
     AND active_owned_community_persona(b.account_id,b.persona_id,original->>'community_id')
     AND owner_credit_canonical_account_private_v1(b.account_id) IS NOT NULL;
  ELSE ready:=FALSE; END IF;
 ELSE RAISE EXCEPTION 'closed ledger identity required' USING ERRCODE='GP003'; END IF;
 RETURN QUERY SELECT receiver_account,receiver_persona,pin,c.identity_version,c.participation_owner_id,coalesce(ready,FALSE);
END $$;

CREATE FUNCTION account_owns_reward_credit_v1(p_account TEXT,p_credit TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c reward_ledger_credits%ROWTYPE;
BEGIN
 SELECT * INTO c FROM reward_ledger_credits WHERE credit_id=p_credit;
 IF NOT FOUND OR p_account IS NULL THEN RETURN FALSE; END IF;
 IF c.identity_version='account_v1' THEN RETURN c.account_id IS NOT DISTINCT FROM p_account; END IF;
 IF c.identity_version='owner_v1' THEN RETURN coalesce(owner_credit_access_private_v1(p_credit,p_account),FALSE); END IF;
 RETURN FALSE;
END $$;

CREATE FUNCTION lock_reward_credit_for_payout_v1(p_credit TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c reward_ledger_credits%ROWTYPE; source TEXT; recipient RECORD;
BEGIN
 -- FIRST, before every credit, chain nonce, assignment or effect lock in caller.
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 SELECT * INTO c FROM reward_ledger_credits WHERE credit_id=p_credit;
 IF NOT FOUND THEN RAISE EXCEPTION 'credit unavailable' USING ERRCODE='GP009'; END IF;
 IF c.identity_version='owner_v1' THEN
  PERFORM require_owner_accounting_ready_private_v1(); source:=c.participation_owner_id;
 ELSE SELECT owner_id INTO STRICT source FROM participation_owners WHERE kind='account' AND account_id=c.account_id; END IF;
 PERFORM lock_owner_participation_group_private_v1(source);
 SELECT * INTO STRICT recipient FROM read_reward_credit_effect_identity_v1(p_credit);
 IF recipient.effective_persona_id IS NOT NULL THEN
  PERFORM 1 FROM personas WHERE persona_id=recipient.effective_persona_id AND account_id=recipient.effective_account_id FOR NO KEY UPDATE;
 END IF;
END $$;

CREATE FUNCTION owner_credit_payable_v1(p_credit TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c reward_ledger_credits%ROWTYPE; i RECORD;
BEGIN
 SELECT * INTO c FROM reward_ledger_credits WHERE credit_id=p_credit;
 IF NOT FOUND THEN RETURN FALSE; END IF;
 IF c.identity_version='account_v1' THEN RETURN TRUE; END IF;
 SELECT * INTO STRICT i FROM read_reward_credit_effect_identity_v1(p_credit);
 RETURN i.recipient_ready IS TRUE AND EXISTS(SELECT 1 FROM persona_wallet_assignments
  WHERE account_id=i.effective_account_id AND persona_id=i.effective_persona_id AND chain_account_kind='evm' AND status='active' AND address IS NOT NULL);
END $$;

CREATE FUNCTION lock_account_persona_reward_identity_v1(p_account TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source TEXT;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 SELECT owner_id INTO STRICT source FROM participation_owners WHERE kind='account' AND account_id=p_account;
 PERFORM lock_owner_participation_group_private_v1(source);
END $$;

CREATE FUNCTION lock_reward_send_financial_source_v1(p_send TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE credit TEXT;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 SELECT credit_id INTO STRICT credit FROM reward_winner_sends WHERE send_id=p_send;
 PERFORM lock_reward_credit_for_payout_v1(credit);
END $$;

CREATE FUNCTION count_reward_gas_topups_for_account_v1(p_account TEXT,p_day DATE)
RETURNS INTEGER LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE canonical TEXT; result INTEGER;
BEGIN
 canonical:=owner_credit_canonical_account_private_v1(p_account);
 IF canonical IS NULL THEN RAISE EXCEPTION 'canonical gas budget authority unavailable' USING ERRCODE='GP003'; END IF;
 -- Quota history includes inactive historical source accounts. Authorization above
 -- remains active/canonical, while this pure group census cannot erase old usage.
 WITH RECURSIVE accounts(id) AS(SELECT canonical UNION SELECT next.id FROM accounts c CROSS JOIN LATERAL(
   SELECT a.source_user_id id FROM account_aliases a WHERE a.canonical_user_id=c.id
     AND((a.kind='alias' AND a.status='active') OR(a.kind='merge' AND a.status IN('finalizing','completed')))
   UNION SELECT a.canonical_user_id FROM account_aliases a WHERE a.source_user_id=c.id
     AND((a.kind='alias' AND a.status='active') OR(a.kind='merge' AND a.status IN('finalizing','completed')))
 ) next)
 SELECT count(*)::INTEGER INTO result FROM reward_gas_topups t
 WHERE t.budget_day=p_day AND t.status<>'released' AND t.account_id IN(SELECT id FROM accounts);
 RETURN result;
END $$;

-- Source: owner-financial-consumer-successor-75faf734/private-standing.sql
CREATE FUNCTION account_owns_participation_source_v1(p_account TEXT,p_owner TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE o participation_owners%ROWTYPE;
BEGIN
 IF p_account IS NULL OR owner_credit_canonical_account_private_v1(p_account) IS DISTINCT FROM p_account THEN RETURN FALSE; END IF;
 SELECT * INTO o FROM participation_owners WHERE owner_id=p_owner;
 IF NOT FOUND THEN RETURN FALSE; END IF;
 IF o.kind='account' THEN RETURN coalesce(owner_credit_canonical_account_private_v1(o.account_id)=p_account,FALSE); END IF;
 RETURN EXISTS(SELECT 1 FROM guest_owner_associations a WHERE a.guest_owner_id=o.owner_id AND a.state='bound'
  AND owner_credit_canonical_account_private_v1(a.account_id) IS NOT DISTINCT FROM p_account);
END $$;

CREATE FUNCTION read_account_megapot_standing_v1(p_account TEXT,p_leg TEXT)
RETURNS TABLE(leg_id TEXT,drawing_id NUMERIC,drawing_status TEXT,share_held BOOLEAN,allocation_amount_atomic NUMERIC,
 credit_id TEXT,credit_state TEXT,beneficiary_count INTEGER,fallback_beneficiary BOOLEAN,fallback_sponsor BOOLEAN)
LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
#variable_conflict use_column
DECLARE current_version SMALLINT;
BEGIN
 IF p_account IS NULL THEN RETURN; END IF;
 SELECT d.beneficiary_version INTO current_version FROM megapot_pool_drawings d WHERE d.pool_leg_id=p_leg ORDER BY d.drawing_id DESC LIMIT 1;
 IF current_version IS NULL OR current_version=2 THEN
  -- Exact original v2 query and original account/persona scope, no wrapper changes.
  RETURN QUERY
SELECT leg.leg_id, drawing.drawing_id, drawing.status AS drawing_status,
                          CASE
                            WHEN drawing.status='entry_open' THEN live_share.account_id IS NOT NULL
                            WHEN coalesce(drawing.fallback_beneficiary,false) THEN false
                            ELSE frozen_share.account_id IS NOT NULL
                          END AS share_held,
                          allocation.amount_atomic AS allocation_amount_atomic,
                          allocation.credit_id, credit.state AS credit_state,
                          CASE
                            WHEN drawing.drawing_id IS NULL THEN 0
                            WHEN drawing.status='entry_open' THEN share_count.value
                            WHEN drawing.fallback_beneficiary THEN 0
                            ELSE coalesce(drawing.frozen_share_count,0)
                          END AS beneficiary_count,
                          drawing.fallback_beneficiary,
                          (leg.empty_pool_policy='funder_fallback'
                            AND leg.funding_source='leg_budget'
                            AND leg.funder_account_id=$1) AS fallback_sponsor
                     FROM song_reward_offer_legs leg
                     JOIN song_reward_offers offer ON offer.offer_id=leg.offer_id
                     LEFT JOIN LATERAL (
                       SELECT candidate.* FROM megapot_pool_drawings candidate
                        WHERE candidate.pool_leg_id=leg.leg_id
                        ORDER BY candidate.drawing_id DESC LIMIT 1
                     ) drawing ON true
                     LEFT JOIN megapot_pool_shares live_share
                       ON live_share.pool_leg_id=leg.leg_id
                      AND live_share.drawing_id=drawing.drawing_id
                      AND live_share.account_id=$1
                     LEFT JOIN megapot_pool_snapshot_private_leaves frozen_share
                       ON frozen_share.snapshot_id=drawing.snapshot_id
                      AND frozen_share.account_id=$1
                     LEFT JOIN LATERAL (
                       SELECT count(*)::integer AS value FROM megapot_pool_shares candidate
                        WHERE candidate.pool_leg_id=leg.leg_id
                          AND candidate.drawing_id=drawing.drawing_id
                     ) share_count ON true
                     LEFT JOIN megapot_allocations allocation
                       ON allocation.allocation_batch_id=drawing.allocation_batch_id
                      AND allocation.account_id=$1
                     LEFT JOIN reward_ledger_credits credit
                       ON credit.credit_id=allocation.credit_id AND credit.account_id=$1
                    WHERE leg.leg_id=$2 AND leg.kind='megapot_pool'
                      AND (
                        leg.funder_account_id=$1
                        OR EXISTS (
                          SELECT 1 FROM community_memberships membership
                           WHERE membership.community_id=offer.community_id
                             AND membership.user_id=$1 AND membership.status='member'
                        )
                        OR EXISTS (
                          SELECT 1 FROM megapot_pool_shares historical_share
                           WHERE historical_share.pool_leg_id=leg.leg_id
                             AND historical_share.account_id=$1
                        )
                      );
  RETURN;
 END IF;
 IF current_version<>3 THEN RAISE EXCEPTION 'closed drawing version required' USING ERRCODE='GP003'; END IF;
 PERFORM require_owner_accounting_ready_private_v1();
 RETURN QUERY
 SELECT leg.leg_id,drawing.drawing_id,drawing.status,
  CASE WHEN drawing.status='entry_open' THEN EXISTS(SELECT 1 FROM megapot_owner_shares s
    WHERE s.pool_leg_id=leg.leg_id AND s.drawing_id=drawing.drawing_id AND account_owns_participation_source_v1(p_account,s.owner_id) IS TRUE)
   WHEN coalesce(drawing.fallback_beneficiary,FALSE) THEN FALSE
   ELSE EXISTS(SELECT 1 FROM megapot_owner_snapshot_leaves l WHERE l.snapshot_id=drawing.snapshot_id
      AND account_owns_participation_source_v1(p_account,l.owner_id) IS TRUE) END,
  owned.amount_atomic,owned.credit_id,c.state,
  CASE WHEN drawing.status='entry_open' THEN(SELECT count(*)::INTEGER FROM megapot_owner_shares s WHERE s.pool_leg_id=leg.leg_id AND s.drawing_id=drawing.drawing_id)
    WHEN drawing.fallback_beneficiary THEN 0 ELSE coalesce(drawing.frozen_share_count,0) END,
  drawing.fallback_beneficiary,
  (leg.empty_pool_policy='funder_fallback' AND leg.funding_source='leg_budget' AND owner_credit_canonical_account_private_v1(leg.funder_account_id) IS NOT DISTINCT FROM p_account)
 FROM song_reward_offer_legs leg JOIN song_reward_offers offer ON offer.offer_id=leg.offer_id
 JOIN LATERAL(SELECT d.* FROM megapot_pool_drawings d WHERE d.pool_leg_id=leg.leg_id ORDER BY d.drawing_id DESC LIMIT 1) drawing ON TRUE
 LEFT JOIN LATERAL(SELECT a.amount_atomic,a.credit_id FROM megapot_owner_allocations a WHERE a.allocation_batch_id=drawing.allocation_batch_id
   AND account_owns_participation_source_v1(p_account,a.owner_id) IS TRUE) owned ON TRUE
 LEFT JOIN reward_ledger_credits c ON c.credit_id=owned.credit_id
 WHERE leg.leg_id=p_leg AND leg.kind='megapot_pool' AND(owner_credit_canonical_account_private_v1(leg.funder_account_id) IS NOT DISTINCT FROM p_account
  OR EXISTS(SELECT 1 FROM community_memberships m WHERE m.community_id=offer.community_id AND m.user_id=p_account AND m.status='member')
  OR EXISTS(SELECT 1 FROM megapot_owner_shares s WHERE s.pool_leg_id=leg.leg_id AND account_owns_participation_source_v1(p_account,s.owner_id) IS TRUE));
END $$;

-- Source: owner-financial-consumer-successor-75faf734/owner-credit-discovery.sql
CREATE FUNCTION list_owned_reward_credits_v1(p_account TEXT,p_cursor TEXT,p_limit INTEGER)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE cursor_at TIMESTAMPTZ; result JSONB; next_id TEXT;
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_account IS NULL OR owner_credit_canonical_account_private_v1(p_account) IS DISTINCT FROM p_account
  OR p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN
   RAISE EXCEPTION 'ordinary canonical owner-credit reader required' USING ERRCODE='GP009'; END IF;
 IF p_cursor IS NOT NULL THEN
  SELECT c.created_at INTO cursor_at FROM reward_ledger_credits c WHERE c.credit_id=p_cursor AND c.identity_version='owner_v1'
    AND owner_credit_access_private_v1(c.credit_id,p_account) IS TRUE;
  IF NOT FOUND THEN RAISE EXCEPTION 'owned cursor required' USING ERRCODE='GP009'; END IF;
 END IF;
 WITH candidates AS MATERIALIZED(
  SELECT c.credit_id,c.created_at FROM reward_ledger_credits c
  WHERE c.identity_version='owner_v1' AND owner_credit_access_private_v1(c.credit_id,p_account) IS TRUE
    AND(p_cursor IS NULL OR(c.created_at,c.credit_id)<(cursor_at,p_cursor))
  ORDER BY c.created_at DESC,c.credit_id DESC LIMIT p_limit+1
 ), ranked AS(SELECT *,row_number() OVER(ORDER BY created_at DESC,credit_id DESC) ordinal FROM candidates)
 SELECT coalesce(jsonb_agg(project_owner_reward_credit_private_v1(credit_id) ORDER BY created_at DESC,credit_id DESC) FILTER(WHERE ordinal<=p_limit),'[]'::JSONB),
   CASE WHEN count(*)>p_limit THEN max(credit_id) FILTER(WHERE ordinal=p_limit) ELSE NULL END INTO result,next_id FROM ranked;
 RETURN jsonb_build_object('object','owner_reward_credit_list_v1','items',result,'next_cursor',next_id);
END $$;
CREATE FUNCTION get_owned_reward_credit_v1(p_account TEXT,p_credit TEXT)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_account IS NULL OR owner_credit_canonical_account_private_v1(p_account) IS DISTINCT FROM p_account
  THEN
   RAISE EXCEPTION 'owned credit required' USING ERRCODE='GP009'; END IF;
 IF NOT EXISTS(SELECT 1 FROM reward_ledger_credits WHERE credit_id=p_credit AND identity_version='owner_v1') THEN
   RAISE EXCEPTION 'owned credit required' USING ERRCODE='GP009'; END IF;
 IF owner_credit_access_private_v1(p_credit,p_account) IS DISTINCT FROM TRUE THEN
   RAISE EXCEPTION 'owned credit required' USING ERRCODE='GP009'; END IF;
 RETURN project_owner_reward_credit_private_v1(p_credit);
END $$;
CREATE INDEX owner_credit_private_page ON reward_ledger_credits(participation_owner_id,created_at DESC,credit_id DESC) WHERE identity_version='owner_v1';

-- Source: owner-financial-consumer-successor-75faf734/guard_reward_payout_effect.successor.sql
CREATE OR REPLACE FUNCTION guard_reward_payout_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  credit_record reward_ledger_credits%ROWTYPE;
  wallet_record persona_wallet_assignments%ROWTYPE;
  solvency_record custody_solvency_observations%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
  recipient RECORD;
  live_reserved_purchase NUMERIC(78, 0);
  live_outstanding_credit NUMERIC(78, 0);
  live_pending_refund NUMERIC(78, 0);
  live_shared_sponsorship NUMERIC(78, 0);
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'reward payout effects are append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.payout_effect_id FOR SHARE;
  SELECT * INTO credit_record FROM reward_ledger_credits
   WHERE credit_id = NEW.credit_id FOR SHARE;
  SELECT * INTO STRICT recipient FROM read_reward_credit_effect_identity_v1(NEW.credit_id);
  IF credit_record.identity_version='owner_v1' AND recipient.recipient_ready IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'owner participant payout requires its accepted immutable recipient' USING ERRCODE='GP003'; END IF;
  IF credit_record.source_kind<>'asset_bonus' AND recipient.pinned_attestation_id IS DISTINCT FROM NEW.attestation_id THEN
    RAISE EXCEPTION 'payout must retain its original pinned obligation attestation' USING ERRCODE='GP003'; END IF;
  SELECT * INTO wallet_record FROM persona_wallet_assignments
   WHERE assignment_id = NEW.wallet_assignment_id FOR SHARE;
  SELECT * INTO solvency_record FROM custody_solvency_observations
   WHERE observation_id = NEW.solvency_observation_id FOR SHARE;
  SELECT * INTO attestation_record FROM megapot_deployment_attestations
   WHERE attestation_id = NEW.attestation_id FOR SHARE;
  SELECT COALESCE(sum(reserved_atomic), 0) INTO live_reserved_purchase
    FROM song_reward_offer_legs WHERE kind='megapot_pool' AND funding_source='leg_budget'
      AND chain_id=credit_record.chain_id AND token_address=credit_record.token_address;
  SELECT COALESCE(sum(amount_atomic - paid_atomic), 0) INTO live_outstanding_credit
    FROM reward_ledger_credits WHERE state <> 'sent'
      AND chain_id=credit_record.chain_id AND token_address=credit_record.token_address;
  SELECT COALESCE(sum(funded_atomic - reserved_atomic - spent_atomic
      - fulfilled_atomic - refunded_atomic), 0) INTO live_pending_refund
    FROM song_reward_offer_legs
   WHERE (funding_source='leg_budget' OR kind='asset_bonus')
     AND chain_id=credit_record.chain_id AND token_address=credit_record.token_address;
  SELECT COALESCE(sum(funded_atomic + winnings_credited_atomic
      - spent_atomic - withdrawn_atomic), 0) INTO live_shared_sponsorship
    FROM platform_sponsorship_budgets
   WHERE chain_id=credit_record.chain_id AND token_address=credit_record.token_address;
  IF chain_record.effect_kind <> 'reward_payout'
     OR chain_record.reserved_amount_atomic <> NEW.amount_atomic
     OR chain_record.chain_id <> credit_record.chain_id
     OR chain_record.signer_address <> attestation_record.custody_address
     OR chain_record.target_address <> credit_record.token_address
     OR attestation_record.chain_id <> credit_record.chain_id
     OR recipient.effective_account_id IS DISTINCT FROM NEW.account_id
     OR recipient.effective_persona_id IS DISTINCT FROM NEW.payout_persona_id
     OR credit_record.amount_atomic - credit_record.paid_atomic < NEW.amount_atomic
     OR credit_record.state <> 'payout_reserved'
     OR credit_record.reserved_atomic <> NEW.amount_atomic
     OR wallet_record.account_id <> NEW.account_id
     OR wallet_record.persona_id <> NEW.payout_persona_id
     OR wallet_record.status <> 'active'
     OR wallet_record.address <> NEW.destination_address
     OR solvency_record.attestation_id <> NEW.attestation_id
     OR solvency_record.chain_id <> credit_record.chain_id
     OR solvency_record.custody_address <> chain_record.signer_address
     OR solvency_record.token_address <> credit_record.token_address
     OR solvency_record.expires_at <= clock_timestamp()
     OR NOT solvency_record.solvent
     OR solvency_record.balance_atomic <> NEW.custody_balance_before_atomic
     OR solvency_record.balance_atomic < live_reserved_purchase
       + live_outstanding_credit + live_pending_refund + live_shared_sponsorship THEN
    RAISE EXCEPTION 'reward payout does not match credit and active persona wallet';
  END IF;
  RETURN NEW;
END
$$;

-- Source: owner-financial-consumer-successor-75faf734/guard_reward_winner_send.successor.sql
CREATE OR REPLACE FUNCTION guard_reward_winner_send() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  outcome_row reward_winner_send_outcomes%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'reward winner sends are never deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'retryable' OR NEW.attempt <> 1 THEN
      RAISE EXCEPTION 'a reward winner send must begin retryable at attempt 1';
    END IF;
    -- Only the caller's own claimed, paid Megapot participant credit.
    IF NOT EXISTS (
      SELECT 1
        FROM reward_ledger_credits credit
        JOIN LATERAL read_reward_credit_effect_identity_v1(credit.credit_id) identity ON true
        JOIN megapot_participant_claims claim
          ON claim.credit_id = credit.credit_id AND claim.status = 'accepted'
       WHERE credit.credit_id = NEW.credit_id
         AND identity.effective_account_id = NEW.account_id
         AND identity.effective_persona_id = NEW.persona_id
         AND credit.source_kind = 'megapot_allocation'
         AND credit.state = 'sent'
         AND credit.chain_id = NEW.chain_id
         AND credit.token_address = NEW.token_address
    ) THEN
      RAISE EXCEPTION 'a reward winner send requires a claimed and paid participant credit';
    END IF;
    -- The sender is the wallet that received the credit's confirmed USDC payout.
    IF NOT EXISTS (
      SELECT 1
        FROM reward_payout_effects payout
        JOIN reward_chain_effects payout_effect
          ON payout_effect.effect_id = payout.payout_effect_id
         AND payout_effect.state = 'confirmed'
        JOIN reward_erc20_transfer_receipt_evidence evidence
          ON evidence.effect_id = payout.payout_effect_id
         AND evidence.transfer_purpose = 'reward_payout'
         AND evidence.recipient_address = payout.destination_address
       WHERE payout.credit_id = NEW.credit_id
         AND payout.account_id = NEW.account_id
         AND payout.payout_persona_id = NEW.persona_id
         AND payout.destination_address = NEW.sender_address
         AND payout.wallet_assignment_id = NEW.wallet_assignment_id
    ) THEN
      RAISE EXCEPTION 'a reward winner send must come from the confirmed payout wallet';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(
    NEW.send_id, NEW.credit_id, NEW.account_id, NEW.persona_id, NEW.wallet_assignment_id,
    NEW.chain_id, NEW.token_address, NEW.sender_address, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.send_id, OLD.credit_id, OLD.account_id, OLD.persona_id, OLD.wallet_assignment_id,
    OLD.chain_id, OLD.token_address, OLD.sender_address, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'reward winner send identity is immutable';
  END IF;
  IF OLD.status IN ('confirmed', 'cancelled') THEN
    RAISE EXCEPTION 'a confirmed or cancelled reward winner send is terminal';
  END IF;
  IF OLD.status = 'settled_unverified' THEN
    -- Only late-hash recovery: the same attempt, proven by a finalized receipt.
    IF NEW.status NOT IN ('confirmed', 'reverted', 'cancelled')
       OR NEW.attempt <> OLD.attempt OR NOT EXISTS (
      SELECT 1 FROM reward_winner_send_outcomes outcome
       WHERE outcome.send_id = NEW.send_id AND outcome.attempt = NEW.attempt
         AND outcome.outcome = NEW.status
    ) THEN
      RAISE EXCEPTION 'a settled_unverified reward winner send requires a proven outcome';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.attempt <> OLD.attempt THEN
    -- A new attempt only after the current one was mined and reverted at depth.
    SELECT * INTO outcome_row FROM reward_winner_send_outcomes
     WHERE send_id = OLD.send_id AND attempt = OLD.attempt AND outcome = 'reverted';
    IF NEW.attempt <> OLD.attempt + 1 OR OLD.status <> 'reverted'
       OR NEW.status <> 'retryable' OR outcome_row.outcome IS NULL THEN
      RAISE EXCEPTION 'a reward winner send may start a new attempt only after a revert';
    END IF;
    IF NOT EXISTS (
      SELECT 1 FROM reward_winner_send_attempts
       WHERE send_id = NEW.send_id AND attempt = NEW.attempt
    ) THEN
      RAISE EXCEPTION 'a reward winner send attempt must be recorded before it is current';
    END IF;
    RETURN NEW;
  END IF;
  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;
  IF OLD.status = 'reverted' THEN
    RAISE EXCEPTION 'a reverted reward winner send changes only by a new attempt';
  END IF;
  IF NEW.status IN ('retryable', 'pending') THEN
    RETURN NEW;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM reward_winner_send_outcomes outcome
     WHERE outcome.send_id = NEW.send_id AND outcome.attempt = NEW.attempt
       AND outcome.outcome = NEW.status
  ) THEN
    RAISE EXCEPTION 'a final reward winner send status requires its recorded outcome';
  END IF;
  RETURN NEW;
END
$$;

-- Source: owner-financial-consumer-successor-75faf734/guard_reward_gas_topup.successor.sql
CREATE OR REPLACE FUNCTION guard_reward_gas_topup() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  active_signer TEXT;
  recipient RECORD;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'reward gas top-ups are never deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'requested' OR NEW.effect_id IS NOT NULL THEN
      RAISE EXCEPTION 'a reward gas top-up must begin requested without an effect';
    END IF;
    SELECT * INTO STRICT recipient FROM read_reward_credit_effect_identity_v1(NEW.credit_id);
    IF recipient.effective_account_id IS DISTINCT FROM NEW.account_id OR recipient.effective_persona_id IS DISTINCT FROM NEW.persona_id THEN
      RAISE EXCEPTION 'gas must retain its original credit recipient' USING ERRCODE='GP003'; END IF;
    -- The recipient is the wallet that received the credit's confirmed USDC payout.
    IF NOT EXISTS (
      SELECT 1
        FROM reward_payout_effects payout
        JOIN reward_chain_effects payout_effect
          ON payout_effect.effect_id = payout.payout_effect_id
         AND payout_effect.state = 'confirmed'
        JOIN reward_erc20_transfer_receipt_evidence evidence
          ON evidence.effect_id = payout.payout_effect_id
         AND evidence.transfer_purpose = 'reward_payout'
       WHERE payout.credit_id = NEW.credit_id
         AND payout.account_id = NEW.account_id
         AND payout.payout_persona_id = NEW.persona_id
         AND payout.destination_address = NEW.recipient_address
         AND payout.wallet_assignment_id = NEW.wallet_assignment_id
         AND evidence.recipient_address = NEW.recipient_address
    ) THEN
      RAISE EXCEPTION 'a reward gas top-up must target the confirmed payout wallet';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(
    NEW.topup_id, NEW.account_id, NEW.persona_id, NEW.credit_id, NEW.wallet_assignment_id,
    NEW.recipient_address, NEW.chain_id, NEW.balance_before_wei, NEW.target_balance_wei,
    NEW.budget_day, NEW.idempotency_key, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.topup_id, OLD.account_id, OLD.persona_id, OLD.credit_id, OLD.wallet_assignment_id,
    OLD.recipient_address, OLD.chain_id, OLD.balance_before_wei, OLD.target_balance_wei,
    OLD.budget_day, OLD.idempotency_key, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'reward gas top-up identity is immutable';
  END IF;
  -- The amount may only shrink, and only before a chain effect exists.
  IF NEW.amount_wei <> OLD.amount_wei AND (
    NEW.amount_wei > OLD.amount_wei OR OLD.status <> 'requested' OR NEW.status <> 'requested'
    OR OLD.effect_id IS NOT NULL OR NEW.effect_id IS NOT NULL
  ) THEN
    RAISE EXCEPTION 'a reward gas top-up amount may only shrink before it is sent';
  END IF;
  IF OLD.effect_id IS NOT NULL AND NEW.effect_id IS DISTINCT FROM OLD.effect_id THEN
    RAISE EXCEPTION 'a reward gas top-up effect binding is immutable';
  END IF;
  IF OLD.status IN ('confirmed', 'released') THEN
    RAISE EXCEPTION 'a confirmed or released reward gas top-up is terminal';
  END IF;
  IF NOT (
    NEW.status = OLD.status
    OR (OLD.status = 'requested' AND NEW.status IN ('broadcast', 'released'))
    OR (OLD.status = 'broadcast' AND NEW.status IN ('confirmed', 'released'))
  ) THEN
    RAISE EXCEPTION 'invalid reward gas top-up transition';
  END IF;
  IF NEW.effect_id IS NOT NULL AND OLD.effect_id IS NULL THEN
    SELECT * INTO chain_record FROM reward_chain_effects WHERE effect_id = NEW.effect_id;
    SELECT wallet.signer_address INTO active_signer
      FROM reward_gas_topup_wallets wallet
     WHERE wallet.chain_id = NEW.chain_id AND wallet.status = 'active';
    IF chain_record.effect_id IS NULL
       OR chain_record.effect_kind <> 'gas_topup'
       OR chain_record.chain_id <> NEW.chain_id
       OR active_signer IS NULL
       OR chain_record.signer_address <> active_signer
       OR chain_record.target_address <> NEW.recipient_address
       OR chain_record.value_wei <> NEW.amount_wei
       OR chain_record.reserved_amount_atomic <> 0 THEN
      RAISE EXCEPTION 'reward gas top-up effect does not match the top-up';
    END IF;
  END IF;
  IF NEW.status <> OLD.status AND NEW.effect_id IS NOT NULL THEN
    SELECT * INTO chain_record FROM reward_chain_effects WHERE effect_id = NEW.effect_id;
    IF (NEW.status = 'broadcast' AND chain_record.transaction_hash IS NULL)
       OR (NEW.status = 'confirmed' AND chain_record.state <> 'confirmed')
       OR (NEW.status = 'released' AND chain_record.state NOT IN ('reverted', 'terminal_failed',
         'reclaimable_failed')) THEN
      RAISE EXCEPTION 'reward gas top-up status disagrees with its chain effect';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

-- Source: owner-financial-authenticated-actor-successor-74039403/new-spend-authority.sql
-- Private NEW-spend proof after the caller has acquired original source/group
-- locks. No late topology/owner/business locks, DML, provider or clock sampling.
CREATE FUNCTION require_reward_credit_new_spend_authority_v1(
 p_actor TEXT,p_credit TEXT,p_account TEXT,p_persona TEXT,p_assignment TEXT,p_address TEXT
) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE c reward_ledger_credits%ROWTYPE; i RECORD;
BEGIN
 IF p_actor IS NULL OR owner_credit_canonical_account_private_v1(p_actor) IS DISTINCT FROM p_actor
  OR account_owns_reward_credit_v1(p_actor,p_credit) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'current financial authority unavailable' USING ERRCODE='GP009'; END IF;
 SELECT * INTO STRICT c FROM reward_ledger_credits WHERE credit_id=p_credit;
 SELECT * INTO STRICT i FROM read_reward_credit_effect_identity_v1(p_credit);
 IF c.source_kind IS DISTINCT FROM 'megapot_allocation' OR c.state IS DISTINCT FROM 'sent'
  OR c.amount_atomic IS DISTINCT FROM c.paid_atomic OR c.reserved_atomic<>0
  OR i.effective_account_id IS DISTINCT FROM p_account OR i.effective_persona_id IS DISTINCT FROM p_persona
  OR (c.identity_version='owner_v1' AND i.recipient_ready IS DISTINCT FROM TRUE)
  OR NOT EXISTS(SELECT 1 FROM megapot_participant_claims WHERE credit_id=p_credit AND status='accepted')
  OR NOT EXISTS(SELECT 1 FROM reward_payout_effects payout
    JOIN reward_chain_effects effect ON effect.effect_id=payout.payout_effect_id AND effect.state='confirmed'
    JOIN reward_erc20_transfer_receipt_evidence receipt ON receipt.effect_id=payout.payout_effect_id
      AND receipt.transfer_purpose='reward_payout' AND receipt.recipient_address=payout.destination_address
      AND receipt.amount_atomic=payout.amount_atomic
    WHERE payout.credit_id=p_credit AND payout.account_id=p_account AND payout.payout_persona_id=p_persona
      AND payout.wallet_assignment_id=p_assignment AND payout.destination_address=p_address)
 THEN RAISE EXCEPTION 'original paid recipient unavailable for a new spend' USING ERRCODE='GP009'; END IF;
END $$;
CREATE FUNCTION require_reward_send_new_spend_authority_v1(p_actor TEXT,p_send TEXT)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE s reward_winner_sends%ROWTYPE;
BEGIN
 SELECT * INTO STRICT s FROM reward_winner_sends WHERE send_id=p_send;
 PERFORM require_reward_credit_new_spend_authority_v1(p_actor,s.credit_id,s.account_id,s.persona_id,s.wallet_assignment_id,s.sender_address);
END $$;

-- Source: owner-megapot-jobs-integration-proposal-v2/zero-allocation-due-private.sql
-- Include in Root's ONE full successor, not a separate ordinal/activation.
CREATE FUNCTION list_owner_zero_allocation_due_private_v1(p_limit INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE result JSONB;
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 500
 THEN RAISE EXCEPTION 'bounded original zero allocation list required' USING ERRCODE='GP003'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('poolLegId',pool_leg_id,'drawingId',drawing_id::TEXT)
  ORDER BY updated_at,convert_to(pool_leg_id,'UTF8'),drawing_id),'[]'::JSONB) INTO result
 FROM (SELECT d.pool_leg_id,d.drawing_id,d.updated_at FROM megapot_pool_drawings d
  JOIN song_reward_offer_legs leg ON leg.leg_id=d.pool_leg_id
  WHERE d.beneficiary_version=3 AND d.net_winnings_atomic=0 AND d.status IN('no_win','winnings_detected')
   AND d.claim_effect_id IS NULL AND d.snapshot_id IS NOT NULL
   AND NOT EXISTS(SELECT 1 FROM megapot_allocation_batches b WHERE b.pool_leg_id=d.pool_leg_id AND b.drawing_id=d.drawing_id)
   AND NOT EXISTS(SELECT 1 FROM megapot_claim_effects c WHERE c.pool_leg_id=d.pool_leg_id AND c.drawing_id=d.drawing_id)
   AND EXISTS(SELECT 1 FROM megapot_drawing_sweeps sw JOIN megapot_sweep_ticket_evidence ev USING(sweep_id)
    JOIN megapot_ticket_inventory t ON t.attestation_id=ev.attestation_id AND t.ticket_id=ev.ticket_id
    WHERE sw.pool_leg_id=d.pool_leg_id AND sw.drawing_id=d.drawing_id AND sw.attestation_id=leg.attestation_id
     AND sw.state='complete' AND sw.completed_at IS NOT NULL AND sw.ticket_count=1
     AND ev.attestation_id=sw.attestation_id AND ev.ticket_id=d.ticket_id AND t.pool_leg_id=d.pool_leg_id AND t.drawing_id=d.drawing_id
     AND ev.net_winnings_atomic=0 AND ev.gross_winnings_atomic=ev.referral_accrual_atomic
     AND ev.gross_winnings_atomic=d.gross_winnings_atomic
     AND ((d.status='no_win' AND sw.winning_ticket_count=0 AND ev.tier_id IN(0,2) AND t.status='no_win')
      OR (d.status='winnings_detected' AND sw.winning_ticket_count=1 AND ev.tier_id NOT IN(0,2) AND t.status='custodied')))
  ORDER BY d.updated_at,convert_to(d.pool_leg_id,'UTF8'),d.drawing_id LIMIT p_limit) due;
 RETURN result;
END $$;
DO $bind_zero_allocation_due$
DECLARE ns OID; owner OID; schema_name TEXT; proc OID; role_name TEXT;
BEGIN
 SELECT c.relnamespace,c.relowner,n.nspname INTO STRICT ns,owner,schema_name FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid='participation_owners'::regclass;
 SELECT p.oid INTO STRICT proc FROM pg_proc p WHERE p.oid=to_regprocedure(format('%I.list_owner_zero_allocation_due_private_v1(integer)',schema_name)) AND p.pronamespace=ns AND p.proowner=owner;
 EXECUTE format('ALTER FUNCTION %I.list_owner_zero_allocation_due_private_v1(integer) SECURITY DEFINER',schema_name);
 EXECUTE format('ALTER FUNCTION %I.list_owner_zero_allocation_due_private_v1(integer) SET search_path TO pg_catalog,%I,pg_temp',schema_name,schema_name);
 EXECUTE format('REVOKE ALL ON FUNCTION %I.list_owner_zero_allocation_due_private_v1(integer) FROM PUBLIC',schema_name);
 FOR role_name IN SELECT r.rolname FROM aclexplode(COALESCE((SELECT proacl FROM pg_proc WHERE oid=proc),acldefault('f',owner))) a JOIN pg_roles r ON r.oid=a.grantee WHERE a.grantee<>owner LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %I.list_owner_zero_allocation_due_private_v1(integer) FROM %I',schema_name,role_name);
 END LOOP;
END $bind_zero_allocation_due$;

-- Source: retained-megapot-clock-window-proposal-0761d789/guard_megapot_pool_share.successor.sql
CREATE OR REPLACE FUNCTION guard_megapot_pool_share() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  drawing_record megapot_pool_drawings%ROWTYPE;
  leg_record song_reward_offer_legs%ROWTYPE;
  offer_record song_reward_offers%ROWTYPE;
  qualification_record activity_qualifications%ROWTYPE;
  eligibility_record reward_eligibility_decisions%ROWTYPE;
  sampled_at TIMESTAMPTZ;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot pool shares are append-only';
  END IF;
  SELECT * INTO drawing_record FROM megapot_pool_drawings
   WHERE pool_leg_id = NEW.pool_leg_id AND drawing_id = NEW.drawing_id FOR UPDATE;
  SELECT * INTO leg_record FROM song_reward_offer_legs
   WHERE leg_id = NEW.pool_leg_id FOR SHARE;
  SELECT * INTO offer_record FROM song_reward_offers
   WHERE offer_id = leg_record.offer_id FOR SHARE;
  SELECT * INTO qualification_record FROM activity_qualifications
   WHERE qualification_id = NEW.qualification_id FOR SHARE;
  SELECT * INTO eligibility_record FROM reward_eligibility_decisions
   WHERE eligibility_decision_id = NEW.eligibility_decision_id FOR SHARE;
  sampled_at := clock_timestamp();
  IF drawing_record.beneficiary_version <> 2
     OR drawing_record.status <> 'entry_open'
     OR qualification_record.account_id <> NEW.account_id
     OR qualification_record.persona_id <> NEW.persona_id
     OR qualification_record.community_id <> offer_record.community_id
     OR qualification_record.post_id <> offer_record.post_id
     OR qualification_record.audio_revision <> offer_record.audio_revision
     OR NOT qualification_record.activity_key = ANY(leg_record.eligible_activities)
     OR qualification_record.score_bps < leg_record.min_score_bps
     OR qualification_record.qualified_at >= drawing_record.entry_cutoff_at
     OR qualification_record.qualified_at < leg_record.participation_starts_at
     OR NEW.qualified_at <> qualification_record.qualified_at
     OR eligibility_record.leg_id <> NEW.pool_leg_id
     OR eligibility_record.account_id <> NEW.account_id
     OR eligibility_record.persona_id <> NEW.persona_id
     OR eligibility_record.purpose <> 'pool_share'
     OR eligibility_record.qualification_id <> NEW.qualification_id
     OR eligibility_record.drawing_id <> NEW.drawing_id
     OR eligibility_record.outcome <> 'eligible' THEN
    RAISE EXCEPTION 'Megapot pool share is not exact eligible qualification output';
  END IF;
  -- Source/identity failures above never become a cutoff continuation.
  IF sampled_at >= drawing_record.entry_cutoff_at
     AND eligibility_record.expires_at >= drawing_record.entry_cutoff_at THEN
    RAISE EXCEPTION 'original entry cutoff passed after locks' USING ERRCODE='RM001';
  END IF;
  IF eligibility_record.expires_at <= sampled_at THEN
    RAISE EXCEPTION 'Megapot pool share eligibility expired';
  END IF;
  IF clock_timestamp() >= drawing_record.entry_cutoff_at THEN
    RAISE EXCEPTION 'original entry cutoff passed before insertion' USING ERRCODE='RM001';
  END IF;
  RETURN NEW;
END
$$;

-- Source: retained-megapot-clock-window-proposal-0761d789/original-purchase-window-private.sql
-- Complete reviewed financial successor only; no ordinal or runtime grants.
-- Caller owns shared topology then exact drawing/leg locks before this read.
-- READ COMMITTED supplies a fresh statement after those lock waits.
CREATE FUNCTION read_megapot_purchase_window_after_draw_private_v1(p_leg TEXT,p_draw NUMERIC,
 p_observation TEXT,p_snapshot TEXT,p_commitment TEXT,p_margin INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE d megapot_pool_drawings%ROWTYPE; observation megapot_drawing_observations%ROWTYPE;
 captured_deadline TIMESTAMPTZ; deadline TIMESTAMPTZ; sampled_at TIMESTAMPTZ;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_leg IS NULL OR p_draw IS NULL OR p_draw<0 OR trunc(p_draw)<>p_draw
  OR p_observation IS NULL OR p_snapshot IS NULL OR p_commitment IS NULL OR p_margin IS NULL OR p_margin<1
 THEN RAISE EXCEPTION 'exact original purchase window and trusted margin required' USING ERRCODE='22023'; END IF;
 PERFORM require_megapot_drawing_admission_resolved_v1(p_leg,p_draw);
 SELECT * INTO STRICT d FROM megapot_pool_drawings WHERE pool_leg_id=p_leg AND drawing_id=p_draw;
 IF d.status NOT IN('committed','purchase_pending') OR d.beneficiary_version NOT IN(2,3)
  OR d.observation_id IS DISTINCT FROM p_observation OR d.snapshot_id IS DISTINCT FROM p_snapshot
  OR d.commitment_effect_id IS DISTINCT FROM p_commitment
 THEN RAISE EXCEPTION 'original purchase capture changed' USING ERRCODE='GP005'; END IF;
 SELECT * INTO STRICT observation FROM megapot_drawing_observations WHERE observation_id=d.observation_id;
 IF observation.drawing_id IS DISTINCT FROM d.drawing_id
 THEN RAISE EXCEPTION 'original observed drawing changed' USING ERRCODE='GP005'; END IF;
 -- Every immutable original capture counts, including resolved/no-entry records.
 -- A newer policy or later source never selects around an earlier deadline.
 SELECT min(original_deadline) INTO captured_deadline FROM (
  SELECT purchase_safety_deadline_at AS original_deadline FROM owner_participation_admission_operations
   WHERE pool_leg_id=p_leg AND drawing_id=p_draw
  UNION ALL
  SELECT purchase_safety_deadline_at FROM account_owner_reward_sources
   WHERE original_terms->>'pool_leg_id'=p_leg AND original_terms->>'original_drawing_id'=trunc(p_draw)::TEXT
  UNION ALL
  SELECT guest_reward_purchase_safety_deadline_at FROM study_sessions_v2
   WHERE guest_reward_mode='megapot_guest_v1' AND guest_reward_terms->>'pool_leg_id'=p_leg
    AND guest_reward_terms->>'original_drawing_id'=trunc(p_draw)::TEXT
 ) originals;
 deadline:=observation.drawing_time-make_interval(secs=>p_margin);
 IF captured_deadline IS NOT NULL THEN deadline:=least(deadline,captured_deadline); END IF;
 sampled_at:=clock_timestamp();
 RETURN jsonb_build_object('checkedAt',sampled_at,'deadlineAt',deadline,'open',sampled_at<deadline);
END $$;

-- Private owning read used before new signatures/sends. No locks are acquired by
-- the after-draw projector above, so it is also safe within an owning transaction.
CREATE FUNCTION read_megapot_original_purchase_window_v1(p_leg TEXT,p_draw NUMERIC,
 p_observation TEXT,p_snapshot TEXT,p_commitment TEXT,p_margin INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM 1 FROM megapot_pool_drawings drawing JOIN song_reward_offer_legs leg ON leg.leg_id=drawing.pool_leg_id
  WHERE drawing.pool_leg_id=p_leg AND drawing.drawing_id=p_draw FOR UPDATE OF drawing,leg;
 IF NOT FOUND THEN RAISE EXCEPTION 'original drawing required' USING ERRCODE='GP005'; END IF;
 RETURN read_megapot_purchase_window_after_draw_private_v1(p_leg,p_draw,p_observation,p_snapshot,p_commitment,p_margin);
END $$;

-- Only the exact retained drawing can be locked by this controlled cutoff leaf.
-- It is not a generic topology/owner/grant primitive and emits no financial rows.
CREATE FUNCTION lock_megapot_retained_cutoff_v1(p_leg TEXT,p_draw NUMERIC)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 PERFORM 1 FROM megapot_pool_drawings drawing JOIN song_reward_offer_legs leg ON leg.leg_id=drawing.pool_leg_id
  WHERE drawing.pool_leg_id=p_leg AND drawing.drawing_id=p_draw AND drawing.beneficiary_version=2
   AND drawing.status='entry_open' FOR UPDATE OF drawing,leg;
 IF NOT FOUND THEN RAISE EXCEPTION 'exact retained cutoff drawing unavailable' USING ERRCODE='GP005'; END IF;
 PERFORM require_megapot_drawing_admission_resolved_v1(p_leg,p_draw);
END $$;

-- Source: retained-megapot-clock-window-proposal-0761d789/bind-clock-window-functions.sql
-- Last in Root's ONE complete financial successor, not a standalone migration.
-- Only Root's reviewed Jobs admission grants the two exact controlled leaves.
DO $bind_megapot_clock_window$
DECLARE ns OID; owner OID; schema_name TEXT; signature TEXT; role_name TEXT; proc OID;
BEGIN
 SELECT c.relnamespace,c.relowner,n.nspname INTO STRICT ns,owner,schema_name FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid='participation_owners'::regclass;
 FOREACH signature IN ARRAY ARRAY['read_megapot_purchase_window_after_draw_private_v1(text,numeric,text,text,text,integer)','read_megapot_original_purchase_window_v1(text,numeric,text,text,text,integer)','lock_megapot_retained_cutoff_v1(text,numeric)','guard_megapot_pool_share()','project_megapot_pool_share_from_qualification()'] LOOP
  SELECT p.oid INTO STRICT proc FROM pg_proc p WHERE p.oid=to_regprocedure(format('%I.%s',schema_name,signature)) AND p.pronamespace=ns AND p.proowner=owner;
  EXECUTE format('ALTER FUNCTION %I.%s SECURITY DEFINER',schema_name,signature);
  EXECUTE format('ALTER FUNCTION %I.%s SET search_path TO pg_catalog,%I,pg_temp',schema_name,signature,schema_name);
  EXECUTE format('REVOKE ALL ON FUNCTION %I.%s FROM PUBLIC',schema_name,signature);
  FOR role_name IN SELECT r.rolname FROM aclexplode(COALESCE((SELECT proacl FROM pg_proc WHERE oid=proc),acldefault('f',owner))) a JOIN pg_roles r ON r.oid=a.grantee WHERE a.grantee<>owner LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %I.%s FROM %I',schema_name,signature,role_name);
  END LOOP;
 END LOOP;
END $bind_megapot_clock_window$;

-- Source: owner-participation-recovery-proposal-v2/original-participation-readers.sql
-- Root-only additive native/119 source. No new ID, share, allocation or proof.
-- One actual journal is one original financial participation locator; completed
-- not_yet_qualified lesson outcomes cannot be relabelled as ineligible shares.
CREATE FUNCTION owner_participation_is_projectable_private_v1(p_state TEXT,p_snapshot JSONB)
RETURNS BOOLEAN LANGUAGE sql IMMUTABLE SECURITY DEFINER AS $$
 SELECT coalesce(p_state='pending' OR (p_state IN('admitted','not_admitted','reconciled_no_commit')
  AND p_snapshot->>'state' IN('admitted','already_participating','entry_closed','unavailable','ineligible')),FALSE)
$$;
CREATE FUNCTION project_original_owner_participation_private_v1(p_id TEXT)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE original owner_participation_admission_operations%ROWTYPE; drawing megapot_pool_drawings%ROWTYPE;
 allocation megapot_owner_allocations%ROWTYPE; batch megapot_allocation_batches%ROWTYPE;
 admission TEXT; purchase TEXT:='not_requested'; reconciliation TEXT:='resolved';
 allocated_id TEXT; credit_id_value TEXT; amount_value TEXT; sampled_at TIMESTAMPTZ:=statement_timestamp();
BEGIN
 SELECT * INTO original FROM owner_participation_admission_operations WHERE admission_id=p_id;
 IF NOT FOUND OR owner_participation_is_projectable_private_v1(original.state,original.result_snapshot) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'original participation unavailable' USING ERRCODE='GP009'; END IF;
 SELECT * INTO drawing FROM megapot_pool_drawings WHERE pool_leg_id=original.pool_leg_id AND drawing_id=original.drawing_id;
 IF NOT FOUND OR drawing.beneficiary_version<>3 OR original.beneficiary_version<>3 OR original.purchase_safety_deadline_at IS NULL THEN
  RAISE EXCEPTION 'original participation source differs' USING ERRCODE='GP003'; END IF;
 IF original.state='pending' THEN
  IF original.result_snapshot IS NOT NULL OR original.resolved_at IS NOT NULL THEN
   RAISE EXCEPTION 'pending admission receipt differs' USING ERRCODE='GP003'; END IF;
  admission:='pending_confirmation'; purchase:='held_unresolved_admission'; reconciliation:='pending';
 ELSE
  admission:=original.result_snapshot->>'state';
  IF original.resolved_at IS NULL OR jsonb_typeof(original.result_snapshot) IS DISTINCT FROM 'object'
    OR admission NOT IN('admitted','already_participating','entry_closed','unavailable','ineligible') THEN
   RAISE EXCEPTION 'original resolved admission receipt differs' USING ERRCODE='GP003'; END IF;
  IF admission='admitted' THEN
   IF original.state IS DISTINCT FROM 'admitted'
    OR original.result_snapshot IS DISTINCT FROM jsonb_build_object('state','admitted','share_id',original.admission_id,
      'original_drawing_id',original.drawing_id::TEXT,'pool_leg_id',original.pool_leg_id)
    OR NOT EXISTS(SELECT 1 FROM megapot_owner_shares s JOIN activity_qualifications q ON q.qualification_id=s.qualification_id
      WHERE s.pool_leg_id=original.pool_leg_id AND s.drawing_id=original.drawing_id AND s.owner_id=original.source_owner_id
       AND s.qualification_id=original.qualification_id AND s.leaf_salt=original.leaf_salt
       AND q.participation_owner_id=original.source_owner_id AND q.participation_owner_kind=original.source_owner_kind
       AND ((original.source_owner_kind='guest' AND q.guest_main_operation_id=original.main_operation_id)
        OR(original.source_owner_kind='account' AND q.account_main_operation_id=original.main_operation_id))) THEN
    RAISE EXCEPTION 'admitted original share/qualification differs' USING ERRCODE='GP003'; END IF;
   -- Confirm only the original persisted receipt/effect/ticket lineage. A clock,
   -- current drawing or absent effect never establishes purchase confirmation.
   IF drawing.purchase_effect_id IS NOT NULL AND EXISTS(
    SELECT 1 FROM megapot_ticket_purchase_effects p JOIN reward_chain_effects e ON e.effect_id=p.purchase_effect_id
     JOIN megapot_purchase_receipt_evidence receipt USING(purchase_effect_id)
     JOIN megapot_ticket_inventory ticket ON ticket.attestation_id=receipt.attestation_id AND ticket.ticket_id=receipt.ticket_id
     JOIN song_reward_offer_legs leg ON leg.leg_id=p.pool_leg_id
    WHERE p.purchase_effect_id=drawing.purchase_effect_id AND p.pool_leg_id=original.pool_leg_id AND p.drawing_id=original.drawing_id
     AND p.snapshot_id=drawing.snapshot_id AND e.effect_kind='ticket_purchase' AND e.state='confirmed' AND e.receipt_status='success'
     AND receipt.transaction_hash=e.transaction_hash AND receipt.receipt_hash=e.receipt_hash
     AND receipt.block_number=e.receipt_block_number AND receipt.block_hash=e.receipt_block_hash
     AND receipt.attestation_id=p.attestation_id AND receipt.attestation_id=leg.attestation_id AND e.chain_id=leg.chain_id
     AND receipt.ticket_id=drawing.ticket_id AND ticket.purchase_effect_id=p.purchase_effect_id
     AND ticket.pool_leg_id=original.pool_leg_id AND ticket.drawing_id=original.drawing_id
   ) THEN
    PERFORM require_owner_megapot_snapshot_private_v1(drawing.snapshot_id);
    purchase:='confirmed';
   ELSIF drawing.purchase_effect_id IS NOT NULL THEN
    IF NOT EXISTS(SELECT 1 FROM megapot_ticket_purchase_effects p JOIN reward_chain_effects e ON e.effect_id=p.purchase_effect_id
      WHERE p.purchase_effect_id=drawing.purchase_effect_id AND p.pool_leg_id=original.pool_leg_id AND p.drawing_id=original.drawing_id
       AND p.snapshot_id=drawing.snapshot_id AND e.effect_kind='ticket_purchase') THEN
     RAISE EXCEPTION 'original purchase lineage unavailable' USING ERRCODE='GP003'; END IF;
    -- Failure without a proved no-commit/custody resolution is pending, not zero.
    purchase:='pending';
   ELSIF drawing.status IN('closed_no_entries','closed_unfunded','closed_fallback_ineligible','closed_fallback_unavailable','closed_fallback_ceiling') THEN
    purchase:='unavailable';
   ELSIF drawing.status='operational_hold' THEN purchase:='pending';
   ELSIF drawing.status NOT IN('entry_open','cutoff_frozen','committed') THEN
    RAISE EXCEPTION 'recorded purchase state lacks original evidence' USING ERRCODE='GP003'; END IF;
   -- Use the original batch table, including genuine zero sweep allocation.
   -- Zero batches are not guaranteed to be stored in drawing.allocation_batch_id.
   SELECT * INTO batch FROM megapot_allocation_batches b WHERE b.pool_leg_id=original.pool_leg_id
    AND b.drawing_id=original.drawing_id AND b.beneficiary_version=3 AND b.state='credited';
   IF FOUND THEN
    IF purchase<>'confirmed' THEN RAISE EXCEPTION 'allocation lacks original confirmed purchase' USING ERRCODE='GP003'; END IF;
    PERFORM require_owner_megapot_allocation_private_v1(batch.allocation_batch_id);
    SELECT a.* INTO allocation FROM megapot_owner_allocations a
     JOIN megapot_owner_snapshot_leaves leaf ON leaf.snapshot_id=a.snapshot_id AND leaf.ordinal=a.ordinal AND leaf.owner_id=a.owner_id
     WHERE a.allocation_batch_id=batch.allocation_batch_id AND a.owner_id=original.source_owner_id AND a.allocation_kind='participant'
      AND leaf.qualification_id=original.qualification_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'original participation allocation leaf differs' USING ERRCODE='GP003'; END IF;
    -- A locator for the existing composite PK, never an allocation INSERT.
    allocated_id:=allocation.allocation_batch_id||':'||allocation.ordinal::TEXT;
    IF char_length(allocated_id)>128 OR allocated_id ~ '[[:space:][:cntrl:]]' THEN
     RAISE EXCEPTION 'original allocation locator is invalid' USING ERRCODE='GP003'; END IF;
    credit_id_value:=allocation.credit_id; amount_value:=allocation.amount_atomic::TEXT;
   END IF;
  ELSIF original.state='admitted' OR original.result_snapshot IS DISTINCT FROM jsonb_build_object('state',admission) THEN
   RAISE EXCEPTION 'original refusal receipt differs' USING ERRCODE='GP003'; END IF;
 END IF;
 RETURN jsonb_build_object('participation_id',original.admission_id,'original_drawing_id',original.drawing_id::TEXT,
  'pool_leg_id',original.pool_leg_id,'admission_state',admission,'purchase_state',purchase,
  'purchase_safety_deadline_at',to_char(original.purchase_safety_deadline_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
  'reconciliation_state',reconciliation,'purchase_deadline_passed',sampled_at>original.purchase_safety_deadline_at,
  'allocation_id',allocated_id,'credit_id',credit_id_value,'amount_atomic',amount_value);
END $$;
CREATE FUNCTION list_original_owner_participations_private_v1(p_account TEXT,p_sources TEXT[],p_cursor TEXT,p_limit INTEGER)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE cursor_at TIMESTAMPTZ; result JSONB; next_id TEXT;
BEGIN
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 OR (p_account IS NULL)=(p_sources IS NULL)
  OR(p_account IS NOT NULL AND owner_credit_canonical_account_private_v1(p_account) IS DISTINCT FROM p_account)
  OR(p_sources IS NOT NULL AND(cardinality(p_sources)=0 OR cardinality(p_sources)>10000)) THEN
  RAISE EXCEPTION 'original participation scope required' USING ERRCODE='GP009'; END IF;
 IF p_cursor IS NOT NULL THEN
  SELECT o.created_at INTO cursor_at FROM owner_participation_admission_operations o
   WHERE o.admission_id=p_cursor AND owner_participation_is_projectable_private_v1(o.state,o.result_snapshot) IS TRUE
    AND((p_account IS NOT NULL AND account_owns_participation_source_v1(p_account,o.source_owner_id) IS TRUE)
      OR(p_sources IS NOT NULL AND o.source_owner_id=ANY(p_sources)));
  IF NOT FOUND THEN RAISE EXCEPTION 'owned original cursor required' USING ERRCODE='GP009'; END IF;
 END IF;
 WITH candidates AS MATERIALIZED(
  SELECT o.admission_id,o.created_at FROM owner_participation_admission_operations o
   WHERE owner_participation_is_projectable_private_v1(o.state,o.result_snapshot) IS TRUE
    AND((p_account IS NOT NULL AND account_owns_participation_source_v1(p_account,o.source_owner_id) IS TRUE)
      OR(p_sources IS NOT NULL AND o.source_owner_id=ANY(p_sources)))
    AND(p_cursor IS NULL OR(o.created_at,o.admission_id)<(cursor_at,p_cursor))
   ORDER BY o.created_at DESC,o.admission_id DESC LIMIT p_limit+1
 ), ranked AS(SELECT *,row_number() OVER(ORDER BY created_at DESC,admission_id DESC) ordinal FROM candidates)
 SELECT coalesce(jsonb_agg(project_original_owner_participation_private_v1(admission_id) ORDER BY created_at DESC,admission_id DESC) FILTER(WHERE ordinal<=p_limit),'[]'::JSONB),
  CASE WHEN count(*)>p_limit THEN max(admission_id) FILTER(WHERE ordinal=p_limit) ELSE NULL END INTO result,next_id FROM ranked;
 RETURN jsonb_build_object('items',result,'nextCursor',next_id);
END $$;
CREATE FUNCTION list_account_owner_participations_v1(p_account TEXT,p_cursor TEXT,p_limit INTEGER)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 RETURN list_original_owner_participations_private_v1(p_account,NULL,p_cursor,p_limit);
END $$;
CREATE FUNCTION get_account_owner_participation_v1(p_account TEXT,p_id TEXT)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE source_id TEXT;
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_account IS NULL OR owner_credit_canonical_account_private_v1(p_account) IS DISTINCT FROM p_account THEN
  RAISE EXCEPTION 'owned original participation required' USING ERRCODE='GP009'; END IF;
 SELECT source_owner_id INTO source_id FROM owner_participation_admission_operations WHERE admission_id=p_id;
 IF NOT FOUND OR account_owns_participation_source_v1(p_account,source_id) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'owned original participation required' USING ERRCODE='GP009'; END IF;
 RETURN project_original_owner_participation_private_v1(p_id);
END $$;
CREATE FUNCTION list_guest_owner_participations_v1(p_access JSONB,p_cursor TEXT,p_limit INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source_ids TEXT[];
BEGIN
 -- Existing258 validates exact4-key access, positive phase, current confirmed
 -- same-origin credential/effective root and full component, no learning lease.
 source_ids:=require_guest_audio_recovery_access_private_v1(p_access,p_access->>'ownerId');
 RETURN list_original_owner_participations_private_v1(NULL,source_ids,p_cursor,p_limit);
END $$;
-- Paging actual retained journals. No financial/history backfill or row rewrite.
CREATE INDEX original_owner_participation_page ON owner_participation_admission_operations(source_owner_id,created_at DESC,admission_id DESC);

-- Source: owner-participation-recovery-proposal-v2/bind-original-participation-readers.sql
DO $pin_original_participation_readers$
DECLARE ns OID; owner_id OID; schema_name TEXT; signature TEXT; id OID; grantee TEXT;
BEGIN
 SELECT c.relnamespace,c.relowner,n.nspname INTO STRICT ns,owner_id,schema_name
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid='participation_owners'::regclass;
 FOREACH signature IN ARRAY ARRAY[
  'owner_participation_is_projectable_private_v1(text,jsonb)',
  'project_original_owner_participation_private_v1(text)',
  'list_original_owner_participations_private_v1(text,text[],text,integer)',
  'list_account_owner_participations_v1(text,text,integer)',
  'get_account_owner_participation_v1(text,text)',
  'list_guest_owner_participations_v1(jsonb,text,integer)'] LOOP
  id:=to_regprocedure(format('%I.%s',schema_name,signature));
  IF id IS NULL OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=id AND proowner=owner_id AND pronamespace=ns AND prokind='f' AND prosecdef) THEN
   RAISE EXCEPTION 'original reader native custody differs' USING ERRCODE='GP003'; END IF;
  EXECUTE format('ALTER FUNCTION %s SET search_path TO pg_catalog,%I,pg_temp',id::regprocedure,schema_name);
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',id::regprocedure);
  FOR grantee IN SELECT DISTINCT pg_get_userbyid(a.grantee) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
   WHERE p.oid=id AND a.grantee<>0 AND a.grantee<>owner_id LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',id::regprocedure,grantee);
  END LOOP;
 END LOOP;
END $pin_original_participation_readers$;

-- Source: financial-native-assembly-v9/enable-original-admission-journal-rls.sql
-- Exact private shared journals: source-only RLS, no policy, FORCE or role grant.
ALTER TABLE owner_participation_admission_operations ENABLE ROW LEVEL SECURITY;
ALTER TABLE owner_participation_admission_attempts ENABLE ROW LEVEL SECURITY;

-- Source: owner-financial-readiness-proposal-v3/native-source-inventory-schema.sql
-- Metadata installation only, Root/migration-owner custody. No runtime data or
-- supplied readiness boolean. The literal manifest comes from accepted source
-- vectors plus independently source-bound owned native structural readback.
CREATE TABLE owner_accounting_native_source_inventory_v1 (
 singleton BOOLEAN PRIMARY KEY CHECK(singleton),
 source_version TEXT NOT NULL CHECK(source_version='owner_accounting_native_source_v1'),
 manifest JSONB NOT NULL CHECK(jsonb_typeof(manifest)='object')
);
ALTER TABLE owner_accounting_native_source_inventory_v1 ENABLE ROW LEVEL SECURITY;
-- Root inserts the ONE complete literal source manifest BEFORE this retained
-- guard is installed. No live expected vector is computed from the candidate
-- database as an acceptance oracle. There is deliberately no partial seed row.

-- Source: owner-financial-readiness-proposal-v5/require-owner-accounting-ready.sql
-- Read-only native positive attestation. The SINGLE native-owned source inventory
-- is installed from sealed source artifacts by the migration owner, never supplied
-- by a request, GUC, function argument, role name guess or success boolean.
-- The verifier itself is one of its source-derived body vectors. The expected
-- inventory lives outside the verifier body, avoiding a self-hash recursion.
CREATE FUNCTION require_owner_accounting_ready_private_v1()
RETURNS VOID LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE
 trusted_namespace OID; trusted_owner OID; trusted_schema TEXT; inventory_oid OID;
 actual_manifest JSONB; expected RECORD; actual RECORD; id OID; relation_oid OID;
 vectors INTEGER; permitted TEXT[]; expected_configuration TEXT[]; root_tables TEXT[];
BEGIN
 SELECT c.relnamespace,c.relowner,n.nspname INTO STRICT trusted_namespace,trusted_owner,trusted_schema
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
 WHERE c.oid='participation_owners'::regclass AND c.relkind='r';
 IF trusted_schema IN('pg_catalog','information_schema') OR trusted_schema LIKE 'pg_%' THEN
  RAISE EXCEPTION 'native accounting namespace unavailable' USING ERRCODE='GP003'; END IF;
 inventory_oid:=to_regclass(format('%I.owner_accounting_native_source_inventory_v1',trusted_schema));
 IF inventory_oid IS NULL OR NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=inventory_oid
   AND c.relnamespace=trusted_namespace AND c.relowner=trusted_owner AND c.relkind='r' AND c.relrowsecurity)
  OR EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=inventory_oid)
  OR EXISTS(SELECT 1 FROM pg_class WHERE oid=inventory_oid AND relforcerowsecurity)
  OR EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
    WHERE c.oid=inventory_oid AND a.grantee<>trusted_owner)
  OR EXISTS(SELECT 1 FROM pg_attribute c CROSS JOIN LATERAL aclexplode(c.attacl) a
    WHERE c.attrelid=inventory_oid AND a.grantee<>trusted_owner)
 THEN RAISE EXCEPTION 'native source inventory custody unavailable' USING ERRCODE='GP003'; END IF;
 -- A missing table/row/array is an error, never financial emptiness or readiness.
 SELECT manifest INTO STRICT actual_manifest FROM owner_accounting_native_source_inventory_v1
 WHERE singleton AND source_version='owner_accounting_native_source_v1';
 IF (SELECT count(*) FROM owner_accounting_native_source_inventory_v1)<>1
  OR jsonb_typeof(actual_manifest) IS DISTINCT FROM 'object'
  OR NOT(actual_manifest ?& ARRAY['phase','functions','relations','columns','constraints','triggers','ownerConsumers','sourceReferences','consumerGraph','privateFinancialRelations','controlledSignatures'])
  OR (SELECT count(*) FROM jsonb_object_keys(actual_manifest))<>11
  OR jsonb_typeof(actual_manifest->'functions') IS DISTINCT FROM 'array'
  OR jsonb_typeof(actual_manifest->'relations') IS DISTINCT FROM 'array'
  OR jsonb_typeof(actual_manifest->'columns') IS DISTINCT FROM 'array'
  OR jsonb_typeof(actual_manifest->'constraints') IS DISTINCT FROM 'array'
  OR jsonb_typeof(actual_manifest->'triggers') IS DISTINCT FROM 'array'
  OR jsonb_typeof(actual_manifest->'ownerConsumers') IS DISTINCT FROM 'array'
  OR jsonb_typeof(actual_manifest->'sourceReferences') IS DISTINCT FROM 'array'
  OR jsonb_typeof(actual_manifest->'consumerGraph') IS DISTINCT FROM 'array'
  OR jsonb_typeof(actual_manifest->'privateFinancialRelations') IS DISTINCT FROM 'array'
  OR jsonb_typeof(actual_manifest->'controlledSignatures') IS DISTINCT FROM 'array'
  OR jsonb_array_length(actual_manifest->'functions')<100
  OR jsonb_array_length(actual_manifest->'relations')<50
  OR jsonb_array_length(actual_manifest->'constraints')<30
  OR jsonb_array_length(actual_manifest->'triggers')<20
  OR jsonb_array_length(actual_manifest->'consumerGraph')<>14
 THEN RAISE EXCEPTION 'complete source vector required' USING ERRCODE='GP003'; END IF;
 -- Both original Account producers and Guest producers are mandatory; omitting
 -- an entire positive family from a partial manifest cannot yield a pass.
 root_tables:=ARRAY['participation_owners','guest_credentials','guest_empty_owner_aliases','participation_owner_clocks',
  'guest_learning_preferences','guest_participation_operations','guest_secret_issuance_operations','guest_attachment_intents',
  'study_sessions_v2','study_review_items','study_session_items_v2','study_spoken_answer_commands','learner_audio_artifacts',
  'guest_resource_session_reservations','guest_resource_provider_calls','guest_resource_release_receipts',
  'learner_audio_owner_fences','learner_audio_delete_commands','learner_audio_delete_sources','learner_audio_delete_target_artifacts',
  'learner_audio_object_names','learner_audio_upload_attempts','learner_audio_delete_batches','learner_audio_delete_batch_items',
  'learner_audio_deleted_objects','guest_study_spoken_captures','guest_study_spoken_checkpoints',
  'learner_audio_account_producer_captures','learner_audio_upload_terminal_facts','learner_audio_upload_cleanup_commands',
  'learner_audio_account_spoken_checkpoints','learner_audio_account_provider_calls','learner_audio_legacy_settlements',
  'guest_owner_associations','guest_owner_association_conflicts','participation_eligibility_decisions','megapot_owner_shares',
  'megapot_owner_snapshot_leaves','megapot_owner_allocations','reward_credit_persona_bindings','reward_credit_recipient_selections',
  'reward_ledger_credits','megapot_pool_drawings','megapot_pool_shares','megapot_pool_beneficiary_snapshots',
  'megapot_allocation_batches','megapot_allocations','megapot_participant_claims','megapot_participant_claim_guards',
  'reward_payout_effects','reward_winner_sends','reward_gas_topups','wallet_sponsored_sends','song_reward_bundle_claim_legs',
  'owner_captured_guest_choice_commands','owner_participation_admission_operations','owner_participation_admission_attempts',
  'account_owner_reward_sources','account_owner_reward_operations'];
 IF EXISTS(SELECT 1 FROM unnest(root_tables) required WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual_manifest->'relations') v
   WHERE v->>'name'=required))
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual_manifest->'functions') v
    WHERE v->>'signature'='require_owner_accounting_ready_private_v1()')
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual_manifest->'functions') v
    WHERE v->>'signature'='reject_owner_accounting_source_inventory_mutation_v1()')
  OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual_manifest->'triggers') v
    WHERE v->>'relation'='owner_accounting_native_source_inventory_v1'
     AND v->>'name'='original_accounting_source_inventory_immutable')
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(actual_manifest->'consumerGraph') v WHERE
    v->>'sha256' IS NULL OR v->>'sha256' !~ '^[0-9a-f]{64}$' OR coalesce(v->>'path','')='')
  OR (SELECT count(DISTINCT v->>'path') FROM jsonb_array_elements(actual_manifest->'consumerGraph') v)<>14
 THEN RAISE EXCEPTION 'closed source graph unavailable' USING ERRCODE='GP003'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid='guest_learning_schema_phase'::regclass
    AND c.relowner=trusted_owner AND c.relnamespace=trusted_namespace AND c.relkind='r')
  OR (SELECT count(*) FROM guest_learning_schema_phase)<>1 OR NOT EXISTS(
  SELECT 1 FROM guest_learning_schema_phase WHERE singleton AND phase=actual_manifest->>'phase')
  OR actual_manifest->>'phase' IS DISTINCT FROM 'owner_accounting_native_source_v1'
 THEN RAISE EXCEPTION 'positive accounting phase unavailable' USING ERRCODE='GP003'; END IF;
 SELECT coalesce(array_agg(v #>> '{}'),'{}'::TEXT[]) INTO permitted FROM jsonb_array_elements(actual_manifest->'controlledSignatures') v;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY['guest_owner_associations','guest_owner_association_conflicts',
  'participation_eligibility_decisions','megapot_owner_shares','megapot_owner_snapshot_leaves','megapot_owner_allocations',
  'reward_credit_persona_bindings','reward_credit_recipient_selections','owner_participation_admission_operations',
  'owner_participation_admission_attempts','owner_captured_guest_choice_commands','account_owner_reward_sources',
  'account_owner_reward_operations']) name WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual_manifest->'relations') v
    WHERE v->>'name'=name AND v->>'private'='true' AND v->>'rls'='true')) THEN
  RAISE EXCEPTION 'private financial family cannot be omitted or opened' USING ERRCODE='GP003'; END IF;
 IF cardinality(permitted)<>(SELECT count(DISTINCT v #>> '{}') FROM jsonb_array_elements(actual_manifest->'controlledSignatures') v)
  OR EXISTS(SELECT 1 FROM unnest(permitted) signature WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual_manifest->'functions') f WHERE f->>'signature'=signature))
  OR jsonb_array_length(actual_manifest->'relations')<>(SELECT count(DISTINCT v->>'name') FROM jsonb_array_elements(actual_manifest->'relations') v)
  OR jsonb_array_length(actual_manifest->'columns')<>(SELECT count(DISTINCT (v->>'relation',v->>'name')) FROM jsonb_array_elements(actual_manifest->'columns') v)
  OR jsonb_array_length(actual_manifest->'constraints')<>(SELECT count(DISTINCT (v->>'relation',v->>'name')) FROM jsonb_array_elements(actual_manifest->'constraints') v)
  OR jsonb_array_length(actual_manifest->'triggers')<>(SELECT count(DISTINCT (v->>'relation',v->>'name')) FROM jsonb_array_elements(actual_manifest->'triggers') v) THEN
  RAISE EXCEPTION 'duplicate or incomplete source vectors' USING ERRCODE='GP003'; END IF;
 -- Every expected function actually exists and has the EXACT source body, ABI,
 -- owner, language and frame. No execution of the inspected financial callbacks.
 vectors:=0;
 FOR expected IN SELECT * FROM jsonb_to_recordset(actual_manifest->'functions') AS f(
  signature TEXT,body_sha256 TEXT,definer BOOLEAN,language TEXT,result TEXT,configuration TEXT[],controlled BOOLEAN,
  acl_class TEXT,source_acl JSONB) LOOP
  IF expected.signature IS NULL OR expected.body_sha256 IS NULL OR expected.body_sha256 !~ '^[0-9a-f]{64}$'
   OR expected.definer IS NULL OR expected.language NOT IN('sql','plpgsql') OR expected.result IS NULL
   OR expected.controlled IS NULL OR expected.controlled IS DISTINCT FROM(expected.signature=ANY(permitted))
   OR expected.acl_class IS NULL OR expected.acl_class NOT IN('private_source_only','controlled_financial','legacy_source_default')
   OR expected.controlled IS DISTINCT FROM(expected.acl_class='controlled_financial')
   OR(expected.acl_class<>'legacy_source_default' AND expected.source_acl IS NOT NULL)
   OR(expected.acl_class='legacy_source_default' AND(
     jsonb_typeof(expected.source_acl) IS DISTINCT FROM 'array'
     OR NOT(expected.source_acl @> '[{"grantor":"@NATIVE_OWNER@","grantee":"PUBLIC","privilege_type":"EXECUTE","is_grantable":false}]'::JSONB)
     OR NOT(expected.source_acl @> '[{"grantor":"@NATIVE_OWNER@","grantee":"@NATIVE_OWNER@","privilege_type":"EXECUTE","is_grantable":false}]'::JSONB))) THEN
   RAISE EXCEPTION 'closed procedure source vector required' USING ERRCODE='GP003'; END IF;
  id:=to_regprocedure(format('%I.%s',trusted_schema,expected.signature));
  SELECT p.*,l.lanname INTO actual FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=id;
  expected_configuration:=CASE WHEN expected.configuration IS NULL THEN NULL
   ELSE ARRAY(SELECT replace(v,'@NATIVE_SCHEMA@',trusted_schema) FROM unnest(expected.configuration) v) END;
  IF id IS NULL OR actual.pronamespace IS DISTINCT FROM trusted_namespace OR actual.proowner IS DISTINCT FROM trusted_owner
   OR actual.prokind IS DISTINCT FROM 'f'::"char" OR actual.prosecdef IS DISTINCT FROM expected.definer
   OR actual.lanname IS DISTINCT FROM expected.language OR actual.proconfig IS DISTINCT FROM expected_configuration
   OR replace(pg_get_function_result(id),trusted_schema||'.','@NATIVE_SCHEMA@.') IS DISTINCT FROM expected.result
   OR encode(sha256(convert_to(actual.prosrc,'UTF8')),'hex') IS DISTINCT FROM expected.body_sha256
   OR(expected.acl_class<>'legacy_source_default' AND EXISTS(
    SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a
    WHERE a.grantee<>trusted_owner AND(a.grantee=0 OR a.privilege_type<>'EXECUTE' OR a.is_grantable OR NOT expected.controlled)))
   OR(expected.acl_class='legacy_source_default' AND expected.source_acl IS DISTINCT FROM(
    SELECT coalesce(jsonb_agg(jsonb_build_object(
      'grantor',CASE WHEN a.grantor=trusted_owner THEN '@NATIVE_OWNER@' ELSE pg_get_userbyid(a.grantor) END,
      'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' WHEN a.grantee=trusted_owner THEN '@NATIVE_OWNER@' ELSE pg_get_userbyid(a.grantee) END,
      'privilege_type',a.privilege_type,'is_grantable',a.is_grantable)
     ORDER BY (CASE WHEN a.grantee=0 THEN 'PUBLIC' WHEN a.grantee=trusted_owner THEN '@NATIVE_OWNER@' ELSE pg_get_userbyid(a.grantee) END) COLLATE "C",
      (CASE WHEN a.grantor=trusted_owner THEN '@NATIVE_OWNER@' ELSE pg_get_userbyid(a.grantor) END) COLLATE "C",
      a.privilege_type COLLATE "C",a.is_grantable),'[]'::JSONB)
    FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a))
  THEN RAISE EXCEPTION 'native procedure source/frame/custody differs' USING ERRCODE='GP003'; END IF;
  -- Only the finite source-owned legacy class can preserve PUBLIC/default ACLs.
  -- Exact equality above refuses extra/missing/duplicate grants or grant options;
  -- every named nonowner retained grantee still undergoes full SET custody below.
  -- The source generator must prove creation-default and ordered explicit ACL
  -- events. Never derive an expected ACL from the candidate's observed grants.
  -- Controlled nonowner EXECUTE still cannot be granted to a principal that can
  -- own/change the native source or bypass row-security/custody. Root's external
  -- four-principal verifier further binds exact managed identities/role profiles.
  IF EXISTS(SELECT 1 FROM aclexplode(coalesce(actual.proacl,acldefault('f',actual.proowner))) a
    JOIN pg_roles role ON role.oid=a.grantee WHERE a.grantee<>trusted_owner AND(
     role.rolsuper OR role.rolcreaterole OR role.rolcreatedb OR role.rolbypassrls OR role.rolreplication
     OR pg_has_role(a.grantee,trusted_owner,'MEMBER') OR has_schema_privilege(a.grantee,trusted_namespace,'CREATE')
     OR EXISTS(SELECT 1 FROM pg_roles reachable WHERE pg_has_role(a.grantee,reachable.oid,'SET') AND(
       reachable.rolsuper OR reachable.rolcreaterole OR reachable.rolcreatedb OR reachable.rolbypassrls OR reachable.rolreplication
       OR pg_has_role(reachable.oid,trusted_owner,'MEMBER') OR has_schema_privilege(reachable.oid,trusted_namespace,'CREATE')))))
  THEN RAISE EXCEPTION 'unsafe controlled principal custody' USING ERRCODE='GP003'; END IF;
  vectors:=vectors+1;
 END LOOP;
 IF vectors<>(SELECT count(DISTINCT v->>'signature') FROM jsonb_array_elements(actual_manifest->'functions') v) THEN
  RAISE EXCEPTION 'duplicate procedure source vector' USING ERRCODE='GP003'; END IF;
 FOR expected IN SELECT * FROM jsonb_to_recordset(actual_manifest->'relations') AS r(name TEXT,kind TEXT,private BOOLEAN,rls BOOLEAN) LOOP
  relation_oid:=to_regclass(format('%I.%I',trusted_schema,expected.name));
  IF expected.name IS NULL OR expected.kind IS NULL OR expected.private IS NULL OR expected.rls IS NULL
   OR NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=relation_oid AND c.relowner=trusted_owner
    AND c.relnamespace=trusted_namespace AND c.relkind::TEXT=expected.kind AND c.relrowsecurity=expected.rls
    AND NOT c.relforcerowsecurity)
   OR(expected.private AND(EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=relation_oid)
    OR EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a
      WHERE c.oid=relation_oid AND a.grantee<>trusted_owner)
    OR EXISTS(SELECT 1 FROM pg_attribute c CROSS JOIN LATERAL aclexplode(c.attacl) a WHERE c.attrelid=relation_oid AND a.grantee<>trusted_owner)))
  THEN RAISE EXCEPTION 'native relation/source custody differs' USING ERRCODE='GP003'; END IF;
 END LOOP;
 FOR expected IN SELECT * FROM jsonb_to_recordset(actual_manifest->'columns') AS c(
  relation TEXT,name TEXT,type TEXT,not_null BOOLEAN,generated TEXT,default_expression TEXT) LOOP
  relation_oid:=to_regclass(format('%I.%I',trusted_schema,expected.relation));
  SELECT a.*,pg_get_expr(d.adbin,d.adrelid) AS default_expression INTO actual FROM pg_attribute a
   LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum
   WHERE a.attrelid=relation_oid AND a.attname=expected.name AND a.attnum>0 AND NOT a.attisdropped;
  IF NOT FOUND OR expected.type IS NULL OR expected.not_null IS NULL OR expected.generated IS NULL
   OR format_type(actual.atttypid,actual.atttypmod) IS DISTINCT FROM expected.type
   OR actual.attnotnull IS DISTINCT FROM expected.not_null OR actual.attgenerated::TEXT IS DISTINCT FROM expected.generated
   OR replace(actual.default_expression,trusted_schema||'.','@NATIVE_SCHEMA@.') IS DISTINCT FROM expected.default_expression
  THEN RAISE EXCEPTION 'original source column differs' USING ERRCODE='GP003'; END IF;
 END LOOP;
 FOR expected IN SELECT * FROM jsonb_to_recordset(actual_manifest->'constraints') AS c(
  relation TEXT,name TEXT,kind TEXT,columns TEXT[],reference_relation TEXT,reference_columns TEXT[],
  validated BOOLEAN,"deferrable" BOOLEAN,initially_deferred BOOLEAN,definition TEXT) LOOP
  relation_oid:=to_regclass(format('%I.%I',trusted_schema,expected.relation));
  SELECT c.* INTO actual FROM pg_constraint c WHERE c.conrelid=relation_oid AND c.conname=expected.name;
  IF NOT FOUND OR expected.kind IS NULL OR expected.validated IS NULL OR expected.deferrable IS NULL OR expected.initially_deferred IS NULL
   OR actual.contype::TEXT IS DISTINCT FROM expected.kind OR actual.convalidated IS DISTINCT FROM expected.validated
   OR actual.condeferrable IS DISTINCT FROM expected.deferrable OR actual.condeferred IS DISTINCT FROM expected.initially_deferred
   OR (SELECT array_agg(a.attname::TEXT ORDER BY k.ordinality) FROM unnest(actual.conkey) WITH ORDINALITY k(attnum,ordinality)
     JOIN pg_attribute a ON a.attrelid=actual.conrelid AND a.attnum=k.attnum) IS DISTINCT FROM expected.columns
   OR(actual.contype='f' AND(actual.confrelid IS DISTINCT FROM to_regclass(format('%I.%I',trusted_schema,expected.reference_relation))
    OR(SELECT array_agg(a.attname::TEXT ORDER BY k.ordinality) FROM unnest(actual.confkey) WITH ORDINALITY k(attnum,ordinality)
      JOIN pg_attribute a ON a.attrelid=actual.confrelid AND a.attnum=k.attnum) IS DISTINCT FROM expected.reference_columns))
   OR expected.definition IS NULL OR replace(pg_get_constraintdef(actual.oid,FALSE),trusted_schema||'.','@NATIVE_SCHEMA@.') IS DISTINCT FROM expected.definition
  THEN RAISE EXCEPTION 'native financial constraint differs' USING ERRCODE='GP003'; END IF;
 END LOOP;
 FOR expected IN SELECT * FROM jsonb_to_recordset(actual_manifest->'triggers') AS t(
  relation TEXT,name TEXT,function_signature TEXT,type INTEGER,enabled TEXT,"deferrable" BOOLEAN,initially_deferred BOOLEAN,definition TEXT) LOOP
  relation_oid:=to_regclass(format('%I.%I',trusted_schema,expected.relation));
  SELECT t.* INTO actual FROM pg_trigger t WHERE t.tgrelid=relation_oid AND t.tgname=expected.name AND NOT t.tgisinternal;
  IF NOT FOUND OR expected.function_signature IS NULL OR expected.type IS NULL OR expected.enabled IS NULL
   OR expected.deferrable IS NULL OR expected.initially_deferred IS NULL OR expected.definition IS NULL
   OR actual.tgfoid IS DISTINCT FROM to_regprocedure(format('%I.%s',trusted_schema,expected.function_signature))
   OR actual.tgtype IS DISTINCT FROM expected.type OR actual.tgenabled::TEXT IS DISTINCT FROM expected.enabled
   OR actual.tgdeferrable IS DISTINCT FROM expected.deferrable OR actual.tginitdeferred IS DISTINCT FROM expected.initially_deferred
   OR replace(pg_get_triggerdef(actual.oid,FALSE),trusted_schema||'.','@NATIVE_SCHEMA@.') IS DISTINCT FROM expected.definition
  THEN RAISE EXCEPTION 'native original-source trigger differs' USING ERRCODE='GP003'; END IF;
 END LOOP;
 IF NOT EXISTS(SELECT 1 FROM pg_class c WHERE c.oid=to_regclass(format('%I.learner_audio_fence_revision_v1',trusted_schema))
    AND c.relnamespace=trusted_namespace AND c.relowner=trusted_owner AND c.relkind='S')
  OR EXISTS(SELECT 1 FROM pg_depend d
    LEFT JOIN pg_attrdef expression ON d.classid='pg_attrdef'::regclass AND expression.oid=d.objid
    LEFT JOIN pg_class consumer ON consumer.oid=CASE WHEN d.classid='pg_attrdef'::regclass THEN expression.adrelid WHEN d.classid='pg_class'::regclass THEN d.objid END
    WHERE d.refclassid='pg_class'::regclass AND d.refobjid=to_regclass(format('%I.learner_audio_fence_revision_v1',trusted_schema))
     AND NOT(coalesce(consumer.relnamespace=trusted_namespace AND consumer.relname IN('learner_audio_owner_fences','learner_audio_delete_commands'),FALSE)
      OR(d.classid='pg_proc'::regclass AND d.objid=to_regprocedure(format('%I.prepare_learner_audio_delete_private_v1(text,text,text,text,text[],text,integer,text)',trusted_schema)))))
  OR EXISTS(SELECT 1 FROM learner_audio_legacy_settlements s JOIN participation_owners o USING(owner_id) WHERE o.kind<>'account') THEN
  RAISE EXCEPTION 'retained native audio source closure differs' USING ERRCODE='GP003'; END IF;
 -- Closed entire owner/FK consumer graph, not just the families we happen to read.
 -- Unknown new relations/columns referencing source tables refuse until reviewed.
 IF EXISTS(SELECT 1 FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid WHERE c.relnamespace=trusted_namespace
    AND c.relkind IN('r','p','f','v','m') AND a.attnum>0 AND NOT a.attisdropped AND a.attname~'(^|_)owner_id$'
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual_manifest->'ownerConsumers') v
      WHERE v->>'relation'=c.relname AND v->>'column'=a.attname))
  OR EXISTS(SELECT 1 FROM pg_constraint f JOIN pg_class c ON c.oid=f.conrelid WHERE f.contype='f'
    AND c.relnamespace=trusted_namespace AND f.confrelid IN(SELECT to_regclass(format('%I.%I',trusted_schema,v #>> '{}'))
      FROM jsonb_array_elements(actual_manifest->'sourceReferences') v)
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(actual_manifest->'constraints') v
      WHERE v->>'relation'=c.relname AND v->>'name'=f.conname))
 THEN RAISE EXCEPTION 'unreviewed original-owner source consumer' USING ERRCODE='GP003'; END IF;
END $$;

