-- Source: owner-financial-readiness-proposal-v3/native-source-inventory-protection.sql
CREATE FUNCTION reject_owner_accounting_source_inventory_mutation_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN RAISE EXCEPTION 'original accounting source attestation is immutable' USING ERRCODE='GP003'; END $$;
-- Root installation order: CREATE relation, insert reviewed full literal,
-- CREATE guard + trigger, pin/revoke, then positive phase and validate readiness.
CREATE TRIGGER original_accounting_source_inventory_immutable
 BEFORE INSERT OR UPDATE OR DELETE OR TRUNCATE ON owner_accounting_native_source_inventory_v1
 FOR EACH STATEMENT EXECUTE FUNCTION reject_owner_accounting_source_inventory_mutation_v1();
DO $protect_native_owner_accounting_source_inventory$
DECLARE ns OID; owner_id OID; schema_name TEXT; id OID; grantee TEXT; column_name TEXT;
BEGIN
 SELECT c.relnamespace,c.relowner,n.nspname INTO STRICT ns,owner_id,schema_name
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid='participation_owners'::regclass;
 id:=to_regclass(format('%I.owner_accounting_native_source_inventory_v1',schema_name));
 IF id IS NULL OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid=id AND relowner=owner_id AND relnamespace=ns) THEN
  RAISE EXCEPTION 'native source inventory custody differs'; END IF;
 REVOKE ALL ON owner_accounting_native_source_inventory_v1 FROM PUBLIC;
 FOR grantee IN SELECT DISTINCT pg_get_userbyid(a.grantee) FROM pg_class c
  CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=id AND a.grantee<>0 AND a.grantee<>owner_id LOOP
  EXECUTE format('REVOKE ALL ON TABLE %I.owner_accounting_native_source_inventory_v1 FROM %I',schema_name,grantee);
 END LOOP;
 FOR column_name,grantee IN SELECT c.attname,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END
  FROM pg_attribute c CROSS JOIN LATERAL aclexplode(c.attacl) a WHERE c.attrelid=id AND a.grantee<>owner_id LOOP
  EXECUTE format('REVOKE ALL(%I) ON TABLE %I.owner_accounting_native_source_inventory_v1 FROM %s',column_name,schema_name,CASE WHEN grantee='PUBLIC' THEN 'PUBLIC' ELSE quote_ident(grantee) END);
 END LOOP;
 FOR id IN SELECT to_regprocedure(format('%I.%s',schema_name,signature)) FROM unnest(ARRAY[
   'require_owner_accounting_ready_private_v1()','reject_owner_accounting_source_inventory_mutation_v1()']) signature LOOP
  IF id IS NULL OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=id AND proowner=owner_id AND pronamespace=ns) THEN
   RAISE EXCEPTION 'native accounting attestation function custody differs'; END IF;
  EXECUTE format('ALTER FUNCTION %s SECURITY DEFINER',id::regprocedure);
  EXECUTE format('ALTER FUNCTION %s SET search_path TO pg_catalog,%I,pg_temp',id::regprocedure,schema_name);
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',id::regprocedure);
  FOR grantee IN SELECT DISTINCT pg_get_userbyid(a.grantee) FROM pg_proc p
   CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=id AND a.grantee<>0 AND a.grantee<>owner_id LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',id::regprocedure,grantee);
  END LOOP;
 END LOOP;
END $protect_native_owner_accounting_source_inventory$;

-- Source: owner-financial-readiness-proposal-v3/financial-history-successor.sql
CREATE OR REPLACE FUNCTION guest_financial_component_has_history_private_v1(component_ids TEXT[])
RETURNS BOOLEAN LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE original_accounts TEXT[];
BEGIN
 IF component_ids IS NULL OR cardinality(component_ids)=0 OR cardinality(component_ids)>10000
  OR EXISTS(SELECT 1 FROM unnest(component_ids) id WHERE id IS NULL
   OR NOT EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=id)) THEN
  RAISE EXCEPTION 'complete original financial component required' USING ERRCODE='GP003'; END IF;
 SELECT array_agg(account_id) INTO original_accounts FROM participation_owners
  WHERE owner_id=ANY(component_ids) AND kind='account';
 RETURN EXISTS(SELECT 1 FROM guest_owner_associations WHERE guest_owner_id=ANY(component_ids) OR account_owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM guest_owner_association_conflicts WHERE guest_owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM activity_qualifications WHERE participation_owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM participation_eligibility_decisions WHERE owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM megapot_owner_shares WHERE owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM megapot_owner_snapshot_leaves WHERE owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM megapot_owner_allocations WHERE owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM reward_credit_recipient_selections WHERE owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM reward_credit_persona_bindings WHERE owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM owner_participation_admission_operations WHERE source_owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM owner_participation_admission_attempts a JOIN owner_participation_admission_operations o USING(admission_id)
  WHERE o.source_owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM owner_captured_guest_choice_commands WHERE source_owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM account_owner_reward_sources WHERE source_owner_id=ANY(component_ids))
 OR EXISTS(SELECT 1 FROM account_owner_reward_operations WHERE source_owner_id=ANY(component_ids))
 -- ONE ledger: include legacy/fallback Account debt by original account ID even
 -- when no persona/user is active, and owner_v1 by immutable original owner ID.
 OR EXISTS(SELECT 1 FROM reward_ledger_credits WHERE participation_owner_id=ANY(component_ids)
  OR(identity_version='account_v1' AND account_id=ANY(coalesce(original_accounts,'{}'::TEXT[]))))
 OR EXISTS(SELECT 1 FROM megapot_pool_shares WHERE account_id=ANY(coalesce(original_accounts,'{}'::TEXT[])))
 OR EXISTS(SELECT 1 FROM megapot_allocations WHERE account_id=ANY(coalesce(original_accounts,'{}'::TEXT[])))
 OR EXISTS(SELECT 1 FROM megapot_participant_claims c JOIN reward_ledger_credits l USING(credit_id)
  WHERE l.participation_owner_id=ANY(component_ids) OR l.account_id=ANY(coalesce(original_accounts,'{}'::TEXT[])))
 OR EXISTS(SELECT 1 FROM reward_payout_effects e JOIN reward_ledger_credits l USING(credit_id)
  WHERE l.participation_owner_id=ANY(component_ids) OR l.account_id=ANY(coalesce(original_accounts,'{}'::TEXT[])))
 OR EXISTS(SELECT 1 FROM reward_winner_sends e JOIN reward_ledger_credits l USING(credit_id)
  WHERE l.participation_owner_id=ANY(component_ids) OR l.account_id=ANY(coalesce(original_accounts,'{}'::TEXT[])))
 OR EXISTS(SELECT 1 FROM reward_gas_topups e JOIN reward_ledger_credits l USING(credit_id)
  WHERE l.participation_owner_id=ANY(component_ids) OR l.account_id=ANY(coalesce(original_accounts,'{}'::TEXT[])));
 -- Creditless wallet_sponsored_sends do not invent a wallet→credit relation;
 -- their original Account/source erasure snapshot remains separately required.
END $$;

-- Source: owner-financial-readiness-proposal-v3/component-empty-successor.sql
-- Exact 0265 retained empty predicate plus complete bidirectional original identity graph.
-- No locks/DML/provider. Root includes all called histories in full native witness.
CREATE OR REPLACE FUNCTION guest_authority_component_is_empty_v1(original_source_id TEXT)
RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE root_id TEXT; member_ids TEXT[];
BEGIN
  PERFORM require_guest_practice_only_schema_phase_v1();
  root_id := resolve_guest_empty_owner_root_v1(original_source_id);
  IF root_id IS NULL THEN RAISE EXCEPTION 'original component unavailable' USING ERRCODE='GP003'; END IF;
  WITH RECURSIVE component(owner_id) AS (
    SELECT root_id UNION SELECT adjacent.owner_id FROM component c CROSS JOIN LATERAL (
     SELECT a.source_owner_id AS owner_id FROM guest_empty_owner_aliases a WHERE a.canonical_owner_id=c.owner_id
     UNION SELECT a.canonical_owner_id FROM guest_empty_owner_aliases a WHERE a.source_owner_id=c.owner_id
     UNION SELECT a.account_owner_id FROM guest_owner_associations a WHERE a.guest_owner_id=c.owner_id
     UNION SELECT a.guest_owner_id FROM guest_owner_associations a WHERE a.account_owner_id=c.owner_id
     -- Conflict is dedup/history only, never authentication authority. Its original
     -- association still joins the complete history component in either state.
     UNION SELECT other.owner_id FROM participation_owners current_owner
      JOIN account_aliases a ON a.source_user_id=current_owner.account_id OR a.canonical_user_id=current_owner.account_id
      JOIN participation_owners other ON other.kind='account' AND other.account_id IN(a.source_user_id,a.canonical_user_id)
      WHERE current_owner.owner_id=c.owner_id AND current_owner.kind='account'
       AND((a.kind='alias' AND a.status='active') OR(a.kind='merge' AND a.status IN('finalizing','completed')))
    ) adjacent
  ) SELECT array_agg(owner_id ORDER BY convert_to(owner_id,'UTF8')) INTO member_ids FROM component;
  IF member_ids IS NULL OR cardinality(member_ids)>10000 OR EXISTS(SELECT 1 FROM unnest(member_ids) id
    WHERE NOT EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=id)) THEN
   RAISE EXCEPTION 'complete history component unavailable' USING ERRCODE='GP003'; END IF;
  RETURN EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=root_id AND kind='guest' AND state='empty')
    AND NOT EXISTS(SELECT 1 FROM participation_owners WHERE owner_id=ANY(member_ids) AND state='established')
    AND NOT EXISTS(SELECT 1 FROM study_sessions_v2 WHERE participation_owner_id=ANY(member_ids))
    AND NOT EXISTS(SELECT 1 FROM study_review_items WHERE participation_owner_id=ANY(member_ids))
    AND NOT EXISTS(SELECT 1 FROM study_session_items_v2 WHERE participation_owner_id=ANY(member_ids))
    AND NOT EXISTS(SELECT 1 FROM study_spoken_answer_commands WHERE participation_owner_id=ANY(member_ids))
    AND NOT EXISTS(SELECT 1 FROM learner_audio_artifacts WHERE participation_owner_id=ANY(member_ids))
    AND NOT guest_resource_component_has_history_v1(member_ids)
    AND NOT learner_audio_component_has_history_private_v1(member_ids)
    AND NOT guest_spoken_component_has_history_private_v1(member_ids)
    AND NOT learner_audio_producer_component_has_history_private_v1(member_ids)
    AND NOT guest_financial_component_has_history_private_v1(member_ids)
    AND NOT EXISTS(SELECT 1 FROM guest_participation_operations WHERE source_owner_id=ANY(member_ids)
      AND operation_kind IN ('study_start','study_answer','learning_retention','learner_audio_deletion')
      AND state<>'known_aborted')
    AND NOT EXISTS(SELECT 1 FROM guest_attachment_intents WHERE owner_id=ANY(member_ids)
      AND state IN ('awaiting_account','awaiting_confirmation') AND expires_at>clock_timestamp());
END $$;

-- Source: owner-financial-readiness-proposal-v3/positive-phase-and-dml-successor.sql
-- Final source-only phase successor; Root assembles all accepted native guards,
-- ONE immutable complete source vector and ACL binder before this final section.
-- The existing 0265 seven-family statement triggers remain installed unchanged;
-- they invoke this replacement, which checks the complete actual native closure.
CREATE OR REPLACE FUNCTION require_guest_practice_only_schema_phase_v1()
RETURNS VOID LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
END $$;
CREATE OR REPLACE FUNCTION require_disabled_owner_financial_inventory_private_v1()
RETURNS VOID LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
BEGIN
 -- Retained call identity, positive full witness: no table-emptiness assertion.
 PERFORM require_owner_accounting_ready_private_v1();
END $$;
CREATE OR REPLACE FUNCTION reject_disabled_owner_financial_dml_v1()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
BEGIN
 -- Complete positive native guards are mandatory even for migration-owner DML.
 -- UPDATE legality is checked by the exact immutable/stateful row guards listed
 -- in the source vector; this statement trigger supplies no transition authority.
 IF TG_OP NOT IN('INSERT','UPDATE') THEN
