  IF routine_id IS NULL OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=routine_id AND pronamespace=namespace_id AND proowner=owner_id) THEN RAISE EXCEPTION 'recipient routine custody differs'; END IF;
  EXECUTE format('ALTER FUNCTION %I.%s SECURITY DEFINER',installed_schema,signature);
  EXECUTE format('ALTER FUNCTION %I.%s SET search_path TO pg_catalog,%I,pg_temp',installed_schema,signature,installed_schema);
  EXECUTE format('REVOKE ALL ON FUNCTION %I.%s FROM PUBLIC',installed_schema,signature);
  FOR grantee IN SELECT DISTINCT pg_get_userbyid(a.grantee) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid=routine_id AND a.grantee<>0 AND a.grantee<>owner_id LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %I.%s FROM %I',installed_schema,signature,grantee);
  END LOOP;
 END LOOP;
 ALTER TABLE guest_owner_association_conflicts ENABLE ROW LEVEL SECURITY;
 REVOKE ALL ON TABLE guest_owner_association_conflicts FROM PUBLIC;
 FOR grantee IN SELECT DISTINCT pg_get_userbyid(a.grantee) FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid='guest_owner_association_conflicts'::regclass AND a.grantee<>0 AND a.grantee<>c.relowner LOOP
  EXECUTE format('REVOKE ALL ON TABLE %I.guest_owner_association_conflicts FROM %I',installed_schema,grantee);
 END LOOP;
 -- Existing seven tables remain RLS/no-policy/no-raw-grant with 0264 blocking DML.
 -- No table-default privilege, controlled role grant or positive phase is installed.
END $bind_owner_recipient_packet$;

