-- Source: owner-account-study-119-proposal-v2/current-account-study-preview.sql
-- Current genuine ordinary prepared source; no Guest proof/public-only auth,
-- fabricated persona, latest drawing fallback or caller policy/revision input.
CREATE FUNCTION read_current_account_study_reward_preview_v1(
 p_account TEXT,p_persona TEXT,p_community TEXT,p_post TEXT,p_disclosure TEXT,p_safety_margin INTEGER,p_target_language TEXT,p_learner_band TEXT
) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE source RECORD;
BEGIN
 IF p_safety_margin IS NULL OR p_safety_margin NOT BETWEEN 1 AND 86400 THEN RETURN NULL; END IF;
 PERFORM require_owner_accounting_ready_private_v1();
 IF active_activity_persona(p_account,p_persona,p_community) IS DISTINCT FROM TRUE
  OR can_account_access_activity_song(p_account,p_community,p_post) IS DISTINCT FROM TRUE THEN
  RAISE EXCEPTION 'actual Account prepared source unavailable' USING ERRCODE='GP002'; END IF;
 SELECT publication.audio_revision,publication.lyrics_revision INTO source
 FROM media_publication_projections publication JOIN media_post_submissions submission
  ON submission.submission_id=publication.submission_id AND submission.community_id=publication.community_id AND submission.post_id=publication.post_id
 JOIN media_song_lyrics_revisions lyrics ON lyrics.submission_id=submission.submission_id AND lyrics.lyrics_revision=publication.lyrics_revision
 WHERE publication.community_id=p_community AND publication.post_id=p_post
  AND submission.status='published' AND publication.lyrics_status='ready' AND publication.language_status='ready'
  AND publication.audio_revision=submission.audio_revision AND publication.lyrics_revision=submission.current_lyrics_revision
  AND EXISTS(SELECT 1 FROM media_song_stems s WHERE s.submission_id=publication.submission_id AND s.community_id=p_community AND s.slot='instrumental_audio')
  AND EXISTS(SELECT 1 FROM media_song_stems s WHERE s.submission_id=publication.submission_id AND s.community_id=p_community AND s.slot='vocal_audio');
 IF NOT FOUND THEN RETURN NULL; END IF;
 -- Same prepared exercise eligibility predicates as the actual ordinary
 -- StudyV2 exerciseRows query; preview never promises an unprepared language/band.
 IF (WITH latest AS(
   SELECT DISTINCT ON(exercise.exercise_review_key) exercise.exercise_review_key
    FROM study_exercise_versions exercise JOIN media_publication_projections publication
     ON publication.community_id=exercise.community_id AND publication.post_id=exercise.post_id
    JOIN media_post_submissions submission ON submission.submission_id=publication.submission_id
     AND submission.audio_revision=exercise.audio_revision AND submission.current_lyrics_revision=exercise.lyrics_revision
    JOIN localization_lyrics_revision_lines membership ON membership.community_id=exercise.community_id
     AND membership.post_id=exercise.post_id AND membership.lyrics_revision=exercise.lyrics_revision AND membership.lyric_line_id=exercise.lyric_line_id
    WHERE exercise.community_id=p_community AND exercise.post_id=p_post AND exercise.retired_at IS NULL
     AND exercise.learner_band IS NOT DISTINCT FROM p_learner_band
     AND((exercise.exercise_type='translation_choice' AND exercise.target_language=p_target_language)
      OR(exercise.exercise_type='say_it_back' AND exercise.target_language IS NULL))
    ORDER BY exercise.exercise_review_key,exercise.content_revision DESC
  ) SELECT count(*) FROM latest)<4 THEN RETURN NULL; END IF;
 -- EXACT installed ordinary StudyV2 source qualification revision (the actual
 -- selected-account producer INSERT literal), not a policy supplied by browser.
 RETURN read_account_owner_reward_terms_private_v1(p_account,p_persona,'study',p_community,p_post,
  source.audio_revision,source.lyrics_revision,'study_session_first_pass_v2@1',p_disclosure,p_safety_margin);
END $$;
-- A captured original source can be resumed before current publication/config
-- checks; selected provenance is checked without minting a Guest/account proof.
CREATE FUNCTION require_original_account_owner_study_source_v1(p_account TEXT,p_community TEXT,p_session TEXT)
RETURNS VOID LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 IF NOT EXISTS(SELECT 1 FROM account_owner_reward_sources src JOIN study_sessions_v2 session ON session.session_id=src.v2_session_id
   WHERE src.account_id=p_account AND src.community_id=p_community AND src.session_id=p_session AND src.session_kind='study_v2'
    AND session.account_id=src.account_id AND session.persona_id=src.persona_id AND session.community_id=src.community_id
    AND session.post_id=src.post_id AND session.audio_revision=src.audio_revision AND session.lyrics_revision=src.lyrics_revision
    AND session.qualification_policy_revision=src.qualification_policy_revision
    AND session.owner_reward_preview_hash=src.preview_terms_hash AND session.participation_owner_id=src.source_owner_id
    AND session.participation_owner_kind='account' AND session.telegram_practice_only IS FALSE) THEN
  RAISE EXCEPTION 'original selected Account Study source unavailable' USING ERRCODE='GP002'; END IF;
END $$;
DO $pin_current_account_study_reward_preview$
DECLARE ns OID; owner_id OID; schema_name TEXT; id OID; grantee TEXT; signature TEXT;
BEGIN
 SELECT c.relnamespace,c.relowner,n.nspname INTO STRICT ns,owner_id,schema_name
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid='participation_owners'::regclass;
 FOREACH signature IN ARRAY ARRAY['read_current_account_study_reward_preview_v1(text,text,text,text,text,integer,text,text)','require_original_account_owner_study_source_v1(text,text,text)'] LOOP
 id:=to_regprocedure(format('%I.%s',schema_name,signature));
 IF id IS NULL OR NOT EXISTS(SELECT 1 FROM pg_proc WHERE oid=id AND proowner=owner_id AND pronamespace=ns AND prosecdef) THEN
  RAISE EXCEPTION 'actual Account preview native custody differs' USING ERRCODE='GP003'; END IF;
 EXECUTE format('ALTER FUNCTION %s SET search_path TO pg_catalog,%I,pg_temp',id::regprocedure,schema_name);
 EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',id::regprocedure);
 FOR grantee IN SELECT DISTINCT pg_get_userbyid(a.grantee) FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
  WHERE p.oid=id AND a.grantee<>0 AND a.grantee<>owner_id LOOP
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',id::regprocedure,grantee);
 END LOOP;
 END LOOP;
END $pin_current_account_study_reward_preview$;

-- Source: owner-accounting-observer-readiness-proposal/read-owner-accounting-readiness.sql
-- Controlled catalogue-only observer capability. No private inventory/table SELECT
-- or raw private readiness EXECUTE is delegated to the observer.
CREATE FUNCTION read_owner_accounting_readiness_v1()
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER AS $$
DECLARE source_version_value TEXT; manifest_value JSONB;
BEGIN
 PERFORM require_owner_accounting_ready_private_v1();
 SELECT source_version,manifest INTO STRICT source_version_value,manifest_value
 FROM owner_accounting_native_source_inventory_v1 WHERE singleton;
 IF source_version_value IS DISTINCT FROM 'owner_accounting_native_source_v1'
  OR jsonb_typeof(manifest_value) IS DISTINCT FROM 'object' THEN
  RAISE EXCEPTION 'native accounting source unavailable' USING ERRCODE='GP003';
 END IF;
 RETURN jsonb_build_object(
  'source_version',source_version_value,
  'manifest_sha256',encode(sha256(convert_to(manifest_value::TEXT,'UTF8')),'hex'));
END $$;

