  'owner_admission_private_receipt_v1(text)',
  'require_megapot_drawing_admission_resolved_v1(text,numeric)',
  'require_original_drawing_admission_resolved_private_v1(text,numeric)',
  'require_owner_admission_read_committed_private_v1()',
  'retain_owner_admission_attempt_private_v1()',
  'retain_owner_admission_operation_private_v1()',
