-- Source: account-original-admission-reconciliation-proposal/account-original-admission-reconciliation.sql
-- Original Account journal recovery only. No grade/attempt/qualification/share,
-- new operation/generation/fence/salt, provider or financial payment is created.
CREATE FUNCTION list_account_owner_admission_reconciliation_due_v1(p_maximum INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE result JSONB;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_maximum IS NULL OR p_maximum NOT BETWEEN 1 AND 8 THEN
  RAISE EXCEPTION 'bounded original Account reconciliation required' USING ERRCODE='GP006'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('mainOperationId',r.main_operation_id,
  'sourceOwnerId',r.source_owner_id,'attemptNumber',r.current_attempt_number,'attemptFence',r.current_attempt_fence)
  ORDER BY r.created_at,r.main_operation_id COLLATE "C"),'[]'::JSONB) INTO result FROM (
  SELECT j.main_operation_id,j.source_owner_id,j.current_attempt_number,j.current_attempt_fence,j.created_at
  FROM owner_participation_admission_operations j
  JOIN account_owner_reward_operations o ON o.operation_id=j.account_main_operation_id AND o.operation_id=j.main_operation_id
   AND o.source_owner_id=j.source_owner_id AND o.session_kind=j.source_session_kind AND o.session_id=j.session_id
  JOIN owner_participation_admission_attempts a ON a.admission_id=j.admission_id
   AND a.attempt_number=j.current_attempt_number AND a.attempt_fence=j.current_attempt_fence
  WHERE j.source_owner_kind='account' AND j.state='pending' AND o.state='captured' AND a.state='pending'
  ORDER BY j.created_at,j.main_operation_id COLLATE "C" LIMIT p_maximum
 ) r;
 -- Includes acknowledged original prepares whose marker was never sent/ACKed.
 -- Existence here authorizes only lock-and-fresh-evidence reconciliation.
 RETURN result;
END $$;

CREATE FUNCTION reconcile_account_owner_admission_attempt_v1(p_main TEXT,p_source TEXT,p_fence TEXT,p_attempt INTEGER)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE op account_owner_reward_operations%ROWTYPE; src account_owner_reward_sources%ROWTYPE;
 hold owner_participation_admission_operations%ROWTYPE; attempt owner_participation_admission_attempts%ROWTYPE;
 drawing megapot_pool_drawings%ROWTYPE; at_time TIMESTAMPTZ; decision JSONB; identity JSONB;
BEGIN
 PERFORM require_owner_admission_read_committed_private_v1();
 PERFORM pg_advisory_xact_lock_shared(83000003,1);
 PERFORM require_owner_accounting_ready_private_v1();
 IF p_main IS NULL OR char_length(p_main) NOT BETWEEN 1 AND 128 OR p_source IS NULL
  OR p_fence IS NULL OR p_fence !~ '^[0-9a-f]{64}$' OR p_attempt IS NULL OR p_attempt<1 THEN
  RAISE EXCEPTION 'exact original Account attempt required' USING ERRCODE='GP006'; END IF;
 SELECT * INTO STRICT op FROM account_owner_reward_operations WHERE operation_id=p_main AND source_owner_id=p_source;
 SELECT * INTO STRICT src FROM account_owner_reward_sources
  WHERE source_owner_id=op.source_owner_id AND session_kind=op.session_kind AND session_id=op.session_id;
 -- Uses the SAME reviewed group/media/session order as the real owning producer.
 -- It checks original source/Account/session identity, not current browser auth,
 -- persona/publication/configuration, age or presence of a provider key.
 PERFORM enter_account_owner_reward_action_v1(p_main,src.account_id,src.community_id,op.session_id,p_fence);
 SELECT * INTO STRICT hold FROM owner_participation_admission_operations
  WHERE main_operation_id=p_main AND source_owner_id=p_source;
 PERFORM 1 FROM megapot_pool_drawings WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id FOR UPDATE;
 -- Fresh READ COMMITTED statements AFTER waiting the complete original locks.
 SELECT * INTO STRICT hold FROM owner_participation_admission_operations
  WHERE main_operation_id=p_main AND source_owner_id=p_source FOR UPDATE;
 SELECT * INTO STRICT op FROM account_owner_reward_operations WHERE operation_id=p_main AND source_owner_id=p_source FOR UPDATE;
 SELECT * INTO STRICT drawing FROM megapot_pool_drawings WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id;
 SELECT * INTO STRICT attempt FROM owner_participation_admission_attempts
  WHERE admission_id=hold.admission_id AND attempt_number=hold.current_attempt_number AND attempt_fence=hold.current_attempt_fence FOR UPDATE;
 IF hold.source_owner_kind IS DISTINCT FROM 'account' OR hold.account_main_operation_id IS DISTINCT FROM op.operation_id
  OR hold.guest_main_operation_id IS NOT NULL OR hold.guest_study_session_id IS NOT NULL
  OR ROW(hold.source_session_kind,hold.session_id,hold.operation_kind,hold.idempotency_key,hold.request_hash,hold.qualification_id,
    hold.pool_leg_id,hold.drawing_id::TEXT,hold.terms_hash,hold.policy_hash,hold.qualification_policy_revision,hold.purchase_safety_deadline_at)
   IS DISTINCT FROM ROW(op.session_kind,op.session_id,op.operation_kind,op.idempotency_key,op.request_hash,op.qualification_id,
    src.original_terms->>'pool_leg_id',src.original_terms->>'original_drawing_id',src.original_terms->>'terms_hash',
    src.original_terms->>'policy_hash',src.qualification_policy_revision,src.purchase_safety_deadline_at)
  OR hold.entry_cutoff_at IS DISTINCT FROM(src.original_terms->>'entry_cutoff_at')::TIMESTAMPTZ
  OR drawing.beneficiary_version IS DISTINCT FROM 3 OR drawing.entry_cutoff_at IS DISTINCT FROM hold.entry_cutoff_at THEN
  RAISE EXCEPTION 'immutable original Account admission lineage differs' USING ERRCODE='GP003'; END IF;
 identity:=jsonb_build_object('mainOperationId',p_main,'sourceOwnerId',p_source,'attemptNumber',p_attempt,'attemptFence',p_fence);
 IF op.state='completed' THEN
  IF hold.state='pending' OR op.completion_snapshot->'participation' IS DISTINCT FROM hold.result_snapshot THEN
   RAISE EXCEPTION 'completed original Account receipt differs' USING ERRCODE='GP003'; END IF;
  RETURN identity||jsonb_build_object('state','completed');
 END IF;
 -- A stale due-list generation never authorizes changing a newer original hold.
 IF hold.current_attempt_number IS DISTINCT FROM p_attempt OR hold.current_attempt_fence IS DISTINCT FROM p_fence THEN
  RETURN identity||jsonb_build_object('state','stale'); END IF;
 IF hold.state='reconciled_no_commit' THEN
  IF attempt.state IS DISTINCT FROM 'authoritative_no_commit'
   OR(hold.result_snapshot IS DISTINCT FROM jsonb_build_object('state','unavailable')
    AND hold.result_snapshot IS DISTINCT FROM jsonb_build_object('state','entry_closed')) THEN
   RAISE EXCEPTION 'original no-commit receipt differs' USING ERRCODE='GP003'; END IF;
  RETURN identity||jsonb_build_object('state','reconciled_no_commit','participation',hold.result_snapshot,'changed',FALSE);
 END IF;
 IF op.state IS DISTINCT FROM 'captured' OR hold.state IS DISTINCT FROM 'pending' OR attempt.state IS DISTINCT FROM 'pending' THEN
  RAISE EXCEPTION 'captured original Account attempt is inconsistent' USING ERRCODE='GP003'; END IF;
 -- Neither expiry nor absent upload/provider evidence is used as financial proof.
 -- Every owning family writes grade + qualification + admission + completion in
 -- the same held source/session/drawing transaction, so ANY orphan fact refuses.
 IF EXISTS(SELECT 1 FROM activity_qualifications WHERE account_main_operation_id=p_main OR qualification_id=op.qualification_id)
  OR EXISTS(SELECT 1 FROM megapot_owner_shares WHERE pool_leg_id=hold.pool_leg_id AND drawing_id=hold.drawing_id
   AND owner_id=hold.source_owner_id AND qualification_id=hold.qualification_id)
  OR(op.session_kind='study_legacy' AND EXISTS(SELECT 1 FROM study_session_answers
   WHERE session_id=op.session_id AND idempotency_key=op.idempotency_key))
  OR(op.session_kind='study_v2' AND EXISTS(SELECT 1 FROM study_attempts_v2
   WHERE session_item_id=op.captured_payload->>'sessionItemId' AND idempotency_key=op.idempotency_key))
  OR(op.session_kind='karaoke' AND EXISTS(SELECT 1 FROM karaoke_attempts
   WHERE session_id=op.session_id AND attempt_id=op.captured_payload->'authority'->>'attemptId'))
  OR(op.producer_kind='v2_spoken' AND EXISTS(SELECT 1 FROM study_spoken_answer_commands
   WHERE command_id=op.captured_payload->>'commandId' AND state='completed')) THEN
  RAISE EXCEPTION 'original Account grade/qualification/outcome atomicity differs' USING ERRCODE='GP003'; END IF;
 at_time:=clock_timestamp();
 decision:=jsonb_build_object('state',CASE WHEN at_time>=hold.entry_cutoff_at OR at_time>=hold.purchase_safety_deadline_at
  THEN 'entry_closed' ELSE 'unavailable' END);
 UPDATE owner_participation_admission_attempts SET state='authoritative_no_commit',resolved_at=at_time
  WHERE admission_id=hold.admission_id AND attempt_number=p_attempt AND attempt_fence=p_fence AND state='pending';
 IF NOT FOUND THEN RAISE EXCEPTION 'original Account attempt fence changed' USING ERRCODE='GP005'; END IF;
 UPDATE owner_participation_admission_operations SET state='reconciled_no_commit',result_snapshot=decision,resolved_at=at_time
  WHERE admission_id=hold.admission_id AND current_attempt_number=p_attempt AND current_attempt_fence=p_fence AND state='pending';
 IF NOT FOUND THEN RAISE EXCEPTION 'original Account journal fence changed' USING ERRCODE='GP005'; END IF;
 RETURN identity||jsonb_build_object('state','reconciled_no_commit','participation',decision,'changed',TRUE);
END $$;

-- Source: account-original-admission-reconciliation-proposal/bind-reconciliation-private.sql
-- Source-bound private default. Proposed ONLY actual Account CONTROL_PLANE
-- scheduled profile candidates; no Guest cron grant or serving ACL installed.
DO $pin_original_account_admission_reconciliation$
DECLARE owner_id OID; namespace_id OID; schema_name TEXT; signature TEXT; id OID; grantee TEXT;
BEGIN
 SELECT c.relowner,c.relnamespace,n.nspname INTO STRICT owner_id,namespace_id,schema_name
 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.oid='participation_owners'::regclass;
 FOREACH signature IN ARRAY ARRAY['list_account_owner_admission_reconciliation_due_v1(integer)',
  'reconcile_account_owner_admission_attempt_v1(text,text,text,integer)'] LOOP
  id:=to_regprocedure(format('%I.%s',schema_name,signature));
  IF id IS NULL OR NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=id AND p.proowner=owner_id
   AND p.pronamespace=namespace_id AND p.prokind='f' AND p.prosecdef AND pg_get_function_result(p.oid)='jsonb') THEN
   RAISE EXCEPTION 'original Account reconciliation custody differs' USING ERRCODE='GP003'; END IF;
  EXECUTE format('ALTER FUNCTION %s SET search_path TO pg_catalog,%I,pg_temp',id::regprocedure,schema_name);
  EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',id::regprocedure);
  FOR grantee IN SELECT DISTINCT pg_get_userbyid(a.grantee) FROM pg_proc p
   CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
   WHERE p.oid=id AND a.grantee<>0 AND a.grantee<>owner_id LOOP
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM %I',id::regprocedure,grantee);
  END LOOP;
 END LOOP;
END $pin_original_account_admission_reconciliation$;

-- Source: owner-financial-readiness-proposal-v5/final-advance-complete-owner-phase
DO $advance_complete_owner_phase$
DECLARE phase_count INTEGER;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='guest_learning_schema_phase'::regclass
   AND relowner=(SELECT relowner FROM pg_class WHERE oid='participation_owners'::regclass)
   AND relnamespace=(SELECT relnamespace FROM pg_class WHERE oid='participation_owners'::regclass)) THEN
  RAISE EXCEPTION 'native phase custody unavailable' USING ERRCODE='GP003'; END IF;
 ALTER TABLE guest_learning_schema_phase DROP CONSTRAINT guest_learning_schema_phase_phase_check;
 UPDATE guest_learning_schema_phase SET phase='owner_accounting_native_source_v1'
  WHERE singleton AND phase='disabled_owner_financial_history_v1';
 GET DIAGNOSTICS phase_count=ROW_COUNT;
 IF phase_count<>1 OR (SELECT count(*) FROM guest_learning_schema_phase)<>1 THEN
  RAISE EXCEPTION 'exact predecessor phase required' USING ERRCODE='GP003'; END IF;
 ALTER TABLE guest_learning_schema_phase ADD CONSTRAINT guest_learning_schema_phase_phase_check
  CHECK(phase='owner_accounting_native_source_v1');
 PERFORM require_owner_accounting_ready_private_v1();
END $advance_complete_owner_phase$;
